#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Order-Bot — platziert die MASTER-Order per SICHTBARER Maus-/Tastatur-Steuerung
(15.08.2026, Finns Ansage: die Order muss serverseitig wie ein Handklick
aussehen — eine API-Order traegt die Expert-Markierung, ein echter Klick nicht).

Choreografie (sichtbar, wie mit Finn geuebt):
  1. Maus faehrt in die Taskleiste und klickt den Terminal-Tab
  2. Fenster-Guard: Titelzeile MUSS die Kontonummer tragen, sonst Abbruch
  3. F9 -> Order-Dialog, Symbol waehlen, Volumen ECHT eintippen (Tastatur-
     Events, kein set_text — s. _feld_tippen) und zuruecklesen
  4. Maus faehrt auf den Buy/Sell-Knopf und klickt — der einzige unumkehrbare Schritt
  5. Bestaetigung NICHT der UI glauben: Positionsliste des Kontos (nur LESEND
     ueber die MetaTrader5-API — Lesen traegt keine Order-Markierung)
  6. SL/TP vom ECHTEN Einstiegskurs rechnen und PER KLICK im Aendern-Dialog
     der Position eintragen (18.08.2026, Finns Ansage: auch die SL/TP-Aenderung
     muss wie Handarbeit aussehen — der fruehere TRADE_ACTION_SLTP-Weg lief
     ueber denselben API-Kanal wie ein EA, unnoetiges Restrisiko). Bestaetigt
     wird auch das nur LESEND am Positionsstand.

Die API wird ausschliesslich LESEND benutzt: aktueller Kurs fuer die
$->Preis-Umrechnung, Positionsstand vorher/nachher, SL/TP-Kontrolle.
mt5.order_send existiert in dieser Datei bewusst NICHT.

Aufruf (vom Panel als kurzlebiger Subprozess):
  python order_bot.py <config-datei.json> "<befehl-json>"
  python order_bot.py inspect <config-datei.json>     (Dialog-Dump, platziert nichts)
  python order_bot.py tvorder "<befehl-json>"         (Orbit: Order auf TradingView)
  python order_bot.py tvlesen "<befehl-json>"         (Orbit V2: Konto lesen — Position offen? Today's P&L)
Befehl:  {"symbol": "NDX100", "richtung": "buy", "volumen": 0.2,
          "sl_usd": 100, "tp_usd": 300}
Antwort: EINE JSON-Zeile auf stdout.

retry_ok-Regel: True nur, solange sicher NICHTS gesendet wurde (jeder Abbruch
VOR dem Buy/Sell-Klick). Nach dem Klick ist jede Unsicherheit retry_ok=False —
'erst im Terminal nachsehen, nie blind wiederholen'.
"""

import json
import math
import os
import random
import re
import sys
import time


# ---------------------------------------------------------------------------
# REIN RECHNENDE Funktionen — ohne Windows/MetaTrader testbar (selftest.py)
# ---------------------------------------------------------------------------

def pruefe_befehl(cmd):
    """Liste von Fehlertexten; leer = Befehl ok."""
    fehler = []
    if not isinstance(cmd, dict):
        return ["Befehl ist kein JSON-Objekt."]
    if str(cmd.get("aktion") or "").lower() == "close":
        # Close-Befehl (28.08.2026, Remote-Close): braucht NUR Ticket + Symbol —
        # Richtung/Volumen/SL/TP gehoeren zur Eroeffnung. Eigener Zweig, damit
        # ein Close nie durch die Order-Pflichtfelder rutscht (und umgekehrt
        # ein alter Bot-Build den unbekannten Befehl an genau diesen Feldern
        # sauber ablehnt, statt etwas zu raten).
        try:
            if int(cmd.get("ticket") or 0) <= 0:
                fehler.append("ticket fehlt oder <= 0")
        except (TypeError, ValueError):
            fehler.append("ticket ist keine Zahl")
        if not str(cmd.get("symbol") or "").strip():
            fehler.append("symbol fehlt")
        return fehler
    if not str(cmd.get("symbol") or "").strip():
        fehler.append("symbol fehlt")
    if str(cmd.get("richtung") or "").lower() not in ("buy", "sell"):
        fehler.append("richtung muss buy oder sell sein")
    try:
        v = float(cmd.get("volumen") or 0)
        # isfinite deckt NaN und Infinity ab ('nan <= 0' waere still False)
        if not math.isfinite(v) or v <= 0:
            fehler.append("volumen fehlt oder <= 0")
    except (TypeError, ValueError):
        fehler.append("volumen ist keine Zahl")
    # SL/TP sind OPTIONAL (18.08.2026, Schalter im Order-Popup): beide gesetzt
    # -> Bot traegt sie nach dem Fill per Klick ein; beide leer -> Order pur,
    # SL/TP macht Finn von Hand. NUR EINES gesetzt ist ein Fehler.
    gesetzt = {}
    for k in ("sl_usd", "tp_usd"):
        roh = cmd.get(k)
        if roh in (None, "", 0, "0"):
            gesetzt[k] = False
            continue
        gesetzt[k] = True
        try:
            v = float(roh)
            if not math.isfinite(v) or v <= 0:
                fehler.append(f"{k} <= 0 oder keine Zahl")
        except (TypeError, ValueError):
            fehler.append(f"{k} ist keine Zahl")
    if gesetzt.get("sl_usd") != gesetzt.get("tp_usd"):
        fehler.append("sl_usd und tp_usd nur ZUSAMMEN setzen (oder beide weglassen)")
    return fehler


def fmt_preis(x, digits):
    """Preis mit PUNKT als Dezimaltrenner — MT5-Eingabefelder erwarten den Punkt
    unabhaengig von der Windows-Sprache."""
    return f"{float(x):.{int(digits)}f}"


def berechne_sl_tp(richtung, ref_preis, volumen, contract_size, sl_usd, tp_usd, digits=2):
    """$-Betraege -> absolute Preise. 1.0 Preis-Einheit ist volumen*contract_size
    wert (Index-CFD in USD) — dieselbe Basis wie die Exposure-Formel im Copier."""
    ref = float(ref_preis)
    je_einheit = float(volumen) * float(contract_size)
    if je_einheit <= 0:
        raise ValueError("volumen*contract_size muss > 0 sein")
    kauf = str(richtung).lower() == "buy"
    d_sl = float(sl_usd) / je_einheit
    d_tp = float(tp_usd) / je_einheit
    sl = round(ref - d_sl if kauf else ref + d_sl, int(digits))
    tp = round(ref + d_tp if kauf else ref - d_tp, int(digits))
    return sl, tp


def finde_neue_position(vorher_tickets, positionen, symbol, richtung, volumen, tol=0.005):
    """Die frisch platzierte Position wiederfinden: neues Ticket, richtiges
    Symbol, richtige Richtung, Volumen im Toleranzfenster (Lot-Raster)."""
    will_typ = 0 if str(richtung).lower() == "buy" else 1
    for p in positionen:
        if p["ticket"] in vorher_tickets:
            continue
        if p["symbol"] != symbol or p["typ"] != will_typ:
            continue
        if abs(p["volumen"] - float(volumen)) <= tol:
            return p
    return None


def ist_aendern_knopf(text):
    """Erkennt den Aendern-Knopf des Positions-Dialogs an der Beschriftung —
    und schliesst alles aus, was loeschen/schliessen/abbrechen koennte. Reine
    Textlogik, damit der Mac-Selbsttest sie abdeckt."""
    t = (text or "").strip().lower()
    if not t:
        return False
    for verboten in ("abbre", "cancel", "schlie", "close", "delet", "loesch", "lösch"):
        if verboten in t:
            return False
    return any(k in t for k in ("ändern", "aendern", "modify", "change"))


def ist_bestaetigen_knopf(text):
    """Der LANGE Bestaetigen-Knopf des Aendern-Dialogs — NICHT der 'Position
    aendern'-Reiter links (Fund 18.08.2026: ist_aendern_knopf traf im UI-Baum
    zuerst den Reiter, der Bot drueckte bei jedem Lauf brav den Reiter statt
    zu bestaetigen — Dialog blieb wirkungslos offen und wurde verworfen).
    Der Bestaetigen-Knopf traegt die Order-Daten in der Beschriftung:
    '#<Ticket> buy 1 NAS100 ... sl: ... tp: ... aendern'."""
    t = (text or "").strip().lower()
    if not ist_aendern_knopf(t):
        return False
    if t in ("position ändern", "position aendern", "modify position"):
        return False
    return ("#" in t or "sl:" in t or "tp:" in t
            or bool(re.search(r"(?<!\d)\d{7,}(?!\d)", t)))


def sltp_bestaetigt(pos_sl, pos_tp, sl, tp, digits):
    """Traegt die Position die gewuenschten SL/TP? Toleranz: 1.5 Einheiten der
    letzten Kursstelle (Server normalisieren minimal). 0.0 heisst 'nicht
    gesetzt' und faellt damit automatisch durch."""
    tol = 1.5 * (10 ** -int(digits))
    return (abs(float(pos_sl) - float(sl)) <= tol
            and abs(float(pos_tp) - float(tp)) <= tol)


def zahl_gleich(text, wert, tol=1e-9):
    """Zeigt der ZURUECKGELESENE Feldtext wirklich den getippten Wert? Vergleich
    als Zahl, nicht als String — MT5 formatiert um ('2' -> '2.00') und kann je
    nach Windows-Locale Komma/Leerzeichen einstreuen."""
    try:
        a = float(str(text).strip().replace(" ", "").replace(",", "."))
        b = float(str(wert).strip().replace(",", "."))
    except (TypeError, ValueError):
        return False
    return abs(a - b) <= tol * max(1.0, abs(b)) + 1e-12


def zeile_nennt_ticket(text, ticket):
    """Steht die Ticket-Nummer als eigenstaendige Zahl im Element-Text? So wird
    die Zeile der Position in der Handel-Liste erkannt, ohne dass 9123456789
    faelschlich auf 123456789 passt."""
    return bool(re.search(r"(?<!\d)" + re.escape(str(int(ticket))) + r"(?!\d)",
                          text or ""))


def ist_handelszeile(text, symbol):
    """Sieht der UIA-Text wie eine Zeile der HANDEL-Liste aus? Symbol UND
    buy/sell muessen drinstehen. Fund 18.08.2026: der .54-Filter (Symbol plus
    Mindestlaenge) traf auch den Chart-Titel ('NAS100,M1: US Tech 100 Index')
    und den Navigator-Eintrag ('ProphosHedgeReader - NAS100,M1') — der
    Doppelklick darauf oeffnete den EA-Eigenschaften-Dialog. Beide tragen
    nie buy/sell."""
    t = (text or "").lower()
    return bool(symbol) and symbol.lower() in t and ("buy" in t or "sell" in t)


def ist_close_menuepunkt(text):
    """Der EINE Kontextmenue-Punkt, den der Close-Weg klicken darf (28.08.2026,
    Remote-Close). Bisher war 'Position schliessen' der Eintrag, den der Bot
    NIEMALS treffen durfte (.57: blinde Pfeiltasten = genau dieses Risiko) —
    jetzt ist er das Ziel, darum besonders strikt: Praefix-Match statt
    contains, und Alle-/Massen-Varianten sind hart ausgeschlossen (ein 'Alle
    Positionen schliessen' traefe alles, was auf dem Konto liegt)."""
    t = (text or "").strip().lower()
    if not t:
        return False
    if "alle" in t or "all p" in t or "massen" in t or "bulk" in t:
        return False
    # 'schlie' deckt schließen/schliessen samt Encoding-Varianten des ß ab
    return t.startswith(("position schlie", "close position"))


def ist_schliessen_knopf(text, ticket):
    """Der gelbe Bestaetigen-Balken im Close-Dialog ('Schliessen #123 buy 1.20
    NAS100 zum Marktpreis' bzw. 'Close #123 ... by Market'). Positiv-Signatur
    wie beim Bestaetigen-Knopf des Aendern-Dialogs (.65): das Ticket MUSS in
    der Beschriftung stehen — die Ticket-Gegenpruefung ist damit Teil der
    Erkennung selbst. Aendern-/Abbrechen-/Loeschen-Knoepfe sind nie Treffer."""
    t = (text or "").strip().lower()
    if not t or not zeile_nennt_ticket(t, ticket):
        return False
    if any(k in t for k in ("ändern", "aendern", "andern", "modify",
                            "abbrechen", "cancel", "lösch", "loesch", "delete")):
        return False
    return "schlie" in t or "close" in t


def ist_einklick_dialog(titel):
    """Der Haftungsausschluss, den MT5 vor dem ERSTEN Ein-Klick-Handel eines
    Terminals dazwischenschiebt (Finn 01.09.2026: "ich habe grad per 'Order
    schliessen' Puls die Aufgabe gegeben zu schliessen, aber hier kam dann die
    Meldung"). Er verschluckt den Close: geklickt wurde, passiert ist nichts.
    Erkennung ueber den Fenstertitel — ergaenzend zur Knopf-Signatur, die die
    eigentliche Zustimmung traegt."""
    t = (titel or "").strip().lower()
    return ("ein-klick" in t or "ein klick" in t or "einklick" in t
            or "one click" in t or "one-click" in t)


def ist_einklick_akzeptieren_knopf(text):
    """Der Zustimmen-Knopf dieses Haftungsausschlusses ('Ich akzeptiere die
    allgemeinen Geschaeftsbedingungen' / 'I accept the terms and conditions').
    Positiv-Signatur aus BEIDEN Haelften — Zustimmung UND Bedingungen —, damit
    kein beliebiger Knopf mit 'akzeptieren' im Text getroffen wird; Abbrechen
    und jede Ablehnung sind hart ausgeschlossen. Reine Textlogik, damit der
    Mac-Selbsttest sie abdeckt."""
    t = (text or "").strip().lower()
    if not t:
        return False
    for verboten in ("abbre", "cancel", "nicht", "ablehn", "decline",
                     "reject", "disagree", "do not", "don't"):
        if verboten in t:
            return False
    zustimmung = any(k in t for k in ("akzeptier", "zustimm", "einverstanden",
                                      "accept", "agree"))
    bedingungen = any(k in t for k in ("bedingung", "geschäft", "geschaeft",
                                       "terms", "conditions"))
    return zustimmung and bedingungen


# Fensterklassen der Browser (28.08.2026): alle Chromium-Ableger (Chrome, Edge,
# Brave — auch die als App installierte PWA-Huelle) teilen sich eine Klasse,
# dazu Firefox.
BROWSER_KLASSEN = ("Chrome_WidgetWin_1", "MozillaWindowClass")


def ist_prophos_fenster(titel, klasse):
    """Ist dieses Fenster der Browser mit dem Prophos-Tab? Positiv-Signatur aus
    Titel UND Fensterklasse (Lehre vom 18.08., EA-Dialog-Fehlgriff: nie nur ein
    String-Treffer): start-prophos.bat setzt der Backend-KONSOLE selbst den
    Titel 'Prophos-Backend' — ein reiner Titel-Match holte also die Konsole
    nach vorn statt des Browsers. Der Titel beginnt stabil mit 'Prophos'
    (prophos.html setzt kein dynamisches document.title; startswith haelt
    ausserdem DevTools-Fenster fern, deren Titel die URL nur ENTHAELT)."""
    t = (titel or "").strip().lower()
    return t.startswith("prophos") and (klasse or "") in BROWSER_KLASSEN


TSX_RX_TITEL = re.compile(r"^\s*(?:\(\d+\)\s*)?[A-Z]{1,5}[FGHJKMNQUVXZ]\d{2}\s+\$\s?\d")


def ist_topstepx_titel(titel):
    """B16 (27.09.2026): TopstepX-Web-App (topstepx.com/trade) — Titel/Tab-Name enthaelt 'topstepx'. Der Titel kann
    wie ein TradingView-Chart aussehen ('MNQZ26 30,922.50 …'), deshalb schliesst dieses Merkmal ihn ueberall aus.
    B19 (27.09.2026, dritter Live-Test bei ID A): der geladene TopstepX-Tab heisst NUR „NQZ26 $30,921.75 ▲ +0.50%" — kein
    'TopstepX'. Merkmal: Kontrakt mit ZWEISTELLIGEM Jahr (NQZ26) und '$' vor dem Kurs. TradingView schreibt 'NQZ2026 30,882.00'
    bzw. 'MNQ1! 30,889.25' (vierstelliges Jahr/Dauerkontrakt, kein '$') — diese Titel bleiben TradingView."""
    t = str(titel or "")
    return "topstepx" in t.lower() or bool(TSX_RX_TITEL.match(t))


def ist_tradingview_fenster(titel, klasse):
    """Ist dieses Fenster der Browser mit AKTIVEM TradingView-Tab? (Orbit-Puls
    Schritt 1, 28.08.2026.) Gleiche Positiv-Signatur wie ist_prophos_fenster:
    Titel UND Browser-Klasse. Der Fenstertitel ist immer der AKTIVE Tab —
    haengt TradingView als Hintergrund-Tab im Prophos-Fenster, ist es hier
    unsichtbar; das Zielbild (Vault, 28.08.2026) ist ohnehin ein EIGENES
    TV-Fenster/Profil pro Konto. 'tradingview' steht bei TV mitten im Titel
    (Chart-Titel davor, Browser-Name dahinter), deshalb contains statt
    startswith — DevTools tragen die URL im Titel und sind explizit raus."""
    t = (titel or "").strip().lower()
    if not t or (klasse or "") not in BROWSER_KLASSEN:
        return False
    if t.startswith("devtools") or ist_topstepx_titel(t):
        return False                  # B16: TopstepX-Tab ist nie TradingView (Suche, Heilung, Strg+W)
    return "tradingview" in t


# ---------------------------------------------------------------------------
# CHROME-PROFIL-RIEGEL (26.09.2026) — Puls fasst das Reader-Chrome nie an
#
# Finn 26.09.2026 (PC von ID B pc-cccccc): "Wenn ich manchmal Trades bei ID B
# machen will, geht der Puls-Bot automatisch in dieses extra neue Chrome-Profil,
# wo nur das Reader-Terminal liegt, will da Orders platzieren und meldet sich
# deshalb auch an." Dort: Hauptprofil "ID B" (Orders), zweites Profil
# "Terminal 1" (nur TradingView 24/7 fuer den Reader). Beleg order_signale:
# Rundgaenge fanden den Reader-Tab ("MNQ1! … Nicht benannt") zuerst, schlossen
# ihn (Feed-Ausfall 10:25:14–10:27:51) und meldeten sich darin bei Tradovate an.
#
# Warum ueber das PROFIL und nicht ueber Titel oder Prozess: beide Profile
# laufen im selben chrome.exe (gleiches User-Data-Verzeichnis), Titel wechseln
# mit Symbol und Sprache, und nach einem Login meldet auch der Reader-Tab
# rolle 'broker'. Chrome haengt aber an JEDES Fenster die Windows-Eigenschaft
# AppUserModel_RelaunchCommand mit '--profile-directory=…' (und eine
# AppUserModelID mit Profil-Endung) — das ist fest, solange das Fenster lebt.
#
# Regel: Puls benutzt nur Fenster SEINES Profils (tv_chrome_profil aus der
# config.json, Verzeichnis ODER Anzeigename; ohne Eintrag das Chrome-Standard-
# profil 'Default'), und nie ein Profil aus tv_reader_profil. Fenster ohne
# lesbares Profil (ein einziges Chrome-Profil, andere Browser) bleiben wie
# bisher erlaubt. Neue TV-Fenster startet er immer mit --profile-directory
# seines Profils — ohne den Schalter oeffnet Chrome im ZULETZT benutzten
# Profil, und das war auf PC von ID B das Reader-Profil.
# ---------------------------------------------------------------------------

_RX_PROFIL_ARG = re.compile(r'--profile-directory=(?:"([^"]+)"|(\S+))', re.I)


def chrome_profil_aus_relaunch(befehl):
    """'--profile-directory=' aus Chromes Relaunch-Befehl eines Fensters. '' = keins."""
    m = _RX_PROFIL_ARG.search(str(befehl or ""))
    return ((m.group(1) or m.group(2) or "").strip().strip('"')) if m else ""


def _profil_kurz(s):
    return re.sub(r"[^a-z0-9]", "", str(s or "").lower())


def chrome_profil_aus_appid(appid, verzeichnisse):
    """AppUserModelID -> Profil-Verzeichnis. Chrome haengt an die ID eines
    Nicht-Standard-Profils das Verzeichnis ohne Sonderzeichen an
    ('Chrome.Profile1'); das Standardprofil traegt keine Endung und bleibt
    hier bewusst unbekannt ('') — gesperrt wird nur, was sicher erkannt ist."""
    teile = [_profil_kurz(t) for t in str(appid or "").split(".")[1:]]
    for d in verzeichnisse or ():
        if d != "Default" and _profil_kurz(d) and _profil_kurz(d) in teile:
            return d
    return ""


def chrome_profile_lesen(local_state):
    """{Verzeichnis: Anzeigename} aus Chromes 'Local State' (profile.info_cache)."""
    try:
        cache = ((local_state or {}).get("profile") or {}).get("info_cache") or {}
        return {str(d): str((v or {}).get("name") or d) for d, v in cache.items()}
    except Exception:
        return {}


def chrome_profil_aufloesen(wert, profile):
    """Config-Wert (Verzeichnis ODER Anzeigename, Gross/klein egal) -> Verzeichnis.
    '' = nicht gefunden. Ohne Profilliste gilt der Wert selbst."""
    w = str(wert or "").strip()
    if not w:
        return ""
    if not profile:
        return w
    for d in profile:
        if w.lower() == d.lower():
            return d
    for d, n in profile.items():
        if w.lower() == str(n).strip().lower():
            return d
    return ""


def puls_profil_regel(profile, eigen="", tabu=""):
    """Die Profil-Regel eines PCs -> {eigen, tabu, mehrere, fehler}.
    eigen = Verzeichnis, in dem Puls arbeitet und startet ('' = unbekannt);
    tabu = Verzeichnisse, die er nie anfasst; fehler = Grund, warum er keinen
    Chrome-Start wagen darf."""
    profile = profile or {}
    regel = {"eigen": "", "tabu": set(), "mehrere": len(profile) > 1, "fehler": ""}
    for teil in re.split(r"[,;]", str(tabu or "")):
        if not teil.strip():
            continue
        d = chrome_profil_aufloesen(teil, profile)
        if d:
            regel["tabu"].add(d)
        else:
            regel["fehler"] = f"tv_reader_profil '{teil.strip()}' ist in Chrome kein Profil."
    if str(eigen or "").strip():
        regel["eigen"] = chrome_profil_aufloesen(eigen, profile)
        if not regel["eigen"]:
            regel["fehler"] = f"tv_chrome_profil '{str(eigen).strip()}' ist in Chrome kein Profil."
    elif len(profile) == 1:
        regel["eigen"] = next(iter(profile))
    elif "Default" in profile:
        regel["eigen"] = "Default"
    elif profile:
        regel["fehler"] = ("mehrere Chrome-Profile und keins heisst 'Default' — "
                           "tv_chrome_profil in der config.json setzen.")
    if regel["eigen"] and regel["eigen"] in regel["tabu"]:
        regel["fehler"] = (f"Das Puls-Profil '{regel['eigen']}' steht zugleich in tv_reader_profil — "
                           "Puls arbeitet nie im Reader-Profil.")
        regel["eigen"] = ""
    return regel


def profil_erlaubt(profil, regel):
    """Darf Puls ein Fenster dieses Profils benutzen? Unbekanntes Profil = ja
    (Verhalten wie vor dem Riegel); Tabu-Profil nie; bei mehreren Profilen nur
    das eigene — und ist das eigene unklar, keins, das sicher erkannt ist."""
    if not profil or not regel:
        return True
    if profil in regel.get("tabu", ()):
        return False
    if regel.get("mehrere"):
        return bool(regel.get("eigen")) and profil == regel["eigen"]
    return True


_PROFIL_REGEL = None
_PROFIL_NAMEN = {}
_FENSTER_PROFIL = {}


def _puls_cfg_datei():
    """config.json neben dem Bot (sonst config.vorlage.json) — dieselbe Quelle wie
    base_config() im Panel. tvorder/tvlesen/tvclose bekommen keine Config mit."""
    hier = os.path.dirname(os.path.abspath(__file__))
    for n in ("config.json", "config.vorlage.json"):
        try:
            with open(os.path.join(hier, n), "r", encoding="utf-8") as f:
                d = json.load(f)
            if isinstance(d, dict) and d:
                return d
        except Exception:
            continue
    return {}


def puls_profil_regel_holen(cfg=None):
    """Regel einmal je Lauf bauen: Local State + Config (Befehl vor Datei)."""
    global _PROFIL_REGEL, _PROFIL_NAMEN
    if _PROFIL_REGEL is not None:
        return _PROFIL_REGEL
    datei = _puls_cfg_datei()
    cfg = cfg or {}
    eigen = str(cfg.get("tv_chrome_profil") or datei.get("tv_chrome_profil") or "").strip()
    tabu = str(cfg.get("tv_reader_profil") or datei.get("tv_reader_profil") or "").strip()
    profile = {}
    try:
        pfad = os.path.join(os.environ.get("LOCALAPPDATA") or "", "Google", "Chrome", "User Data", "Local State")
        with open(pfad, "r", encoding="utf-8") as f:
            profile = chrome_profile_lesen(json.load(f))
    except Exception:
        profile = {}
    _PROFIL_NAMEN = profile
    _PROFIL_REGEL = puls_profil_regel(profile, eigen, tabu)
    return _PROFIL_REGEL


def _fenster_profil(hwnd):
    """Chrome-Profil-Verzeichnis eines Fensters aus seinen Windows-Eigenschaften
    (pywin32, kommt mit pywinauto). '' = nicht lesbar."""
    try:
        h = int(hwnd)
    except Exception:
        return ""
    if h in _FENSTER_PROFIL:
        return _FENSTER_PROFIL[h]
    profil = ""
    try:
        import pywintypes
        from win32com.propsys import propsys
        fmt = pywintypes.IID("{9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3}")   # PKEY_AppUserModel_*
        store = propsys.SHGetPropertyStoreForWindow(h, propsys.IID_IPropertyStore)

        def lies(pid):
            try:
                return str(store.GetValue((fmt, pid)).GetValue() or "")
            except Exception:
                return ""
        profil = chrome_profil_aus_relaunch(lies(2))                       # RelaunchCommand
        if not profil:
            profil = chrome_profil_aus_appid(lies(5), list(_PROFIL_NAMEN))  # AppUserModelID
    except Exception:
        profil = ""
    _FENSTER_PROFIL[h] = profil
    return profil


_PULS_CHROME_PID = {"geholt": False, "pid": None}


def _puls_chrome_browser_pid():
    """Prozess-ID des Puls-Chrome-Browsers (CDP-Port 9333, SystemInfo.getProcessInfo), einmal je Lauf. None = läuft nicht."""
    if _PULS_CHROME_PID["geholt"]:
        return _PULS_CHROME_PID["pid"]
    _PULS_CHROME_PID["geholt"] = True
    try:
        v = _cdp_http("/json/version", timeout=1.0)
        if v and v.get("webSocketDebuggerUrl"):
            ws = _CdpVerbindung(v["webSocketDebuggerUrl"], timeout=3.0)
            try:
                info = ws.rufe("SystemInfo.getProcessInfo", timeout=3.0)
            finally:
                ws.zu()
            for pr in info.get("processInfo") or []:
                if pr.get("type") == "browser":
                    _PULS_CHROME_PID["pid"] = int(pr.get("id"))
                    break
    except Exception:
        pass
    return _PULS_CHROME_PID["pid"]


def _fenster_relaunch(hwnd):
    """Chromes Relaunch-Befehl eines Fensters (PKEY_AppUserModel_RelaunchCommand) — '' = nicht lesbar."""
    try:
        import pywintypes
        from win32com.propsys import propsys
        fmt = pywintypes.IID("{9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3}")
        store = propsys.SHGetPropertyStoreForWindow(int(hwnd), propsys.IID_IPropertyStore)
        return str(store.GetValue((fmt, 2)).GetValue() or "")
    except Exception:
        return ""


def fenster_ist_puls_chrome(fenster_pid, browser_pid, relaunch):
    """REIN RECHNEND (testbar): gehört ein Fenster zum Puls-Chrome (CDP)? Gleiche Prozess-ID wie dessen Browser ODER
    'puls-chrome' im --user-data-dir des Relaunch-Befehls."""
    try:
        if browser_pid and fenster_pid and int(fenster_pid) == int(browser_pid):
            return True
    except (TypeError, ValueError):
        pass
    return bool(re.search(r"--user-data-dir=\"?[^\"]*[\\/]" + re.escape(PULS_CHROME_ORDNER) + r"(\"|\s|$|[\\/])", str(relaunch or ""), re.I))


def _fenster_gesperrt(hwnd):
    """'' = Puls darf das Fenster benutzen, sonst die Bezeichnung des fremden Profils."""
    # 29.09.2026 (ID B pc-cccccc, 23:5x UTC): das Puls-Chrome (CDP, eigenes Profil „Default" im Ordner puls-chrome) sah für
    # die Fenster-Wahl aus wie das Puls-Fenster — der UIA-Puls schloss/öffnete darin TradingView-Tabs. Nie benutzen.
    try:
        import ctypes
        pid_ = ctypes.c_ulong()
        ctypes.windll.user32.GetWindowThreadProcessId(int(hwnd), ctypes.byref(pid_))
        if fenster_ist_puls_chrome(pid_.value, _puls_chrome_browser_pid(), _fenster_relaunch(hwnd)):
            return "Puls-Chrome (CDP)"
    except Exception:
        pass
    regel = puls_profil_regel_holen()
    p = _fenster_profil(hwnd)
    if profil_erlaubt(p, regel):
        return ""
    n = _PROFIL_NAMEN.get(p) or p
    return n if n == p else f"{n} ({p})"


def puls_start_profil(cfg=None):
    """(Verzeichnis fuer --profile-directory, fehler). Ohne Profilliste (kein
    Local State lesbar) der Config-Wert wie bisher."""
    regel = puls_profil_regel_holen(cfg)
    if regel.get("eigen"):
        return regel["eigen"], ""
    if regel.get("fehler") or regel.get("mehrere"):
        return "", (regel.get("fehler") or "Puls-Profil unklar") + \
            " Chrome wird nicht gestartet (sonst oeffnet es im zuletzt benutzten Profil — womoeglich dem Reader-Profil)."
    return str((cfg or {}).get("tv_chrome_profil") or "").strip(), ""


# ---------------------------------------------------------------------------
# FENSTER-TREUE (26.09.2026, Auftrag Koordination B6, Finn: „Das Einfachste: Puls muss immer im bestehenden Chrome-
# Fenster bleiben. Er darf einen neuen Tab oeffnen, aber kein neues Fenster … er darf kein anderes Profil oeffnen,
# einfach immer im gleichen Profil sein, nur Tabs hinzufuegen, keine Fenster.")
#
# Puls hat EIN Handels-Fenster je PC. Gemerkt in puls_fenster.json neben dem Bot (HWND, Prozess-ID, Profil wenn
# lesbar). Danach sucht er TradingView NUR in diesem Fenster und aktiviert nie ein anderes — auch wenn dort
# TradingView offen ist (das Reader-Chrome). Braucht er TradingView neu: Strg+T IN diesem Fenster, nie Strg+N, nie
# chrome.exe mit URL (das oeffnete am Freitag ein Fenster im zuletzt benutzten Profil = Reader-Profil).
# Erstes Finden (nichts gemerkt oder Fenster weg nach Chrome-Neustart): Kandidaten = Browser-Hauptfenster von
# chrome.exe/msedge.exe/brave.exe (Chrome_WidgetWin_1 haben auch Electron-Apps wie Claude/Slack/VS Code), ohne
# Reader-Profil (Profil-Riegel), ohne das Fenster, dessen Lage der Reader fuer seinen Feed-Tab meldet, ohne DevTools,
# Tradovate-Anmeldefenster und kleine Popups. Genau ein Kandidat mit TradingView → der; sonst genau ein Kandidat
# ueberhaupt → der; sonst NICHT raten, Lauf endet mit „Puls-Fenster unklar". Chrome starten nur, wenn gar keins
# laeuft — dann mit --profile-directory (Profil-Riegel).
# Diagnose (gemerktes Fenster, gesehene Fenster + Ausschlussgrund) einmal je Lauf an POST /puls-diagnose/<pc_id>.
# ---------------------------------------------------------------------------
PULS_BACKEND = "https://web-production-bec81.up.railway.app"
PULS_BROWSER_EXE = ("chrome.exe", "msedge.exe", "brave.exe")
_PULS_FENSTER = {"w": None, "code": "", "msg": ""}
_FENSTER_DIAG = {"gemerkt": None, "code": "", "kandidaten": [], "gesendet": ""}


def puls_fenster_wahl(kandidaten, vorn=None):
    """REIN RECHNEND (testbar): kandidaten = [{handle, aus: '' | Grund, tv: bool}] → (handle | None, code, text).
    code: 'neu' (eindeutig), 'kein_chrome' (gar kein Browser-Fenster), 'unklar' (0 oder mehrere Kandidaten).
    vorn = Handle des Vordergrund-Fensters: bei mehreren Kandidaten entscheidet es, wenn es selbst ein zulaessiger
    Kandidat ist (bei TradingView-Fenstern nur ein TradingView-Fenster) — daher „Handels-Chrome nach vorn holen"."""
    if not kandidaten:
        return None, "kein_chrome", "Es laeuft kein Chrome."
    rest = [k for k in kandidaten if not k.get("aus")]
    tv = [k for k in rest if k.get("tv")]
    if len(tv) == 1:
        return tv[0]["handle"], "neu", "einziges Handels-Fenster mit TradingView"
    if len(tv) > 1:
        if vorn is not None and any(k["handle"] == vorn for k in tv):
            return vorn, "neu", "Handels-Fenster = vorderes Chrome-Fenster mit TradingView"
        return None, "unklar", f"{len(tv)} Chrome-Fenster mit TradingView (ohne Reader)"
    if len(rest) == 1:
        return rest[0]["handle"], "neu", "einziges Chrome-Fenster (ohne Reader)"
    if len(rest) > 1 and vorn is not None and any(k["handle"] == vorn for k in rest):
        return vorn, "neu", "Handels-Fenster = vorderes Chrome-Fenster"
    if not rest:
        return None, "unklar", "nur ausgeschlossene Chrome-Fenster (Reader/Popups)"
    return None, "unklar", f"{len(rest)} Chrome-Fenster ohne TradingView"


def puls_fenster_gueltig(merk, info):
    """REIN RECHNEND (testbar): passt das gemerkte Fenster noch? info = {da, klasse, pid, exe, profil}."""
    if not isinstance(merk, dict) or not isinstance(info, dict) or not info.get("da"):
        return False
    if (info.get("klasse") or "") not in BROWSER_KLASSEN or int(info.get("pid") or -1) != int(merk.get("pid") or -2):
        return False
    if merk.get("profil") and info.get("profil") and merk["profil"] != info["profil"]:
        return False
    return True


def reader_geo_passt(rect, geo, tol=16):
    """REIN RECHNEND (testbar): liegt ein Fenster-Rechteck (l, t, r, b in Bildschirm-Pixeln) dort, wo der Reader
    seinen Feed-Tab meldet (screenX/Y, outerWidth/Height in CSS-Pixeln, dpr)? Skaliert mit dpr und mit 1."""
    try:
        l, t, r, b = [float(x) for x in rect]
        sx, sy, ow, oh = (float(geo[k]) for k in ("screenX", "screenY", "outerWidth", "outerHeight"))
        dpr = float(geo.get("dpr") or 1) or 1.0
    except (TypeError, ValueError, KeyError):
        return False
    for f in {dpr, 1.0}:
        if (abs(l - sx * f) <= tol and abs(t - sy * f) <= tol
                and abs((r - l) - ow * f) <= tol * 2 and abs((b - t) - oh * f) <= tol * 2):
            return True
    return False


def lage_ausschluss(fenster, eigen="", tabu=()):
    """REIN RECHNEND (testbar): welche Fenster schliesst die Lage-Pruefung aus? fenster = [{profil, lage}] (lage = liegt dort,
    wo der Reader seinen Feed-Tab meldet) → Menge der Indizes, die raus sind.
    Ausnahme (28.09.2026, PC von ID B: Handels-Chrome „Profile 1" und Reader-Chrome „Profile 2" beide maximiert → deckungsgleich,
    Puls sperrte sein eigenes Fenster und platzierte nichts): liegt ein Fenster eines TABU-Profils an derselben Stelle, ist der
    Feed-Tab damit erklaert — ein Fenster im EIGENEN Profil bleibt dann erlaubt. Sonst gilt die Lage wie bisher (Profil unlesbar,
    kein Tabu-Fenster dort)."""
    tabu = set(tabu or ())
    erklaert = any(f.get("lage") and f.get("profil") and f.get("profil") in tabu for f in fenster)
    raus = set()
    for i, f in enumerate(fenster):
        if not f.get("lage"):
            continue
        if erklaert and eigen and f.get("profil") == eigen:
            continue
        raus.add(i)
    return raus


def tab_neu_plan(n):
    """REIN RECHNEND (testbar): Tastenfolge fuer „TradingView-Tab schliessen und neu mit Link", ohne dass das Fenster
    zugeht. n = Tabs im Fenster. ≥ 2: aktiven TV-Tab schliessen, dann neuer Tab. 1: erst neuer (leerer) Tab, dann
    Tab 1 (= der TV-Tab) schliessen, Adresse im leeren Tab. Unbekannt → None (nichts schliessen)."""
    if not isinstance(n, int) or n < 1:
        return None
    if n >= 2:
        return ["schliessen", "neuer_tab", "adresse"]
    return ["neuer_tab", "tab_1", "schliessen", "adresse"]


def _puls_merk_pfad():
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "puls_fenster.json")


def _puls_merk_lesen():
    try:
        with open(_puls_merk_pfad(), "r", encoding="utf-8") as f:
            d = json.load(f)
        return d if isinstance(d, dict) and d.get("hwnd") else None
    except Exception:
        return None


def _puls_merk_schreiben(d):
    try:
        with open(_puls_merk_pfad() + ".tmp", "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False)
        os.replace(_puls_merk_pfad() + ".tmp", _puls_merk_pfad())
    except Exception:
        pass


def _fenster_info(hwnd):
    """{da, klasse, pid, exe, profil, titel, rect} eines Top-Level-Fensters (Windows), {} ohne Windows."""
    try:
        import ctypes
        import ctypes.wintypes as wt
        u32, k32 = ctypes.windll.user32, ctypes.windll.kernel32
        h = int(hwnd)
        if not u32.IsWindow(h):
            return {"da": False}
        kb = ctypes.create_unicode_buffer(128)
        u32.GetClassNameW(h, kb, 128)
        n = u32.GetWindowTextLengthW(h)
        tb = ctypes.create_unicode_buffer(n + 1)
        u32.GetWindowTextW(h, tb, n + 1)
        pid = wt.DWORD()
        u32.GetWindowThreadProcessId(h, ctypes.byref(pid))
        exe = ""
        hp = k32.OpenProcess(0x1000, False, pid.value)      # PROCESS_QUERY_LIMITED_INFORMATION
        if hp:
            try:
                pb = ctypes.create_unicode_buffer(520)
                ln = wt.DWORD(520)
                if k32.QueryFullProcessImageNameW(hp, 0, pb, ctypes.byref(ln)):
                    exe = os.path.basename(pb.value).lower()
            finally:
                k32.CloseHandle(hp)
        r = wt.RECT()
        u32.GetWindowRect(h, ctypes.byref(r))
        return {"da": True, "klasse": kb.value, "pid": int(pid.value), "exe": exe, "titel": tb.value,
                "profil": _fenster_profil(h), "rect": (r.left, r.top, r.right, r.bottom),
                "sichtbar": bool(u32.IsWindowVisible(h))}
    except Exception:
        return {}


def _reader_geos():
    """Fensterlagen der Feed-Tabs, die der Reader meldet (reader-server >= 0.9.5: tabs[].geo). [] ohne Reader."""
    d = _tv_http("/positions", timeout=1.0) or {}
    out = []
    for t in d.get("tabs") or []:
        if isinstance(t, dict) and isinstance(t.get("geo"), dict) and (t.get("rolle") == "feed" or t.get("login_im_feed")):
            out.append(t["geo"])
    return out


def _puls_diagnose_senden(spur=None, schritt=""):
    """Einmal je Lauf: gemerktes Fenster + gesehene Fenster mit Ausschlussgrund ans Backend (2 s, Fehler still).
    B17 (27.09.2026): mit spur/schritt IMMER senden — die Spur liegt dann schon in puls_diagnose, bevor ein riskanter
    Schritt laeuft (ueberlebt einen Absturz/ein geschlossenes Fenster)."""
    if spur is None:
        if _FENSTER_DIAG.get("gesendet") == (_FENSTER_DIAG.get("code") or "-"):
            return                     # je Lauf einmal je Ergebnis (z. B. erst 'kein_chrome', nach dem Start 'neu')
        _FENSTER_DIAG["gesendet"] = _FENSTER_DIAG.get("code") or "-"
    try:
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "pc_id.json"), "r", encoding="utf-8") as f:
            pc = (json.load(f) or {}).get("pc_id")
        if not (isinstance(pc, str) and re.fullmatch(r"pc-[a-z0-9]{4,12}", pc)):
            return
        import urllib.request
        regel = puls_profil_regel_holen()
        daten = {"modus": " ".join(sys.argv[1:2])[:20], "code": _FENSTER_DIAG.get("code"), "gemerkt": _FENSTER_DIAG.get("gemerkt"),
                 "eigen": regel.get("eigen") or "", "tabu": sorted(regel.get("tabu") or ()),
                 "profile": [{"dir": d_, "name": n_} for d_, n_ in sorted(_PROFIL_NAMEN.items())][:12],
                 "fenster": (_FENSTER_DIAG.get("kandidaten") or [])[:12]}
        if spur is not None:
            daten["schritt"] = str(schritt or "")[:20]
            daten["spur"] = " > ".join(list(spur))[-1800:]
        req = urllib.request.Request(f"{PULS_BACKEND}/puls-diagnose/{pc}", data=json.dumps(daten).encode("utf-8"),
                                     headers={"Content-Type": "application/json"})
        urllib.request.urlopen(req, timeout=2.0).read()
    except Exception:
        pass


def _puls_fenster(trail):
    """Das Handels-Fenster dieses PCs → (pywinauto-Fenster | None, code, text). code 'gemerkt' | 'neu' | 'kein_chrome' |
    'unklar'. Ein Mal je Lauf gesucht; danach nur noch geprueft, ob es noch lebt."""
    from pywinauto import Desktop
    alt = _PULS_FENSTER.get("w")
    if alt is not None:
        try:
            if _fenster_info(alt.handle).get("da"):
                return alt, _PULS_FENSTER["code"], _PULS_FENSTER["msg"]
        except Exception:
            pass
    merk = _puls_merk_lesen()
    if merk:
        info = _fenster_info(merk.get("hwnd"))
        if puls_fenster_gueltig(merk, info):
            try:
                w = Desktop(backend="uia").window(handle=int(merk["hwnd"])).wrapper_object()
                _PULS_FENSTER.update(w=w, code="gemerkt", msg="gemerktes Puls-Fenster")
                _FENSTER_DIAG.update(gemerkt=dict(merk), code="gemerkt")
                trail.append(f"Puls-Fenster (gemerkt): {(info.get('titel') or '')[:40]}")
                _puls_diagnose_senden()
                return w, "gemerkt", "gemerktes Puls-Fenster"
            except Exception:
                pass
        trail.append("gemerktes Puls-Fenster ist weg (Chrome neu gestartet?) — suche neu")
    geos = _reader_geos()
    kand, fenster = [], {}
    _FENSTER_DIAG["kandidaten"] = []
    # Lage vorab fuer ALLE Browser-Fenster (auch gesperrte): nur so sieht lage_ausschluss, ob das Reader-Profil den Feed-Tab erklaert
    alle = []
    for w in Desktop(backend="uia").windows():
        try:
            if (w.element_info.class_name or "") not in BROWSER_KLASSEN:
                continue
            info = _fenster_info(w.handle)
        except Exception:
            continue
        alle.append((w, info))
    regel = puls_profil_regel_holen()
    lage_raus = lage_ausschluss([{"profil": i_.get("profil") or "",
                                  "lage": any(reader_geo_passt(i_.get("rect") or (0, 0, 0, 0), g) for g in geos)} for _, i_ in alle],
                                regel.get("eigen") or "", regel.get("tabu") or ())
    for idx, (w, info) in enumerate(alle):
        titel = info.get("titel") or ""
        exe = info.get("exe") or ""
        l, t, r, b = info.get("rect") or (0, 0, 0, 0)
        aus = ""
        if exe and exe not in PULS_BROWSER_EXE:
            continue                                   # Electron-App (Claude, Slack, …) — gar kein Browser
        if not info.get("sichtbar", True) or not titel.strip():
            aus = "unsichtbar/ohne Titel"
        elif titel.strip().lower().startswith("devtools"):
            aus = "DevTools"
        elif TV_RX_TRADOVATE_TITEL.search(titel):
            aus = "Tradovate-Anmeldefenster"
        elif (r - l) < 400 or (b - t) < 300:
            aus = "kleines Popup"
        elif _fenster_gesperrt(w.handle):
            aus = "Reader-/Fremdprofil " + _fenster_gesperrt(w.handle)
        elif idx in lage_raus:
            aus = "Lage = Feed-Tab des Readers"
        tv = False
        if not aus:
            tv = ist_tradingview_fenster(titel, w.element_info.class_name) or tv_tab_rang(titel, "", "") > 0
            if not tv:
                try:
                    tv = _tv_tab_suchen(w, "", "", []) is not None
                except Exception:
                    tv = False
        kand.append({"handle": int(w.handle), "aus": aus, "tv": tv})
        fenster[int(w.handle)] = (w, info)
        _FENSTER_DIAG["kandidaten"].append({"titel": titel[:50], "profil": info.get("profil") or "", "exe": exe,
                                             "grund": aus or ("TradingView" if tv else "Kandidat")})
    try:
        import ctypes
        vorn = int(ctypes.windll.user32.GetForegroundWindow())
    except Exception:
        vorn = None
    h, code, text = puls_fenster_wahl(kand, vorn)
    _FENSTER_DIAG["code"] = code
    if h is None:
        trail.append(f"Puls-Fenster nicht bestimmt: {text} · gesehen: "
                     + "; ".join(f"{k['titel'][:25]}={k['grund']}" for k in _FENSTER_DIAG["kandidaten"][:6]))
        _puls_diagnose_senden()
        msg = ("Puls-Fenster unklar: " + text + " — bitte einmal das Handels-Chrome nach vorn holen "
               "(nur dort laeuft Puls) und neu starten.") if code == "unklar" else text
        return None, code, msg
    w, info = fenster[h]
    merk = {"hwnd": h, "pid": info.get("pid"), "profil": info.get("profil") or "", "titel": (info.get("titel") or "")[:60],
            "at": time.strftime("%Y-%m-%d %H:%M:%S")}
    _puls_merk_schreiben(merk)
    _PULS_FENSTER.update(w=w, code="neu", msg=text)
    _FENSTER_DIAG["gemerkt"] = merk
    trail.append(f"Puls-Fenster gemerkt ({text}): {merk['titel'][:40]}")
    _puls_diagnose_senden()
    return w, "neu", text


def _tab_anzahl(w):
    """Tabs im Fenster per UIA (0 = nicht lesbar)."""
    try:
        return len([t for t in w.descendants(control_type="TabItem") if (t.window_text() or "").strip()])
    except Exception:
        return 0


def _tv_neuer_tab(w, url, trail):
    """TradingView in einem NEUEN TAB des Puls-Fensters oeffnen (Strg+T, Adresse, Enter). Getippt wird nur, wenn das
    Puls-Fenster nachweislich vorn steht. (ok, fehlertext)"""
    try:
        from pywinauto import keyboard
        import ctypes
    except ImportError:
        return False, "pywinauto fehlt"
    try:
        if w.is_minimized():
            w.restore()
            _warte(0.2, 0.25)
        w.set_focus()
    except Exception:
        pass
    _warte(0.35, 0.3)
    try:
        if int(ctypes.windll.user32.GetForegroundWindow()) != int(w.handle):
            return False, "Puls-Fenster steht nicht im Vordergrund — kein neuer Tab."
    except Exception:
        pass
    try:
        keyboard.send_keys("^t")
        _warte(0.5, 0.3)
        keyboard.send_keys(tv_tasten_escape(url), with_spaces=True, pause=0.012)
        _warte(0.25, 0.2)
        keyboard.send_keys("{DELETE}")
        _warte(0.15, 0.15)
        keyboard.send_keys("{ENTER}")
    except Exception as e:
        return False, f"neuer Tab liess sich nicht oeffnen ({type(e).__name__})"
    trail.append("Neuer Tab im Puls-Fenster geoeffnet: " + re.sub(r"^https?://", "", str(url))[:40])   # B18: war fest „TradingView"
    return True, ""


