    while not ber:
        teile = any(x[1] and (TV_RX_TP.search(tv_name_norm(x[0])) or TV_RX_SL.search(tv_name_norm(x[0])) or TV_RX_UNITS.search(tv_name_norm(x[0])))
                    for x in roh)
        leer = 0 if teile else leer + 1
