TSX_URL = "https://topstepx.com/trade"
TSX_RX_KONTO = re.compile(r"\$\s*\d+(?:[.,]\d+)?\s*K\b.*\|\s*([A-Z0-9][A-Z0-9-]{5,})", re.I)
TSX_RX_LOGIN = re.compile(r"^(log ?in|sign ?in|connect|anmelden|verbinden|einloggen)$", re.I)
TSX_RX_SCHLIESSEN = re.compile(r"^(close|schlie(ß|ss)en|dismiss|×|✕|x)$", re.I)
TSX_RX_KEINE_POS = re.compile(r"no active position|keine aktive position", re.I)
TSX_RX_BRACKET_TEXT = re.compile(r"position bracket", re.I)
TSX_RX_MANAGE_BRACKETS = re.compile(r"manage brackets", re.I)
TSX_KOPF_LABELS = {"BAL": "balance", "MLL": "mll", "RP&L": "rpl", "UP&L": "upl"}


def tsx_geld(text):
    """REIN RECHNEND (testbar): US-Geldformat ('$11,079.66', '-$1,234.50', '($12.50)', '11079.66') → float | None.
    PARITÄT mit geld() in augen_tsx.js (Terminal 2, tsx-0.2.1, 30.09.2026): ein Minus zählt überall VOR der ersten Ziffer („$-7.00"
    ergab vorher +7.0), Klammern nur mit beiden Enden."""
    t = str(text or "").strip().replace("−", "-")
    neg = bool(re.match(r"^[^\d]*-", t)) or (t.startswith("(") and t.endswith(")"))
    m = re.search(r"\d[\d,]*(?:\.\d+)?", t)
    if not m:
        return None
    try:
        v = float(m.group(0).replace(",", ""))
    except ValueError:
        return None
    return -v if neg else v


TSX_RX_KOPF = re.compile(r"^(BAL|MLL|RP&L|UP&L)\s*:?\s*(.*)$", re.I)
TSX_RX_VORSATZ = re.compile(r"^[-−(]?\s*\$?\s*[-−]?$")      # Knoten nur aus Vorzeichen/Klammer/„$" (Teil eines zerlegten Werts)


def tsx_summary(werte):
    """REIN RECHNEND (testbar): Kopfwerte {balance, mll, rpl, upl} → summary {Label: Text} für tvBalanceAus im Frontend. Minus VOR dem
    Dollar („-$300.00"): tvGeldText erkennt ein Minus nur ganz vorn, „$-300.00" wurde dort +300 (K1-Prüfer 30.09.2026 — Express zeigt
    BAL relativ, im Verlust also negativ → falsche balance_start/-end, P&L und tv_balance; betraf auch den UIA-Weg). Zahlwerte bleiben."""
    def t(v):
        if v is None:
            return None
        v = float(v) + 0.0                                    # -0.0 → 0.0
        return f"-${abs(v):,.2f}" if v < 0 else f"${v:,.2f}"
    w = werte if isinstance(werte, dict) else {}
    return {lbl: t(w.get(k)) for lbl, k in (("Balance", "balance"), ("MLL", "mll"), ("RP&L", "rpl"), ("UP&L", "upl"))}


def tsx_kopf_werte(elemente):
    """REIN RECHNEND (testbar): Kopfzeile → {balance, mll, rpl, upl}. elemente = [(name, rect|None, typ)] in Lesereihenfolge.
    Form 1 'BAL: $11,079.66' in einem Element; Form 2 Label 'BAL:' und Wert im naechsten Element; B22 (UIA-Inventar) „BAL:" · „$" ·
    „154,504.88" als DREI Knoten. PARITÄT mit kopfAusTexten() in augen_tsx.js (Terminal 2, 30.09.2026): bei negativen Werten noch
    feiner — „RP&L:" · „-" · „$" · „50.00" oder „(" · „$" · „12.50" · „)": bis zu drei Vorsatz-Knoten (auch ein Rest im Label-Knoten
    wie „RP&L: -") vor die Zahl, eine schließende Klammer als eigener Knoten wird angehängt, das nächste Label nie als Wert."""
    out = {v: None for v in TSX_KOPF_LABELS.values()}
    namen = [str(e[0] or "").strip() for e in (elemente or ())]
    for i, n in enumerate(namen):
        m = TSX_RX_KOPF.match(n)
        if not m:
            continue
        key = TSX_KOPF_LABELS[m.group(1).upper()]
        if out[key] is not None:
            continue
        text = m.group(2) or ""
        wert = tsx_geld(text) if text else None
        if wert is None and i + 1 < len(namen):
            vor, j = (text if TSX_RX_VORSATZ.match(text) else ""), i + 1
            while j < len(namen) - 1 and j - i <= 3 and TSX_RX_VORSATZ.match(namen[j]):
                vor += namen[j]
                j += 1
            text = vor if TSX_RX_KOPF.match(namen[j]) else vor + namen[j]
            if text.startswith("(") and not text.endswith(")") and j + 1 < len(namen) and namen[j + 1] == ")":
                text += ")"
            wert = tsx_geld(text)
        out[key] = wert
    return out


def tsx_konto_aus_text(text):
    """REIN RECHNEND (testbar): '$150K EXPRESS | EXPRESS-V2-000000-10000001' → 'EXPRESS-V2-000000-10000001' | ''."""
    m = TSX_RX_KONTO.search(str(text or ""))
    return m.group(1).upper() if m else ""


TSX_RX_AUSLOESER = re.compile(r"\$\s*\d+(?:[.,]\d+)?\s*K\b[^|]*\|\s*([A-Z0-9][A-Z0-9-]*)\s*(…|\.\.\.)?", re.I)


def tsx_konto_sichtbar(text):
    """REIN RECHNEND (testbar, B18): Konto-Auslöser oben links → (sichtbare Kennung, abgekürzt?). TopstepX kürzt die Kennung im
    Auslöser („$150K EXPRESS | EXPRESS-…"); die volle ID steht erst in der aufgeklappten Liste. ('', False) = kein Auslöser."""
    m = TSX_RX_AUSLOESER.search(str(text or ""))
    if not m:
        return "", False
    return m.group(1).upper().rstrip("-") if m.group(2) else m.group(1).upper(), bool(m.group(2))


TSX_RX_OHNE_ID = re.compile(r"^\s*(\$\s*\d+(?:[.,]\d+)?\s*K\b[^|$]*?)\s*\|?\s*(…|\.\.\.)?\s*$", re.I)


def tsx_label(text):
    """REIN RECHNEND (testbar, B22): Produkt-Label vor dem '|' („$150K TRADING COMBINE"), normalisiert; '' ohne Label."""
    # B23: ohne Anker am Textanfang — Listeneinträge tragen vorne womöglich Haken/Symbole oder die Kennung
    m = re.search(r"(\$\s*\d+(?:[.,]\d+)?\s*K\b[^|$]*)", str(text or ""), re.I)
    return re.sub(r"\s+", " ", m.group(1)).strip().upper() if m else ""


def tsx_eintrag_label(eintrag, roh):
    """REIN RECHNEND (testbar, B23): Label eines Listeneintrags — aus seinem Text, sonst aus Nachbarknoten derselben Listenzeile
    (vertikal ±25 px, waagerecht überlappend oder links davon): TopstepX setzt Label und Kennung als getrennte Knoten."""
    lab = tsx_label(eintrag[0] if eintrag else "")
    if lab or not eintrag or not eintrag[1]:
        return lab
    l, t, r, b = eintrag[1]
    for tt, rr in tsx_zeilen(roh):
        if tsx_label(tt) and rr[1] >= t - 25 and rr[3] <= b + 25 and rr[0] <= r:
            return tsx_label(tt)
    return ""


def tsx_markiert_urteil(markiert_texte, ext_id):
    """REIN RECHNEND (testbar, B23): welcher Listeneintrag ist als ausgewählt markiert? 'ja' (die Ziel-ID), 'nein' (ein anderer mit
    Kennung), 'unbekannt' (nichts Markiertes mit Kennung lesbar)."""
    ids = [_nur_alnum(m.group(0)) for t in (markiert_texte or ())
           for m in [re.search(r"[A-Z0-9]{3,}(?:-[A-Z0-9]+){2,}", str(t or "").upper())] if m]
    if not ids:
        return "unbekannt"
    return "ja" if _nur_alnum(ext_id) in ids else "nein"


def tsx_ist_ausloeser_text(text):
    """REIN RECHNEND (testbar, B22): Konto-Auslöser — mit Kennung („… | EXPRESS-V2-…") ODER ohne (TopstepX lässt die Kennung
    bei langen Namen ganz weg: nur „$150K TRADING COMBINE" + „|", Inventar ID A 11:24 UTC)."""
    t = str(text or "")
    return bool(tsx_konto_sichtbar(t)[0]) or bool(TSX_RX_OHNE_ID.match(t))


def tsx_konto_steht(text, ext_id):
    """REIN RECHNEND (testbar, B18): 'ja' (volle Kennung = External ID), 'vielleicht' (abgekürzt, Präfix passt — erst die Liste
    beweist es), 'nein'."""
    k, kurz = tsx_konto_sichtbar(text)
    if not k:
        return "unbekannt" if TSX_RX_OHNE_ID.match(str(text or "")) else "nein"
    if not kurz:
        return "ja" if _nur_alnum(k) == _nur_alnum(ext_id) else "nein"
    return "vielleicht" if len(_nur_alnum(k)) >= 4 and _nur_alnum(ext_id).startswith(_nur_alnum(k)) else "nein"


def tsx_wechsel_urteil(ausloeser_text, ext_id, liste_texte, bal_vorher, bal_jetzt, ziel_label=""):
    """REIN RECHNEND (testbar, B21, 27.09.2026 — ID A: TopstepX HATTE gewechselt, Puls meldete trotzdem Fehler, weil er
    zusätzlich „Liste zu" verlangte und unterhalb des Auslösers weiter Kontozeilen stehen blieben). Bestätigt ist der Wechsel:
    - Auslöser trägt die VOLLE Ziel-ID ('ja') — Regelfall, per UIA steht die volle ID auch bei optisch gekürzter Anzeige;
    - oder Auslöser abgekürzt mit passendem Präfix ('vielleicht'), der Präfix ist in der Liste EINDEUTIG (ID A hat zwei
      „$150K TRADING COMBINE") UND BAL hat sich gegenüber vorher geändert.
    -> (True|False, grund)"""
    stand = tsx_konto_steht(ausloeser_text, ext_id)
    if stand == "ja":
        return True, "Auslöser zeigt die Ziel-ID"
    if stand == "unbekannt":
        # B22: Auslöser ohne Kennung — Label muss dem Ziel-Eintrag entsprechen; bewiesen durch geänderte BAL oder ein in der
        # Liste EINDEUTIGES Label (die zwei „$150K TRADING COMBINE" von ID A → nur über die BAL)
        ziel = [t for t in liste_texte or () if _nur_alnum(tsx_konto_aus_text(t)) == _nur_alnum(ext_id)]
        z_label = (tsx_label(ziel[0]) if ziel else "") or str(ziel_label or "").strip().upper()
        if not z_label or tsx_label(ausloeser_text) != z_label:
            return False, f"Auslöser-Label '{tsx_label(ausloeser_text)}' ≠ Ziel '{z_label}'"
        if bal_vorher is not None and bal_jetzt is not None and abs(bal_jetzt - bal_vorher) >= 0.005:
            return True, "Auslöser ohne Kennung, Label passt und BAL geändert"
        if sum(1 for t in liste_texte or () if tsx_label(t) == z_label) == 1 and any(tsx_label(t) for t in liste_texte or ()):
            return True, "Auslöser ohne Kennung, Label in der Liste eindeutig"
        return False, "Auslöser ohne Kennung, Label doppelt und BAL unverändert — Wechsel nicht beweisbar"
    if stand == "vielleicht":
        k, _kurz = tsx_konto_sichtbar(ausloeser_text)
        gleich = [t for t in liste_texte or () if _nur_alnum(tsx_konto_aus_text(t)).startswith(_nur_alnum(k))]
        if len(gleich) != 1:
            return False, f"Auslöser abgekürzt, Präfix {len(gleich)}× in der Liste — nicht eindeutig"
        if bal_vorher is None or bal_jetzt is None or abs(bal_jetzt - bal_vorher) < 0.005:
            return False, "Auslöser abgekürzt, BAL unverändert — Wechsel nicht bewiesen"
        return True, "Auslöser abgekürzt, Präfix eindeutig und BAL geändert"
    return False, f"Auslöser zeigt ein anderes Konto ('{str(ausloeser_text or '')[:50]}')"


def tsx_konto_treffer(texte, ext_id):
    """REIN RECHNEND (testbar): Dropdown-Eintraege (Texte) → (Index | None, grund). Genau EIN Eintrag, dessen Kontokennung
    die External ID exakt ist; „(Ineligible)" nie."""
    ziel = _nur_alnum(ext_id)
    if len(ziel) < 5:
        return None, "External ID fehlt"
    treffer, ineligible = [], 0
    for i, t in enumerate(texte or ()):
        k = tsx_konto_aus_text(t)
        if not k or _nur_alnum(k) != ziel:
            continue
        if "ineligible" in str(t).lower():
            ineligible += 1
            continue
        treffer.append(i)
    if len(treffer) == 1:
        return treffer[0], ""
    if not treffer:
        return None, ("Konto steht nur als (Ineligible) in der Liste" if ineligible else "Konto nicht in der Liste")
    return None, f"Konto {len(treffer)}× in der Liste — nicht eindeutig"


def tsx_contract_wahl(texte, wurzel):
    """REIN RECHNEND (testbar): Vorschlagsliste ('MNQZ26 · Micro Nasdaq (Dec 2026)') → Index des Eintrags, dessen CODE genau
    die Wurzel + Monatsbuchstabe + Jahr ist (MNQ ≠ NQ, Roll-Monat nie hart). Genau einer, sonst None."""
    w = str(wurzel or "").upper()
    rx = re.compile(rf"^{re.escape(w)}[FGHJKMNQUVXZ]\d{{1,2}}\b")
    t_ = [i for i, t in enumerate(texte or ()) if rx.match(str(t or "").strip().upper())]
    return t_[0] if len(t_) == 1 else None


def tsx_bracket_werte(tp_usd, sl_usd):
    """REIN RECHNEND (testbar, B16-Korrektur 27.09.2026, Finn): Werte für den Dialog „Position Brackets".
    Profit (~$) = TP immer (Pflicht, > 0). Risk (~$) = SL NUR, wenn der Plan einen SL hat (master_sl > 0) — sonst wird das
    Feld GELEERT (''), damit kein alter Wert aus dem letzten Lauf stehen bleibt (Winning Days UND meist auch normale Trades).
    -> ({'profit': '…', 'risk': '…' | ''}, None) oder (None, fehler)"""
    def zahl(v):
        try:
            f = float(v)
            return f if f == f else None
        except (TypeError, ValueError):
            return None
    tp, sl = zahl(tp_usd), zahl(sl_usd)
    if tp is None or tp <= 0:
        return None, "TP in $ fehlt — ohne Profit-Bracket wird nicht gehandelt"
    fmt = lambda x: (f"{x:.2f}".rstrip("0").rstrip(".") if x != int(x) else str(int(x)))
    return {"profit": fmt(tp), "risk": fmt(sl) if (sl is not None and sl > 0) else ""}, None


def tsx_knopf_passt(name, richtung, menge):
    """REIN RECHNEND (testbar): Order-Knopf traegt Richtung UND Menge: 'BUY +2 @ MARKET' / 'SELL -2 @ MARKET'."""
    m = re.match(r"^\s*(BUY|SELL)\s*([+-]?)\s*(\d+)\s*@\s*MARKET\s*$", str(name or ""), re.I)
    if not m:
        return False
    try:
        n = int(menge)
    except (TypeError, ValueError):
        return False
    r = m.group(1).lower()
    vorz_ok = (m.group(2) in ("+", "")) if r == "buy" else (m.group(2) in ("-", ""))
    return r == str(richtung or "").lower() and int(m.group(3)) == n and vorz_ok


def tsx_position_zustand(namen):
    """REIN RECHNEND (testbar): 'keine' bei „No Active Position", sonst None (unbekannt — Etappe 2 liest die Position)."""
    return "keine" if any(TSX_RX_KEINE_POS.search(str(n or "")) for n in (namen or ())) else None


def _tsx_roh(w, typen=("Button", "Text", "Edit", "ComboBox", "ListItem", "MenuItem", "DataItem", "TabItem", "Hyperlink")):
    """Alle benannten Elemente MIT Rechteck (Inventar/Suche) — Muster '.+' holt fuer jedes Element das Rechteck."""
    return _tv_uia_roh(w, typen, 6000, muster=(re.compile(r".+"),))


def tsx_inventar_kurz(roh, fenster=None, max_n=260):
    """REIN RECHNEND (testbar): Inventar kompakt [name[:60], typ, [l,t,r,b]] — nur sichtbare, im Fenster, ohne Dubletten."""
    out, gesehen = [], set()
    for e in roh or ():
        try:
            n, r, typ = str(e[0] or "").strip(), e[1], (e[2] if len(e) > 2 else "")
            l, t, rr, b = (int(v) for v in r)
        except (TypeError, ValueError, IndexError):
            continue
        if not n or rr - l < 2 or b - t < 2:
            continue
        if fenster and not (fenster[0] <= (l + rr) // 2 <= fenster[2] and fenster[1] <= (t + b) // 2 <= fenster[3]):
            continue
        k = (n[:60], typ, l // 4, t // 4)
        if k in gesehen:
            continue
        gesehen.add(k)
        out.append([n[:60], typ, [l, t, rr, b]])
        if len(out) >= max_n:
            break
    return out


TSX_RX_ADRESSLEISTE = re.compile(r"address and search bar|adress- und suchleiste|adressleiste|address bar", re.I)


_EDIT_NAMEN = []


def _chrome_url(w):
    """Adresse des AKTIVEN Tabs aus Chromes Adressleiste (UIA-Edit 'Address and search bar'). '' = nicht lesbar.
    B20: ohne Tiefengrenze (depth=12 fand sie bei ID A nicht); gesehene Edit-Namen landen in _EDIT_NAMEN (Inventar)."""
    try:
        for e in w.descendants(control_type="Edit"):
            try:
                if len(_EDIT_NAMEN) < 8:
                    _EDIT_NAMEN.append((e.window_text() or "")[:50])
            except Exception:
                pass
            try:
                n_ = e.window_text() or ""
                if re.match(r"^(https?://)?[\w-]+(\.[\w-]+)+(/|$)", n_.strip()):
                    return n_.strip()          # B22 (ID A): das Edit HEISST die Adresse („topstepx.com/trade")
                if TSX_RX_ADRESSLEISTE.search(n_):
                    try:
                        return str(e.get_value() or "")
                    except Exception:
                        return str(e.iface_value.CurrentValue or "")
            except Exception:
                continue
    except Exception:
        pass
    return ""


def ist_topstepx_url(url):
    """REIN RECHNEND (testbar): Adresse gehört zu TopstepX (topstepx.com, auch ohne https://)."""
    return bool(re.search(r"(^|[/.])topstepx\.com(/|$)", str(url or "").strip().lower()))


def _tsx_tab_holen(trail, warten_s=25.0):
    """TopstepX-Tab im Puls-Fenster nach vorn, sonst Strg+T + topstepx.com/trade (Fenster-Treue). (fenster, fehler)"""
    vorher = _vordergrund_titel()                        # B35: Heimweg nur, wenn der Lauf den Vordergrund wechselt
    pw, code, msg = _puls_fenster(trail)
    if pw is None:
        return None, msg
    _puls_vorn_merken(pw, vorher)
    try:
        if ist_topstepx_titel(pw.window_text()) or ist_topstepx_url(_chrome_url(pw)):
            pw.set_focus()
            trail.append(f"TopstepX war schon der aktive Tab ({(pw.window_text() or '')[:40]})")
            return pw, ""
    except Exception:
        pass
    try:
        tabs = pw.descendants(control_type="TabItem")
    except Exception:
        tabs = []
    kand = [t for t in tabs if ist_topstepx_titel(t.window_text())]
    try:   # B20: warum „neuer Tab"? — alle Tabs mit Erkennung in die Spur
        trail.append("Tabs: " + " | ".join(f"{(t.window_text() or '')[:28]}={'TSX' if ist_topstepx_titel(t.window_text()) else 'TV' if tv_tab_rang(t.window_text() or '', '', '') > 0 else '-'}"
                                           for t in tabs[:10]) if tabs else "Tabs: keine gelesen")
    except Exception:
        pass
    if len(kand) >= 1:
        try:
            pw.set_focus()
            _warte(0.2, 0.2)
            r = kand[0].rectangle()
            x, y = int((r.left + r.right) / 2), int((r.top + r.bottom) / 2)
            _maus_fahren(x, y)
            _klick_absolut(x, y)
            _warte(0.4, 0.3)
            trail.append(f"TopstepX-Tab angeklickt ({(kand[0].window_text() or '')[:40]})")
            return pw, ""
        except Exception as e:
            trail.append(f"TopstepX-Tab-Klick fehlgeschlagen ({type(e).__name__})")
    ok, f = _tv_neuer_tab(pw, TSX_URL, trail)
    if not ok:
        return None, f
    ende = time.time() + warten_s
    while time.time() < ende:
        _warte(0.5, 0.3)
        try:
            if ist_topstepx_titel(pw.window_text()) or ist_topstepx_url(_chrome_url(pw)):
                trail.append("TopstepX-Tab offen (neuer Tab) — warte auf die Seite")
                return pw, ""
        except Exception:
            pass
    return None, f"TopstepX-Tab nach {int(warten_s)} s nicht geladen (Titel ohne 'TopstepX')."


def seiten_filter(roh, seite):
    """REIN RECHNEND (testbar, B17): nur Elemente, deren Mitte INNERHALB der Webseite liegt (seite = l,t,r,b des Chrome-
    Dokuments). Chromes eigene Leisten — Tab-X „Schließen", Fenster-X, Adressleiste — liegen darüber und fallen raus.
    Ohne Seitenbereich: leere Liste (lieber nichts klicken als Chrome selbst)."""
    if not seite:
        return []
    l, t, r, b = seite
    out = []
    for e in roh or ():
        try:
            el, et, er, eb = (int(v) for v in e[1])
        except (TypeError, ValueError, IndexError):
            continue
        mx, my = (el + er) // 2, (et + eb) // 2
        if l <= mx <= r and t <= my <= b:
            out.append(e)
    return out


def strg_w_erlaubt(titel_vorn, ziel, tab_anzahl):
    """REIN RECHNEND (testbar, B17 — allgemeine Regel für ALLE Puls-Modi): Strg+W nur, wenn der Titel des Vordergrund-Fensters
    DIREKT vor dem Tastendruck nachweislich der Ziel-Tab ist ('tv' = TradingView, 'tsx' = TopstepX), er NIE Prophos ist und
    das Fenster danach noch mindestens einen Tab hat (tab_anzahl ≥ 2)."""
    t = str(titel_vorn or "")
    if not t.strip() or t.strip().lower().startswith("prophos") or " prophos" in t.lower()[:40]:
        return False
    try:
        if int(tab_anzahl) < 2:
            return False
    except (TypeError, ValueError):
        return False
    if ziel == "tsx":
        return ist_topstepx_titel(t)
    if ziel == "tv":
        return ist_tradingview_fenster(t, "Chrome_WidgetWin_1") or tv_tab_rang(t, "", "") > 0
    return False


_TSX_SEITE = {}


def _tsx_seite(w):
    """Rechteck der Webseite (Chrome-Dokument) im Fenster — das größte sichtbare 'Document'-Element. None = unbekannt.
    B18: einmal je Lauf und Fenster (der Baum-Durchgang ist auf der TopstepX-Seite teuer)."""
    try:
        k = int(w.handle)
    except Exception:
        k = id(w)
    if k in _TSX_SEITE:
        return _TSX_SEITE[k]
    _TSX_SEITE[k] = r_ = _tsx_seite_suchen(w)
    return r_


def _tsx_seite_suchen(w):
    """B22: das Document des AKTIVEN Tabs — sein Name ist der Seitentitel = Fenstertitel ohne „ - Google Chrome"; nur
    sichtbare. Rückfall: das größte sichtbare Document."""
    try:
        docs = w.descendants(control_type="Document", depth=8)
    except Exception:
        return None
    try:
        titel = re.sub(r"\s+[-–]\s+(Google Chrome|Microsoft Edge|Brave).*$", "", w.window_text() or "").strip()
    except Exception:
        titel = ""
    best, passend = None, None
    for d in docs:
        try:
            if hasattr(d, "is_visible") and not d.is_visible():
                continue
            r = d.rectangle()
            if not (r.right - r.left > 300 and r.bottom - r.top > 200):
                continue
            rr = (r.left, r.top, r.right, r.bottom)
            fl = (r.right - r.left) * (r.bottom - r.top)
            if titel and (d.window_text() or "").strip() == titel:
                passend = rr
            if best is None or fl > best[0]:
                best = (fl, rr)
        except Exception:
            continue
    return passend or (best[1] if best else None)


def _tsx_seite_roh(w, typen=None):
    """_tsx_roh, aber NUR innerhalb der Webseite (B17: nie Chromes eigene Knöpfe)."""
    return seiten_filter(_tsx_roh(w, typen) if typen else _tsx_roh(w), _tsx_seite(w))


def tsx_zeilen(roh, tol=8, luecke=40):
    return [(t, r) for t, r, _e in tsx_zeilen_voll(roh, tol, luecke)]


def tsx_zeilen_voll(roh, tol=8, luecke=40):
    """REIN RECHNEND (testbar, B20): Elemente zu Text-Stücken zusammenfügen — gleiche Zeile (Mitte ±tol px), von links nach
    rechts, neues Stück bei einer Lücke > luecke px. TopstepX liefert „$150K EXPRESS", „|" und „EXPRESS-…" womöglich als
    GETRENNTE Knoten; kein einzelnes trägt dann das ganze Muster. -> [(text, (l,t,r,b))] (Rechteck = Vereinigung des Stücks)"""
    els = []
    for e in roh or ():
        try:
            l, t, r, b = (int(v) for v in e[1])
        except (TypeError, ValueError, IndexError):
            continue
        n = str(e[0] or "").strip()
        if n and r - l >= 2 and b - t >= 2 and r - l <= 600:      # B24: breite Container gehören in kein Stück
            els.append((n, (l, t, r, b)))
    els.sort(key=lambda x: ((x[1][1] + x[1][3]) // 2, x[1][0]))
    zeilen = []
    for n, r in els:
        cy = (r[1] + r[3]) // 2
        if zeilen and abs(zeilen[-1]["cy"] - cy) <= tol:
            zeilen[-1]["els"].append((n, r))
        else:
            zeilen.append({"cy": cy, "els": [(n, r)]})
    out = []
    for z in zeilen:
        stueck = None
        for n, r in sorted(z["els"], key=lambda x: x[1][0]):
            if stueck and r[0] - stueck["r"][2] <= luecke:
                if n not in stueck["t"].split(" | ") and n not in stueck["t"]:
                    stueck["t"] = stueck["t"] + " " + n
                stueck["r"] = (min(stueck["r"][0], r[0]), min(stueck["r"][1], r[1]), max(stueck["r"][2], r[2]), max(stueck["r"][3], r[3]))
                if not stueck["label"] and re.search(r"\$\s*\d+(?:[.,]\d+)?\s*K\b", n, re.I):
                    stueck["erst"], stueck["label"] = r, True
            else:
                if stueck:
                    out.append((stueck["t"], stueck["r"], stueck["erst"]))
                # erst = Rechteck des Label-Knotens („$150K …") bzw. des ersten Knotens — Klickpunkt (B24)
                stueck = {"t": n, "r": r, "erst": r, "label": bool(re.search(r"\$\s*\d+(?:[.,]\d+)?\s*K\b", n, re.I))}
        if stueck:
            out.append((stueck["t"], stueck["r"], stueck["erst"]))
    return out


def tsx_ausloeser_waehlen(roh):
    """REIN RECHNEND (testbar, B20): Konto-Auslöser — erst ein einzelnes Element mit dem ganzen Muster, sonst ein
    zusammengefügtes Stück (tsx_zeilen). Oberstes zuerst. -> (text, rect, typ) | None"""
    # B22: IMMER der oberste Kandidat — Einzel-Element mit Kennung ODER zusammengefügtes Stück. Vorher gingen Einzel-Elemente
    # vor: blieb die Liste nach dem Klick im Baum, galt ein Listeneintrag (volle ID) als „Auslöser" → falsche Bestätigung.
    kand = [(str(e[0]), tuple(e[1]), e[2] if len(e) > 2 else "", 0, tuple(e[1])) for e in roh or ()
            if e[1] and tsx_konto_sichtbar(e[0])[0]]
    kand += [(t, r, "Zeile", 1, erst) for t, r, erst in tsx_zeilen_voll(roh) if tsx_ist_ausloeser_text(t)]
    if not kand:
        return None
    t, r, typ, _v, erst = sorted(kand, key=lambda x: (x[1][1], x[3], x[1][0]))[0]
    # B24 (27.09.2026, ID A): NIE in die Mitte eines zusammengefügten Stücks klicken — mit ID im Auslöser reichte es bis x≈560,
    # die Mitte (477) lag neben dem Knopf → „Liste: 0 Einträge". Klick-Rechteck: kleinster Button/ComboBox, der den ersten
    # Knoten (Label) umschließt; sonst der erste Knoten selbst.
    return (t, tsx_klick_rechteck(roh, erst), typ)


def tsx_klick_rechteck(roh, erst):
    """REIN RECHNEND (testbar, B24): kleinstes Button/ComboBox-Rechteck, das die Mitte von 'erst' enthält (Breite < 700 px);
    sonst 'erst'."""
    try:
        mx, my = (erst[0] + erst[2]) // 2, (erst[1] + erst[3]) // 2
    except (TypeError, IndexError):
        return erst
    best = None
    for e in roh or ():
        try:
            if (e[2] if len(e) > 2 else "") not in ("Button", "ComboBox"):
                continue
            l, t, r, b = (int(v) for v in e[1])
        except (TypeError, ValueError, IndexError):
            continue
        if l <= mx <= r and t <= my <= b and (r - l) < 700 and (best is None or (r - l) * (b - t) < best[0]):
            best = ((r - l) * (b - t), (l, t, r, b))
    return best[1] if best else tuple(erst)


def tsx_eintraege_waehlen(roh, unter_y):
    """REIN RECHNEND (testbar, B20): Dropdown-Einträge unterhalb des Auslösers — einzeln oder als zusammengefügte Stücke."""
    einzeln = [(str(e[0]), e[1], e[2] if len(e) > 2 else "") for e in roh or () if e[1] and tsx_konto_aus_text(e[0]) and e[1][1] > unter_y]
    if einzeln:
        return einzeln
    return [(t, r, "Zeile") for t, r in tsx_zeilen(roh) if tsx_konto_aus_text(t) and r[1] > unter_y]


def _tsx_ausloeser(w):
    return tsx_ausloeser_waehlen(_tsx_seite_roh(w, ("Button", "Text", "ComboBox", "Hyperlink", "Group", "Custom")))


def _tsx_warte_seite(w, trail, sek=20.0, login=None):
    """B19: nach Tab-Öffnen/-Wechsel rendert TopstepX erst nach einigen Sekunden — warten, bis der Konto-Auslöser da ist
    (Obergrenze sek). -> Auslöser-Element | None
    B27: login (dict je Lauf) — steht die Login-Seite im Weg, EIN Klick auf „PLATFORM LOGIN" (nur bei vorausgefüllten
    Feldern), danach bis 20 s auf /trade warten; login['fehler'] = (code, msg) → Aufrufer beendet den Lauf."""
    login = {} if login is None else login
    ende = time.time() + sek
    while True:
        _TSX_SEITE.clear()                    # Seitenbereich neu (Tab kann gerade erst gezeichnet sein)
        ke = _tsx_ausloeser(w)
        if not ke and _tsx_login_versuch(w, trail, login):
            if login.get("fehler"):
                trail.append("ENDE " + login["fehler"][0] + ": " + login["fehler"][1])
                return None
            if login.get("geklickt") and not login.get("verlaengert"):
                login["verlaengert"] = True
                ende = max(ende, login["geklickt"] + 20.0)
        if ke or time.time() >= ende:
            if not ke and login.get("geklickt") and _tsx_login_versuch(w, trail, login):
                # nach dem einen Klick immer noch Login-Seite (ohne Fehlertext) — kein zweiter Klick, ehrliches Ende
                login.setdefault("fehler", ("login", "Login geklickt, aber TopstepX steht nach 20 s noch auf der Login-Seite "
                                                     "— bitte einmal von Hand anmelden."))
                trail.append("ENDE " + login["fehler"][0] + ": " + login["fehler"][1])
                return None
            trail.append(f"Seite bereit ({(ke[0] or '')[:40]})" if ke else f"Seite nach {int(sek)} s ohne Konto-Auslöser")
            return ke
        _warte(0.8, 0.4)


def _tsx_wachhund(res, trail, sek=100.0):
    """B19: hängt ein UIA-Aufruf ohne eigene Zeitgrenze, beendet der Wachhund den Lauf nach sek ehrlich (JSON + Spur in
    puls_diagnose) — das Panel bekommt eine Antwort statt eines Timeouts, der PC-Tab kann das Signal abschließen."""
    import threading

    def aus():
        trail.append(f"Wachhund: nach {int(sek)} s abgebrochen (UIA-Aufruf hing, Schritt {res.get('schritt')})")
        res.update(ok=False, code="haenger", msg=f"TopstepX-Lauf hing nach {int(sek)} s (Schritt {res.get('schritt')}) — abgebrochen.")
        try:
            _puls_diagnose_senden(trail, "tsx_haenger")
        except Exception:
            pass
        try:
            _tsx_ausgabe(res, trail)
            sys.stdout.flush()
        finally:
            os._exit(0)
    t = threading.Timer(sek, aus)
    t.daemon = True
    t.start()
    return t


def _puls_inventar_senden(res, trail):
    """B20: volles TopstepX-Inventar an POST /puls-inventar/<pc_id> (Tabelle puls_inventar) — 6 s, Fehler still."""
    try:
        with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "pc_id.json"), "r", encoding="utf-8") as f:
            pc = (json.load(f) or {}).get("pc_id")
        if not (isinstance(pc, str) and re.fullmatch(r"pc-[a-z0-9]{4,12}", pc)):
            return
        import urllib.request
        daten = dict(res)
        daten["trail"] = " > ".join(list(trail))[-3000:]
        req = urllib.request.Request(f"{PULS_BACKEND}/puls-inventar/{pc}", data=json.dumps(daten, ensure_ascii=False).encode("utf-8"),
                                     headers={"Content-Type": "application/json"})
        urllib.request.urlopen(req, timeout=6.0).read()
    except Exception:
        pass


def _tsx_markiert(w):
    """B23: Texte der als ausgewählt markierten Listeneinträge in der Webseite — UIA SelectionItem.IsSelected, sonst Legacy-
    Zustand STATE_SYSTEM_SELECTED (0x2). [] = nichts lesbar (TopstepX markiert womöglich nur farbig)."""
    seite = _tsx_seite(w)
    out = []
    for typ in ("ListItem", "MenuItem", "RadioButton"):      # kein 'Custom' — der Baumgang wäre auf TopstepX teuer
        try:
            els = w.descendants(control_type=typ)
        except Exception:
            continue
        for e in els[:200]:
            try:
                r = e.rectangle()
                if seite and not (seite[0] <= (r.left + r.right) // 2 <= seite[2] and seite[1] <= (r.top + r.bottom) // 2 <= seite[3]):
                    continue
                sel = None
                try:
                    sel = bool(e.iface_selection_item.CurrentIsSelected)
                except Exception:
                    try:
                        sel = bool(int(e.legacy_properties().get("State") or 0) & 0x2)
                    except Exception:
                        sel = None
                if sel:
                    t = (e.window_text() or "").strip()
                    if not t:
                        try:
                            t = " ".join((c.window_text() or "").strip() for c in e.descendants()[:12])
                        except Exception:
                            t = ""
                    out.append(t[:150])
            except Exception:
                continue
    return out[:6]


def _tsx_felder(w):
    """B26 (Inventar v2, 27.09.2026): Eingabefelder und Kästchen in der Seite — AUCH UNBENANNTE — mit Wert und Zustand:
    [(name, (l,t,r,b), typ, wert, toggle)] für Edit/CheckBox/Spinner/ComboBox. wert = ValuePattern-Wert, toggle = 0 aus / 1 an /
    2 unbestimmt / None. Grundlage für das Mengenfeld „# of Contracts" und den Haken „Automatically apply …"."""
    try:
        from pywinauto.uia_defines import IUIA
        u = IUIA()
        dll = u.UIA_dll
        anfrage = u.iuia.CreateCacheRequest()
        wert_id, toggle_id, pw_id, an_id = 30045, 30086, 30019, 30010   # Value, ToggleState, IsPassword (B27), IsEnabled (B36)
        for pid in (dll.UIA_NamePropertyId, dll.UIA_BoundingRectanglePropertyId, dll.UIA_IsOffscreenPropertyId,
                    dll.UIA_ControlTypePropertyId, wert_id, toggle_id, pw_id, an_id):
            anfrage.AddProperty(pid)
        bed = None
        for t in ("Edit", "CheckBox", "Spinner", "ComboBox"):
            c = u.iuia.CreatePropertyCondition(dll.UIA_ControlTypePropertyId, _UIA_TYPID[t])
            bed = c if bed is None else u.iuia.CreateOrCondition(bed, c)
        feld = w.element_info.element.FindAllBuildCache(u.tree_scope["descendants"], bed, anfrage)
        name_von = {v: k for k, v in _UIA_TYPID.items()}
        seite = _tsx_seite(w)
        out = []
        for i in range(min(feld.Length, 400)):
            e = feld.GetElement(i)
            try:
                if e.CachedIsOffscreen:
                    continue
                r = e.CachedBoundingRectangle
                rr = (r.left, r.top, r.right, r.bottom)
                if seite and not seiten_filter([("x", rr)], seite):
                    continue
                try:
                    wert = str(e.GetCachedPropertyValue(wert_id) or "")[:60]
                except Exception:
                    wert = ""
                try:
                    tg = e.GetCachedPropertyValue(toggle_id)
                    tg = int(tg) if isinstance(tg, int) else None
                except Exception:
                    tg = None
                try:
                    pw = bool(e.GetCachedPropertyValue(pw_id))
                except Exception:
                    pw = False
                if pw:
                    wert = "•" * len(wert)             # B27: Passwort nie im Klartext — nur „gefüllt ja/nein" zählt
                try:
                    an = e.GetCachedPropertyValue(an_id)
                    an = bool(an) if isinstance(an, (bool, int)) else None
                except Exception:
                    an = None
                # Index 6 = bearbeitbar (B36, 30.09.2026): False = in TopstepX gesperrt, None = unbekannt
                out.append((str(e.CachedName or "").strip()[:60], rr, name_von.get(e.CachedControlType, ""), wert, tg, pw, an))
            except Exception:
                continue
        return out
    except Exception:
        return []


# ═══════════════════════════════════════════════════════════════════════════
# TOPSTEPX-LOGIN-SEITE (B27, 27.09.2026, Finn mit Screenshot bei ID A): beim ↻/Lesen landet TopstepX manchmal auf
# topstepx.com/login — Username/Password von Chrome vorausgefüllt, gelber Knopf „PLATFORM LOGIN". Finn: „Da müsste man nochmal
# auf Login drücken … die Daten müssten immer schon automatisch ausgefüllt sein." Puls drückt deshalb NUR den Knopf, wenn
# beide Felder schon einen Wert haben — er tippt, liest oder speichert nie Zugangsdaten, höchstens EIN Klick je Lauf.
# ═══════════════════════════════════════════════════════════════════════════
TSX_RX_PLATFORM_LOGIN = re.compile(r"^\s*(platform\s+)?log\s?in\s*$", re.I)
TSX_RX_USER_FELD = re.compile(r"user|e-?mail|benutzer|login", re.I)
TSX_RX_PW_FELD = re.compile(r"pass|kennwort", re.I)
TSX_RX_LOGIN_FEHLER = re.compile(r"invalid|incorrect|wrong|failed|error|not\s+found|locked|required|erforderlich|ungültig|falsch|fehl", re.I)


def tsx_ist_zugangsfeld(f):
    """REIN RECHNEND (testbar): Feld trägt womöglich Zugangsdaten (Passwort, Username/Mail, „@" im Wert)."""
    try:
        return bool((len(f) > 5 and f[5]) or TSX_RX_PW_FELD.search(str(f[0] or "")) or TSX_RX_USER_FELD.search(str(f[0] or ""))
                    or "@" in str(f[3] or ""))
    except (TypeError, IndexError):
        return True


def tsx_login_lage(url, roh, felder):
    """REIN RECHNEND (testbar): ist das die TopstepX-Login-Seite, und darf Puls „PLATFORM LOGIN" drücken?
    -> {'seite': bool, 'knopf': Element|None, 'user': bool, 'pw': bool} — user/pw = Feld hat einen Wert (nie der Wert selbst).
    Seite = Adresse …/login ODER Knopf „PLATFORM LOGIN" + Passwortfeld. Felder: über Namen, sonst die zwei Edits über dem Knopf."""
    knoepfe = [e for e in roh or () if e[1] and (e[2] if len(e) > 2 else "Button") == "Button"
               and TSX_RX_PLATFORM_LOGIN.match(str(e[0] or ""))]
    knopf = knoepfe[0] if len(knoepfe) == 1 else None
    edits = [f for f in felder or () if len(f) > 3 and f[2] == "Edit" and f[1]]
    pw_f = [f for f in edits if (len(f) > 5 and f[5]) or TSX_RX_PW_FELD.search(str(f[0] or ""))]
    user_f = [f for f in edits if f not in pw_f and TSX_RX_USER_FELD.search(str(f[0] or ""))]
    if knopf and (not pw_f or not user_f):
        ueber = sorted([f for f in edits if f[1][3] <= knopf[1][1] + 4], key=lambda f: f[1][1])[-2:]
        if len(ueber) == 2:
            user_f, pw_f = user_f or [ueber[0]], pw_f or [ueber[1]]
    url_login = bool(re.search(r"topstepx\.com/+(login|signin|sign-in)\b", str(url or "").lower()))
    seite = url_login or bool(knopf and pw_f)
    return {"seite": seite, "knopf": knopf,
            "user": bool(user_f and str(user_f[0][3] or "").strip()),
            "pw": bool(pw_f and str(pw_f[0][3] or ""))}


def _tsx_login_versuch(w, trail, stand):
    """B27: Login-Seite? Felder gefüllt → EIN Klick auf „PLATFORM LOGIN". stand (dict je Lauf) merkt den Klick;
    stand['fehler'] = (code, msg) beendet den Lauf. -> True, wenn die Login-Seite gerade im Weg ist."""
    url = _chrome_url(w)
    roh = _tsx_seite_roh(w, ("Button", "Text"))
    lage = tsx_login_lage(url, roh, _tsx_felder(w))
    if not lage["seite"]:
        return False
    if stand.get("geklickt"):
        fehl = [str(e[0]).strip() for e in roh if e[1] and (e[2] if len(e) > 2 else "") == "Text"
                and TSX_RX_LOGIN_FEHLER.search(str(e[0] or "")) and len(str(e[0])) < 200]
        if fehl:
            stand["fehler"] = ("login", f"TopstepX-Login abgelehnt: {fehl[0][:160]}")
        return True
    gefuellt = lage["user"] and lage["pw"]
    # Nachtrag B27 (27.09.2026, ID A pc-aaaaaa, 4,1 s nach Tab-Öffnen „Username leer, Passwort leer", obwohl Chrome beide
    # sichtbar ausgefüllt hatte — Finn: „er muss nur hier drauf drücken"): Chrome gibt Autofill-Werte erst nach einem echten
    # Klick an die Seite (und an UIA) frei — also trotzdem EIN Klick, getippt wird nie.
    # B28 (27.09.2026, Finn: „nur der Klick geht langsam, mach schneller" — 5 s Feld-Wartezeit vor dem Klick): nicht mehr auf
    # die Felder warten (UIA liest sie ohnehin nicht), nur eine kurze Jitter-Pause.
    if not lage["knopf"]:
        return True                                  # Seite zeichnet noch — nächste Runde
    _warte(0.4, 0.6)
    _tsx_klick(lage["knopf"], "TopstepX-Login geklickt (Felder vorausgefüllt)" if gefuellt else
               "TopstepX-Login geklickt (Felder per UIA leer — Chrome-Autofill gibt sie erst beim Klick frei)", trail)
    stand["geklickt"] = time.time()
    _puls_diagnose_senden(trail, "tsx_login")
    return True


def tsx_felder_kurz(felder, max_n=120):
    """REIN RECHNEND (testbar): [name, typ, [l,t,r,b], wert, toggle] für Inventar/DB.
    B27: Werte von Zugangsfeldern (Passwort, Username/Mail, „@" im Wert) nur als „<n Zeichen>" — nie in die DB."""
    out = []
    for f in felder or ():
        try:
            wert = str(f[3] or "")
            if tsx_ist_zugangsfeld(f):
                wert = f"<{len(wert)} Zeichen>" if wert else ""
            out.append([str(f[0] or "")[:60], str(f[2] or "")[:20], [int(v) for v in f[1]], wert[:60],
                        f[4] if isinstance(f[4], int) else None])
        except (TypeError, ValueError, IndexError):
            continue
        if len(out) >= max_n:
            break
    return out


def _tsx_klick(e, name, trail):
    # 06.10.2026 (Finn: „wohin man genau klickt … alles ein bisschen zufällig"): nie mehr exakt die Rechteck-Mitte — Punkt je Klick
    # aus klick_punkt (Hand des Laufs, Zug, Streuung, Saum zum Rand)
    return _tv_uia_klick({"punkt": klick_punkt(e[1][0], e[1][1], e[1][2], e[1][3])}, name, trail)


def _tsx_vorbereiten(w, trail):
    """Einmal Login/Connect mittig drücken, benannte Banner-/Modal-X oben schließen (nur benannte Knöpfe).
    B17 (27.09.2026, PC von ID A pc-aaaaaa): gesucht wird NUR innerhalb der Webseite. Vorher sah die Suche das ganze Chrome-
    Fenster — Chromes Tab-X „Close" und das Fenster-X oben rechts heißen genauso und lagen im oberen Viertel: Puls klickte
    sie und schloss das Fenster samt Prophos-Tab (Signal ohne Ergebnis). Ohne erkannten Seitenbereich: gar kein Klick."""
    seite = _tsx_seite(w)
    if not seite:
        trail.append("Seitenbereich (Chrome-Dokument) nicht erkannt — kein Login-/X-Klick")
        return
    roh = seiten_filter(_tsx_roh(w, ("Button",)), seite)
    login = [e for e in roh if e[1] and TSX_RX_LOGIN.match(str(e[0]).strip())]
    if len(login) == 1:
        _tsx_klick(login[0], f"'{login[0][0]}' (Login/Connect)", trail)
        _warte(2.0, 1.0)
        roh = seiten_filter(_tsx_roh(w, ("Button",)), seite)
    # B18 (27.09.2026, zweiter Live-Test): KEINE Banner-X mehr — der orange „Weekend Hours"-Banner liegt über dem Dropdown,
    # verdeckt nichts, und zwei Klicks auf „close"/„Schließen" trafen ihn nicht. Overlays/Modals mittig kommen mit Etappe 2.


def _tsx_konto_element(roh):
    """Das Konto-Dropdown oben links (Text mit '$…K … | KENNUNG'), das oberste zuerst."""
    k = [e for e in roh if e[1] and tsx_konto_aus_text(e[0])]
    return sorted(k, key=lambda e: (e[1][1], e[1][0]))[0] if k else None


def _tsx_esc():
    try:
        from pywinauto import keyboard
        keyboard.send_keys("{ESC}")
    except Exception:
        pass


def _tsx_ausgabe(res, trail):
    h = _puls_heim()                                     # B35: zurück zu Prophos (auch nach Wachhund/Fehler)
    if h:
        trail.append(h)
    res["trail"] = " > ".join(trail)
    print(json.dumps(res, ensure_ascii=False))


def modus_tsxinventar(cmd):
    """Nur lesen: Inventar Grundzustand / Konto-Dropdown / Bracket-Dialog (je öffnen und wieder schließen)."""
    if tsx_weg_lauf() == "cdp":                        # K0-Riegel: auf einem Topstep-CDP-PC nie über UIA (Doppelsitzung)
        return modus_tsxinventar_cdp(cmd if isinstance(cmd, dict) else {})
    res = {"ok": False, "code": "", "msg": "", "trail": "", "schritt": "start", "inventar": {}}
    trail = _StempelSpur()
    trail.append(puls_bot_stand())                    # B33: erste Spur-Zeile = welcher Bot lief
    trail.append(maus_hand_text())                 # 06.10.2026: welche Hand lief
    try:
        from pywinauto import Desktop  # noqa: F401
    except ImportError:
        res.update(code="pywinauto", msg="pywinauto fehlt (nur auf dem PC lauffaehig).")
        return _tsx_ausgabe(res, trail)
    _dpi_bewusst()
    _tsx_wachhund(res, trail, 110.0)
    _warte(0.1, 0.4)
    w, f = _tsx_tab_holen(trail)
    if w is None:
        res.update(code="tab", schritt="tab", msg=f)
        return _tsx_ausgabe(res, trail)
    fr = _tv_fenster_rect(w)
    lg = {}
    _tsx_warte_seite(w, trail, 20.0, lg)
    if lg.get("fehler"):
        res.update(code=lg["fehler"][0], schritt="login", msg=lg["fehler"][1])
        _puls_diagnose_senden(trail, "tsx_login")
        return _tsx_ausgabe(res, trail)
    # B19: die offenen Fragen direkt beantworten — Titel/URL/Erkennung, alle Tabs, Seitenbereich, erste 150 Seiten-Elemente,
    # Kandidaten für den Konto-Auslöser
    res["titel"] = (w.window_text() or "")[:120]
    res["url"] = _chrome_url(w)[:200]
    res["erkannt"] = {"titel_tsx": ist_topstepx_titel(res["titel"]), "url_tsx": ist_topstepx_url(res["url"]),
                      "titel_tv": ist_tradingview_fenster(res["titel"], "Chrome_WidgetWin_1")}
    try:
        res["tabs"] = [{"name": (t.window_text() or "")[:70], "tsx": ist_topstepx_titel(t.window_text()),
                        "tv": tv_tab_rang(t.window_text() or "", "", "") > 0}
                       for t in w.descendants(control_type="TabItem", depth=12)][:20]
    except Exception:
        res["tabs"] = []
    roh = _tsx_roh(w)
    seite0 = _tsx_seite(w)
    res["seite"] = list(seite0) if seite0 else None
    res["inventar"]["grund"] = tsx_inventar_kurz(roh, fr)
    res["inventar"]["seite_150"] = tsx_inventar_kurz(seiten_filter(roh, seite0), fr, 150)
    res["ausloeser_kandidaten"] = tsx_inventar_kurz([e for e in seiten_filter(roh, seite0)
                                                     if re.search(r"\$\s*\d+(?:[.,]\d+)?\s*K\b|\|", str(e[0] or ""))], fr, 30)
    res["edits"] = list(_EDIT_NAMEN)
    res["inventar"]["felder_grund"] = tsx_felder_kurz(_tsx_felder(w))         # B26: auch unbenannte Felder, Wert + Haken
    res["zeilen_kandidaten"] = [[t[:120], list(r)] for t, r in tsx_zeilen(seiten_filter(roh, seite0))
                                if re.search(r"\$\s*\d+(?:[.,]\d+)?\s*K\b|\|", t)][:20]
    trail.append(f"Grundzustand: {len(res['inventar']['grund'])} Elemente, Seite {len(res['inventar']['seite_150'])}, "
                 f"Auslöser-Kandidaten {len(res['ausloeser_kandidaten'])}, Zeilen {len(res['zeilen_kandidaten'])}, URL {res['url'][:40] or '—'}")
    _puls_diagnose_senden(trail, "tsx_inventar")
    _puls_inventar_senden(res, trail)                 # B20: volles Inventar sofort in die DB (unabhängig vom Aufrufer)
    seite = _tsx_seite(w)
    res["seite"] = list(seite) if seite else None
    _puls_diagnose_senden(trail, "tsx_inventar")      # B17: Spur vor den Klicks
    ke = tsx_ausloeser_waehlen(seiten_filter(roh, seite))       # B22: auch Auslöser ohne Kennung
    if ke:
        _tsx_klick(ke, f"Konto-Dropdown ('{ke[0][:40]}')", trail)
        _warte(0.8, 0.4)
        res["inventar"]["konto_offen"] = tsx_inventar_kurz(_tsx_roh(w), fr)
        trail.append(f"Konto-Dropdown offen: {len(res['inventar']['konto_offen'])} Elemente")
        _tsx_esc()
        _warte(0.4, 0.3)
    else:
        trail.append("Konto-Dropdown nicht gefunden (kein Text '$…K … | KENNUNG')")
    # Bracket-Dialog: benannter Knopf 'Manage Brackets', sonst GENAU EIN kleiner Knopf rechts neben 'Position Bracket'
    roh = seiten_filter(_tsx_roh(w), seite)
    gear = [e for e in roh if e[1] and e[2] == "Button" and TSX_RX_MANAGE_BRACKETS.search(str(e[0]))]
    if not gear:
        txt = [e for e in roh if e[1] and TSX_RX_BRACKET_TEXT.search(str(e[0]))]
        if len(txt) == 1:
            ty = (txt[0][1][1] + txt[0][1][3]) // 2
            gear = [e for e in roh if e[1] and e[2] == "Button" and e[1][0] >= txt[0][1][2] - 2
                    and abs((e[1][1] + e[1][3]) // 2 - ty) <= 12 and (e[1][2] - e[1][0]) <= 44
                    and not TSX_RX_BRACKET_TEXT.search(str(e[0]))]
    if len(gear) == 1:
        _tsx_klick(gear[0], f"Bracket-Zahnrad ('{gear[0][0][:30]}')", trail)
        _warte(0.8, 0.4)
        roh_b = _tsx_roh(w)
        res["inventar"]["bracket_offen"] = tsx_inventar_kurz(roh_b, fr)
        res["inventar"]["felder_bracket"] = tsx_felder_kurz(_tsx_felder(w))    # B26: Risk/Profit-Wert + Haken-Zustand
        trail.append(f"Bracket-Dialog: {len(res['inventar']['bracket_offen'])} Elemente")
        zu = [e for e in seiten_filter(roh_b, seite) if e[1] and e[2] == "Button" and TSX_RX_SCHLIESSEN.match(str(e[0]).strip())]
        if len(zu) == 1:
            _tsx_klick(zu[0], "Bracket-Dialog schliessen (X)", trail)
        else:
            _tsx_esc()
            trail.append(f"Bracket-Dialog per Esc geschlossen ({len(zu)} X-Knöpfe)")
        _warte(0.4, 0.3)
    else:
        trail.append(f"Bracket-Zahnrad nicht eindeutig ({len(gear)} Kandidaten) — nichts geklickt")
    res.update(ok=True, schritt="fertig", msg="Inventar gelesen (keine Order).")
    _puls_inventar_senden(res, trail)
    try:
        pfad = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tsx_inventar.json")
        with open(pfad, "w", encoding="utf-8") as fh:
            json.dump(res, fh, ensure_ascii=False, indent=1)
        res["datei"] = pfad
    except Exception:
        pass
    return _tsx_ausgabe(res, trail)


def modus_tsxlesen(cmd, weiter=None, wachhund_s=100.0, weg=None):
    """Konto wählen und lesen: {ok, konto, balance, mll, rpl, upl, position, trail, code, schritt}. Keine Order.
    weiter (Etappe 2): nach erfolgreicher Kopf-Lesung weiter(w, res, trail) statt der Lese-Antwort (tsxorder).
    weg: vom Aufrufer schon bestimmter Weg (tsxorder prüft selbst VORHER) — sonst hier tsx_weg_lauf()."""
    if (weg or tsx_weg_lauf()) == "cdp":               # Riegel: nie UIA auf einem cdp-PC — Lesen über CDP (K1), Order folgt (K3/K4)
        if weiter is None and TSX_K1_AKTIV:
            return modus_tsxlesen_cdp(cmd if isinstance(cmd, dict) else {})
        print(json.dumps(tsx_cdp_folgt("tsxorder" if weiter else "tsxlesen"), ensure_ascii=False))
        return
    res = {"ok": False, "code": "", "msg": "", "trail": "", "schritt": "start", "konto": "", "balance": None,
           "mll": None, "rpl": None, "upl": None, "position": None}
    trail = _StempelSpur()
    trail.append(puls_bot_stand())                    # B33: erste Spur-Zeile = welcher Bot lief
    trail.append(maus_hand_text())                 # 06.10.2026: welche Hand lief
    ext = str((cmd or {}).get("konto") or (cmd or {}).get("ext_id") or "").strip()
    if len(_nur_alnum(ext)) < 5:
        res.update(code="befehl", msg="Feld 'konto' (External ID) fehlt")
        return _tsx_ausgabe(res, trail)
    try:
        from pywinauto import Desktop  # noqa: F401
    except ImportError:
        res.update(code="pywinauto", msg="pywinauto fehlt (nur auf dem PC lauffaehig).")
        return _tsx_ausgabe(res, trail)
    _dpi_bewusst()
    _tsx_wachhund(res, trail, wachhund_s)             # B19: ehrliches Ende nach 100 s, auch wenn UIA hängt
    _warte(0.1, 0.4)
    w, f = _tsx_tab_holen(trail)
    if w is None:
        res.update(code="tab", schritt="tab", msg=f)
        return _tsx_ausgabe(res, trail)
    fr = _tv_fenster_rect(w)
    res["schritt"] = "tsx_seite"
    _puls_diagnose_senden(trail, "tsx_tab")          # B17: Spur liegt schon in der DB, bevor geklickt wird
    lg = {}
    _tsx_warte_seite(w, trail, 20.0, lg)
    if lg.get("fehler"):
        res.update(code=lg["fehler"][0], schritt="login", msg=lg["fehler"][1])
        _puls_diagnose_senden(trail, "tsx_login")
        return _tsx_ausgabe(res, trail)
    res["schritt"] = "tsx_vorbereiten"
    _tsx_vorbereiten(w, trail)
    _puls_diagnose_senden(trail, "tsx_vorbereitet")
    # Konto (B18, 27.09.2026 — zweiter Live-Test: Auslöser zeigt die Kennung ABGEKÜRZT „$150K EXPRESS | EXPRESS-…", Lauf stand
    # danach ohne Spur): Auslöser finden (auch abgekürzt) → steht die volle ID da, fertig; sonst aufklappen, Eintrag mit der
    # vollen External ID (nie Ineligible, genau einer) klicken, Liste zu + Präfix passt = gewählt. Jeder Schritt mit
    # Obergrenze und Spur in puls_diagnose; ehrliches Ende mit Fehler statt Stillstand.
    frist = time.time() + 90.0

    def ende_mit(code, msg, **extra):
        res.update(code=code, schritt=code, msg=msg, **extra)
        trail.append("ENDE " + code + ": " + msg)            # B19: Grund steht in der Spur (puls_diagnose)
        _puls_diagnose_senden(trail, "tsx_" + code)
        return _tsx_ausgabe(res, trail)

    def ausloeser():
        return _tsx_ausloeser(w)

    res["schritt"] = "tsx_konto"
    ke = ausloeser()
    if not ke:
        return ende_mit("konto", "Konto-Auslöser oben links nicht gefunden (kein Text '$…K … | KENNUNG').",
                        inventar=tsx_inventar_kurz(_tsx_seite_roh(w), fr, 80))
    stand = tsx_konto_steht(ke[0], ext)
    trail.append(f"Konto-Auslöser: '{ke[0][:50]}' → {stand}")
    _puls_diagnose_senden(trail, "tsx_konto")
    ok_vor, ke2 = False, None
    if stand != "ja":
        bal_vorher = tsx_kopf_werte(_tsx_seite_roh(w, ("Text", "Button", "Group", "Custom")))["balance"]
        _tsx_klick(ke, "Konto-Dropdown öffnen", trail)
        eintraege, t_bis = [], time.time() + 4.0
        while time.time() < min(t_bis, frist):
            _warte(0.35, 0.25)
            eintraege = tsx_eintraege_waehlen(_tsx_seite_roh(w, ("Button", "Text", "ListItem", "MenuItem", "Hyperlink", "DataItem",
                                                                 "Group", "Custom")), ke[1][1] + 4)
            if len(eintraege) >= 1:
                break
        if not eintraege:
            # B24: Rückfall — einmal am linken Rand des Auslösers (Label-Knoten) erneut öffnen
            l_, t_, r_, b_ = ke[1]
            rueck = (ke[0], (l_, t_, min(r_, l_ + 60), b_), ke[2])
            trail.append("Liste leer — zweiter Versuch am Label-Knoten")
            _tsx_klick(rueck, "Konto-Dropdown öffnen (Rückfall)", trail)
            t_bis2 = time.time() + 3.0
            while time.time() < min(t_bis2, frist):
                _warte(0.35, 0.25)
                eintraege = tsx_eintraege_waehlen(_tsx_seite_roh(w, ("Button", "Text", "ListItem", "MenuItem", "Hyperlink", "DataItem",
                                                                     "Group", "Custom")), ke[1][1] + 4)
                if eintraege:
                    break
        texte = [str(e[0]) for e in eintraege]
        trail.append(f"Liste: {len(texte)} Einträge")
        _puls_diagnose_senden(trail, "tsx_liste")
        if not eintraege:
            _tsx_esc()
            return ende_mit("konto", "Konto-Dropdown ging nicht auf (keine Einträge in 4 s).")
        i, grund = tsx_konto_treffer(texte, ext)
        if i is None:
            _tsx_esc()
            return ende_mit("konto", f"{grund} ({ext}).", liste=texte[:20])
        roh_l = _tsx_seite_roh(w, ("Button", "Text", "ListItem", "MenuItem", "Hyperlink", "DataItem", "Group", "Custom"))
        ziel_label = tsx_eintrag_label(eintraege[i], roh_l)
        # B23: markierten Eintrag VOR dem Klick lesen — steht das Ziel schon, kein Wechsel nötig
        m_vor = tsx_markiert_urteil(_tsx_markiert(w), ext)
        trail.append(f"Liste: Ziel-Label '{ziel_label or '—'}', markiert vorher: {m_vor}")
        if m_vor == "ja":
            _tsx_esc()
            trail.append("Ziel war schon ausgewählt (markiert) — kein Klick")
            ok_vor = True
        else:
            ok_vor = False
    if stand != "ja" and not ok_vor:
        _tsx_klick(eintraege[i], f"Konto {ext}", trail)
        # B21: in Runden bis 6 s frisch sammeln (jede Runde ein neuer UIA-Aufruf) — bestätigt, sobald der Auslöser die volle
        # Ziel-ID trägt; abgekürzt nur mit eindeutigem Präfix + geänderter BAL. „Liste zu" ist KEINE Bedingung mehr.
        ok_k, grund_k, runde, t_bis = False, "", 0, time.time() + 6.0
        while time.time() < min(t_bis, frist):
            _warte(0.35, 0.25)
            runde += 1
            roh_n = _tsx_seite_roh(w, ("Button", "Text", "ComboBox", "Hyperlink", "Group", "Custom"))
            ke2 = tsx_ausloeser_waehlen(roh_n)
            # Beweis (1): volle ID im Auslöser — nur die sichere Stufe in der Schleife
            if ke2 and tsx_konto_steht(ke2[0], ext) == "ja":
                ok_k, grund_k = True, "Auslöser zeigt die Ziel-ID"
                break
            if ke2 and runde >= 3 and tsx_konto_steht(ke2[0], ext) in ("unbekannt", "vielleicht"):
                break                     # Auslöser ohne volle ID — gleich zu Beweis (2), nicht 6 s warten
        if not ok_k and ke2:
            # Beweis (2): Liste erneut öffnen, markierten Eintrag lesen, Esc
            _tsx_klick(ke2, "Konto-Dropdown erneut öffnen (Beweis)", trail)
            _warte(0.6, 0.3)
            m_nach = tsx_markiert_urteil(_tsx_markiert(w), ext)
            _tsx_esc()
            _warte(0.3, 0.2)
            if m_nach == "ja":
                ok_k, grund_k = True, "markierter Listeneintrag = Ziel-ID"
            elif m_nach == "nein":
                ok_k, grund_k = False, "markierter Listeneintrag ist ein anderes Konto"
        if not ok_k and grund_k != "markierter Listeneintrag ist ein anderes Konto":
            # Beweis (3): Label gleich + BAL geändert (bzw. Label eindeutig)
            roh_n = _tsx_seite_roh(w, ("Button", "Text", "ComboBox", "Hyperlink", "Group", "Custom"))
            ke2 = tsx_ausloeser_waehlen(roh_n)
            ok_k, grund_k = tsx_wechsel_urteil(ke2[0] if ke2 else "", ext, texte, bal_vorher, tsx_kopf_werte(roh_n)["balance"], ziel_label)
        trail.append(f"Wechsel-Prüfung ({runde} Runden): {grund_k}")
        if not ok_k:
            return ende_mit("konto", f"Konto {ext} geklickt, Wechsel nicht bewiesen: {grund_k}.")
        # Steht die Liste noch sichtbar da, einmal Esc (schließt nur das Dropdown)
        if ke2 and tsx_eintraege_waehlen(_tsx_seite_roh(w, ("ListItem", "MenuItem")), ke2[1][1] + 4):
            _tsx_esc()
        trail.append("Konto per Liste gewählt")
    if time.time() > frist:
        return ende_mit("zeit", "Obergrenze 90 s überschritten.")
    trail.append(f"Konto steht auf {ext}")
    res["konto"] = ext
    _puls_diagnose_senden(trail, "tsx_kopf")
    roh = _tsx_seite_roh(w)
    werte = tsx_kopf_werte(roh)
    res.update(werte)
    res["position"] = tsx_position_zustand([e[0] for e in roh if e[1]])
    trail.append(f"Kopf: BAL {werte['balance']} · MLL {werte['mll']} · RP&L {werte['rpl']} · UP&L {werte['upl']}"
                 f" · Position {res['position'] or 'unbekannt'}")
    if werte["balance"] is None:
        res.update(code="balance", schritt="lesen", msg="BAL in der Kopfzeile nicht lesbar.", inventar=tsx_inventar_kurz(roh, fr, 80))
        return _tsx_ausgabe(res, trail)
    # Vertrag wie tv-lesen (F23): summary {Label: Text} fuer tvBalanceAus, konto_aktiv, positionen ([] = flach, None = unbekannt)
    res["summary"] = tsx_summary(werte)
    res["konto_aktiv"] = ext
    res["positionen"] = [] if res["position"] == "keine" else None
    if weiter is not None:
        return weiter(w, res, trail)
    res.update(ok=True, schritt="fertig", msg=f"Balance {werte['balance']:,.2f} $ gelesen ({ext}).")
    _puls_diagnose_senden(trail, "tsx_fertig")
    return _tsx_ausgabe(res, trail)


