AUFNAHME_KOMPAKT_MAX = 48_000       # Railway-Route deckelt bei 60 KB (erste Aufnahme 00:38 UTC: 119 Ereignisse → HTTPError)
_AUFNAHME_KLICKTYPEN = ("pointerdown", "mousedown", "focusin", "click", "pointerup", "mouseup")


def _aufnahme_element_kompakt(e, text_max=40):
    if not isinstance(e, dict):
        return None
    out = {}
    for k in ("tag", "dn", "role", "aria", "id"):
        if e.get(k):
            out[k] = str(e[k])[:60]
    if e.get("text"):
        out["text"] = str(e["text"])[:text_max]
    if e.get("wert") not in (None, ""):
        out["wert"] = str(e["wert"])[:20]
    if isinstance(e.get("rect"), (list, tuple)):
        out["rect"] = [int(v) if isinstance(v, (int, float)) else v for v in e["rect"][:4]]
    return out


def aufnahme_kompakt(wert, vorfahren_n=2, text_max=40, max_bytes=AUFNAHME_KOMPAKT_MAX):
    """REIN RECHNEND (testbar): Aufnahme-Ergebnis (augen.js aufnahme_stopp) → kompakte Form unter max_bytes.
    Je Ereignis nur t/typ/zone/maus/taste/wert, Element = Ziel + höchstens vorfahren_n Vorfahren mit dn/role/aria/id/text/wert/
    rect. Aufeinanderfolgende Klick-Ereignisse (pointerdown/mousedown/focusin/click/…) auf DEMSELBEN Ziel werden zu EINEM
    'klick' mit typen[] zusammengefasst. Zu groß → weniger Vorfahren, kürzere Texte, zuletzt abschneiden (abgeschnitten=n)."""
    if not isinstance(wert, dict):
        return {"ereignisse": [], "anzahl": 0}
    roh = [e for e in (wert.get("ereignisse") or []) if isinstance(e, dict)]
    zus = []
    for e in roh:
        ziel = _aufnahme_element_kompakt(e.get("ziel"), text_max)
        vor = [v for v in (_aufnahme_element_kompakt(x, text_max) for x in (e.get("vorfahren") or [])[:vorfahren_n]) if v]
        typ = str(e.get("typ") or "")
        schl = json.dumps(ziel, sort_keys=True) if ziel else None
        if typ in _AUFNAHME_KLICKTYPEN and zus and zus[-1].get("typ") == "klick" and zus[-1].get("_schl") == schl \
                and int(e.get("t") or 0) - int(zus[-1].get("t_bis") or 0) <= 1500:
            zus[-1]["typen"].append(typ)
            zus[-1]["t_bis"] = int(e.get("t") or 0)
            continue
        k = {"t": int(e.get("t") or 0), "typ": "klick" if typ in _AUFNAHME_KLICKTYPEN else typ, "ziel": ziel, "vorfahren": vor}
        if typ in _AUFNAHME_KLICKTYPEN:
            k["typen"], k["t_bis"], k["_schl"] = [typ], int(e.get("t") or 0), schl
        for f in ("zone", "maus", "taste", "wert"):
            if e.get(f) not in (None, ""):
                k[f] = e[f] if f != "wert" else str(e[f])[:20]
        zus.append(k)
    for k in zus:
        k.pop("_schl", None)
    out = {k: wert.get(k) for k in ("v", "tab_id", "roh", "anzahl", "verloren", "dauer_ms", "url", "sichtbar_start", "sichtbar_stopp",
                                    "fokus_start", "fokus_stopp") if k in wert}
    out.update({"ereignisse": zus, "anzahl": len(roh), "zusammengefasst": len(zus), "kompakt": True})
    if len(json.dumps(out, ensure_ascii=False)) <= max_bytes:
        return out
    if vorfahren_n > 0 or text_max > 16:
        return aufnahme_kompakt(wert, max(0, vorfahren_n - 1), max(16, text_max - 12), max_bytes)
    while zus and len(json.dumps(out, ensure_ascii=False)) > max_bytes:
        zus.pop()
        out["abgeschnitten"] = len(roh) - len(zus)
    return out


def _aufnahme_lokal_schreiben(daten, trail):
    """Volle Aufnahme (alle Targets) als Datei neben dem Bot — überlebt jeden Upload-Fehler. -> Pfad | None"""
    try:
        name = os.path.join(_AUGEN_HIER, "augen_aufnahme_" + time.strftime("%Y%m%d_%H%M%S") + ".json")
        with open(name, "w", encoding="utf-8") as f:
            json.dump(daten, f, ensure_ascii=False)
        trail.append(f"Aufnahme lokal gesichert: {os.path.basename(name)}")
        return name
    except Exception as e:
        trail.append(f"Aufnahme lokal NICHT gesichert ({type(e).__name__})")
        return None


def _aufnahme_lokal_letzte():
    """Neueste augen_aufnahme_*.json neben dem Bot. -> (pfad, daten) | (None, None)"""
    try:
        kand = sorted(n for n in os.listdir(_AUGEN_HIER) if n.startswith("augen_aufnahme_") and n.endswith(".json"))
        if not kand:
            return None, None
        p = os.path.join(_AUGEN_HIER, kand[-1])
        with open(p, "r", encoding="utf-8") as f:
            return p, json.load(f)
    except Exception:
        return None, None


def _aufnahme_senden(daten_kompakt, stand, pc, trail, ziel_url=""):
    """Kompakte Aufnahme (+ kleiner Stand) nach puls_augen. -> True/False"""
    if not pc:
        return False
    import urllib.request
    ok = True
    for art, daten in (("inventar", {"inventar": {"aufnahme": daten_kompakt}}), ("stand", stand if isinstance(stand, dict) else None)):
        if not isinstance(daten, dict):
            continue
        body = json.dumps({"art": art, "daten": dict(daten, target=str(ziel_url)[:200])}, ensure_ascii=False).encode("utf-8")
        try:
            req = urllib.request.Request(f"{PULS_BACKEND}/puls-augen/{pc}", data=body, headers={"Content-Type": "application/json"})
            urllib.request.urlopen(req, timeout=8.0).read()
            trail.append(f"puls_augen ({art}) geschrieben ({len(body)} Bytes)")
        except Exception as e_:
            ok = False
            trail.append(f"puls_augen ({art}) nicht geschrieben ({type(e_).__name__}, {len(body)} Bytes)")
    return ok


def _augen_aufnahme(aktion, js, trail, res, pc):
    """Aufnahme start|stopp in ALLEN TradingView-Tabs des Puls-Chrome. Ergebnis je Target in Spur + res; stopp schreibt
    inventar.aufnahme (alle Targets) + einen Stand (Target mit den meisten Ereignissen) nach puls_augen."""
    if aktion == "senden":
        # Nachreichen (29.09.2026, erste Aufnahme verlor den Upload am 60-KB-Deckel): neueste lokale Volldatei, sonst die Kopie
        # im Tab (augen.js ≥ 0.6.1 aufnahme_letzte()). Nie eine neue Aufnahme, nie ein Klick.
        pfad, voll = _aufnahme_lokal_letzte()
        if isinstance(voll, dict) and voll.get("targets"):
            best = max((t for t in voll["targets"] if isinstance(t, dict)), key=lambda t: len(t.get("ereignisse") or []), default=None)
            if best:
                k = aufnahme_kompakt(best)
                trail.append(f"Aufnahme aus {os.path.basename(pfad)}: {k.get('anzahl')} Ereignisse → {k.get('zusammengefasst')} kompakt")
                ok = _aufnahme_senden(k, None, pc, trail, best.get("url") or "")
                res.update(ok=ok, msg=f"Aufnahme nachgereicht ({k.get('anzahl')} Ereignisse, lokal)" if ok else "Nachreichen fehlgeschlagen")
                return
        trail.append("keine lokale Aufnahme-Datei — frage die Tabs (aufnahme_letzte)")
    targets = augen_tv_targets(_cdp_http("/json/list"))
    alle = _cdp_http("/json/list") or []
    n_tabs = sum(1 for t in alle if isinstance(t, dict) and t.get("type") == "page")
    trail.append(f"Puls-Chrome: {n_tabs} Tab(s), davon {len(targets)} TradingView — Aufnahme in "
                 + (", ".join(str(t.get('url'))[:45] for t in targets) or "keinem"))
    if not targets:
        res["msg"] = "im Puls-Chrome ist keine TradingView-Seite offen"
        return
    ergebnisse, bester, bester_n = [], None, -1
    fn = {"start": "aufnahme_start", "stopp": "aufnahme_stopp", "senden": "aufnahme_letzte"}[aktion]
    for t in targets:
        eintrag = {"target_id": str(t.get("id") or "")[:40], "url": str(t.get("url") or "")[:200]}
        try:
            ws = _CdpVerbindung(t.get("webSocketDebuggerUrl"), timeout=8.0)
            try:
                ws.rufe("Runtime.evaluate", {"expression": js, "returnByValue": False}, timeout=8)
                # start mit 5-min-Autostopp (augen.js ≥ 0.7.2; Master 29.09.2026: eine vergessene Aufnahme lief parallel zum
                # K2-Probelauf weiter) — ältere augen.js ignorieren das Argument
                arg = "({max_ms: 300000})" if fn == "aufnahme_start" else "()"
                r = ws.rufe("Runtime.evaluate", {"expression": f"globalThis.prophosAugen.{fn} ? globalThis.prophosAugen.{fn}{arg} : "
                                                 "({fehler: 'augen.js ohne Aufnahme'})", "returnByValue": True}, timeout=10)
                wert = ((r or {}).get("result") or {}).get("value") or {}
                if r.get("exceptionDetails"):
                    wert = {"fehler": str((r.get("exceptionDetails") or {}).get("text"))[:120]}
                if aktion == "senden" and not wert:
                    wert = {"fehler": "keine letzte Aufnahme in diesem Tab"}
                if aktion != "senden":
                    ws.rufe("Runtime.evaluate", {"expression": AUGEN_BANNER_JS if aktion == "start" else AUGEN_BANNER_WEG_JS,
                                                 "returnByValue": True}, timeout=5)
                stand = None
                if aktion in ("stopp", "senden"):
                    r2 = ws.rufe("Runtime.evaluate", {"expression": "globalThis.prophosAugen.stand()", "returnByValue": True}, timeout=10)
                    stand = ((r2 or {}).get("result") or {}).get("value")
            finally:
                ws.zu()
        except Exception as e:
            eintrag["fehler"] = f"{type(e).__name__}: {str(e)[:80]}"
            ergebnisse.append(eintrag)
            trail.append(f"Target {eintrag['url'][:40]}: {eintrag['fehler']}")
            continue
        if isinstance(wert, dict):
            eintrag.update({k: wert.get(k) for k in ("tab_id", "sichtbar", "fokus", "roh", "anzahl", "verloren", "laeuft", "fehler",
                                                     "sichtbar_start", "sichtbar_stopp", "fokus_start", "fokus_stopp") if k in wert})
            if aktion in ("stopp", "senden"):
                eintrag["ereignisse"] = wert.get("ereignisse") or []
                eintrag["anzahl"] = len(eintrag["ereignisse"])
                for k_ in ("v", "dauer_ms", "url"):
                    if k_ in wert:
                        eintrag[k_ + ("_tab" if k_ == "url" else "")] = wert.get(k_)
                if eintrag["anzahl"] > bester_n:
                    bester, bester_n = (eintrag, stand), eintrag["anzahl"]
        ergebnisse.append(eintrag)
        trail.append(f"Target {eintrag['url'][:40]} (tab {eintrag.get('tab_id') or '?'}): "
                     + (f"{fn} ok" if not eintrag.get("fehler") else f"FEHLER {eintrag['fehler']}")
                     + (f", roh {eintrag.get('roh')}, Ereignisse {eintrag.get('anzahl')}" if aktion != "start" else "")
                     + (", VERLOREN" if eintrag.get("verloren") else "") + (", lief schon" if eintrag.get("laeuft") else ""))
    if aktion == "start":
        ok_n = sum(1 for e in ergebnisse if not e.get("fehler"))
        trail.append(f"Aufnahme läuft in {ok_n}/{len(ergebnisse)} Tab(s) — im Fenster mit dem ROTEN Rahmen klicken (NICHT kaufen), "
                     "dann 'augen aufnahme stopp'")
        res.update(ok=ok_n > 0, msg=f"Aufnahme gestartet ({ok_n} Tab(s))", targets=ergebnisse)
        return
    gesamt = sum(int(e.get("anzahl") or 0) for e in ergebnisse)
    roh = sum(int(e.get("roh") or 0) for e in ergebnisse if isinstance(e.get("roh"), int))
    verloren = all(e.get("verloren") for e in ergebnisse if not e.get("fehler")) if ergebnisse else True
    trail.append(f"Aufnahme gestoppt: {gesamt} Ereignisse (roh {roh}) über {len(ergebnisse)} Target(s)"
                 + (" — AUFNAHME VERLOREN (Seite neu geladen?)" if verloren else "")
                 + (" — roh 0 überall: in keinem Puls-Chrome-Tab kam ein Klick an (anderes Fenster/Reader-Chrome?)" if roh == 0 and not verloren else ""))
    # Volle Aufnahme IMMER zuerst lokal (überlebt jeden Upload-Fehler), dann kompakt (< 48 KB) in die DB
    if aktion == "stopp" and gesamt > 0:
        _aufnahme_lokal_schreiben({"targets": ergebnisse, "gesamt": gesamt, "roh": roh, "verloren": verloren,
                                   "at": time.strftime("%Y-%m-%dT%H:%M:%S")}, trail)
    gesendet = False
    if bester and bester_n > 0:
        k = aufnahme_kompakt(bester[0])
        k["targets_n"], k["roh_gesamt"] = len(ergebnisse), roh
        trail.append(f"kompakt: {k.get('anzahl')} Ereignisse → {k.get('zusammengefasst')}"
                     + (f", {k['abgeschnitten']} abgeschnitten" if k.get("abgeschnitten") else ""))
        gesendet = _aufnahme_senden(k, bester[1], pc, trail, bester[0].get("url") or "")
    res.update(ok=gesamt > 0 and gesendet, msg=f"Aufnahme: {gesamt} Ereignisse, roh {roh}, {len(ergebnisse)} Target(s)"
               + (", verloren" if verloren else "") + ("" if gesendet or gesamt == 0 else " — Upload fehlgeschlagen, lokal gesichert; 'augen aufnahme senden'"),
               targets=[{k_: v for k_, v in e.items() if k_ != "ereignisse"} for e in ergebnisse])


def augen_kurzform(stand):
    """REIN RECHNEND (testbar): lesbare Spur-Zeile aus augen.js stand() (29.09.2026, erste echte Zeile von PC von ID B: ticket.da
    statt offen, toasts als {log, gruppen} statt Liste — die erste Fassung meldete „Ticket zu · Toasts 2")."""
    if not isinstance(stand, dict):
        return "kein Stand"
    if stand.get("fehler"):
        return "Fehler: " + str(stand.get("fehler"))[:80]
    tk = stand.get("ticket") if isinstance(stand.get("ticket"), dict) else {}

    def wert(x):
        if isinstance(x, dict):
            if "wert" in x:
                return x.get("wert")
            return wert(x.get("feld"))
        return x
    offen = tk.get("da", tk.get("offen"))
    teile = [f"Ticket {'offen' if offen else 'zu'}"]
    if offen:
        teile.append(f"{tk.get('typ') or '?'} · Units {wert(tk.get('menge') or tk.get('units')) or '-'}"
                     f" · TP {wert(tk.get('tp')) or '-'} · SL {wert(tk.get('sl')) or '-'}")
    kk = stand.get("kauf_knopf") if isinstance(stand.get("kauf_knopf"), dict) else {}
    teile.append(f"Knopf '{str(kk.get('text') or '-')[:40]}'")
    to = stand.get("toasts")
    if isinstance(to, dict):
        n_to = sum(len(v) for v in to.values() if isinstance(v, list))
    else:
        n_to = len(to) if isinstance(to, list) else 0
    po = stand.get("popups")
    teile.append(f"Toasts {n_to}")
    teile.append(f"Popups {len(po) if isinstance(po, list) else 0}")
    ko = stand.get("konto") if isinstance(stand.get("konto"), dict) else {}
    if ko.get("aktiv"):
        teile.append(f"Konto {str(ko.get('aktiv'))[:30]}")
    return " · ".join(teile)


def modus_augen(cmd):
    """Augen-Lauf (E0, nur lesen). cmd.start = True: Puls-Chrome auch ohne Schalter starten (einmaliger Menschen-Login)."""
    t0, trail = time.time(), []
    res = {"ok": False, "trail": trail}
    if _handlauf_aktiv():
        # K3-Handlauf (29.09.2026): kein Lesen, solange er läuft — inventar() las jeden Feldwert, auch im Tradovate-Login-Formular
        res.update(ok=True, msg="K3-Handlauf läuft — Augen lesen in dieser Zeit nicht")
        print(json.dumps(res, ensure_ascii=False))
        return
    pc = _augen_pc_id()
    sperre = os.path.join(_AUGEN_HIER, "augen.lock")
    try:
        if os.path.exists(sperre) and time.time() - os.path.getmtime(sperre) < 120:
            res["msg"] = "Augen-Lauf läuft schon"
            print(json.dumps(res, ensure_ascii=False))
            return
        with open(sperre, "w") as f:
            f.write(str(os.getpid()))
    except Exception:
        pass
    try:
        start = bool(cmd.get("start"))
        jetzt = bool(cmd.get("jetzt")) or bool(cmd.get("aufnahme"))   # Hand-Test/Aufnahme: ohne Schalter + 60-s-Sperre, nie schließen
        augen = _augen_regel_holen(pc) if pc else "uia"
        if augen != "cdp" and not start and not jetzt and not _AUGEN_REGEL_STAND["explizit"]:
            res.update(ok=True, msg="Regel nicht abrufbar und keine gültige 'cdp'-Regel gemerkt — Puls-Chrome bleibt, nichts gelesen")
            return
        tsx_hier = _AUGEN_REGEL_STAND.get("tsx") or tsx_regel_weiche(_augen_json_lesen("augen_regel.json"), pc)
        if augen != "cdp" and not start and not jetzt and tsx_hier == "cdp":
            # K0 (30.09.2026): ein Topstep-PC (puls_topstep_pcs) braucht das Puls-Chrome, auch wenn TradingView dort 'uia' ist —
            # sonst schlösse jeder Augen-Lauf nach einem tsx-Lauf das TopstepX-Fenster (Browser.close). Aber: TradingView-Tabs darin
            # zu (Prüfer: ein angemeldeter TV-Tab im Puls-Chrome kickte am 29.09. den Reader) — nur Tabs, nie das ganze Chrome.
            zu = 0
            for t in augen_tv_targets(_cdp_http("/json/list", timeout=1.0)):
                if t.get("id") and _cdp_tab_schliessen(t.get("id")):
                    zu += 1
            if zu:
                trail.append(f"Regel 'uia' für TradingView — {zu} TradingView-Tab(s) im Puls-Chrome geschlossen, TopstepX bleibt")
            res.update(ok=True, msg="Regel 'uia' für TradingView, Topstep läuft über das Puls-Chrome — es bleibt offen")
            return
        if augen != "cdp" and not start and not jetzt:
            # Aufräumen (29.09.2026, ID B pc-cccccc: Schalter zurück auf uia, das Puls-Chrome lief weiter und kickte die
            # TradingView-Sitzung des Readers): antwortet Port 9333, das Puls-Chrome per CDP Browser.close schließen — trifft nur
            # die Instanz mit diesem Debug-Port (das Reader-Chrome hat keinen), kein taskkill, keine Fenstersuche.
            v = _cdp_http("/json/version", timeout=1.0)
            if v and v.get("webSocketDebuggerUrl"):
                try:
                    ws = _CdpVerbindung(v["webSocketDebuggerUrl"], timeout=3.0)
                    try:
                        ws.rufe("Browser.close", timeout=3.0)
                    except Exception:
                        pass            # Chrome schließt die Verbindung beim Beenden — kein Fehler
                    finally:
                        ws.zu()
                    trail.append("Regel 'uia' — Puls-Chrome (Port 9333) per Browser.close geschlossen")
                except Exception as e:
                    trail.append(f"Puls-Chrome schließen fehlgeschlagen ({type(e).__name__})")
                res.update(ok=True, msg="Regel 'uia' — Puls-Chrome geschlossen")
                return
            res.update(ok=True, msg="Regel 'uia' — nichts zu tun")
            return
        letzt = _augen_json_lesen("augen_letzt.json") or {}
        if not start and not jetzt and time.time() - float(letzt.get("at") or 0) < AUGEN_ABSTAND_S:
            res.update(ok=True, msg="letztes Lesen < 60 s — übersprungen")
            return
        _augen_json_schreiben("augen_letzt.json", {"at": time.time()})
        if not _puls_chrome_sicher(trail, sichtbar=start, url=TSX_URL if cmd.get("tsx") else AUGEN_TV_URL):
            res["msg"] = "Puls-Chrome nicht erreichbar"
            return
        if start and cmd.get("tsx"):
            # K0 (30.09.2026): 'order_bot.py augen start tsx' — TopstepX-Tab im Puls-Chrome öffnen (keine .bat) und zeigen, damit
            # Finn/ID A dort EINMAL von Hand anmeldet (Passwort in Chrome speichern)
            ziel = _tsx_tab_sicher(trail)
            if not ziel:
                res["msg"] = "TopstepX-Tab im Puls-Chrome nicht geöffnet"
                return
            _cdp_tab_zeigen(ziel.get("id"), trail)
            res.update(ok=True, msg="Puls-Chrome mit TopstepX offen — jetzt dort anmelden und das Passwort in Chrome speichern")
            return
        if start:
            res.update(ok=True, msg="Puls-Chrome läuft — jetzt von Hand einloggen (TradingView, Tradovate mit Remember me)")
            return
        ziel = augen_target_waehlen(_cdp_http("/json/list"))
        if not ziel:
            _cdp_http("/json/new?" + AUGEN_TV_URL, methode="PUT")
            trail.append("Puls-Chrome: TradingView-Tab angelegt — Lesen beim nächsten Lauf")
            res.update(ok=True, msg="TV-Tab angelegt")
            return
        js = _augen_js_holen(trail)
        if not js:
            res["msg"] = "augen.js fehlt (noch nicht im Repo?)"
            return
        if cmd.get("aufnahme"):
            # AUFNAHME (29.09.2026, Finns Idee + Freigabe): Finn klickt den Order-Ablauf im Puls-Chrome einmal SELBST durch (bis
            # VOR den Kauf-Knopf); augen.js ≥ 0.5 zeichnet Klicks/Eingaben auf (Capture-Listener, Puffer im Fenster, Passwortfelder
            # und Login-Formulare nur „[verborgen]"). Puls klickt hier NICHTS. 'stopp' holt Puffer + frischen Stand nach puls_augen
            # (inventar.aufnahme). Neuladen der Seite verwirft den Puffer → verloren.
            # ERSTE LIVE-AUFNAHME (00:36–00:38 UTC, pc-cccccc): 0 Ereignisse — Puls hatte nur EIN Target (das erste aus
            # /json/list); Finn klickte womöglich in einem anderen TV-Tab oder im Reader-Chrome. Deshalb jetzt: ALLE TradingView-
            # Seiten des Puls-Chrome (je Target eigene Verbindung), rotes Banner „AUFNAHME LÄUFT" in jedem Tab (pointer-events
            # none, blockiert keinen Klick), beim Stopp wieder weg; je Target roh/anzahl/tab_id in Spur + DB. roh 0 = dort kam
            # nichts an (T1: hidden/fokus allein beweisen nichts).
            _augen_aufnahme(cmd["aufnahme"], js, trail, res, pc)
            return
        ws = _CdpVerbindung(ziel.get("webSocketDebuggerUrl"))
        try:
            ws.rufe("Runtime.evaluate", {"expression": js, "returnByValue": False, "awaitPromise": True}, timeout=8)
            ausdruck = ("(async () => { const A = globalThis.prophosAugen; if (!A) return {fehler: 'prophosAugen fehlt'};"
                        " return {stand: await A.stand(), inventar: A.inventar ? await A.inventar() : null}; })()")
            r = ws.rufe("Runtime.evaluate", {"expression": ausdruck, "returnByValue": True, "awaitPromise": True}, timeout=10)
        finally:
            ws.zu()
        wert = ((r or {}).get("result") or {}).get("value") or {}
        if r.get("exceptionDetails") or wert.get("fehler"):
            res["msg"] = "augen.js: " + str(wert.get("fehler") or (r.get("exceptionDetails") or {}).get("text") or "Ausnahme")[:160]
            return
        stand, inv = wert.get("stand") or {}, wert.get("inventar")
        trail.append(f"Augen (cdp): {str(ziel.get('url'))[:50]} · " + augen_kurzform(stand))
        dauer = int((time.time() - t0) * 1000)
        if pc:
            import urllib.request
            for art, daten in (("stand", stand), ("inventar", {"inventar": inv} if inv is not None else None)):
                if not isinstance(daten, dict):
                    continue
                daten = dict(daten, dauer_ms=dauer, target=str(ziel.get("url"))[:200])
                try:
                    req = urllib.request.Request(f"{PULS_BACKEND}/puls-augen/{pc}",
                                                 data=json.dumps({"art": art, "daten": daten}, ensure_ascii=False).encode("utf-8"),
                                                 headers={"Content-Type": "application/json"})
                    urllib.request.urlopen(req, timeout=6.0).read()
                except Exception as e:
                    trail.append(f"puls_augen ({art}) nicht geschrieben ({type(e).__name__})")
        res.update(ok=True, msg="gelesen", dauer_ms=dauer)
    except Exception as e:
        res["msg"] = f"Augen-Lauf abgebrochen: {type(e).__name__}: {str(e)[:160]}"
    finally:
        try:
            os.remove(sperre)
        except Exception:
            pass
        # Fehler NICHT nach puls_diagnose (eine Zeile je PC — würde die Diagnose des echten Puls-Laufs überschreiben),
        # sondern als Stand mit 'fehler' nach puls_augen
        if pc and not res.get("ok") and res.get("msg") != "Augen-Lauf läuft schon":
            try:
                import urllib.request
                daten = {"fehler": (str(res.get("msg") or "") + " | " + " > ".join(trail))[:1500], "ts": int(time.time() * 1000)}
                req = urllib.request.Request(f"{PULS_BACKEND}/puls-augen/{pc}", data=json.dumps({"art": "stand", "daten": daten},
                                             ensure_ascii=False).encode("utf-8"), headers={"Content-Type": "application/json"})
                urllib.request.urlopen(req, timeout=6.0).read()
            except Exception:
                pass
        print(json.dumps(res, ensure_ascii=False))


