# 1–2 s, vor jedem Druck 0,3–0,8 s über dem Ziel stehen — beides über _warte (Streuung). Gilt für K2, Login und das Ticket.
TSX_SCHRITT_PAUSE = (1.0, 1.0)
TSX_HOVER_PAUSE = (0.3, 0.5)


def tsx_pause_dauer(zufall=None, hand=None):
    """REIN RECHNEND (testbar): Länge einer Pause zwischen zwei TopstepX-Schritten (s). Mindestens TSX_SCHRITT_PAUSE[0] (1 s — was die
    Seite braucht, nie kürzer), obendrauf schief verteilt 0–1,8 s mal Pausen-Faktor der Hand (kurze Zugaben häufiger als lange,
    u^1,7), in rund 10 % ein längeres Nachdenken (+1,5–3 s). Vorher fix 1 + 0–1 s (Finn 06.10.2026: „alles ein bisschen zufällig")."""
    rnd = zufall or random
    h = hand or _hand()
    d = TSX_SCHRITT_PAUSE[0] + (rnd.random() ** 1.7) * 1.8 * h["pause"]
    if rnd.random() < 0.10:
        d += rnd.uniform(1.5, 3.0)
    return d


def tsx_hover_pause(zufall=None, hand=None):
    """REIN RECHNEND (testbar): (minimum, streuung) in s für die Hover-Pause vor dem Druck auf TopstepX (Finn 01.10.2026: erst über dem
    Ziel stehen, dann drücken). Minimum bleibt TSX_HOVER_PAUSE[0] (0,3 s) plus 0–0,1 s, Streuung 0,15–0,7 s mal Pausen-Faktor der
    Hand — jede Hover-Pause anders lang. Vorher fix (0,3, 0,5)."""
    rnd = zufall or random
    h = hand or _hand()
    return TSX_HOVER_PAUSE[0] + rnd.uniform(0.0, 0.1), rnd.uniform(0.15, 0.7) * h["pause"]


# ── NACH DER ORDER IM TAB BLEIBEN (06.10.2026, Finn: „wenn die Order platziert ist, ist es nicht immer direkt nach einer Millisekunde
# raus, sondern es bleibt aus Zufallsprinzip noch im Tab … 15 Sekunden bis ein paar Minuten, und geht nicht insta raus"). Bisher
# minimierte zu() das Puls-Chrome im selben Moment, in dem die Antwort stand. Das Panel wartet aber auf das PROZESS-Ende des Bots
# (subprocess.run) — darum bleibt nicht der Lauf, sondern ein ABGEKOPPELTES Kind (modus_tsxbleiben): der Lauf antwortet sofort wie
# bisher (Fill → Prophos → Hedge unverändert), das Kind lässt das Puls-Chrome stehen und minimiert es erst nach der gewürfelten
# Zeit. Deckel 240 s: ab 5 min verdecktem Fenster drosselt Chrome den Reader-Tab daneben stark (deshalb wurde überhaupt minimiert).
# Nur nach GESENDETER Order (res.gesendet) — Probe/Lesen minimieren wie bisher sofort. Nur der CDP-Weg (Puls-Chrome).
TSX_BLEIBEN_S = (15.0, 240.0)
TSX_BLEIBEN_MARKE = "puls_tsx_bleiben.json"


def tsx_bleiben_dauer(zufall=None, hand=None):
    """REIN RECHNEND (testbar): wie lange der Bot nach einer gesendeten Order noch im TopstepX-Tab bleibt (s). In rund einem Viertel
    der Fälle kurz (15–60 s), sonst 1–4 min, mal Pausen-Faktor der Hand, immer innerhalb TSX_BLEIBEN_S."""
    rnd = zufall or random
    h = hand or _hand()
    d = rnd.uniform(15.0, 60.0) if rnd.random() < 0.25 else rnd.uniform(60.0, 240.0)
    return max(TSX_BLEIBEN_S[0], min(TSX_BLEIBEN_S[1], d * h["pause"]))


def tsx_bleiben_befehl(hwnd, bis, pid):
    """REIN RECHNEND (testbar): Marke/Befehl des Kindes {hwnd, bis, pid}; None bei Unsinn (kein Fenster, Zeit schon vorbei)."""
    try:
        hwnd, bis, pid = int(hwnd), float(bis), int(pid)
    except (TypeError, ValueError):
        return None
    if hwnd <= 0 or bis <= time.time():
        return None
    return {"hwnd": hwnd, "bis": bis, "pid": pid}


def tsx_bleiben_weiter(marke, pid, handlauf, fenster_da, jetzt):
    """REIN RECHNEND (testbar): soll das Kind weiter warten (True), aufhören OHNE zu minimieren (None) oder jetzt minimieren (False)?
    Abgelöst (Marke trägt eine andere pid — ein neuerer Lauf hat ein neues Kind), neuer Lauf (Hand-Lauf-Sperre: der minimiert am Ende
    selbst) oder Fenster weg/schon minimiert → None; Zeit um → False; sonst True."""
    if not isinstance(marke, dict) or marke.get("pid") != pid or handlauf or not fenster_da:
        return None
    try:
        return True if float(marke.get("bis") or 0) > float(jetzt) else False
    except (TypeError, ValueError):
        return None


def _tsx_bleiben_starten(s, res, trail):
    """Nach einer gesendeten Order (res.gesendet): Puls-Chrome NICHT sofort minimieren — Kind-Prozess übernimmt das später. Setzt
    s._bleiben, damit zu() das Fenster stehen lässt. Nur Windows mit bekanntem Fenster; nie ein Fehler nach außen."""
    try:
        hwnd = getattr(s, "_win_hwnd", None)
        if not (_WIN_EINGABE and hwnd and res.get("gesendet")):
            return
        dauer = tsx_bleiben_dauer()
        marke = tsx_bleiben_befehl(hwnd, time.time() + dauer, 0)
        if not marke:
            return
        import subprocess
        flags = 0x00000008 | 0x00000200 | 0x08000000 | 0x00004000   # DETACHED, NEW_PROCESS_GROUP, NO_WINDOW, BELOW_NORMAL (wie augen_anstossen)
        subprocess.Popen([sys.executable, os.path.abspath(__file__), "tsxbleiben", json.dumps(marke)], creationflags=flags,
                         stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, close_fds=True)
        s._bleiben = True
        res["bleibt_s"] = int(dauer)
        trail.append(f"bleibt noch ~{int(dauer)} s im TopstepX-Tab (Kind-Prozess minimiert später)")
    except Exception as e:
        trail.append(f"Bleiben im Tab nicht gestartet ({type(e).__name__}) — Fenster wird wie bisher minimiert")


def modus_tsxbleiben(cmd):
    """Kind-Prozess nach einer gesendeten TopstepX-Order: lässt das Puls-Chrome bis 'bis' stehen (die Maus zuckt ab und zu, solange das
    Fenster vorn ist), prüft alle 2–4 s die Marke (abgelöst?), die Hand-Lauf-Sperre (ein neuer Lauf minimiert selbst) und das Fenster,
    und minimiert erst dann (SW_SHOWMINNOACTIVE wie zu()). Keine Ausgabe, kein Fehler nach außen, auf dem Mac sofort zu Ende."""
    try:
        hwnd, bis = int((cmd or {}).get("hwnd") or 0), float((cmd or {}).get("bis") or 0)
    except (TypeError, ValueError):
        return
    if not _WIN_EINGABE or hwnd <= 0:
        return
    import ctypes
    p = os.path.join(_AUGEN_HIER, TSX_BLEIBEN_MARKE)
    pid = os.getpid()
    try:
        with open(p, "w", encoding="utf-8") as f:
            json.dump({"hwnd": hwnd, "bis": bis, "pid": pid}, f)
    except OSError:
        return

    def marke():
        try:
            with open(p, "r", encoding="utf-8") as f:
                return json.load(f)
        except (OSError, ValueError):
            return None

    def fenster_da():
        try:
            return bool(ctypes.windll.user32.IsWindow(hwnd)) and not _win_minimiert(hwnd)
        except Exception:
            return False
    while True:
        w = tsx_bleiben_weiter(marke(), pid, _handlauf_aktiv(), fenster_da(), time.time())
        if w is None:
            return
        if w is False:
            break
        if random.random() < 0.3:
            try:
                if _win_vordergrund() == hwnd:
                    _maus_zittern(random.uniform(0.6, 2.5))
            except Exception:
                pass
        time.sleep(min(max(0.5, bis - time.time()), random.uniform(2.0, 4.0)))
    try:
        _win_zeigen(hwnd, 7)
    except Exception:
        pass
    try:
        if (marke() or {}).get("pid") == pid:
            os.remove(p)
    except OSError:
        pass


def _tsx_pause():
    """Pause zwischen zwei TopstepX-Schritten (Finn 01.10.2026: 1–2 s, gewürfelt, nie fix; seit 06.10.2026 Länge aus tsx_pause_dauer je
    Hand). Die Maus steht dabei nicht still (kleine Zucker, _maus_zittern) — nur mit echter Windows-Eingabe, sonst reines Warten."""
    d = tsx_pause_dauer()
    if _WIN_EINGABE:
        _maus_zittern(d)
    else:
        _warte(d, 0.05)


def tsx_regel_weiche(regel_datei, pc_id):
    """REIN RECHNEND (testbar): lokale TopstepX-Regel. 'cdp' ist KLEBRIG (kein Verfall), gilt nur für DIESEN PC; sonst 'uia'."""
    if not isinstance(regel_datei, dict) or regel_datei.get("tsx") != "cdp" or not pc_id:
        return "uia"
    return "cdp" if regel_datei.get("tsx_pc", regel_datei.get("pc")) in (None, pc_id) else "uia"


def tsx_regel_aus_antwort(d):
    """REIN RECHNEND (testbar): tsx aus der /puls-regel-Antwort — 'cdp' | 'uia' | None (fehlt/unbekannt → lokale Regel gilt)."""
    v = d.get("tsx") if isinstance(d, dict) else None
    return v if v in ("cdp", "uia") else None


def _augen_regel_mischen(neu):
    """augen_regel.json aktualisieren, ohne die jeweils andere Regel zu verlieren (augen = TradingView, tsx = TopstepX). Lesen-Mischen-
    Schreiben unter einer kurzen Sperrdatei (≤ 1,5 s warten, ältere als 5 s gelten als verwaist) — sonst schreibt ein Lauf seinen alten
    Stand über ein gerade gekommenes ausdrückliches 'uia' (K0-Prüfer 30.09.2026)."""
    sperre = os.path.join(_AUGEN_HIER, "augen_regel.lock")
    fd, ende = None, time.time() + 1.5
    while fd is None and time.time() < ende:
        try:
            fd = os.open(sperre, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            try:
                if time.time() - os.path.getmtime(sperre) > 5.0:
                    os.remove(sperre)
                    continue
            except OSError:
                pass
            time.sleep(0.05)                                   # Sperr-Takt, kein Warten auf die Seite (nicht über _warte)
        except OSError:
            break
    try:
        alt = _augen_json_lesen("augen_regel.json")
        d = dict(alt) if isinstance(alt, dict) else {}
        d.update(neu)
        _augen_json_schreiben("augen_regel.json", d)
    finally:
        if fd is not None:
            try:
                os.close(fd)
                os.remove(sperre)
            except OSError:
                pass


def _tsx_regel_holen(pc):
    """tsx frisch von Railway (2 s) und lokal merken; ohne ausdrückliche Antwort gilt die lokale (klebrige) Regel."""
    import urllib.request
    try:
        with urllib.request.urlopen(f"{PULS_BACKEND}/puls-regel/{pc}", timeout=2.0) as r:
            v = tsx_regel_aus_antwort(json.loads(r.read().decode("utf-8", "replace")))
    except Exception:
        v = None
    if v:
        alt = _augen_json_lesen("augen_regel.json") or {}
        vorher = tsx_regel_weiche(alt, pc)
        if alt.get("tsx") != v or alt.get("tsx_pc") != pc:          # nur bei Änderung schreiben (Prüfer K0: sonst jeder Lauf)
            _augen_regel_mischen({"tsx": v, "tsx_at": time.time(), "tsx_pc": pc})
        if vorher == "cdp" and v == "uia":
            # Prüfer K0: sonst läuft der UIA-Weg sofort, während TopstepX im Puls-Chrome noch angemeldet ist (Doppelsitzung)
            _tsx_tabs_schliessen()
        return v
    return tsx_regel_weiche(_augen_json_lesen("augen_regel.json"), pc)


def tsx_weg_lauf():
    """'cdp' | 'uia' für DIESEN TopstepX-Lauf. Ohne pc_id = 'uia' (alter Weg); jeder Fehler = lokale Regel."""
    pc = _augen_pc_id()
    if not pc:
        return "uia"
    try:
        return _tsx_regel_holen(pc)
    except Exception:
        return tsx_regel_weiche(_augen_json_lesen("augen_regel.json"), pc)


def tsx_cdp_folgt(modus):
    """REIN RECHNEND (testbar): ehrliche Antwort eines tsx-Modus, dessen CDP-Etappe noch fehlt — nie „nichts gesendet, neu starten"."""
    etappe = TSX_ETAPPE.get(modus, "K1")
    return {"ok": False, "code": "cdp_folgt", "etappe": etappe, "weg": "cdp", "schritt": "weg", "gesendet": False, "retry_ok": False,
            "msg": (f"Topstep läuft auf diesem PC über das Puls-Chrome — dieser Schritt kommt mit Etappe {etappe}. Der alte Weg im "
                    "normalen Chrome ist hier gesperrt (Doppelsitzung). Plan bleibt stehen, NICHT erneut starten.")}


def tsx_url_login(url):
    """REIN RECHNEND (testbar): steht dieser TopstepX-Tab laut Adresse auf der Login-Seite (…/login, /signin, /sign-in)?"""
    return bool(re.search(r"topstepx\.com/+(login|signin|sign-in)\b", str(url or "").lower()))


def tsx_targets(liste):
    """REIN RECHNEND (testbar): TopstepX-Seiten (type page) aus /json/list — angemeldete vor Login-Seiten, …/trade zuerst. -> Liste
    Live 30.09.2026 11:15 UTC (erster Topstep-PC): der vom Bot geöffnete Tab stand noch auf der alten Login-Seite, während der Nutzer sich in
    einem zweiten Tab desselben Puls-Chrome angemeldet hatte — der Bot las den alten."""
    t = [x for x in (liste or []) if isinstance(x, dict) and x.get("type") == "page" and ist_topstepx_url(x.get("url"))]
    t.sort(key=lambda x: (1 if tsx_url_login(x.get("url")) else 0, 0 if "/trade" in str(x.get("url")) else 1))
    return t


def _tsx_tab_sicher(trail, warten_s=20.0):
    """TopstepX-Tab im Puls-Chrome finden, sonst EINEN neuen öffnen (topstepx.com/trade) und warten, bis er in /json/list steht.
    Keine .bat, kein Alltags-Chrome. -> Target | None"""
    t = tsx_targets(_cdp_http("/json/list"))
    if t:
        if len(t) > 1:
            trail.append(f"Puls-Chrome: {len(t)} TopstepX-Tabs ({[str(x.get('url'))[:40] for x in t][:4]}) — nehme den ersten (angemeldet vor Login-Seite)")
        # ein Tab ohne webSocketDebuggerUrl (anderer DevTools-Client hängt dran) wäre ein cdp_fehler — einen verbindbaren vorziehen
        return ([x for x in t if x.get("webSocketDebuggerUrl")] or t)[0]
    neu = _cdp_http("/json/new?" + TSX_URL, methode="PUT")
    trail.append("Puls-Chrome: TopstepX-Tab geöffnet (topstepx.com/trade)" if isinstance(neu, dict) and neu.get("id")
                 else "Puls-Chrome: TopstepX-Tab öffnen ohne Antwort (/json/new) — warte trotzdem auf die Tab-Liste")
    if isinstance(neu, dict) and neu.get("id"):
        # vom Bot geöffnete Tabs merken — nur SOLCHE darf er später als toten Login-Tab schließen (nie einen Tab des Menschen)
        eigene = [x for x in ((_augen_json_lesen("tsx_tabs.json") or {}).get("ids") or []) if isinstance(x, str)][-9:]
        _augen_json_schreiben("tsx_tabs.json", {"ids": eigene + [str(neu.get("id"))]})
    ende = time.time() + warten_s
    while time.time() < ende:
        _warte(0.8, 0.4)
        t = tsx_targets(_cdp_http("/json/list"))
        if t and t[0].get("webSocketDebuggerUrl"):
            return t[0]
    trail.append(f"TopstepX-Tab nach {warten_s:.0f} s nicht in der Tab-Liste")
    return None


def _cdp_tab_schliessen(target_id):
    """Einen Tab im Puls-Chrome schließen (/json/close antwortet Text „Target is closing", kein JSON). -> True bei HTTP 200"""
    import urllib.request
    try:
        with urllib.request.urlopen(f"http://{PULS_CDP_HOST}:{PULS_CDP_PORT}/json/close/{target_id}", timeout=1.5) as r:
            return r.status == 200
    except Exception:
        return False


def _tsx_tabs_schliessen(trail=None):
    """Alle TopstepX-Tabs im Puls-Chrome schließen (Rückschaltung auf den alten Weg — keine zweite Sitzung). -> Anzahl"""
    n = 0
    for t in tsx_targets(_cdp_http("/json/list", timeout=1.0)):
        if t.get("id") and _cdp_tab_schliessen(t.get("id")):
            n += 1
    if n and trail is not None:
        trail.append(f"Topstep wieder über den alten Weg — {n} TopstepX-Tab(s) im Puls-Chrome geschlossen")
    return n


def cdp_tabs_kurz(liste, n=8):
    """REIN RECHNEND (testbar): Tab-Liste für die Spur — 'Titel (Adresse)' je Seite, gekürzt."""
    out = [f"{str(t.get('title') or '')[:24]} ({str(t.get('url') or '')[:44]})" for t in (liste or [])
           if isinstance(t, dict) and t.get("type") == "page"]
    return " | ".join(out[:n]) + (f" | +{len(out) - n}" if len(out) > n else "") if out else "keine"


def _puls_chrome_wo():
    """Welches Chrome ist das? Port + Profilordner, mit dem der Bot das Puls-Chrome startet (puls_chrome_argumente lässt keinen anderen
    zu). Die echte Kommandozeile gibt Chrome per CDP nur mit --enable-automation her (Prüfer 30.09.2026) — deshalb ehrlich „Soll". -> Text"""
    return f"Puls-Chrome Port {PULS_CDP_PORT}, Profilordner (Soll) {puls_chrome_profil_pfad()}"


def _tsx_sitzung_waehlen(trail, sitz=None):
    """TopstepX-Sitzung im Puls-Chrome: Tab finden/öffnen, Login-Lage klären. -> (Sitzung | None, True | Fehlertext)
    sitz = [Sitzung] des Aufrufers: wird SOFORT gesetzt (und beim Tab-Wechsel ersetzt), damit finally/Wachhund sie auch dann schließen
    und das Fenster minimieren, wenn im Login-Teil etwas wirft.
    Live 30.09.2026 11:11–11:15 UTC (erster Topstep-PC): der Bot-Tab zeigte die alte Login-Seite, der Nutzer war in einem ANDEREN Tab desselben
    Puls-Chrome angemeldet. Deshalb bei einer Login-Seite: alle Tabs in die Spur, einen anderen TopstepX-Tab OHNE Login-Seite nehmen
    (den toten Login-Tab nur schließen, wenn der Bot ihn selbst geöffnet hat), sonst _tsx_cdp_login (Autofill abwarten, EINMAL neu
    laden, Klick nur mit Beweis)."""
    ziel = _tsx_tab_sicher(trail)
    if not ziel:
        return None, "TopstepX-Tab im Puls-Chrome nicht erreichbar."
    s = _AugenSitzung(trail, ziel=ziel, js_datei="augen_tsx.js", tv_riegel=False)
    if sitz is not None:
        sitz[0] = s

    def login_seite(sz):
        b = sz.lese_js(TSX_K0_BLICK_JS) or {}
        return bool((b.get("login") or {}).get("seite")) if isinstance(b.get("login"), dict) else False

    if login_seite(s):
        liste = _cdp_http("/json/list") or []
        trail.append(f"TopstepX-Login-Seite im Tab {str(ziel.get('url'))[:40]} — Tabs: {cdp_tabs_kurz(liste)} · {_puls_chrome_wo()}")
        eigene = (_augen_json_lesen("tsx_tabs.json") or {}).get("ids") or []
        for t in tsx_targets(liste):
            if t.get("id") == ziel.get("id") or not t.get("webSocketDebuggerUrl"):
                continue
            s2 = None
            try:
                s2 = _AugenSitzung(trail, ziel=t, js_datei="augen_tsx.js", tv_riegel=False)
                if not login_seite(s2):
                    trail.append(f"anderer TopstepX-Tab ist angemeldet ({str(t.get('url'))[:40]}) — nehme diesen")
                    if ziel.get("id") in eigene and _cdp_tab_schliessen(ziel.get("id")):
                        trail.append("eigenen Login-Tab geschlossen")
                    if sitz is not None:
                        sitz[0] = s2
                    s.zu()
                    return s2, True
                s2.zu()
            except Exception as e_:
                trail.append(f"Tab {str(t.get('url'))[:30]} nicht prüfbar ({type(e_).__name__})")
                if s2:
                    s2.zu()
    return s, _tsx_cdp_login(s, trail)


def _cdp_tab_zeigen(target_id, trail):
    """Tab nach vorn und sein Fenster auf „normal" (Hand-Login: das Puls-Chrome liegt sonst minimiert). Nur Browser-Befehle, kein Klick."""
    _cdp_http(f"/json/activate/{target_id}")
    v = _cdp_http("/json/version")
    if not (v or {}).get("webSocketDebuggerUrl"):
        return
    ws = None
    try:
        ws = _CdpVerbindung(v["webSocketDebuggerUrl"], timeout=4.0)
        w = ws.rufe("Browser.getWindowForTarget", {"targetId": target_id}, timeout=4)
        ws.rufe("Browser.setWindowBounds", {"windowId": w.get("windowId"), "bounds": {"windowState": "normal"}}, timeout=4)
        trail.append("Puls-Chrome-Fenster sichtbar (normal)")
    except Exception as e:
        trail.append(f"Fenster nicht sichtbar gemacht ({type(e).__name__}) — bitte das Puls-Chrome in der Taskleiste öffnen")
    finally:
        if ws:
            ws.zu()


# Lese-Blick für K0 (NUR LESEN, klickt nie): Login-Lage (Knopf „PLATFORM LOGIN", Felder mit Autofill-Markierung — Werte nie),
# Kandidaten für den Konto-Auslöser ('$…K … | KENNUNG') und das Bracket-Zahnrad („Manage brackets" bzw. kleiner Knopf rechts neben
