TSX_K0_BLICK_JS = r"""(function () {
  function sb(e) { try { if (!e || !e.getBoundingClientRect) return false; var r = e.getBoundingClientRect(); if (r.width < 3 || r.height < 3) return false;
    if (r.bottom < 0 || r.right < 0 || r.top > innerHeight || r.left > innerWidth) return false; var s = getComputedStyle(e);
    return s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0'; } catch (_) { return false; } }
  function R(e) { var r = e.getBoundingClientRect(); return [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)]; }
  function T(e) { return String((e && e.textContent) || '').replace(/\s+/g, ' ').trim(); }
  function A(e, n) { try { return e.getAttribute(n) || ''; } catch (_) { return ''; } }
  function Q(s, w) { try { return Array.prototype.slice.call((w || document).querySelectorAll(s)); } catch (_) { return []; } }
  function innen(l) { return l.filter(function (e) { return !l.some(function (f) { return f !== e && e.contains(f); }); }); }
  function af(e) { try { return e.matches(':-webkit-autofill'); } catch (_) { try { return e.matches(':autofill'); } catch (__) { return false; } } }
  function zeiger(e) { try { return getComputedStyle(e).cursor === 'pointer'; } catch (_) { return false; } }
  function K(e) { return { tag: e.tagName.toLowerCase(), text: T(e).slice(0, 90), aria: A(e, 'aria-label').slice(0, 60), title: A(e, 'title').slice(0, 60),
    role: A(e, 'role'), testid: A(e, 'data-testid').slice(0, 40), rect: R(e), aus: !!(e.disabled || A(e, 'aria-disabled') === 'true'),
    popup: A(e, 'aria-haspopup'), offen: A(e, 'aria-expanded') }; }
  var KLICKBAR = 'button,[role="button"],[role="combobox"],[aria-haspopup],a[href],[tabindex]';
  var RX_KONTO = /\$\s*\d+(?:[.,]\d+)?\s*K\b[^|]*\|/i;
  var o = { url: String(location.href).slice(0, 160), titel: String(document.title).slice(0, 80), fokus: document.hasFocus() };
  // Login-Seite (B27: topstepx.com/login, gelber Knopf „PLATFORM LOGIN", Felder von Chrome vorausgefüllt)
  var pws = Q('input[type="password"]').filter(sb);
  var lk = innen(Q('button,[role="button"],input[type="submit"]').filter(sb).filter(function (e) {
    return /^\s*(platform\s+)?log\s?in\s*$/i.test(T(e) || A(e, 'value') || A(e, 'aria-label')); }));
  var lg = { seite: /\/(login|signin|sign-in)\b/i.test(location.pathname) || (pws.length > 0 && lk.length > 0), knoepfe: lk.length,
             knopf: lk.length === 1 ? K(lk[0]) : null, pw_n: pws.length };
  if (pws.length) {
    var pw = pws[0], box = pw.closest('form') || document.body;
    var felder = Q('input', box).filter(sb).filter(function (e) { var t = String(e.type || 'text').toLowerCase();
      return (t === 'text' || t === 'email') && !e.readOnly && !e.disabled; });
    var vor = felder.filter(function (e) { return !!(e.compareDocumentPosition(pw) & 4); });
    var u = vor.length ? vor[vor.length - 1] : null;
    lg.pw = { rect: R(pw), gefuellt: String(pw.value || '').length > 0, autofill: af(pw), fokus: document.activeElement === pw };
    lg.user = u ? { rect: R(u), gefuellt: String(u.value || '').length > 0, autofill: af(u), fokus: document.activeElement === u } : null;
  }
  var bt = document.body ? T(document.body) : '';
  var fm = bt.match(/(invalid|incorrect|wrong password|login failed|access denied|locked|too many attempts)[^.]{0,80}/i);
  lg.fehler_text = fm ? fm[0].slice(0, 100) : null;
  lg.zwei_faktor = /captcha|verification code|two.?factor|2fa|one.?time (pass)?code|code (was )?sent|recaptcha/i.test(bt);
  o.login = lg;
  // Konto-Auslöser: klickbare Elemente mit '$…K … |' (innerstes), dazu wie viele Konto-Zeilen sichtbar sind
  o.konto = innen(Q(KLICKBAR + ',div,span').filter(sb).filter(function (e) {
    var t = T(e); if (!RX_KONTO.test(t) || t.length > 140) return false;
    return e.matches(KLICKBAR) || zeiger(e);
  })).slice(0, 8).map(K);
  o.konto_zeilen = innen(Q('div,li,span,button,[role="option"],[role="menuitem"]').filter(sb).filter(function (e) {
    var t = T(e); return RX_KONTO.test(t) && t.length <= 140; })).length;
  // Bracket-Zahnrad: benannt („Manage brackets"), sonst kleine Knöpfe rechts neben dem Text „Position Bracket"
  var gear = innen(Q(KLICKBAR + ',svg').filter(sb).filter(function (e) {
    return /manage\s*brackets?/i.test(A(e, 'aria-label') + ' ' + A(e, 'title') + ' ' + T(e)); }));
  if (!gear.length) {
    var pb = innen(Q('div,span,label,p').filter(sb).filter(function (e) { return /^position\s*brackets?$/i.test(T(e)); }));
    if (pb.length === 1) {
      var pr = pb[0].getBoundingClientRect(), my = pr.top + pr.height / 2;
      gear = innen(Q(KLICKBAR + ',svg').filter(sb).filter(function (e) {
        var q = e.getBoundingClientRect();
        return q.left >= pr.right - 2 && q.left <= pr.right + 120 && Math.abs(q.top + q.height / 2 - my) <= 14 && q.width <= 44 && q.height <= 44
               && !/position\s*bracket/i.test(T(e)); }));
    }
  }
  o.bracket = gear.slice(0, 6).map(K);
  o.dialoge = Q('[role="dialog"],[role="alertdialog"],[aria-modal="true"]').filter(sb).slice(0, 4).map(function (d) {
    var x = innen(Q('button,[role="button"]', d).filter(sb).filter(function (e) {
      var w = A(e, 'aria-label') + ' ' + A(e, 'title') + ' ' + T(e); return /\bclose\b|schlie|dismiss|^\s*[×✕✖]\s*$/i.test(w) && T(e).length <= 12; }));
    return { titel: T(d.querySelector('h1,h2,h3,h4,[class*="title"],[class*="header"]')).slice(0, 60), text: T(d).slice(0, 160), rect: R(d),
             x: x.length === 1 ? K(x[0]) : null, x_n: x.length };
  });
  // Offene Listen und Dialog-Inhalt eigens (Live 30.09.2026 11:18 UTC): das Inventar kappt von hinten, MUI-Popover hängen am Ende
  // von body — die Kontozeilen fehlten in der Elementliste. Werte nur ohne Passwortfeld im Dialog, Passwörter nie.
  function KZ(e) { var k = K(e); k.sel = A(e, 'aria-selected'); k.dis = A(e, 'aria-disabled'); k.dv = A(e, 'data-value').slice(0, 60);
    k.id = String(e.id || '').slice(0, 40); k.cls = String(typeof e.className === 'string' ? e.className : '').slice(0, 50); return k; }
  o.menues = Q('[role="listbox"],[role="menu"]').filter(sb).slice(0, 3).map(function (m) {
    return { role: A(m, 'role'), rect: R(m), id: String(m.id || '').slice(0, 40), label: A(m, 'aria-labelledby').slice(0, 40),
             eintraege: Q('[role="option"],[role="menuitem"],li', m).filter(sb).slice(0, 30).map(KZ) }; });
  // Werte NUR als Zahl (Risk/Profit im Bracket-Dialog) und nie, wenn der Dialog oder das Feld nach Zugangsdaten aussieht — gleiche
  // Vorsicht wie geheim() in augen_tsx.js (Prüfer 30.09.2026: 2FA-Code, Benutzername, sichtbar geschaltetes Passwort)
  var RX_GEHEIM = /pass|pin\b|cvc|otp|one.?time|code|user|mail|log.?in|sign.?in|anmeld|verif|2fa|two.?factor|token|secret/i;
  o.dialog_inhalt = innen(Q('[role="dialog"],[role="alertdialog"],[aria-modal="true"]').filter(sb)).slice(0, 2).map(function (d) {
    var geheim = Q('input[type="password"]', d).length > 0 || RX_GEHEIM.test(T(d).slice(0, 400));
    return { rect: R(d), geheim: geheim,
      felder: Q('input,select,textarea,button,[role="button"],[role="combobox"],[role="switch"],label,h1,h2,h3,h4,[data-testid]', d).filter(sb).slice(0, 40).map(function (e) {
        var k = KZ(e); k.text = k.text.slice(0, 40); k.cls = ''; k.typ = String(e.type || '').slice(0, 12); k.name = A(e, 'name').slice(0, 30); k.ph = A(e, 'placeholder').slice(0, 30);
        var v = e.value === undefined ? '' : String(e.value), fg = geheim || /password|email/i.test(k.typ) ||
                RX_GEHEIM.test(k.name + ' ' + k.ph + ' ' + k.id + ' ' + k.aria + ' ' + A(e, 'autocomplete'));
        k.wert = (!fg && /^[-+$€%.,\d\s]{1,14}$/.test(v)) ? v : ''; return k; }),
      kaestchen: Q('input[type="checkbox"],input[type="radio"],[role="checkbox"],[role="switch"]', d).slice(0, 20).map(function (e) {
        var l = e.closest('label') || e.parentElement, z = sb(e) ? e : (l && sb(l) ? l : null);
        return { an: e.checked === undefined ? A(e, 'aria-checked') === 'true' : !!e.checked, text: T(l).slice(0, 60), testid: A(e, 'data-testid').slice(0, 40),
                 rect: z ? R(z) : null, aus: !!(e.disabled || A(e, 'aria-disabled') === 'true') }; }) }; });
  o.bracket_dialog = o.dialoge.some(function (d) { return /bracket/i.test(d.titel + ' ' + d.text); }) ||
                     /position\s*brackets?[\s\S]{0,200}(risk|profit)/i.test(Q('[role="dialog"],[aria-modal="true"]').filter(sb).map(T).join(' '));
  return o;
})()"""

# Chart-Blick (Master-Merkposten 30.09.2026: Finn will SL/TP später per Drag & Drop an der Positions-/Orderlinie im TopstepX-Chart
# setzen): ist die Positionslinie mit ziehbaren SL/TP-Griffen im DOM greifbar oder nur Canvas? Liest nur — Canvas-Flächen, iframes
# (gleiche Herkunft → innen lesbar), DOM-Knoten mit Linien-/Griff-Merkmalen. Noch KEIN Umbau, nur die Fakten fürs Inventar.
TSX_K0_CHART_JS = r"""(function () {
  function R(e) { var r = e.getBoundingClientRect(); return [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)]; }
  function T(e) { return String((e && e.textContent) || '').replace(/\s+/g, ' ').trim(); }
  function A(e, n) { try { return e.getAttribute(n) || ''; } catch (_) { return ''; } }
  function blick(doc, tiefe) {
    var out = { canvas: [], linien: [], iframes: [] };
    try {
      Array.prototype.slice.call(doc.querySelectorAll('canvas')).forEach(function (c) {
        var r = c.getBoundingClientRect(); if (r.width * r.height >= 20000 && out.canvas.length < 12) out.canvas.push(R(c)); });
      var rx = /(order|position|bracket|stop|take.?profit|sl|tp)[-_ ]?(line|handle|drag|label|marker)|draggable|drag-handle/i;
      Array.prototype.slice.call(doc.querySelectorAll('*')).forEach(function (e) {
        if (out.linien.length >= 20) return;
        var c = typeof e.className === 'string' ? e.className : ((e.className && e.className.baseVal) || '');
        var m = c + ' ' + A(e, 'data-testid') + ' ' + A(e, 'data-name') + ' ' + A(e, 'aria-label') + ' ' + (A(e, 'draggable') === 'true' ? 'draggable' : '');
        if (/MuiDataGrid/.test(c)) return;               // Live 30.09.2026: 13 Spaltenköpfe der Trades-Tabelle galten als „Linien"
        if (rx.test(m)) out.linien.push({ tag: e.tagName.toLowerCase(), cls: c.slice(0, 60), testid: A(e, 'data-testid').slice(0, 40),
                                          text: T(e).slice(0, 40), rect: R(e) }); });
      if (tiefe < 2) Array.prototype.slice.call(doc.querySelectorAll('iframe')).slice(0, 6).forEach(function (f) {
        var i = { src: String(f.src || '').slice(0, 120), rect: R(f), gleiche_herkunft: false };
        try { if (f.contentDocument && f.contentDocument.body) { i.gleiche_herkunft = true; i.innen = blick(f.contentDocument, tiefe + 1); } } catch (_) {}
        out.iframes.push(i); });
    } catch (e) { out.fehler = String(e).slice(0, 80); }
    return out;
  }
  return blick(document, 0);
})()"""


def tsx_k0_eindeutig(kandidaten, art):
    """REIN RECHNEND (testbar): GENAU EIN klickbarer Kandidat (Konto-Auslöser bzw. Bracket-Zahnrad), nie gesperrt, nie mit einem
    Order-/Close-/Flatten-Wort (TSX_K0_TABU). -> (element | None, grund)"""
    k = [e for e in (kandidaten or []) if isinstance(e, dict) and isinstance(e.get("rect"), (list, tuple)) and len(e["rect"]) >= 4
         and str(e.get("role") or "").lower() not in ("option", "menuitem", "listitem", "menuitemradio")]   # nie eine Listen-Zeile
    if art == "konto":
        k = [e for e in k if tsx_konto_sichtbar(e.get("text"))[0] or TSX_RX_OHNE_ID.match(str(e.get("text") or ""))]
    tabu = [e for e in k if TSX_K0_TABU.search(" ".join(str(e.get(f) or "") for f in ("text", "aria", "title", "testid")))]
    k = [e for e in k if e not in tabu and not e.get("aus")]
    if len(k) != 1:
        return None, f"{len(k)} Kandidaten" + (f" (+{len(tabu)} mit Order-/Close-Wort verworfen)" if tabu else "")
    return k[0], ""


def tsx_login_beweis(lg):
    """REIN RECHNEND (testbar): Darf Puls EINMAL „PLATFORM LOGIN" drücken? Nur mit genau einem Knopf und beiden Feldern gefüllt bzw.
    von Chrome als Autofill markiert (Werte nie gelesen); nie bei 2FA/Captcha oder Fehlermeldung. -> (ok, text)"""
    lg = lg if isinstance(lg, dict) else {}
    u = lg.get("user") if isinstance(lg.get("user"), dict) else {}
    p = lg.get("pw") if isinstance(lg.get("pw"), dict) else {}
    # nur Chromes Autofill-Markierung zählt (Prüfer K0: „gefüllt" bleibt nach einem Fehlversuch stehen → jeder Lauf klickte erneut)
    u_ok, p_ok = bool(u.get("autofill")), bool(p.get("autofill"))
    text = (f"Benutzer {'von Chrome ausgefüllt' if u_ok else ('gefüllt, aber nicht von Chrome' if u.get('gefuellt') else 'LEER')}, "
            f"Passwort {'von Chrome ausgefüllt' if p_ok else ('gefüllt, aber nicht von Chrome' if p.get('gefuellt') else 'LEER')}, "
            f"Login-Knöpfe {lg.get('knoepfe', 0)} (Werte nie gelesen)")
    if lg.get("zwei_faktor"):
        return False, text + " — 2FA/Captcha auf der Seite"
    if lg.get("fehler_text"):
        return False, text + f" — Meldung '{str(lg.get('fehler_text'))[:60]}'"
    return bool(u_ok and p_ok and isinstance(lg.get("knopf"), dict)), text


def tsx_inventar_deckeln(daten, max_bytes=TSX_INVENTAR_MAX):
    """REIN RECHNEND (testbar): puls_augen-Zeile unter max_bytes — erst Blatt-Texte, dann Elemente von hinten kürzen (Kopf bleibt),
    Zähler inventar.gekuerzt. -> daten (Kopie)"""
    d = json.loads(json.dumps(daten, ensure_ascii=False, default=str))
    inv = d.get("inventar") if isinstance(d.get("inventar"), dict) else {}
    n = 0
    while len(json.dumps(d, ensure_ascii=False)) > max_bytes and n < 60:
        n += 1
        if len(inv.get("blatt") or []) > 40:
            inv["blatt"] = inv["blatt"][:int(len(inv["blatt"]) * 0.8)]
        elif len(inv.get("elemente") or []) > 40:
            inv["elemente"] = inv["elemente"][:int(len(inv["elemente"]) * 0.85)]
        elif isinstance(inv.get("stand"), dict) and not inv["stand"].get("gekuerzt"):
            inv["stand"] = {"gekuerzt": True}
        elif isinstance(inv.get("chart"), dict) and not inv["chart"].get("gekuerzt"):
            inv["chart"] = {"gekuerzt": True}
        elif isinstance(inv.get("k0_blick"), dict) and any(len(d_.get("felder") or []) > 12 for d_ in inv["k0_blick"].get("dialog_inhalt") or []
                                                           if isinstance(d_, dict)):
            for d_ in inv["k0_blick"]["dialog_inhalt"]:        # Prüfer: der Blick wuchs ungebremst → Railway lehnte die ganze Zeile ab
                if isinstance(d_, dict) and isinstance(d_.get("felder"), list):
                    d_["felder"] = d_["felder"][:max(12, int(len(d_["felder"]) * 0.6))]
        elif isinstance(inv.get("k0_blick"), dict) and (inv["k0_blick"].get("menues") or inv["k0_blick"].get("dialog_inhalt")):
            inv["k0_blick"]["menues"], inv["k0_blick"]["dialog_inhalt"] = [], []
        else:
            break
        inv["gekuerzt"] = n
    return d


def _tsx_k0_lesen(s, trail, zustand, pc, blick=None):
    """Inventar + Stand + Chart-Blick im aktuellen Zustand → puls_augen (inventar_tsx_<zustand>; beim Grundzustand auch stand_tsx)
    und lokal tsx_inventar_cdp_<zustand>.json. -> Kurzinfo | None"""
    import urllib.request
    t0 = time.time()
    ausdruck = ("(async () => { const A = globalThis.prophosAugen; if (!A) return {fehler: 'prophosAugen fehlt'};"
                " return {stand: await A.stand(), inventar: A.inventar ? await A.inventar() : null}; })()")
    wert = s.lese_js(ausdruck, timeout=15)
    if not isinstance(wert, dict) or wert.get("fehler"):
        s._seite_abwarten(10.0)
        s._augen_laden()
        wert = s.lese_js(ausdruck, timeout=15)
    if not isinstance(wert, dict) or wert.get("fehler") or not isinstance(wert.get("inventar"), dict):
        trail.append(f"Inventar ({zustand}) nicht lesbar ({(wert or {}).get('fehler') if isinstance(wert, dict) else 'keine Antwort'})")
        return None
    inv = wert["inventar"]
    try:
        inv["chart"] = s.lese_js(TSX_K0_CHART_JS, timeout=10)
    except Exception as e_:
        inv["chart"] = {"fehler": type(e_).__name__}
    if isinstance(blick, dict):
        inv["k0_blick"] = {k: blick.get(k) for k in ("konto", "konto_zeilen", "bracket", "dialoge", "bracket_dialog", "menues", "dialog_inhalt")}
    stand = wert.get("stand") if isinstance(wert.get("stand"), dict) else {}
    kopf = {"zustand": zustand, "bot": puls_bot_stand(), "target": str(inv.get("url") or "")[:200], "dauer_ms": int((time.time() - t0) * 1000)}
    daten = tsx_inventar_deckeln(dict(kopf, inventar=inv))
    try:
        with open(os.path.join(_AUGEN_HIER, f"tsx_inventar_cdp_{zustand}.json"), "w", encoding="utf-8") as f:
            json.dump(dict(kopf, inventar=inv, stand=stand), f, ensure_ascii=False, default=str)
    except Exception:
        pass
    pakete = [("inventar_tsx_" + zustand, daten)]
    if zustand == "grund" and stand:
        pakete.append(("stand_tsx", tsx_inventar_deckeln(dict(stand, zustand=zustand, bot=kopf["bot"], target=kopf["target"]))))
    geschrieben = []
    for art, d in pakete:
        if not pc:
            break
        body = json.dumps({"art": art, "daten": d}, ensure_ascii=False, default=str).encode("utf-8")
        try:
            req = urllib.request.Request(f"{PULS_BACKEND}/puls-augen/{pc}", data=body, headers={"Content-Type": "application/json"})
            urllib.request.urlopen(req, timeout=8.0).read()
            geschrieben.append(art)
        except Exception as e_:
            trail.append(f"puls_augen ({art}) nicht geschrieben ({type(e_).__name__}, {len(body)} Bytes)")
    ch = inv.get("chart") if isinstance(inv.get("chart"), dict) else {}
    trail.append(f"Inventar {zustand}: {len(inv.get('elemente') or [])} Elemente, {len(inv.get('blatt') or [])} Texte, "
                 f"Chart {len(ch.get('canvas') or [])} Canvas/{len(ch.get('iframes') or [])} iframes/{len(ch.get('linien') or [])} Linien-Knoten"
                 + (f" → {', '.join(geschrieben)}" if geschrieben else ""))
    return {"zustand": zustand, "arts": geschrieben, "elemente": len(inv.get("elemente") or [])}


def _tsx_cdp_login(s, trail):
    """TopstepX-Login-Seite im Puls-Chrome? Dann höchstens EIN Klick auf „PLATFORM LOGIN" — nur mit Autofill-Beweis (tsx_login_beweis),
    nie tippen, nie Enter, kein zweiter Versuch. -> True (angemeldet) | Fehlertext"""
    def blick():
        b = s.lese_js(TSX_K0_BLICK_JS) or {}
        return b.get("login") if isinstance(b.get("login"), dict) else {}

    def warten(lg_):
        """Bis ~6 s auf Chromes Autofill-Markierung (nur lesen). -> (login-Blick | None = Login-Seite weg, ok, text)"""
        ok_, text_ = tsx_login_beweis(lg_)
        for _ in range(6):
            if ok_ or lg_.get("fehler_text") or lg_.get("zwei_faktor"):
                break
            _warte(1.0, 0.3)
            lg_ = blick()
            if not lg_.get("seite"):
                return None, False, ""
            ok_, text_ = tsx_login_beweis(lg_)
        return lg_, ok_, text_

    lg = blick()
    if not lg.get("seite"):
        return True
    # 01.10.2026 (Kette in einem Lauf): nach dem Kaltstart liegt das Puls-Chrome minimiert — Chrome füllt ein Formular im minimierten
    # Fenster womöglich nicht aus. Vor dem Warten auf die Autofill-Markierung das Fenster nach vorn (nur Fenster, kein Klick).
    if _WIN_EINGABE:
        try:
            s._win_vorn()
        except Exception as e_:
            trail.append(f"Login: Fenster nicht nach vorn ({type(e_).__name__})")
    # Live 30.09.2026 11:11/11:15 UTC (erster Topstep-PC): „Benutzer LEER, Passwort LEER" — beim ersten Mal 2,6 s nach dem Öffnen des Tabs
    # (Chrome füllt ein spät gezeichnetes Formular erst etwas später aus), beim zweiten Mal stand der Tab noch auf der ALTEN Login-Seite,
    # obwohl der Nutzer sich inzwischen in einem anderen Tab desselben Puls-Chrome angemeldet hatte (TopstepX lädt sich nicht selbst neu).
    # Deshalb: erst kurz auf die Autofill-Markierung warten, dann den Tab EINMAL neu laden (Navigation, kein Klick) und erneut schauen.
    lg, ok, text = warten(lg)
    if lg is None:
        trail.append("TopstepX: Login-Seite von selbst weg (Sitzung gültig)")
        return True
    def feld_frei(f):
        return not (isinstance(f, dict) and (f.get("gefuellt") or f.get("fokus")))

    letzt0 = _augen_json_lesen("tsx_login.json") or {}
    try:
        gesperrt = bool(letzt0.get("at")) and 0 <= time.time() - float(letzt0["at"]) < TSX_LOGIN_SPERRE_S
    except (TypeError, ValueError):
        gesperrt = False
    # Neuladen NUR, wenn niemand gerade von Hand anmeldet (Prüfer 30.09.2026: getippte Eingaben wären weg) — beide Felder leer, kein
    # Feld im Fokus — und nicht innerhalb der Login-Sperre (dann folgt ohnehin kein Klick)
    if not ok and not lg.get("fehler_text") and not lg.get("zwei_faktor") and not gesperrt \
            and feld_frei(lg.get("user")) and feld_frei(lg.get("pw")):
        try:
            s.ws.rufe("Page.navigate", {"url": TSX_URL}, timeout=8)
            trail.append("TopstepX-Login-Seite ohne Autofill — Tab einmal neu geladen (topstepx.com/trade)")
            _warte(1.5, 0.5)
            s._seite_abwarten(20.0)
            s._augen_laden()
            _warte(1.5, 0.5)                             # die App entscheidet erst nach dem Laden: Handelsseite oder zurück zum Login
            lg = blick()
            if not lg.get("seite"):
                trail.append("TopstepX nach dem Neuladen angemeldet (Sitzung aus einem anderen Tab)")
                return True
            lg, ok, text = warten(lg)
            if lg is None:
                trail.append("TopstepX nach dem Neuladen angemeldet")
                return True
        except Exception as e_:
            trail.append(f"Neuladen des TopstepX-Tabs nicht möglich ({type(e_).__name__}) — urteile nach dem alten Stand")
            lg = lg or {}
    trail.append(f"TopstepX-Login-Seite: {text}")
    letzt = _augen_json_lesen("tsx_login.json") or {}
    try:
        seit = time.time() - float(letzt["at"]) if letzt.get("at") else 1e9
    except (TypeError, ValueError):
        seit = 1e9
    if 0 <= seit < TSX_LOGIN_SPERRE_S:
        # Prüfer K0: ein Login-Klick ohne Erfolg darf sich nicht Lauf für Lauf wiederholen (Fehlversuche bis zur Kontosperre)
        return (f"TopstepX zeigt wieder die Login-Seite, der letzte Login-Klick war vor {int(seit // 60)} min — kein neuer Versuch. "
                "Bitte im Puls-Chrome von Hand anmelden (`python order_bot.py augen start tsx`).")
    if not ok:
        return (f"TopstepX im Puls-Chrome nicht angemeldet ({text}; {_puls_chrome_wo()}) — bitte genau in DIESEM Chrome einmal von "
                "Hand anmelden und das Passwort speichern (`python order_bot.py augen start tsx` holt das Fenster nach vorn).")
    _augen_json_schreiben("tsx_login.json", {"at": time.time()})    # vor dem Druck merken — auch ein Absturz danach zählt als Versuch
    _tsx_pause()                                           # menschliches Tempo vor dem Login-Klick (Finn 01.10.2026)
    if not s.klick(lg["knopf"]["rect"], "PLATFORM LOGIN (Autofill bewiesen)",
                   pruef={"rect": lg["knopf"].get("rect"), "text": "login", "aria": "", "tabu": r"\b(buy|sell|order|logout|log out)\b"}):
        return "Login-Knopf nicht gedrückt (Klick ohne Beweis) — nichts weiter versucht."
    ende = time.time() + 25.0
    while time.time() < ende:
        _warte(1.0, 0.4)
        try:
            b2 = s.lese_js(TSX_K0_BLICK_JS) or {}
        except Exception:
            continue                                        # Seite lädt gerade neu
        l2 = b2.get("login") if isinstance(b2.get("login"), dict) else {}
        if not l2.get("seite"):
            s._seite_abwarten(15.0)
            s._augen_laden()
            trail.append("TopstepX angemeldet (Login-Seite weg)")
            return True
        if l2.get("fehler_text") or l2.get("zwei_faktor"):
            return f"TopstepX-Login nach dem Klick: '{l2.get('fehler_text') or '2FA/Captcha'}' — nicht angemeldet, kein zweiter Versuch."
    return "TopstepX zeigt 25 s nach dem Login-Klick weiter die Login-Seite — kein zweiter Versuch, bitte im Puls-Chrome nachsehen."


def tsx_k0_pruef(el):
    """REIN RECHNEND (testbar): Ziel-Merkmale für den Druck (win_ziel_pruef_js) — Rechteck, Text (Konto: die sichtbare Kennung, sonst
    der Anfang), Beschriftung, Tabu-Wörter."""
    t = str(el.get("text") or "")
    kenn = tsx_konto_sichtbar(t)[0]
    return {"rect": list(el.get("rect") or [])[:4], "text": (kenn or " ".join(t.split())[:24]).strip()[:40],
            "aria": str(el.get("aria") or el.get("title") or "")[:40], "tabu": TSX_K0_TABU.pattern}


def _tsx_k0_esc(s, bl, trail, grund, erlaubt_dialog=False):
    """Esc im K0 — nie, solange ein FREMDER Dialog offen ist (erlaubt_dialog: nur der eigene Bracket-Dialog darf offen sein); Windows-
    Fehler werfen nicht. -> True, wenn gedrückt"""
    dlg = [d for d in ((bl or {}).get("dialoge") or []) if isinstance(d, dict)]
    fremd = [d for d in dlg if not (erlaubt_dialog and re.search(r"bracket", str(d.get("titel")) + " " + str(d.get("text")), re.I))]
    if fremd:
        trail.append(f"{grund}: fremder Dialog offen ('{str(fremd[0].get('titel') or fremd[0].get('text') or '')[:40]}') — kein Esc")
        return False
    try:
        s.taste("Escape")
    except Exception as e_:
        trail.append(f"{grund}: Esc nicht möglich ({type(e_).__name__})")
        return False
    trail.append(f"{grund} → Esc")
    return True


def _tsx_k0_zustand(s, trail, pc, art, res):
    """Konto-Liste bzw. Bracket-Dialog EINMAL öffnen (genau ein Kandidat, Windows-Maus mit Ziel-Beweis beim Druck), Wirkung beweisen,
    Inventar, wieder zu (X nur im Bracket-Dialog, sonst Esc ohne fremde Dialoge) und das Schließen beweisen. -> True, wenn inventarisiert
    Prüfer K0 (30.09.2026): das Rechteck erst NACH dem Nach-vorn-Holen lesen (ein Hintergrund-Tab holt beim bringToFront Änderungen nach,
    z. B. fällt der „Weekend Hours"-Banner weg und alles rutscht 43 px) — und beim Druck beweisen, dass dort genau der Kandidat liegt."""
    name = "Konto-Auslöser" if art == "konto" else "Bracket-Zahnrad"
    if _WIN_EINGABE:
        hw, gr = s._win_vorn()
        if not hw:
            trail.append(f"{name}: {gr} — nichts geklickt")
            res.setdefault("offen", []).append(f"{art}: {gr}")
            return False
        _warte(0.6, 0.3)
    bl = s.lese_js(TSX_K0_BLICK_JS) or {}
    if art == "bracket" and (bl.get("dialoge") or []):
        trail.append(f"{name}: es ist schon ein Dialog offen — nichts geklickt")
        res.setdefault("offen", []).append(f"{art}: Dialog offen")
        return False
    el, grund = tsx_k0_eindeutig(bl.get(art), art)
    if not el:
        trail.append(f"{name} nicht eindeutig ({grund}) — nichts geklickt")
        res.setdefault("offen", []).append(f"{art}: {grund}")
        return False
    vorher_z, vorher_d = int(bl.get("konto_zeilen") or 0), bool(bl.get("bracket_dialog"))
    if not s.klick(el["rect"], f"{name} ('{str(el.get('text') or el.get('aria') or '')[:40]}')", pruef=tsx_k0_pruef(el)):
        res.setdefault("offen", []).append(f"{art}: Klick ohne Beweis")
        return False
    b2 = {}
    for _ in range(5):                                      # Treffer ≠ Wirkung (Regel .835)
        _warte(0.6, 0.3)
        b2 = s.lese_js(TSX_K0_BLICK_JS) or {}
        if (art == "konto" and int(b2.get("konto_zeilen") or 0) > vorher_z) or (art == "bracket" and b2.get("bracket_dialog") and not vorher_d):
            break
    else:
        trail.append(f"{name} geklickt, Wirkung nicht erkannt (Zeilen {vorher_z}→{b2.get('konto_zeilen')}, Dialog {b2.get('bracket_dialog')}) "
                     "— Inventar trotzdem (zeigt, was nach dem Klick steht)")
    info = _tsx_k0_lesen(s, trail, art, pc, blick=b2)
    if info:
        res["arts"] += info["arts"]
    # wieder zu: Bracket-Dialog über sein EINES X (frisch gelesen, nur wenn es DER Bracket-Dialog ist), sonst Esc — nie ein anderer Knopf
    b_x = s.lese_js(TSX_K0_BLICK_JS) or {}
    dlg = [d for d in (b_x.get("dialoge") or []) if isinstance(d, dict)]
    x = None
    if art == "bracket" and b_x.get("bracket_dialog") and len(dlg) == 1 and isinstance(dlg[0].get("x"), dict) \
            and re.search(r"bracket", str(dlg[0].get("titel")) + " " + str(dlg[0].get("text")), re.I):
        x = dlg[0]["x"]
    if not (x and s.klick(x["rect"], "Bracket-Dialog schließen (X)", pruef={"rect": x.get("rect"), "text": "", "aria": str(x.get("aria") or "")[:40],
                                                                       "tabu": r"\b(buy|sell|flatten|cancel|order|market|limit|all)\b"})):
        _tsx_k0_esc(s, b_x, trail, "Konto-Liste" if art == "konto" else "Bracket-Dialog", erlaubt_dialog=(art == "bracket"))
    _warte(0.6, 0.3)
    b3 = s.lese_js(TSX_K0_BLICK_JS) or {}
    zu = (int(b3.get("konto_zeilen") or 0) <= vorher_z) if art == "konto" else not b3.get("bracket_dialog")
    trail.append(f"{name}: wieder zu {'(bewiesen)' if zu else '— NICHT bewiesen, bitte im Puls-Chrome ansehen'}")
    if not zu:
        res.setdefault("offen", []).append(f"{art}: nach dem Inventar noch offen")
        res["_nicht_zu"] = True
    return bool(info)


# ─── K1: Lesen über CDP (Vorbau 30.09.2026, NICHT live — die DOM-Anker liefert Terminal 2 nach dem K0-Inventar in augen_tsx.js) ───
# Vertrag = tv-lesen (Orbit-V2-Rundgang, prophos.html tvV2): ok, konto_aktiv, positionen [{symbol, seite, menge, einstieg, pnl, *_zahl}]
# ([] = flach, None = unbekannt), summary {Label: Text}, today_pnl (TopstepX: RP&L des Tages + UP&L), today_label, alter_s, gelesen_at —
# dazu wie bisher balance/mll/rpl/upl/position/konto. alter_s NUR mit Frische-Beweis (Tab vorn + requestAnimationFrame läuft): ein
# gedrosselter Hintergrund-Tab zeigt alte Werte, und das Frontend zählt nur alter_s < 30. Der UIA-Weg lieferte nie alter_s.
# Erwartete stand()-Schlüssel von augen_tsx.js (Vorschlag an T2): konto {aktiv, kontonr, abgekuerzt}, kopf {balance|mll|rpl|upl: {text,
# wert}}, positionen [{symbol, seite, menge, avg, pl_text}], positionen_sichtbar (Positions-Bereich sichtbar: Zeilen oder „No Active
# Position"), flach (true/false/null). Fehlt ein Anker, antwortet K1 ehrlich 'anker_fehlt' — nie eine geratene Zahl.
TSX_FRISCH_JS = r"""(function () {
  return new Promise(function (ok) {
    var fertig = false, t0 = performance.now();
    function aus(v) { if (!fertig) { fertig = true; ok(v); } }
    try { requestAnimationFrame(function () { requestAnimationFrame(function () { aus({ raf: true, ms: Math.round(performance.now() - t0),
      sichtbar: document.visibilityState, fokus: document.hasFocus() }); }); }); } catch (e) { aus({ raf: false, fehler: String(e).slice(0, 60) }); }
    setTimeout(function () { aus({ raf: false, ms: Math.round(performance.now() - t0), sichtbar: document.visibilityState, fokus: document.hasFocus() }); }, 1500);
  });
})()"""


def tsx_frisch_urteil(f):
    """REIN RECHNEND (testbar): Frische-Beweis aus TSX_FRISCH_JS — Seite sichtbar und zwei Animations-Frames in ≤ 1,5 s (ein
    gedrosselter Hintergrund-Tab rendert nicht). -> (frisch, text)"""
    f = f if isinstance(f, dict) else {}
    ok = bool(f.get("raf")) and f.get("sichtbar") == "visible"
    return ok, f"Seite {'frisch' if ok else 'NICHT frisch'} (sichtbar {f.get('sichtbar') or '?'}, Frames {'ja' if f.get('raf') else 'nein'}, {f.get('ms', '?')} ms)"


TSX_K1_BEREIT_S = 20.0              # so lange wartet K1 auf Konto-Auslöser + BAL (Seite baut sich nach dem Laden noch auf) — 01.10.2026
                                    # von 8 auf 20 s: K0 sah 7,1 s nach dem Login noch eine leere Seite; die Kette „kalt → Login → K2" in
                                    # einem Lauf braucht das Fenster nach Kaltstart, Login und Kontowechsel. Ist die Seite bereit, geht es sofort weiter.


def _tsx_bereit_warten(s, trail, opts=None, sek=None):
    """Bereit-Probe für K0 und K1 — nur lesen, kein Klick: bis TSX_K1_BEREIT_S auf Konto-Auslöser + BAL warten (K0 30.09.2026: 0,8 s
    nach dem Start stand noch „Loading the Ultimate Trading Experience", 7,1 s nach dem Login war die Seite noch leer — 2 Elemente,
    Konto-Auslöser 0 Kandidaten). -> (stand, bereit)"""
    grenze = TSX_K1_BEREIT_S if sek is None else float(sek)
    t_ende = time.time() + grenze
    runden = 0
    while True:
        runden += 1
        st = s.stand(opts or {})
        if tsx_k1_bereit(st) or time.time() >= t_ende:
            break
        _warte(0.5, 0.4)
    bereit = tsx_k1_bereit(st)
    if runden > 1:
        trail.append(f"Bereit-Probe: {runden} Lesungen" + ("" if bereit else f" — nach {int(grenze)} s NICHT bereit"))
    return st, bereit


# TSX-LADEN (05.10.2026, Finn: „der Tab wird wieder minimiert, obwohl TopstepX noch lädt"): Live-Lauf auf einem Topstep-PC — 7,5 s
# nach dem Kaltstart waren Konto-Auslöser und BAL schon lesbar (Bereit-Probe bestanden, 3 Lesungen), der Lade-Schirm lag aber noch
# darüber; K2 brach sofort ab: „Konto-Auslöser verdeckt ('Loading the Ultimate Trading Experience') — Dialog offen?". Der Text ist der
# aus diesem Lauf (augen_tsx.js zustand(): oberstes Element am Mittelpunkt des Auslösers). Nur DIESE Verdeckung heißt „lädt noch";
# jede andere (echter Dialog) bleibt wie bisher ein sofortiger Abbruch.
TSX_LADEN_RX = re.compile(r"^\s*loading the ultimate", re.I)
TSX_LADEN_K2_S = 10.0               # so lange wartet K2 selbst noch (die Bereit-Probe davor hat schon bis TSX_K1_BEREIT_S gewartet)


def tsx_ladeschirm(ko):
    """REIN RECHNEND (testbar): liegt über dem Konto-Auslöser der TopstepX-Lade-Schirm? ko = stand.konto (zu.verdeckt + zu.oben.text)."""
    zu = ko.get("zu") if isinstance(ko, dict) and isinstance(ko.get("zu"), dict) else {}
    oben = zu.get("oben") if isinstance(zu.get("oben"), dict) else {}
    return bool(zu.get("verdeckt") and TSX_LADEN_RX.search(str(oben.get("text") or "")))


def tsx_k1_bereit(stand):
    """REIN RECHNEND (testbar): TopstepX aufgebaut? Konto-Auslöser gelesen UND BAL lesbar (beides kommt erst nach dem Lade-Schirm) —
    und seit 05.10.2026: der Lade-Schirm liegt nicht mehr über dem Auslöser (tsx_ladeschirm)."""
    st = stand if isinstance(stand, dict) else {}
    ko, kopf = st.get("konto"), st.get("kopf")
    return bool(isinstance(ko, dict) and ko.get("aktiv") and isinstance(kopf, dict) and _tsx_wert(kopf.get("balance")) is not None
                and not tsx_ladeschirm(ko))


def _tsx_wert(x):
    """Kopfwert aus augen_tsx.js: {wert} zuerst, sonst der Text im US-Format von TopstepX (tsx_geld: auch „$-50.00", „($50.00")."""
    if isinstance(x, dict):
        w = x.get("wert")
        return float(w) if isinstance(w, (int, float)) and not isinstance(w, bool) else tsx_geld(x.get("text"))
    return float(x) if isinstance(x, (int, float)) and not isinstance(x, bool) else tsx_geld(x)


def tsx_konto_urteil(ko, ext):
    """REIN RECHNEND (testbar): steht in TopstepX das Konto ext? konto aus augen_tsx.js → 'ja' | 'vielleicht' | 'nein' | 'fehlt'.
    Aus tsx_cdp_lesung herausgezogen (K2 01.10.2026), damit Lesen und Kontowechsel dieselbe Regel nutzen. 'ja' nur mit VOLLER
    Kennung (kontonr == External ID und nicht abgekürzt; augen_tsx.js liest sie aus dem DOM des Auslösers)."""
    ko = ko if isinstance(ko, dict) else {}
    aktiv = str(ko.get("kontonr") or ko.get("aktiv") or "")
    if not aktiv.strip():
        return "fehlt"
    nr = _nur_alnum(ko.get("kontonr"))
    if not nr:
        return tsx_konto_steht(ko.get("aktiv"), ext)           # nur der Auslöser-Text ('$150K … | KENNUNG')
    if nr == _nur_alnum(ext) and ko.get("abgekuerzt") is not True:
        return "ja"
    # abgekürzt beweist nichts — auch nicht, wenn der sichtbare Teil zufällig genau die External ID ist (K1-Prüfer: …-1 vs …-1…)
    return "vielleicht" if ko.get("abgekuerzt") and _nur_alnum(ext).startswith(nr) else "nein"


def tsx_k2_eintrag(liste, ext):
    """REIN RECHNEND (testbar, K2 01.10.2026): Zeile der OFFENEN TopstepX-Konto-Liste (augen_tsx.js konto.liste: {text, label, id,
    ineligible, aus, rect, zu}) → (eintrag | None, anzahl, grund). Genau EINE Zeile, deren volle Kennung die External ID ist; „(Ineligible)"
    ist zum LESEN erlaubt (Entscheidung 01.10.2026 — der Hinweis geht in die Antwort; handeln geht auf so einem Konto ohnehin nicht);
    gesperrte (aus/disabled) oder verdeckte Zeilen und Zeilen ohne Rechteck nie."""
    ziel = _nur_alnum(ext)
    if len(ziel) < 5:
        return None, 0, "External ID fehlt"
    treffer = [x for x in (liste or []) if isinstance(x, dict) and _nur_alnum(x.get("id")) == ziel]
    if not treffer:
        return None, 0, "Konto nicht in der Liste"
    if len(treffer) > 1:
        return None, len(treffer), f"Konto {len(treffer)}× in der Liste — nicht eindeutig"
    x = treffer[0]
    zu = x.get("zu") if isinstance(x.get("zu"), dict) else {}
    if x.get("aus") or zu.get("disabled"):
        return None, 1, "Zeile gesperrt"
    if zu.get("verdeckt"):
        return None, 1, f"Zeile verdeckt ({str((zu.get('oben') or {}).get('text') if isinstance(zu.get('oben'), dict) else zu.get('oben') or '')[:30]})"
    r = cdp_rect(x.get("rect"))
    if not (isinstance(r, (list, tuple)) and len(r) >= 4 and r[2] >= 2 and r[3] >= 2):
        return None, 1, "Zeile ohne Rechteck"
    return x, 1, ""


def tsx_kopf_gleich(a, b):
    """REIN RECHNEND (testbar, K2-Beweis 3): zwei Lesungen mit derselben Kopfzeile (BAL/MLL/RP&L/UP&L) und lesbarer BAL — TopstepX lädt
    die Werte nach dem Kontowechsel nach; erst zwei gleiche Lesungen hintereinander zählen als frisch."""
    ka = (a or {}).get("kopf") if isinstance(a, dict) else None
    kb = (b or {}).get("kopf") if isinstance(b, dict) else None
    if not (isinstance(ka, dict) and isinstance(kb, dict)):
        return False
    wa = [_tsx_wert(ka.get(k)) for k in ("balance", "mll", "rpl", "upl")]
    wb = [_tsx_wert(kb.get(k)) for k in ("balance", "mll", "rpl", "upl")]
    return wa[0] is not None and wa == wb


def tsx_cdp_lesung(stand, ext):
    """REIN RECHNEND (testbar): stand_tsx (augen_tsx.js) → Antwortfelder im tv-lesen-Vertrag. -> (felder, code, msg)
    code '' = gelesen; 'anker_fehlt' (augen_tsx.js liefert Konto/Kopf/Positionen noch nicht); 'konto' (ein anderes Konto steht — der
    Wechsel davor ist K2, _tsx_konto_sichern); 'balance' (BAL unlesbar); 'tabelle_unklar' (Positions-Bereich nicht sichtbar ODER „flach" nicht bewiesen).
    Vertrag augen_tsx.js tsx-0.3.1 (Terminal 2, 30.09.2026): kopf.balance_relativ ist true|false|null und KEIN {text, wert} — wird als
    balance_relativ DURCHGEREICHT, hier nie umgerechnet (Express zeigt BAL relativ: „$0.00" bei MLL „$-4,500.00"; was das Frontend daraus
    macht, entscheidet das Frontend). flach ist nur true bei „No Active Position" UND gesperrtem „Close Position"; eine OFFENE Position
    kann augen_tsx.js noch nicht lesen (positionen_sichtbar false, flach null) → ehrlich 'tabelle_unklar', nie „keine Position"."""
    st = stand if isinstance(stand, dict) else {}
    ko = st.get("konto") if isinstance(st.get("konto"), dict) else None
    kopf = st.get("kopf") if isinstance(st.get("kopf"), dict) else None
    fehlt = [n for n, da in (("konto", ko is not None), ("kopf", kopf is not None), ("positionen_sichtbar", "positionen_sichtbar" in st)) if not da]
    if fehlt:
        return {}, "anker_fehlt", ("TopstepX über das Puls-Chrome kann noch nicht lesen — augen_tsx.js liefert " + "/".join(fehlt)
                                   + " noch nicht (Anker kommen aus dem K0-Inventar). Nichts gelesen.")
    aktiv = str(ko.get("kontonr") or ko.get("aktiv") or "")
    if not aktiv.strip():
        # Konto-Auslöser gar nicht gelesen: Seite noch im Lade-Schirm oder TopstepX hat den Anker umbenannt — das ist KEIN „anderes Konto"
        return {}, "anker_fehlt", "Konto-Auslöser in TopstepX nicht gefunden (Seite lädt noch oder Anker geändert). Nichts gelesen."
    steht = tsx_konto_urteil(ko, ext)
    if steht != "ja":
        return {"konto_aktiv": aktiv[:80]}, "konto", (f"Im Puls-Chrome steht nicht {ext} ('{aktiv[:40] or '-'}', {steht}) — Konto nicht "
                                                      "gewechselt (K2). Nichts gelesen.")
    w = {k: _tsx_wert(kopf.get(k)) for k in ("balance", "mll", "rpl", "upl")}
    rel = kopf.get("balance_relativ")
    # konto_aktiv = External ID wie im UIA-Weg (das Konto ist hier bewiesen; das Frontend prüft includes(ext)), die angezeigte
    # Kennung steht in konto_anzeige (K1-Prüfer 30.09.2026: andere Schreibweise der ID in Prophos ließ die Prüfung scheitern)
    felder = dict(w, konto=ext, konto_aktiv=ext, konto_anzeige=aktiv[:80], balance_relativ=(rel if isinstance(rel, bool) else None),
                  summary=tsx_summary(w))
    if w["balance"] is None:
        return felder, "balance", "BAL in der TopstepX-Kopfzeile nicht lesbar."
    if st.get("positionen_sichtbar") is not True:
        return felder, "tabelle_unklar", ("Positions-Bereich in TopstepX nicht sichtbar (eine offene Position kann das Puls-Chrome noch "
                                          "nicht lesen) — kein Stand ohne Positionen.")
    pos = cdp_positionen_vertrag(st.get("positionen"))
    flach = st.get("flach")
    if not pos and flach is not True:
        return felder, "tabelle_unklar", "„No Active Position“ steht da, aber „Close Position“ ist nicht gesperrt — flach nicht bewiesen."
    if pos and flach is True:
        return felder, "tabelle_unklar", "TopstepX zeigt Positionen UND „No Active Position“ — Widerspruch, nichts gezählt."
    felder.update(positionen=pos, offen=bool(pos), position=("offen" if pos else "keine"),
                  avg_fill_je_wurzel=tv_avg_fill_je_wurzel(pos),
                  today_pnl=(None if w["rpl"] is None else round(w["rpl"] + (w["upl"] or 0.0), 2)),
                  today_label="RP&L" + (" + UP&L" if pos else ""), today_pnl_text=(kopf.get("rpl") or {}).get("text") if isinstance(kopf.get("rpl"), dict) else None)
    return felder, "", f"Konto {ext}: Balance {w['balance']:,.2f} $, {len(pos)} Position(en) (CDP)"


# ══ K3a: TICKET ÜBER DAS PULS-CHROME (01.10.2026, Finn: „Hier bei Contracts einfach reinklicken und dann MNQ oder NQ auswählen. Bei
# Number of Contracts auch einfach rein klicken und die Zahl weg machen, und dann die eigentliche Zahl angeben."). Probe: endet vor
# dem Order-Knopf. Reine Regeln (testbar) — die Schritte stehen in _tsx_k3_ticket/_tsx_k3_probe. Anker: augen_tsx.js tsx-0.5.0 (ticket.contract,
# ticket.vorschlaege, ticket.menge, ticket.ordertyp, ticket.kauf/verkauf; ticket.k3 = Vertrag da).

def tsx_frontmonat(jetzt=None):
    """REIN RECHNEND (testbar): Front-Monat der Nasdaq-Futures wie das Frontend (tpFuturesFrontcode, prophos.html): Quartal H/M/U/Z,
    Roll 8 Tage vor dem 3. Freitag des Verfallsmonats (UTC) → 'Z26' (Monat + zweistelliges Jahr, wie TopstepX „MNQZ26")."""
    import datetime as _dt
    d = _dt.datetime.utcfromtimestamp(time.time() if jetzt is None else float(jetzt))
    mon = {3: "H", 6: "M", 9: "U", 12: "Z"}
    for i in range(13):
        roh = d.month - 1 + i
        jahr, monat = d.year + roh // 12, roh % 12 + 1
        if monat not in mon:
            continue
        erster = _dt.datetime(jahr, monat, 1)
        dritter_fr = erster + _dt.timedelta(days=(4 - erster.weekday()) % 7 + 14)     # weekday: Montag 0 … Freitag 4
        if dritter_fr - _dt.timedelta(days=8) > d:
            return f"{mon[monat]}{jahr % 100:02d}"
    return ""


def tsx_k3_contract_ziel(vorschlaege, wurzel, jetzt=None):
    """REIN RECHNEND (testbar): Vorschlag der Contract-Liste für die Wurzel → (eintrag | None, grund). Nur Codes GENAU Wurzel + Monat
    + Jahr (MNQ ≠ NQ: „nq" findet nie MNQZ26). Ein Code → der. Mehrere Monate → der Front-Monat (tsx_frontmonat), sonst None."""
    w = str(wurzel or "").upper()
    rx = re.compile(rf"^{re.escape(w)}[FGHJKMNQUVXZ]\d{{1,2}}$")
    kand = [v for v in (vorschlaege or []) if isinstance(v, dict) and rx.match(str(v.get("code") or "").strip().upper())]
    codes = sorted({str(v.get("code")).strip().upper() for v in kand})
    if not kand:
        return None, "kein passender Vorschlag"
    if len(codes) == 1:
        return kand[0], ""
    front = w + tsx_frontmonat(jetzt)
    f_ = [v for v in kand if str(v.get("code")).strip().upper() == front]
    if f_:
        return f_[0], ""
    return None, f"mehrere Monate ({', '.join(codes)}), Front-Monat {front} nicht dabei"


def tsx_k3_contract_steht(contract, code, wurzel, titel):
    """REIN RECHNEND (testbar): Gilt der Contract als gewählt? -> (ok, wie). Zwei Beweise, die Liste muss immer zu sein:
    (a) das Feld zeigt genau den Code („MNQZ26") → 'feld'. (b) Finn live 06.10.2026 (Chris-PC): nach dem Klick auf den Vorschlag
    blieb im Feld die getippte Wurzel („mnq") stehen, die Auswahl galt trotzdem — der Chart stand schon auf MNQ („das kann man
    cross-checken, indem auf dem Chart einfach schon MNQ drauf ist"). Der Seitentitel des TopstepX-Tabs trägt den Chart-Contract
    („MNQZ26 $31,516.00 ▲ +0.63%"); der Contract-Wähler oben treibt Chart UND Order-Karte. Beweis (b) = Feld leer oder genau die
    Wurzel, Titel beginnt mit genau dem Code UND die Wurzel des Codes ist die getippte („nq" bestätigt nie MNQZ26) → 'chart'.
    Ein beliebiger anderer Feldtext (halb getippt, fremder Code) zählt nie."""
    c = contract if isinstance(contract, dict) else None
    cd = str(code or "").strip().upper()
    if c is None or "wert" not in c or not cd or c.get("offen"):   # kein gelesenes Feld → auch der Titel beweist nichts
        return False, ""
    wert = str(c.get("wert") or "").strip().upper()
    if wert == cd:
        return True, "feld"
    w = str(wurzel or "").strip().upper()
    kopf = str(titel or "").strip().split(" ")[0].strip().upper() if titel else ""
    if w and wert in ("", w) and kopf == cd and tv_symbol_root(cd) == w:
        return True, "chart"
    return False, ""


def tsx_k3_menge_passt(wert, menge):
    """REIN RECHNEND (testbar): steht im Mengenfeld genau die Plan-Menge? („3" == 3; „", „3a", „1.5" nie)"""
    m = re.fullmatch(r"\s*(\d{1,3})\s*", str(wert if wert is not None else ""))
    try:
        return bool(m) and int(m.group(1)) == int(menge)
    except (TypeError, ValueError):
        return False


def tsx_k3_knopf(ticket, richtung):
    """REIN RECHNEND (testbar): der Order-Knopf zur Richtung — ticket.kauf für buy, ticket.verkauf für sell, sonst None."""
    t = ticket if isinstance(ticket, dict) else {}
    k = t.get("kauf") if str(richtung or "").lower() == "buy" else t.get("verkauf") if str(richtung or "").lower() == "sell" else None
    return k if isinstance(k, dict) else None


def tsx_k3_vor_klick(stand, befehl, code, ext):
    """REIN RECHNEND (testbar): Probe-Urteil aus EINEM frischen Blick — stünde das Ticket so da, dass eine Order genau dem Plan entspräche?
    Nur lesen, klickt nichts. -> (ok, fehler[], knopf, markt_zu). Konto = ext (volle Kennung) und Liste zu · kein Dialog · flach bewiesen („No Active Position" + „Close Position" gesperrt —
    keine zweite Order auf eine offene Position) · Order-Typ Market · Contract = code und Liste zu · Menge = Plan · Knopf zur Richtung mit
    Text genau „Buy +n @ Market" / „Sell -n @ Market", nicht gesperrt, nicht verdeckt, mit Rechteck."""
    st = stand if isinstance(stand, dict) else {}
    b = befehl if isinstance(befehl, dict) else {}
    t = st.get("ticket") if isinstance(st.get("ticket"), dict) else {}
    ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
    f = []
    if tsx_konto_urteil(ko, ext) != "ja":
        f.append(f"Konto steht nicht auf {ext} ('{str(ko.get('kontonr') or ko.get('aktiv') or '-')[:40]}')")
    if ko.get("liste_offen"):
        f.append("Konto-Liste offen")
    if st.get("popups"):
        f.append("Dialog offen ('" + str((st["popups"][0] or {}).get("titel") or (st["popups"][0] or {}).get("text") or "")[:40] + "')")
    if st.get("flach") is not True:
        f.append("Konto nicht flach bewiesen (keine zweite Order auf eine offene Position)")
    g = t.get("gitter") if isinstance(t.get("gitter"), dict) else {}
    # Nachprüfer 06.10.2026: eine Tabellenzeile zählt nur mit Menge ≠ 0 — augen_tsx.js lässt 0-Zeilen in positionAus selbst weg
    offen_tab = [z for z in (g.get("zeilen") or []) if isinstance(z, dict) and isinstance(z.get("menge"), (int, float)) and z["menge"] != 0]
    if st.get("positionen") or (g.get("da") and offen_tab):
        # Prüfer 06.10.2026: „flach" gilt nur für den Contract der Order-Karte — eine Zeile der Positions-Tabelle / Order-Karte in
        # irgendeinem Contract ist eine offene Position auf diesem Konto
        f.append("offene Position gelesen (Positions-Tabelle/Order-Karte) — keine zweite Order")
    ot = str((t.get("ordertyp") or {}).get("text") or "").strip() if isinstance(t.get("ordertyp"), dict) else ""
    if ot.lower() != "market":
        f.append(f"Order-Typ '{ot or '-'}' statt Market")
    c = t.get("contract") if isinstance(t.get("contract"), dict) else {}
    if c.get("offen"):
        f.append("Contract-Liste noch offen")
    elif not tsx_k3_contract_steht(c, code, b.get("wurzel"), st.get("titel"))[0]:   # Feld = Code, oder Wurzel im Feld + Chart-Titel = Code (06.10.2026)
        f.append(f"Contract '{c.get('wert') or '-'}' statt {code or '-'}")
    m = t.get("menge") if isinstance(t.get("menge"), dict) else {}
    if not tsx_k3_menge_passt(m.get("wert"), b.get("menge")):
        f.append(f"Menge '{m.get('wert') if m.get('wert') is not None else '-'}' statt {b.get('menge')}")
    kn = tsx_k3_knopf(t, b.get("richtung"))
    markt_zu = False
    if not kn:
        f.append("Order-Knopf nicht gefunden")
    else:
        text = str(kn.get("text") or "")
        if not tsx_knopf_passt(text, b.get("richtung"), b.get("menge")):
            markt_zu = bool(re.search(r"market\s+closed|markt\s+geschlossen", text, re.I))
            f.append(f"Knopf zeigt '{text[:40] or '-'}'")
        zu = kn.get("zu") if isinstance(kn.get("zu"), dict) else {}
        if zu.get("disabled") or zu.get("verdeckt"):
            f.append("Order-Knopf " + ("gesperrt" if zu.get("disabled") else "verdeckt"))
        if not cdp_rect(kn.get("rect")):
            f.append("Order-Knopf ohne Rechteck")
    return (not f), f, kn, markt_zu


class _EineAntwort:
    """Genau EINE JSON-Antwort je Lauf, für Wachhund und Hauptpfad (K1-Prüfer + Stapel-Prüfer 30.09.2026). nehmen(): wer die Sperre
    NICHT bekommt, wartet, bis der andere geschrieben hat (sonst konnte der Prozess enden, bevor überhaupt etwas ausgegeben war —
    Panel: „bot_stumm"). ausgeben(): erst print + flush, die Netz-Diagnose macht der Aufrufer DANACH."""

    def __init__(self):
        import threading
        self._sperre = threading.Lock()
        self._fertig = threading.Event()

    def nehmen(self, warten_s=8.0):
        if self._sperre.acquire(blocking=False):
            return True
        self._fertig.wait(warten_s)
        return False

    def ausgeben(self, res):
        try:
            print(json.dumps(res, ensure_ascii=False))
            sys.stdout.flush()
        finally:
            self._fertig.set()


def _tsx_konto_sichern(s, ext, st, trail):
    """K2 (01.10.2026, „das mit dem Dropdown"): steht in TopstepX nicht das Konto ext, per Windows-Maus wechseln — NUR Konto, keine
    Order, kein Order-Ticket. -> (ok, code, msg, stand, extra); extra.konto_gewechselt = {von, zu} nach einem Wechsel.
    Muster wie _cdp_konto_sichern (Orbit): Auslöser höchstens EINMAL (ein zweiter Klick schlösse die Liste wieder), eine Liste zählt nur,
    wenn DIESER Lauf sie geöffnet hat (fremd offen → EINMAL Esc, neu lesen, nie daraus wählen — Regression .865), genau EINE Zeile
    (tsx_k2_eintrag), jeder Druck mit Ziel-Beweis (win_ziel_pruef_js: Hover + das klickbare Element dort ist die Zeile mit der vollen
    Kennung, kein Order-/Close-Wort), jeder Fehlschlag schließt die Liste mit Esc (nie bei fremdem Dialog), nach jedem Schritt neu lesen,
    alle Pausen über _warte (Jitter). Beweis nach dem Wechsel: (1) Liste zu (aria-expanded), (2) Auslöser trägt die volle Ziel-Kennung
    (tsx_konto_urteil 'ja'), (3) die Kopfzeile macht der Aufrufer frisch (Bereit-Probe + zwei gleiche Lesungen, tsx_kopf_gleich)."""
    st = st if isinstance(st, dict) else {}
    geklickt = False
    fremd_esc = False
    gewaehlt = None
    lade_gewartet = False
    ko0 = st.get("konto") if isinstance(st.get("konto"), dict) else {}
    von = str(ko0.get("kontonr") or ko0.get("aktiv") or "")[:80]

    def _zeilen(ko_):
        return [str(x.get("text"))[:60] for x in (ko_.get("liste") or []) if isinstance(x, dict)][:12]

    def _raus(code, msg, st_, **ex):
        return False, code, msg, st_, ex
    for _runde in range(6):
        ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
        aktiv = str(ko.get("kontonr") or ko.get("aktiv") or "")
        if tsx_konto_urteil(ko, ext) == "ja":
            if ko.get("liste_offen"):
                _cdp_esc(s, st, trail, "Konto-Liste nach dem Wechsel noch offen")
                _warte(0.6, 0.3)
                st = s.stand()
                if (st.get("konto") or {}).get("liste_offen"):
                    return _raus("konto_nicht_erreicht", f"Konto {ext} steht, aber die Konto-Liste geht mit Esc nicht zu — nichts gelesen.",
                                 st, konto_zeilen=_zeilen(ko))
            ex = {"konto_aktiv": aktiv[:80]}
            if gewaehlt is not None:
                ex["konto_gewechselt"] = {"von": von, "zu": str(gewaehlt.get("id") or ext)[:80]}
                if gewaehlt.get("ineligible"):
                    ex["konto_hinweis"] = "Ineligible"
                trail.append(f"K2: Konto gewechselt '{von[:40]}' → '{aktiv[:40]}' (Liste zu, volle Kennung bewiesen)")
            return True, "", "", st, ex
        if ko.get("liste_offen") and not geklickt:
            zl = _zeilen(ko)
            if fremd_esc:
                return _raus("konto_nicht_erreicht", (f"Konto-Liste steht ohne eigenen Klick offen und bleibt es nach Esc (aktiv "
                                                      f"'{aktiv[:40] or '-'}', Zeilen {zl[:4]}) — nichts gewählt."), st, konto_zeilen=zl)
            fremd_esc = True
            _cdp_esc(s, st, trail, f"Konto-Liste stand schon offen, nicht von diesem Lauf ({len(zl)} Zeilen), neu lesen")
            _warte(0.6, 0.3)
            st = s.stand()
            continue
        if ko.get("liste_offen"):
            if gewaehlt is not None:
                # Zeile gedrückt, Liste noch offen und Konto nicht gewechselt: nicht noch einmal drücken — zu und ehrlich raus
                _cdp_esc(s, st, trail, "Konto-Liste nach dem Zeilen-Klick noch offen")
                return _raus("konto_nicht_erreicht", f"Konto-Zeile {ext} gedrückt, Liste blieb offen, Konto nicht gewechselt — Esc, nichts gelesen.",
                             st, konto_zeilen=_zeilen(ko))
            x, n, grund = tsx_k2_eintrag(ko.get("liste"), ext)
            if not x:
                _cdp_esc(s, st, trail, "Konto-Liste schließen")
                return _raus("konto_nicht_erreicht", f"Konto {ext} in der TopstepX-Liste: {grund} ({n}×) — nichts gewählt, Esc.", st,
                             konto_zeilen=_zeilen(ko), konto_treffer=n)
            r = list(cdp_rect(x.get("rect")))[:4]
            pruef = {"rect": r, "text": str(x.get("id") or ext)[:60], "aria": "", "tabu": TSX_K0_TABU.pattern}
            _tsx_pause()                                  # die offene Liste steht 1–2 s da, dann erst die Zeile (Finn 01.10.2026)
            if not s.klick(r, f"Konto {ext}", pruef=pruef):
                _cdp_esc(s, st, trail, "Konto-Zeile nicht gedrückt")
                return _raus("konto_nicht_erreicht", f"Konto-Zeile {ext} nicht gedrückt (Klick ohne Beweis) — Liste mit Esc zu, nichts gewechselt.",
                             st, konto_zeilen=_zeilen(ko))
            gewaehlt = x
            # TopstepX schaltet das Konto nach dem Klick um (Liste zu, Auslöser neu) — bis ~4 s lesen, bis es steht oder die Liste offen bleibt
            for _ in range(4):
                _warte(1.0, 0.5)
                st = s.stand()
                k2 = st.get("konto") if isinstance(st.get("konto"), dict) else {}
                if tsx_konto_urteil(k2, ext) == "ja" or k2.get("liste_offen"):
                    break
            continue
        if gewaehlt is not None:
            return _raus("konto_nicht_erreicht", (f"Konto-Zeile {ext} gedrückt, Liste zu, aber im Auslöser steht '{aktiv[:40] or '-'}' — "
                                                  "nicht gewechselt, nichts gelesen."), st)
        if geklickt:
            return _raus("konto_nicht_erreicht", (f"Konto-Auslöser geklickt, Liste nicht erkannt (aktiv '{aktiv[:40] or '-'}') — nichts gewählt."),
                         st, popups=st.get("popups"))
        r = cdp_rect(ko.get("rect"))
        if not (isinstance(r, (list, tuple)) and len(r) >= 4 and r[2] >= 2 and r[3] >= 2):
            return _raus("konto_nicht_erreicht", "Konto-Auslöser ohne Rechteck (augen_tsx.js) — nichts geklickt.", st)
        zu = ko.get("zu") if isinstance(ko.get("zu"), dict) else {}
        if not zu.get("disabled") and tsx_ladeschirm(ko) and not lade_gewartet:
            # TSX-LADEN (05.10.2026): über dem Auslöser liegt noch der Lade-Schirm — EINMAL in kurzen Schritten warten und neu lesen,
            # dann die Runde von vorn (das Konto kann inzwischen stehen). Kein Klick; bleibt er, ehrlich „lädt noch".
            lade_gewartet = True
            t_l = time.time()
            while tsx_ladeschirm(ko) and time.time() - t_l < TSX_LADEN_K2_S:
                _warte(0.6, 0.4)
                st = s.stand()
                ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
            n_l = int(round(time.time() - t_l))
            if tsx_ladeschirm(ko):
                return _raus("konto_nicht_erreicht", (f"TopstepX lädt noch (Lade-Schirm über dem Konto-Auslöser, weitere {n_l} s gewartet) — "
                                                      "nichts geklickt, gleich erneut."), st, popups=st.get("popups"))
            trail.append(f"K2: Lade-Schirm über dem Konto-Auslöser ist weg ({n_l} s gewartet) — weiter")
            continue
        if zu.get("disabled") or zu.get("verdeckt"):
            oben = zu.get("oben") if isinstance(zu.get("oben"), dict) else {}
            return _raus("konto_nicht_erreicht", (f"Konto-Auslöser {'gesperrt' if zu.get('disabled') else 'verdeckt'} "
                                                  f"('{str(oben.get('text') or oben.get('tag') or '')[:40]}') — Dialog offen? Nichts geklickt."),
                         st, popups=st.get("popups"))
        geklickt = True
        r = list(r)[:4]
        # Ziel-Beweis mit dem Auslöser-TEXT ('$150K … | KENNUNG' → volle Kennung), nicht der nackten kontonr (tsx_k0_pruef erkennt die
        # Kennung nur im Auslöser-Format, sonst nähme es die ersten 24 Zeichen)
        _tsx_pause()                                      # menschliches Tempo vor dem Auslöser (Finn 01.10.2026)
        if not s.klick(r, "Konto-Auslöser", pruef=tsx_k0_pruef({"rect": r, "text": str(ko.get("aktiv") or aktiv), "aria": ""})):
            return _raus("konto_nicht_erreicht", "Konto-Auslöser nicht gedrückt (Klick ohne Beweis) — nichts gewechselt.", st)
        _warte(0.9, 0.4)
        st = s.stand()
        if not (st.get("konto") or {}).get("liste_offen"):
            _warte(1.0, 0.4)
            st = s.stand()
    ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
    if ko.get("liste_offen"):
        _cdp_esc(s, st, trail, "Konto-Liste nach der letzten Runde")
    return _raus("konto_nicht_erreicht", f"Konto {ext} nicht aktiv (steht: '{str(ko.get('kontonr') or ko.get('aktiv') or '-')[:40]}')", st)


def _tsx_kopf_frisch(s, st, ext, trail, runden=4):
    """K2-Beweis 3: nach dem Wechsel die Kopfzeile ZWEIMAL hintereinander gleich gelesen (BAL lesbar), Konto weiter das Ziel, Liste zu.
    -> (stand, frisch)"""
    for _ in range(runden):
        _warte(0.8, 0.4)
        st2 = s.stand()
        k2 = st2.get("konto") if isinstance(st2.get("konto"), dict) else {}
        if tsx_kopf_gleich(st, st2) and tsx_konto_urteil(k2, ext) == "ja" and not k2.get("liste_offen"):
            return st2, True
        st = st2
    trail.append(f"K2: Kopfzeile nach dem Wechsel nicht zweimal gleich ({runden} Lesungen)")
    return st, False


def _tsx_tk(st):
    return st.get("ticket") if isinstance(st, dict) and isinstance(st.get("ticket"), dict) else {}


def _tsx_fokus_exakt(s, art, trail, schritt):
    """K3a-Prüfer 01.10.2026: fokus_im prüft nur, ob IRGENDEIN fokussiertes Element das Feld überlappt (ein Dialog-Container würde
    reichen). Vor jeder Tastenfolge deshalb exakt: augen_tsx.js meldet ticket.<art>.fokus = document.activeElement === dieses input.
    -> True nur dann"""
    try:
        f = _tsx_tk(s.stand()).get(art)
        if isinstance(f, dict) and f.get("fokus") is True:
            return True
    except Exception:
        pass
    trail.append(f"{schritt}: das Feld selbst hat nicht den Fokus — keine Taste")
    return False


def _tsx_k3_contract(s, st, wurzel, trail):
    """K3a Schritt 1: ins Contract-Feld klicken (Ziel-Beweis), Fokus beweisen, Wurzel („mnq"/„nq") per echter Tastatur tippen, den
    EINEN passenden Vorschlag (tsx_k3_contract_ziel) am Code-Text anklicken, Rücklesung Feld = Code und Liste zu. Höchstens zwei
    Versuche, jeder Fehlschlag schließt die Liste mit Esc. -> (ok, code, msg, stand, contract-code | None)"""
    letzter = ""
    for versuch in range(2):
        c = _tsx_tk(st).get("contract") if isinstance(_tsx_tk(st).get("contract"), dict) else {}
        r = cdp_rect(c.get("rect"))
        if not (isinstance(r, (list, tuple)) and len(r) >= 4 and r[2] >= 2 and r[3] >= 2):
            return False, "contract", "Contract-Feld in TopstepX nicht gefunden (augen_tsx.js) — nichts getan.", st, None
        zu = c.get("zu") if isinstance(c.get("zu"), dict) else {}
        if zu.get("disabled") or zu.get("verdeckt"):
            return False, "contract", f"Contract-Feld {'gesperrt' if zu.get('disabled') else 'verdeckt'} — Dialog offen? Nichts getan.", st, None
        r = list(r)[:4]
        _tsx_pause()
        if not s.klick(r, "Contract-Feld", pruef={"rect": r, "text": "", "aria": "", "tabu": TSX_K0_TABU.pattern}):
            return False, "contract", "Contract-Feld nicht gedrückt (Klick ohne Beweis) — nichts getan.", st, None
        _warte(0.4, 0.3)
        if not s.fokus_im(r, "Contract-Feld") or not _tsx_fokus_exakt(s, "contract", trail, "Contract-Feld"):
            _cdp_esc(s, st, trail, "Contract-Feld ohne Fokus")
            return False, "contract", "Contract-Feld hat nach dem Klick keinen Fokus — nichts getippt, Esc.", st, None
        s.taste("a", modifiers=2)                   # Strg+A: den alten Wert markieren, das Tippen ersetzt ihn
        _warte(0.25, 0.2)
        if not _tsx_fokus_exakt(s, "contract", trail, "Contract-Feld vor dem Tippen"):
            _cdp_esc(s, st, trail, "Contract-Feld verlor den Fokus")
            return False, "contract", "Contract-Feld verlor vor dem Tippen den Fokus — nichts getippt, Esc.", st, None
        s.tippen(str(wurzel).lower())
        trail.append(f"Contract: '{str(wurzel).lower()}' getippt")
        _warte(0.9, 0.5)                             # die Liste filtert
        st = s.stand()
        vs = _tsx_tk(st).get("vorschlaege") or []
        x, grund = tsx_k3_contract_ziel(vs, wurzel)
        codes = [str(v.get("code")) for v in vs if isinstance(v, dict)][:8]
        if not x:
            letzter = f"Contract {wurzel}: {grund} (Vorschläge {codes or '-'})"
            _cdp_esc(s, st, trail, letzter)
            _warte(0.6, 0.3)
            st = s.stand()
            continue
        rr = cdp_rect(x.get("code_rect"))           # NUR der Code-Text — nie die Zeilenmitte (links sitzt der Favoriten-Stern)
        zeile = cdp_rect(x.get("rect")) or rr
        zu = x.get("zu") if isinstance(x.get("zu"), dict) else {}
        if not rr or zu.get("disabled") or zu.get("verdeckt"):
            letzter = f"Vorschlag {x.get('code')} ohne klickbaren Code-Text"
            _cdp_esc(s, st, trail, letzter)
            _warte(0.6, 0.3)
            st = s.stand()
            continue
        _warte(0.6, 0.6)                             # die Liste steht einen Moment sichtbar da, dann erst wählen
        # Klickpunkt im Code-Text (links sitzt der Favoriten-Stern). Beweis: die Zeile ist das klickbare Ziel UND der Text genau am
        # Punkt ist der Code (wort) — „nqz26" steckt auch in „mnqz26", ein Teilstring der Zeile allein genügt nie
        cd = str(x.get("code")).lower()
        if not s.klick(list(rr)[:4], f"Contract {x.get('code')}", pruef={"rect": list(zeile)[:4], "text": cd, "aria": "", "wort": cd,
                                                                         "tabu": TSX_K0_TABU.pattern}):
            letzter = f"Vorschlag {x.get('code')} nicht gedrückt (Klick ohne Beweis)"
            _cdp_esc(s, st, trail, letzter)
            _warte(0.6, 0.3)
            st = s.stand()
            continue
        c2, esc_getan = {}, False
        for _ in range(6):
            _warte(0.6, 0.3)
            st = s.stand()
            c2 = _tsx_tk(st).get("contract") if isinstance(_tsx_tk(st).get("contract"), dict) else {}
            # Finn live 06.10.2026 (Chris-PC, Lauf 17:33 UTC): 1. Versuch — Feld blieb 'mnq', Liste zu, Chart längst auf MNQZ26 (galt);
            # 2. Versuch — Feld 'MNQZ26', aber die Liste blieb offen → beides endete als „nichts getan". Jetzt: Beweis über Feld ODER
            # Wurzel + Chart-Titel (tsx_k3_contract_steht); eine nach der Auswahl offen gebliebene Liste wird EINMAL mit Esc geschlossen.
            steht, wie = tsx_k3_contract_steht(c2, x.get("code"), wurzel, st.get("titel") if isinstance(st, dict) else None)
            if steht:
                trail.append(f"Contract {x.get('code')} gewählt — Rücklesung '{c2.get('wert')}', Liste zu"
                             + (f", Chart-Titel '{str(st.get('titel') or '')[:20]}'" if wie == "chart" else ""))
                return True, "", "", st, str(x.get("code")).upper()
            if c2.get("offen") and not esc_getan:
                esc_getan = True
                _cdp_esc(s, st, trail, "Contract-Liste nach der Auswahl noch offen")
        letzter = f"Contract nach dem Klick '{c2.get('wert') or '-'}'{' (Liste offen)' if c2.get('offen') else ''}, erwartet {x.get('code')}"
        if c2.get("offen"):
            _cdp_esc(s, st, trail, letzter)
            _warte(0.6, 0.3)
            st = s.stand()
        trail.append(letzter + (" — zweiter Versuch" if versuch == 0 else ""))
    return False, "contract", letzter + " — nichts weiter getan.", st, None


def _tsx_k3_menge(s, st, menge, trail):
    """K3a Schritt 2: ins Feld „# of Contracts" klicken (Ziel-Beweis), Fokus beweisen, alte Zahl MARKIEREN und direkt mit der Plan-Menge
    überschreiben — nie löschen. Finn live 06.10.2026 (Chris-PC, 18:12 UTC): Strg+A, Rücktaste, „2" ergab „12" — das MUI-Zahlenfeld
    füllt sich nach dem Löschen sofort wieder mit „1" (Mindestwert), die getippte Zahl hängt hinten dran. 1. Versuch: Klick + Strg+A +
    tippen (ersetzt die Markierung). 2. Versuch = Finns Handgriff („ganz leicht vor die Zahl doppelklicken, sodass sie blau markiert
    wird, dann die Zahl eingeben"): Doppelklick ins linke Stück des Felds, tippen. Rücklesung Feld = Menge. Kein Tab (der Fokus bleibt
    im Feld). Steht die Menge schon da: nichts tun. -> (ok, code, msg, stand)"""
    m = _tsx_tk(st).get("menge") if isinstance(_tsx_tk(st).get("menge"), dict) else {}
    if tsx_k3_menge_passt(m.get("wert"), menge):
        trail.append(f"Menge steht schon auf {menge}")
        return True, "", "", st
    for versuch in range(2):
        r = cdp_rect(m.get("rect"))
        if not (isinstance(r, (list, tuple)) and len(r) >= 4 and r[2] >= 2 and r[3] >= 2):
            return False, "menge", "Feld „# of Contracts“ nicht gefunden (augen_tsx.js).", st
        zu = m.get("zu") if isinstance(m.get("zu"), dict) else {}
        if zu.get("disabled") or zu.get("verdeckt"):
            return False, "menge", f"Feld „# of Contracts“ {'gesperrt' if zu.get('disabled') else 'verdeckt'}.", st
        r = list(r)[:4]
        _tsx_pause()
        if versuch == 0:
            if not s.klick(r, "# of Contracts", pruef={"rect": r, "text": "", "aria": "", "tabu": TSX_K0_TABU.pattern}):
                return False, "menge", "Feld „# of Contracts“ nicht gedrückt (Klick ohne Beweis).", st
            _warte(0.35, 0.25)
            if not s.fokus_im(r, "# of Contracts") or not _tsx_fokus_exakt(s, "menge", trail, "# of Contracts"):
                return False, "menge", "Feld „# of Contracts“ hat keinen Fokus — nichts getippt.", st
            s.taste("a", modifiers=2)                 # markieren — das Tippen ersetzt die Markierung
            _warte(0.2, 0.2)
        else:
            links = [r[0] + 2.0, r[1], max(12.0, min(40.0, r[2] * 0.15)), r[3]]   # die Zahl steht links im Feld (Finns Bild 06.10.2026)
            if not s.klick(links, "# of Contracts (Doppelklick)", pruef={"rect": r, "text": "", "aria": "", "tabu": TSX_K0_TABU.pattern}, doppel=True):
                return False, "menge", "Feld „# of Contracts“ nicht gedrückt (Doppelklick ohne Beweis).", st
            _warte(0.35, 0.25)
            if not s.fokus_im(r, "# of Contracts"):
                return False, "menge", "Feld „# of Contracts“ hat nach dem Doppelklick keinen Fokus — nichts getippt.", st
        if not _tsx_fokus_exakt(s, "menge", trail, "# of Contracts vor dem Tippen"):
            return False, "menge", "Feld „# of Contracts“ verlor den Fokus — Menge nicht getippt.", st
        s.tippen(str(int(menge)))
        _warte(0.6, 0.3)
        st = s.stand()
        m = _tsx_tk(st).get("menge") if isinstance(_tsx_tk(st).get("menge"), dict) else {}
        if tsx_k3_menge_passt(m.get("wert"), menge):
            trail.append(f"Menge {menge} getippt — Rücklesung '{m.get('wert')}'" + (" (Doppelklick)" if versuch else ""))
            return True, "", "", st
        trail.append(f"Menge nach dem Tippen '{m.get('wert')}', erwartet {menge}" + (" — zweiter Versuch (Doppelklick vor die Zahl)" if versuch == 0 else ""))
    return False, "menge", f"Menge steht auf '{m.get('wert')}', nicht {menge}.", st


def _tsx_k3_ticket(s, st, befehl, trail):
    """K3a: Ticket füllen (Contract, Menge). -> (ok, code, msg, stand, contract-code | None)"""
    t = _tsx_tk(st)
    if not t.get("k3"):
        return False, "anker_fehlt", ("Das TopstepX-Ticket liest das Puls-Chrome noch nicht (augen_tsx.js ohne K3-Felder — Stand "
                                      f"{str(st.get('v') if isinstance(st, dict) else '-')[:12]}). Nichts getan."), st, None
    ot = str((t.get("ordertyp") or {}).get("text") or "").strip() if isinstance(t.get("ordertyp"), dict) else ""
    if ot.lower() != "market":
        return False, "ordertyp", f"Order-Typ steht auf '{ot or '-'}', nicht Market — nichts getan (Prophos stellt ihn nicht um).", st, None
    ok, code, msg, st, ziel = _tsx_k3_contract(s, st, befehl["wurzel"], trail)
    if not ok:
        return False, code, msg, st, None
    ok, code, msg, st = _tsx_k3_menge(s, st, befehl["menge"], trail)
    if not ok:
        return False, code, msg, st, ziel
    return True, "", "", st, ziel


# ══ K4: SCHARFER ORDER-KNOPF + RISK / TO MAKE (05.10.2026, Finn im Terminal-3-Fenster, sechs Schritte: „1. Konto auswählen
# 2. Contract auswählen 3. Number of contract auswählen 4. Market buy to market sell 5. Unten auf diese Leiste auf Position gehen
# 6. Doppelklicken auf Risk und da eine Zahl eingeben — das ist ja so viel einfacher."). Schritte 1–3 sind K2/K3a. Hier 4–6:
# EIN Klick auf den Order-Knopf (gesendet/retry_ok VOR dem Klick gesetzt, wie Orbit K4), Beweis über die Fill-Meldung oder die
# Positionszeile, dann im Reiter „Positions" Risk (SL) und To Make (TP) als Dollar-Betrag der ganzen Position eintippen — belegt durch
# Finns Bild: −6 MNQ, Risk 21 $ = 1,75 Pkt, To Make 198 $ = 16,5 Pkt. TopstepX rundet auf Ticks; darum zählt die Rücklesung der Zelle
# mit einem Tick Spiel. Scheitert Risk/To Make NACH dem Fill, bleibt die Order stehen: ok + warnung („Brackets in TopstepX prüfen").
# Nie geklickt: das Kreuz der Spalte Close, Close/Reverse/Flatten/Cancel der Order-Karte. Reine Regeln zuerst (testbar).

def tsx_k4_betraege(cmd):
    """REIN RECHNEND (testbar): (tp_usd, sl_usd) aus dem Befehl — je float > 0 oder None (Winning Days: SL fehlt)."""
    def z(v):
        try:
            f = float(str(v).replace(",", ".")) if v not in (None, "") else 0.0
        except (TypeError, ValueError):
            return None
        return f if f > 0 else None
    c = cmd if isinstance(cmd, dict) else {}
    return z(c.get("tp_usd")), z(c.get("sl_usd"))


def tsx_k4_betrag_text(usd):
    """REIN RECHNEND (testbar): der Text, den die Hand tippt — ganze Dollar ohne Nachkommastellen, sonst zwei Stellen mit Punkt."""
    f = float(usd)
    return str(int(round(f))) if abs(f - round(f)) < 0.005 else f"{f:.2f}"


def tsx_k4_wert_gleich(feldwert, usd):
    """REIN RECHNEND (testbar): steht im Eingabefeld genau der getippte Betrag? ('27' == 27; '', '2127', '27a' nie)"""
    t = str(feldwert if feldwert is not None else "").strip().replace(",", ".")
    if not re.fullmatch(r"\d+(\.\d+)?", t):
        return False
    return abs(float(t) - float(usd)) < 0.005


def tsx_k4_toleranz(wurzel, menge):
    """REIN RECHNEND (testbar): Spiel der Rücklesung in $ — ein Tick der ganzen Position (TopstepX rundet den Betrag auf Ticks)."""
    return TSX_PUNKTWERT.get(str(wurzel or "").upper(), 20.0) * TSX_TICK * max(1, int(menge or 1)) + 0.01


def tsx_k4_level(einstieg, richtung, usd, wurzel, menge, art):
    """REIN RECHNEND (testbar): Preis-Level aus Einstieg und Dollar-Betrag der ganzen Position, auf den Tick gerundet.
    art 'sl' liegt gegen die Richtung, 'tp' mit ihr. -> float | None"""
    try:
        pw = TSX_PUNKTWERT[str(wurzel).upper()]
        pkt = float(usd) / (pw * int(menge))
        vz = (1 if str(richtung).lower() == "buy" else -1) * (1 if art == "tp" else -1)
        return round(round((float(einstieg) + vz * pkt) / TSX_TICK) * TSX_TICK, 2)
    except (KeyError, TypeError, ValueError, ZeroDivisionError):
        return None


def _tsx_k4_key(m):
    return "|".join(str(m.get(k)) for k in ("art", "status", "seite", "menge", "symbol", "typ", "preis"))


def _tsx_k4_anzahl(meldungen):
    """REIN RECHNEND: Schlüssel → Anzahl Knoten dieses Blicks."""
    n = {}
    for m in meldungen or []:
        if isinstance(m, dict):
            k = _tsx_k4_key(m)
            n[k] = n.get(k, 0) + 1
    return n


def tsx_k4_meldung_schluessel(stand):
    """REIN RECHNEND (testbar): Schlüssel → Anzahl aller Meldungen dieses Blicks — der Vorher-Stand vor dem Klick (eine alte, gleich
    lautende Fill-Meldung darf nie als Beweis der neuen Order gelten). Nachprüfer 06.10.2026: Anzahl statt Menge — bleibt ein alter
    gleich lautender Toast im DOM stehen, gibt augen_tsx.js dem neuen Knoten dasselbe erst_gesehen; neu ist er dann nur an der
    gewachsenen Anzahl erkennbar."""
    t = stand.get("toasts") if isinstance(stand, dict) and isinstance(stand.get("toasts"), dict) else {}
    return _tsx_k4_anzahl(t.get("meldungen"))


def _tsx_k4_neu(m, key, jetzt_n, vorher, klick_ms):
    """REIN RECHNEND: Ist diese Meldung NEU (nach dem Klick entstanden)? Schlüssel vorher unbekannt → nur, wenn erst nach dem Klick
    gesehen; Schlüssel vorher da → nur, wenn jetzt mehr Knoten dieses Schlüssels stehen als vorher. vorher: dict (Anzahl) oder Menge."""
    v = vorher.get(key, 0) if isinstance(vorher, dict) else (1 if key in (vorher or ()) else 0)
    if v == 0:
        try:
            return float(m.get("erst_gesehen") or 0) >= float(klick_ms) - 500
        except (TypeError, ValueError):
            return False
    return (jetzt_n or {}).get(key, 0) > v


def tsx_k4_fill(stand, befehl, vorher, klick_ms):
    """REIN RECHNEND (testbar): Beweis nach dem Klick aus EINEM Blick -> (einstieg | None, quelle, abgelehnt_text).
    1. NEUE Meldung „Order Filled" (nicht im Vorher-Stand, erst nach dem Klick gesehen) mit Richtung, Wurzel und Menge des Plans →
       Execute Price, quelle 'fill'. 2. Positionszeile (Tabelle unten oder Order-Karte) mit Wurzel, Richtung und GENAU der Plan-Menge →
       Entry Price, quelle 'position' (das Konto war vor dem Klick flach bewiesen). Eine neue Meldung „Order Rejected" → abgelehnt_text —
       Prüfer 06.10.2026: NUR die Ablehnung der eigenen Market-Order (Seite des Plans, Typ Market, Wurzel; eine Meldung ohne diese Angaben
       zählt) und NUR, wenn derselbe Blick weder Fill noch Position zeigt. Ein abgelehntes Bracket-Bein (Gegenseite, Stop/Limit — Vorfall
       B37 30.09.2026: „SL-Bracket abgelehnt, Position steht") hätte sonst 'abgelehnt' gemeldet, der Plan blieb „Geplant" bei offener
       Position (tsx_k4_ablehnungen macht daraus eine Warnung)."""
    st = stand if isinstance(stand, dict) else {}
    b = befehl if isinstance(befehl, dict) else {}
    r, w, n = str(b.get("richtung") or "").lower(), str(b.get("wurzel") or "").upper(), b.get("menge")
    t = st.get("toasts") if isinstance(st.get("toasts"), dict) else {}
    abg = ""
    jetzt_n = _tsx_k4_anzahl(t.get("meldungen"))
    for m in (t.get("meldungen") or []):
        if not isinstance(m, dict):
            continue
        if not _tsx_k4_neu(m, _tsx_k4_key(m), jetzt_n, vorher, klick_ms):
            continue
        typ_market = str(m.get("typ") or "market").strip().lower() == "market"
        if m.get("status") == "abgelehnt":
            if (not abg and m.get("seite") in (None, r) and typ_market
                    and (not m.get("symbol") or tv_symbol_root(str(m.get("symbol"))) == w)):
                abg = str(m.get("text") or m.get("titel") or "Order Rejected")[:120]
            continue
        if (m.get("art") == "fill" and m.get("seite") == r and tv_symbol_root(str(m.get("symbol") or "")) == w and typ_market
                and isinstance(m.get("preis"), (int, float)) and m.get("preis") > 0 and m.get("menge") in (None, n, float(n or 0))):
            return float(m["preis"]), "fill", ""
    for p in (st.get("positionen") or []):
        if (isinstance(p, dict) and p.get("seite") == r and tv_symbol_root(str(p.get("symbol") or "")) == w
                and isinstance(p.get("menge"), (int, float)) and int(p["menge"]) == int(n or 0) and p["menge"] == int(p["menge"])
                and isinstance(p.get("avg"), (int, float)) and p["avg"] > 0):
            return float(p["avg"]), "position", ""
    return None, "", abg


def tsx_k4_ablehnungen(stand, vorher, klick_ms):
    """REIN RECHNEND (testbar): Texte aller NEUEN, nach dem Klick gesehenen Meldungen „Order Rejected" eines Blicks (gleich welcher Order) —
    neben einem bewiesenen Fill eine Warnung „Brackets in TopstepX prüfen", nie ein Urteil über die Order. -> [text, …]"""
    st = stand if isinstance(stand, dict) else {}
    t = st.get("toasts") if isinstance(st.get("toasts"), dict) else {}
    aus = []
    jetzt_n = _tsx_k4_anzahl(t.get("meldungen"))
    for m in (t.get("meldungen") or []):
        if not isinstance(m, dict) or m.get("status") != "abgelehnt":
            continue
        if not _tsx_k4_neu(m, _tsx_k4_key(m), jetzt_n, vorher, klick_ms):
            continue
        x = str(m.get("text") or m.get("titel") or "Order Rejected")[:120]
        if x not in aus:
            aus.append(x)
    return aus[:4]


def tsx_k4_zeile(stand, befehl):
    """REIN RECHNEND (testbar): GENAU EINE Zeile der Positions-Tabelle zum Plan (Wurzel, Vorzeichen und Menge) -> (zeile | None, grund)"""
    g = _tsx_tk(stand).get("gitter") if isinstance(_tsx_tk(stand).get("gitter"), dict) else {}
    if not g.get("da"):
        return None, str(g.get("grund") or "Positions-Tabelle nicht im Bild")[:90]
    b = befehl if isinstance(befehl, dict) else {}
    soll = int(b.get("menge") or 0) * (1 if str(b.get("richtung") or "").lower() == "buy" else -1)
    w = str(b.get("wurzel") or "").upper()
    tr = [z for z in (g.get("zeilen") or []) if isinstance(z, dict) and tv_symbol_root(str(z.get("symbol") or "")) == w
          and isinstance(z.get("menge"), (int, float)) and z["menge"] == soll]
    if len(tr) != 1:
        da = [f"{z.get('symbol')} {z.get('menge')}" for z in (g.get("zeilen") or []) if isinstance(z, dict)][:4]
        return None, f"Zeile {w} {soll:+d} {len(tr)}× in der Positions-Tabelle (dort: {da or '-'})"
    return tr[0], ""


def _tsx_k4_reiter(s, st, trail):
    """K4 Schritt 5: Reiter „Positions" unten offen und die Tabelle mit Risk / To Make im Bild. Höchstens EIN Klick auf den Reiter
    (Ziel-Beweis), danach neu lesen. -> (ok, stand, grund)"""
    geklickt = False
    for _ in range(6):
        t = _tsx_tk(st)
        rt = (t.get("reiter") or {}).get("positions") if isinstance(t.get("reiter"), dict) else None
        g = t.get("gitter") if isinstance(t.get("gitter"), dict) else {}
        if not t.get("k4"):
            return False, st, "augen_tsx.js liest die Positions-Tabelle noch nicht (Stand ohne K4-Felder)"
        if g.get("da") and (not isinstance(rt, dict) or rt.get("aktiv")):
            return True, st, ""
        if isinstance(rt, dict) and not rt.get("aktiv") and not geklickt:
            r = cdp_rect(rt.get("rect"))
            zu = rt.get("zu") if isinstance(rt.get("zu"), dict) else {}
            if not r or zu.get("verdeckt") or zu.get("disabled"):
                return False, st, "Reiter „Positions“ unten verdeckt oder ohne Rechteck"
            r = list(r)[:4]
            _tsx_pause()
            if not s.klick(r, "Reiter Positions", pruef={"rect": r, "text": "positions", "aria": "", "tabu": TSX_K4_TABU}):
                return False, st, "Reiter „Positions“ nicht gedrückt (Klick ohne Beweis)"
            geklickt = True
        elif not isinstance(rt, dict) and not g.get("da"):
            return False, st, "Reiter „Positions“ unten nicht gefunden"
        _warte(0.7, 0.4)
        st = s.stand()
    return False, st, "Reiter „Positions“ offen, aber die Tabelle mit Risk / To Make ist nicht zu sehen"


def _tsx_k4_feld_aus(st, befehl, feld):
    z, grund = tsx_k4_zeile(st, befehl)
    f = z.get(feld) if isinstance(z, dict) and isinstance(z.get(feld), dict) else None
    return f, (grund if not z else ("" if f else "Zelle nicht gefunden"))


def _tsx_k4_feld(s, st, befehl, feld, usd, name, trail):
    """K4 Schritt 6: EINE Zelle (Risk bzw. To Make) der Plan-Zeile setzen — Doppelklick ins linke Stück der Zelle (nie der Stift, nie
    die Close-Spalte), Eingabefeld MIT Fokus beweisen, alten Wert weg (Strg+A, Rücktaste — leer bewiesen), Betrag tippen, Rücklesung
    des Felds, Enter, Rücklesung der Zelle (ein Tick Spiel). Höchstens zwei Versuche; ein offenes Eingabefeld wird mit Esc verlassen.
    -> (ok, ist_usd | None, grund, stand)"""
    tol = tsx_k4_toleranz(befehl.get("wurzel"), befehl.get("menge"))
    text = tsx_k4_betrag_text(usd)
    letzter = ""
    for versuch in range(2):
        if versuch == 1 and TSX_K3_WACHHUND_S - trail.sekunden() < 27.0:
            # Prüfer 06.10.2026: ein zweiter Versuch braucht bis ~19 s — der Wachhund (os._exit) träfe sonst mitten ins Tippen
            letzter += " — kein zweiter Versuch (Zeitlimit des Laufs)"
            break
        f, grund = _tsx_k4_feld_aus(st, befehl, feld)
        if not f and versuch == 0:
            # Prüfer 06.10.2026: nach einem Fill über die Meldung zeigt die Positions-Tabelle die Zeile womöglich erst Sekunden später
            for _ in range(4):
                _warte(0.7, 0.4)
                st = s.stand()
                f, grund = _tsx_k4_feld_aus(st, befehl, feld)
                if f:
                    break
        if not f:
            return False, None, f"{name}: {grund}", st
        e = f.get("edit") if isinstance(f.get("edit"), dict) else {}
        if not e.get("offen"):
            w = f.get("wert")
            if isinstance(w, (int, float)) and w > 0 and abs(w - usd) <= tol:   # 0 $ (kein Bracket) zählt nie als „steht schon"
                trail.append(f"{name} steht schon auf {w:g} $")
                return True, float(w), "", st
            r = cdp_rect(f.get("rect"))
            zu = f.get("zu") if isinstance(f.get("zu"), dict) else {}
            if not r or r[2] < 30 or zu.get("verdeckt") or zu.get("disabled"):
                return False, None, f"{name}-Zelle verdeckt, gesperrt oder ohne Rechteck", st
            r = list(r)[:4]
            links = [r[0] + 4.0, r[1], max(12.0, r[2] * 0.4), r[3]]      # linkes Stück: der Stift sitzt rechts neben dem Wert
            _tsx_pause()
            if not s.klick(links, f"{name}-Zelle (Doppelklick)", pruef={"rect": r, "text": "", "aria": "", "tabu": TSX_K4_TABU}, doppel=True):
                return False, None, f"{name}-Zelle nicht gedrückt (Klick ohne Beweis)", st
            _warte(0.5, 0.3)
            st = s.stand()
            f, grund = _tsx_k4_feld_aus(st, befehl, feld)
            e = f.get("edit") if isinstance(f, dict) and isinstance(f.get("edit"), dict) else {}
        if not e.get("offen") or e.get("fokus") is not True:
            letzter = f"{name}: nach dem Doppelklick kein Eingabefeld mit Fokus"
            trail.append(letzter + (" — zweiter Versuch" if versuch == 0 else ""))
            if e.get("offen"):
                _cdp_esc(s, st, trail, f"{name}-Feld ohne Fokus")
            _warte(0.6, 0.3)
            st = s.stand()
            continue
        # alten Wert weg: Strg+A + Rücktaste, danach muss das Feld LEER sein (sonst hinge der Betrag an der alten Zahl)
        s.taste("a", modifiers=2)
        _warte(0.2, 0.2)
        s.taste("Backspace")
        _warte(0.3, 0.2)
        st = s.stand()
        f, _g = _tsx_k4_feld_aus(st, befehl, feld)
        e = f.get("edit") if isinstance(f, dict) and isinstance(f.get("edit"), dict) else {}
        rest = str(e.get("wert") or "")
        if e.get("offen") and e.get("fokus") is True and rest and len(rest) <= 12:
            for _ in range(len(rest) + 1):                # Strg+A griff nicht: Zeichen für Zeichen (der Zeiger steht am Ende)
                s.taste("Backspace")
            _warte(0.3, 0.2)
            st = s.stand()
            f, _g = _tsx_k4_feld_aus(st, befehl, feld)
            e = f.get("edit") if isinstance(f, dict) and isinstance(f.get("edit"), dict) else {}
        if not e.get("offen") or e.get("fokus") is not True or str(e.get("wert") or ""):
            letzter = f"{name}: Eingabefeld nicht leer oder ohne Fokus ('{e.get('wert')}') — nichts getippt"
            trail.append(letzter + (" — zweiter Versuch" if versuch == 0 else ""))
            if e.get("offen"):
                _cdp_esc(s, st, trail, f"{name}-Feld nicht leer")
            _warte(0.6, 0.3)
            st = s.stand()
            continue
        s.tippen(text)
        _warte(0.5, 0.3)
        st = s.stand()
        f, _g = _tsx_k4_feld_aus(st, befehl, feld)
        e = f.get("edit") if isinstance(f, dict) and isinstance(f.get("edit"), dict) else {}
        if not (e.get("offen") and e.get("fokus") is True and tsx_k4_wert_gleich(e.get("wert"), usd)):
            letzter = f"{name}: im Eingabefeld steht '{e.get('wert')}', erwartet {text} — nicht bestätigt"
            trail.append(letzter + (" — zweiter Versuch" if versuch == 0 else ""))
            if e.get("offen"):
                _cdp_esc(s, st, trail, f"{name}-Feld mit falschem Wert")
            _warte(0.6, 0.3)
            st = s.stand()
            continue
        s.taste("Enter")
        f = {}
        for _ in range(5):
            _warte(0.7, 0.3)
            st = s.stand()
            if st.get("popups"):
                titel = str((st["popups"][0] or {}).get("titel") or (st["popups"][0] or {}).get("text") or "")[:50]
                return False, None, f"{name}: TopstepX fragt nach dem Eintragen etwas ('{titel}') — nichts bestätigt, bitte ansehen", st
            f, _g = _tsx_k4_feld_aus(st, befehl, feld)
            f = f if isinstance(f, dict) else {}
            if not (f.get("edit") or {}).get("offen") and isinstance(f.get("wert"), (int, float)) and f["wert"] > 0 and abs(f["wert"] - usd) <= tol:
                trail.append(f"{name} {text} $ eingetragen — Rücklesung {f['wert']:g} $")
                return True, float(f["wert"]), "", st
        letzter = f"{name}: nach Enter steht '{f.get('text') or '-'}' statt {text} $"
        trail.append(letzter + (" — zweiter Versuch" if versuch == 0 else ""))
        if (f.get("edit") or {}).get("offen"):
            _cdp_esc(s, st, trail, f"{name}-Feld blieb offen")
            _warte(0.6, 0.3)
            st = s.stand()
    return False, None, letzter or f"{name} nicht gesetzt", st


def _tsx_k4_feld_retten(s, st, befehl, name, trail):
    """Nach einer Ausnahme in einer Zelle: Stand frisch lesen, ein offenes Eingabefeld mit Esc verlassen (_cdp_esc fängt selbst, nie über
    einem Dialog), noch einmal lesen. -> (stand, abbruch) — abbruch True, wenn die Plan-Zeile nicht lesbar ist oder ein Feld noch offen
    steht: dann wird keine weitere Zelle angeklickt (ein Klick daneben übernähme den halben Betrag). Wirft nie."""
    try:
        try:
            st = s.stand()
        except Exception:
            pass
        _cdp_esc(s, st, trail, f"{name}-Feld nach Abbruch")
        _warte(0.5, 0.3)
        try:
            st = s.stand()
        except Exception:
            return st, True
        z, _g = tsx_k4_zeile(st, befehl)
        if not isinstance(z, dict):
            return st, True
        offen = any(isinstance(z.get(k), dict) and isinstance(z[k].get("edit"), dict) and z[k]["edit"].get("offen") for k in ("risk", "to_make"))
        return st, bool(offen)
    except Exception:
        return st, True


def _tsx_k4_senden(s, st, befehl, ziel, kn, res, trail, raus, order_cmd):
    """K4: aus dem bestandenen Vor-Klick-Blick (tsx_k3_vor_klick) EIN Klick auf den Order-Knopf, Fill beweisen, Risk / To Make
    eintragen. Nach dem Klick gibt es nur noch Lesen und die zwei Zellen — nie einen zweiten Order-Klick, nie ein Close."""
    res["schritt"] = "senden"
    res.update(etappe="K4", scharf=True)
    ktext = " ".join(str(kn.get("text") or "").split())
    rest = TSX_K3_WACHHUND_S - trail.sekunden()
    if rest < TSX_K4_REST_S:
        return raus("zeit", (f"Ticket bereit ({ktext}), aber nur noch {int(rest)} s bis zum Zeitlimit — nichts gesendet. "
                             "Bitte erneut starten (TopstepX ist jetzt offen und angemeldet)."), "senden")
    tp, sl = tsx_k4_betraege(order_cmd)
    # Prüfer 06.10.2026: der K4-Vertrag der Augen VOR dem unumkehrbaren Klick — mit einer alten augen_tsx.js (ohne Reiter/Tabelle)
    # ginge die Order sonst raus und Risk / To Make blieben leer
    t4 = _tsx_tk(st)
    if not t4.get("k4"):
        return raus("anker_fehlt", ("Ticket bereit, aber augen_tsx.js liest die Positions-Tabelle noch nicht (Stand "
                                    f"{str(st.get('v') if isinstance(st, dict) else '-')[:12]} ohne K4-Felder) — nichts gesendet. Bitte erneut starten."), "senden")
    rt = (t4.get("reiter") or {}).get("positions") if isinstance(t4.get("reiter"), dict) else None
    g4 = t4.get("gitter") if isinstance(t4.get("gitter"), dict) else {}
    if (tp or sl) and not isinstance(rt, dict) and not g4.get("da"):
        return raus("anker_fehlt", "Reiter „Positions“ unten nicht gefunden — Risk / To Make wären nicht setzbar, nichts gesendet.", "senden")
    vorher = tsx_k4_meldung_schluessel(st)
    r = list(cdp_rect(kn.get("rect")))[:4]
    try:                                               # Spur VOR dem unumkehrbaren Klick sichern, ohne ihn aufzuhalten
        import threading
        threading.Thread(target=_puls_diagnose_senden, args=(list(trail), "tsx_order_cdp"), daemon=True).start()
    except Exception:
        pass
    res.update(gesendet=True, retry_ok=False)          # VOR dem Klick: Wachhund/Absturz danach melden nie „nichts gesendet"
    klick_ms = int(time.time() * 1000)
    s._druck_versucht = False                          # die Hand setzt ihn unmittelbar vor dem Druck (Prüfer 06.10.2026)
    try:
        gedrueckt = s.klick(r, f"ORDER-Knopf '{ktext}'", pruef={"rect": r, "text": ktext.lower(), "aria": "", "tabu": TSX_K4_TABU})
    except Exception as e_:
        if getattr(s, "_druck_versucht", True):
            raise                                      # Druck versucht: gesendet true / retry_ok false bleiben (wie Wachhund/Absturz)
        res.update(gesendet=False, retry_ok=True)      # Ausnahme nachweislich VOR dem Druck (Lesen über CDP riss ab)
        return raus("knopf", f"Order-Knopf '{ktext}' nicht gedrückt ({type(e_).__name__} vor dem Druck) — nichts gesendet.", "senden")
    if not gedrueckt:
        res.update(gesendet=False, retry_ok=True)      # nachweislich kein Druck
        return raus("knopf", f"Order-Knopf '{ktext}' nicht gedrückt (Klick ohne Beweis) — nichts gesendet.", "senden")
    res.update(klick_at=time.strftime("%Y-%m-%dT%H:%M:%S", time.gmtime(klick_ms / 1000)) + "Z", order_klick_ms=klick_ms, geklickt=True)
    _puls_ergebnis_senden("order", "geklickt", order_cmd, res, trail)
    res["schritt"] = "beweis"
    einstieg, quelle, abg = None, "", ""
    nach, t_nach = None, 0.0                           # nur ein gelungener, junger Blick NACH dem Klick darf „flach" belegen (Prüfer 06.10.2026)
    ende = time.time() + TSX_K4_BEWEIS_S
    while time.time() < ende:
        _warte(0.5, 0.25)
        try:
            st = s.stand()
        except Exception as e_:
            trail.append(f"Lesen nach dem Klick: {type(e_).__name__}")
            nach = None
            continue
        nach, t_nach = st, time.time()
        einstieg, quelle, abg_ = tsx_k4_fill(st, befehl, vorher, klick_ms)
        # Nachprüfer 06.10.2026: eine Ablehnung ohne Seite/Typ/Symbol (Toast ohne Order-Zeile) kann ein Bracket-Bein sein — nur merken,
        # weiterlesen; ein Fill/Position im nächsten Blick gewinnt. Kostet im echten Ablehnungsfall höchstens die Beweiszeit (nur Lesen).
        abg = abg_ or abg
        if einstieg is not None:
            break
    if einstieg is None and abg:
        return raus("abgelehnt", f"TopstepX hat die Order abgelehnt: {abg}", "beweis", abgelehnt_text=abg)
    if einstieg is None:
        # vor dem Klick war flach PFLICHT — ein alter Stand bewiese hier nichts: ohne jungen Blick nach dem Klick immer UNKLAR
        jung = isinstance(nach, dict) and (time.time() - t_nach) <= 3.0
        flach = nach.get("flach") if jung else None
        return raus("beweis", (f"Order-Knopf '{ktext}' gedrückt, aber in {int(TSX_K4_BEWEIS_S)} s weder Fill-Meldung noch Position gelesen"
                               + (" — TopstepX zeigt „No Active Position“." if flach is True else
                                  " — ⚠ Ergebnis UNKLAR: in TopstepX nachsehen, NICHT erneut starten.")),
                    "beweis", unklar=(flach is not True))
    pos = cdp_positionen_vertrag(st.get("positionen"))
    res.update(einstieg=einstieg, einstieg_quelle=quelle, positionen=pos, offen=True, position="offen")
    trail.append(f"Fill bewiesen ({quelle}): {befehl['richtung'].upper()} {befehl['menge']} {ziel} @ {einstieg:g}")
    warn, ist, abbruch = [], {}, False
    for a_ in tsx_k4_ablehnungen(st, vorher, klick_ms):   # abgelehntes Bracket-Bein neben dem Fill (B37) → Warnung, kein Urteil
        warn.append(f"TopstepX hat eine Order abgelehnt: {a_}")
    if abg and not any(abg in w_ for w_ in warn):     # in einem früheren Blick gemerkte Ablehnung (Toast evtl. schon weg)
        warn.append(f"TopstepX hat eine Order abgelehnt: {abg}")
    # Ab hier ist die Order bewiesen: KEINE Ausnahme darf den Lauf noch als 'cdp_fehler' enden lassen (Prüfer 06.10.2026 — Tastatur
    # wirft, wenn das Puls-Chrome nicht vorn ist; ein halb getippter Betrag bliebe im offenen Feld). Jeder Fehler wird Warnung, ein
    # offenes Eingabefeld wird mit Esc verlassen, und solange es offen sein könnte, wird keine zweite Zelle angeklickt.
    if tp or sl:
        res["schritt"] = "brackets"
        if isinstance(st, dict) and st.get("popups"):       # ein Dialog nach dem Fill: nichts darunter anklicken
            ok_r, grund_r = False, "nach dem Fill steht ein Dialog offen — Risk / To Make nicht gesetzt"
        else:
            try:
                ok_r, st, grund_r = _tsx_k4_reiter(s, st, trail)
            except Exception as e_:
                ok_r, grund_r = False, f"Reiter Positions abgebrochen ({type(e_).__name__}: {str(e_)[:80]})"
        if not ok_r:
            warn.append(grund_r)
        else:
            for feld, usd, name in (("risk", sl, "Risk"), ("to_make", tp, "To Make")):
                if not usd:
                    continue
                if abbruch:
                    warn.append(f"{name} {tsx_k4_betrag_text(usd)} $ nicht gesetzt (nach dem Abbruch nicht mehr versucht — ein Eingabefeld könnte offen sein)")
                    continue
                if isinstance(st, dict) and st.get("popups"):
                    warn.append(f"{name} {tsx_k4_betrag_text(usd)} $ nicht gesetzt (Dialog offen)")
                    continue
                if TSX_K3_WACHHUND_S - trail.sekunden() < 30.0:      # eine Zelle mit zwei Versuchen + Zeilen-Warten braucht bis ~29 s (Nachprüfer 06.10.2026)
                    warn.append(f"{name} {tsx_k4_betrag_text(usd)} $ nicht gesetzt (Zeitlimit des Laufs)")
                    continue
                try:
                    ok_f, wert, grund_f, st = _tsx_k4_feld(s, st, befehl, feld, usd, name, trail)
                except Exception as e_:
                    ok_f, wert, grund_f = False, None, f"abgebrochen: {type(e_).__name__}: {str(e_)[:80]} — Eingabefeld evtl. offen"
                    trail.append(f"{name}: {grund_f}")
                    st, abbruch = _tsx_k4_feld_retten(s, st, befehl, name, trail)
                if ok_f:
                    ist[feld] = wert
                else:
                    warn.append(f"{name} {tsx_k4_betrag_text(usd)} $ nicht gesetzt ({grund_f})")
    z, _g = tsx_k4_zeile(st, befehl)
    if not sl and isinstance(z, dict) and isinstance((z.get("risk") or {}).get("wert"), (int, float)) and z["risk"]["wert"] > 0:
        warn.append(f"Risk steht auf {z['risk']['wert']:g} $ (TopstepX-Bracket), der Plan hat keinen SL")
    if not tp and isinstance(z, dict) and isinstance((z.get("to_make") or {}).get("wert"), (int, float)) and z["to_make"]["wert"] > 0:
        warn.append(f"To Make steht auf {z['to_make']['wert']:g} $ (TopstepX-Bracket), der Plan hat keinen TP")
    for feld, key, art in (("risk", "sl_level", "sl"), ("to_make", "tp_level", "tp")):
        if feld in ist:
            lv = tsx_k4_level(einstieg, befehl["richtung"], ist[feld], befehl["wurzel"], befehl["menge"], art)
            if lv:
                res[key], res[key + "_quelle"] = lv, "tsx_rechnung"
            res[("sl" if art == "sl" else "tp") + "_usd_ist"] = ist[feld]
    # balance/mll/rpl/upl bleiben die Werte der Lesung VOR dem Klick (flach, UP&L 0) — das Frontend nimmt rpl + upl als Start des
    # Tages-P&L (tsxBaselineAusOrder); ein Wert nach dem Fill trüge schon den laufenden Trade
    if warn:
        res["warnung"] = "Brackets in TopstepX prüfen: " + "; ".join(warn)
    msg = (f"Order platziert: {befehl['richtung'].upper()} {befehl['menge']} {ziel} @ {einstieg:g}"
           + (f" · Risk {ist['risk']:g} $" if "risk" in ist else "") + (f" · To Make {ist['to_make']:g} $" if "to_make" in ist else "")
           + (f" — ⚠ {res['warnung']}" if warn else "") + f" (bewiesen: {'Fill-Meldung' if quelle == 'fill' else 'Positionszeile'})")
    # Nachprüfer 06.10.2026: Antwort ZUERST — der Wachhund (158 s, os._exit) kann sie dann nicht mehr als 'haenger' überschreiben; die
    # beiden Netz-Sendungen (bis 2 s + 3 s) laufen danach, letzt_order.json liegt ohnehin vor dem Netz atomar auf der Platte
    r_ = raus("", msg, "fertig", ok=True)
    try:
        _puls_diagnose_senden(list(trail), "tsx_order_cdp")
    except Exception:
        pass
    _puls_ergebnis_senden("order", "ende", order_cmd, dict(res, ok=True, code="", schritt="fertig", msg=msg), trail)
    return r_


def _tsx_k3_probe(s, st, befehl, res, trail, raus, order_cmd=None):
    """K3a nach der K1/K2-Kette (Konto steht, Kopf gelesen, flach): Ticket füllen, dann aus EINEM frischen Blick prüfen
    (tsx_k3_vor_klick) und ehrlich enden — „Ticket bereit (nicht gesendet)". Klickt nie einen Order-Knopf.
    Seit K4 (05.10.2026): bei scharf:true übergibt die Probe nach bestandener Vorprüfung an _tsx_k4_senden."""
    res["schritt"] = "ticket"
    res["balance_start"] = res.get("balance")
    ok, code, msg, st, ziel = _tsx_k3_ticket(s, st, befehl, trail)
    if not ok:
        return raus(code, msg, "ticket")
    res["tv_symbol"] = ziel
    _tsx_pause()
    st = s.stand()                                    # EIN frischer Blick — daraus wird geurteilt
    ok, fehler, kn, markt_zu = tsx_k3_vor_klick(st, befehl, ziel, befehl["ext"])
    ktext = str((kn or {}).get("text") or "")
    nur_markt = markt_zu and len(fehler) == 1
    if not ok and not nur_markt:
        return raus("vorpruefung", "Ticket gefüllt, aber es passt noch nicht: " + "; ".join(fehler), "probe")
    if befehl.get("scharf") is True and TSX_K4_AKTIV:
        if not ok:                                    # Markt zu: der Knopf trägt nicht „Buy/Sell ±n @ Market" — nie drücken
            return raus("markt_zu", f"Ticket gefüllt, aber der Markt ist zu (Knopf zeigt '{ktext[:40]}') — nichts gesendet.", "probe")
        return _tsx_k4_senden(s, st, befehl, ziel, kn, res, trail, raus, order_cmd if isinstance(order_cmd, dict) else {})
    trail.append(f"Knopf '{ktext}' — nicht geklickt (Probe)")
    try:
        _puls_diagnose_senden(list(trail), "tsx_probe_cdp")
    except Exception:
        pass
    return raus("", (f"Ticket bereit (nicht gesendet): {ktext or '-'} · {ziel} · Konto {befehl['ext']}"
                     + (" — Markt zu, Knopf nicht prüfbar" if nur_markt else "")), "probe", ok=True)


def modus_tsxlesen_cdp(cmd, order=None, order_cmd=None):
    """order (K3a, 01.10.2026): geprüfter tsx_order_befehl ohne scharf — nach der Lesung füllt _tsx_k3_probe das Ticket (Contract, Menge)
    und endet vor dem Order-Knopf; Antwort wie tsx-konto (gesendet false, retry_ok), Wachhund TSX_K3_WACHHUND_S.
    K1: TopstepX im Puls-Chrome lesen — die ganze Kette in EINEM Lauf (Entscheidung 01.10.2026): Puls-Chrome starten, TopstepX-Tab öffnen,
    Login (ein Klick mit Autofill-Beweis), Tab nach vorn + Frische-Beweis, Bereit-Probe, bei falschem Konto K2 (_tsx_konto_sichern:
    Konto im Dropdown per Windows-Maus wechseln, KEINE Order), dann EIN stand() im Vertrag wie tv-lesen. Klicks nur Login + K2 (Hand-
    lauf-Sperre gesetzt, damit kein anderer Lauf dazwischen klickt). Wachhund TSX_K1_WACHHUND_S (140 s)."""
    res = {"ok": False, "code": "", "msg": "", "trail": "", "schritt": "start", "weg": "cdp", "etappe": "K1", "quelle": "cdp",
           "konto": "", "balance": None, "balance_relativ": None, "mll": None, "rpl": None, "upl": None, "position": None, "alter_s": None}
    if order:
        # tsx-konto-Vertrag: das Panel ergänzt nichts — gesendet/retry_ok kommen vom Bot (Prüfer K3a: sonst fehlten sie)
        res.update(etappe="K3", gesendet=False, retry_ok=True, scharf=False, plattform="tsx")
    k4 = bool(order and order.get("scharf") is True and TSX_K4_AKTIV)     # K4 (05.10.2026): scharfer Lauf — die Kette davor ist dieselbe
    wachhund_s = TSX_K3_WACHHUND_S if order else TSX_K1_WACHHUND_S
    diag_art = "tsx_order_cdp" if k4 else "tsx_probe_cdp" if order else "tsx_lesen_cdp"
    trail = _StempelSpur()
    trail.append(puls_bot_stand())
    trail.append(maus_hand_text())                 # 06.10.2026: welche Hand lief
    trail.append("Weg: Puls-Chrome (CDP) — " + (f"{'K4 SCHARF' if k4 else 'K3a Probe'} TopstepX ({order.get('richtung')} {order.get('menge')} {order.get('wurzel')})"
                                                 if order else "K1 Lesen TopstepX"))
    ext = str((cmd or {}).get("konto") or (cmd or {}).get("ext_id") or "").strip()
    sitz = [None]
    import threading
    antwort = _EineAntwort()

    def raus(code, msg, schritt, ok=False, zuerst=None, **extra):
        if not antwort.nehmen():
            return
        if sitz[0] and res.get("gesendet"):
            _tsx_bleiben_starten(sitz[0], res, trail)        # 06.10.2026: nach gesendeter Order im Tab bleiben (Kind minimiert später)
        if zuerst:
            zuerst()                                          # Wachhund: erst die Sitzung schließen (Hauptpfad anhalten), dann antworten
        res.update(ok=ok, code=code, msg=msg, schritt=schritt, **extra)
        res["trail"] = " > ".join(trail)
        antwort.ausgeben(res)
        if not ok:
            _puls_diagnose_senden(trail, diag_art)

    if len(_nur_alnum(ext)) < 5:
        return raus("befehl", "Feld 'konto' (External ID) fehlt", "befehl")
    if _handlauf_aktiv():
        return raus("handlauf", "Im Puls-Chrome läuft gerade ein Hand-Lauf — nichts gelesen, gleich erneut.", "sperre")
    # K2 klickt (Login, Konto-Auslöser, Konto-Zeile): Sperre wie K0 setzen, damit kein zweiter Puls-Chrome-Lauf dazwischen klickt
    _handlauf_setzen(True)

    def _schliessen():
        try:
            if sitz[0]:
                sitz[0].zu()
        except Exception:
            pass

    def _wachhund():
        trail.append(f"Wachhund: nach {int(wachhund_s)} s abgebrochen (Schritt {res.get('schritt')})")
        try:
            raus("haenger", f"TopstepX-{'Order' if k4 else 'Probe' if order else 'Lesen'} hing nach {int(wachhund_s)} s — abgebrochen.", "haenger",
                 zuerst=_schliessen)
        finally:
            _schliessen()
            _handlauf_setzen(False)
            os._exit(0)
    wh = threading.Timer(wachhund_s, _wachhund)
    wh.daemon = True
    wh.start()
    try:
        if not _puls_chrome_sicher(trail, url=TSX_URL):
            return raus("chrome", "Puls-Chrome nicht erreichbar (Port 9333).", "chrome")
        res["schritt"] = "login"
        s, lg = _tsx_sitzung_waehlen(trail, sitz)       # anderer angemeldeter TopstepX-Tab vor dem Login-Weg (Live 30.09.2026)
        if s is None:
            return raus("tab", lg, "tab")
        if lg is not True:
            return raus("login", lg, "login")
        res["schritt"] = "frisch"
        if _WIN_EINGABE:
            hw, gr = s._win_vorn()                      # Tab + Fenster nach vorn — ein Hintergrund-Tab rendert gedrosselt
            if not hw:
                trail.append(f"Nach vorn: {gr}")
        try:
            s.ws.rufe("Page.bringToFront", {}, timeout=3)
        except Exception:
            pass
        frisch, ftext = tsx_frisch_urteil(s.lese_js(TSX_FRISCH_JS, timeout=5))
        trail.append(ftext)
        if not frisch:
            # K1-Prüfer 30.09.2026: ok mit leerem alter_s nahm „Balance jetzt lesen" trotzdem als Live-Wert — ein gedrosselter Tab
            # liefert womöglich einen alten Stand. Ehrlich ablehnen; das Frontend wiederholt wie bei jedem anderen Fehler.
            return raus("nicht_frisch", "TopstepX-Tab nicht frisch (Hintergrund/gedrosselt) — nichts gelesen, gleich erneut.", "frisch")
        res["schritt"] = "lesen"
        # Bereit-Probe (K0 30.09.2026: 0,8 s nach Laufbeginn stand noch „Loading the Ultimate Trading Experience" in der Seite):
        # bis TSX_K1_BEREIT_S auf Konto-Auslöser + BAL warten, erst dann zählt die Lesung. Nur lesen, kein Klick.
        st, bereit = _tsx_bereit_warten(s, trail)
        if not bereit:
            # Ladephase nach Kaltstart/Neuladen (01.10.2026): _tsx_cdp_login sah vielleicht noch den Lade-Schirm („Loading the Ultimate
            # Trading Experience") statt der Login-Seite. Steht JETZT die Login-Seite da, einmal den Login-Weg (ein Klick, Beweis,
            # 30-min-Sperre) und die Bereit-Probe noch einmal — sonst ehrlich weiter (tsx_cdp_lesung meldet anker_fehlt).
            bl = s.lese_js(TSX_K0_BLICK_JS) or {}
            if isinstance(bl, dict) and isinstance(bl.get("login"), dict) and bl["login"].get("seite"):
                res["schritt"] = "login"
                trail.append("Nach der Ladephase steht die TopstepX-Login-Seite da — Login-Weg")
                lg2 = _tsx_cdp_login(s, trail)
                if lg2 is not True:
                    return raus("login", lg2, "login")
                res["schritt"] = "lesen"
                st, bereit = _tsx_bereit_warten(s, trail)
        ko = st.get("konto") if isinstance(st, dict) and isinstance(st.get("konto"), dict) else {}
        # TSX-LADEN (05.10.2026): steht nach der Bereit-Probe nur noch der Lade-Schirm im Weg, trotzdem in den Konto-Schritt — der wartet
        # dort noch einmal kurz und meldet sonst ehrlich „lädt noch" (ohne das läse K1 unter dem Lade-Schirm das falsche Konto an)
        if (bereit or tsx_ladeschirm(ko)) and TSX_K2_AKTIV and tsx_konto_urteil(ko, ext) in ("nein", "vielleicht"):
            res["schritt"] = "konto"
            trail.append(f"K2: im Puls-Chrome steht '{str(ko.get('kontonr') or ko.get('aktiv') or '-')[:40]}', Ziel {ext} — Konto wechseln")
            ok2, c2, m2, st, ex2 = _tsx_konto_sichern(s, ext, st, trail)
            res.update({k: v for k, v in ex2.items() if k in ("konto_gewechselt", "konto_hinweis", "konto_zeilen", "konto_treffer", "popups")})
            if not ok2:
                return raus(c2, m2, "konto")
            if ex2.get("konto_gewechselt"):
                res["schritt"] = "lesen"
                st, bereit = _tsx_bereit_warten(s, trail)
                st, frisch_k = _tsx_kopf_frisch(s, st, ext, trail)
                if not frisch_k:
                    return raus("kopf_unruhig", (f"Konto auf {ext} gewechselt, aber die Kopfzeile stand nicht zweimal gleich — nichts gelesen, "
                                                 "gleich erneut (das Konto steht jetzt)."), "lesen")
        elif isinstance(st, dict) and ko.get("liste_offen"):
            trail.append("Konto-Liste steht offen (nicht von diesem Lauf) — nur gelesen, nichts geklickt")
        felder, code, msg = tsx_cdp_lesung(st, ext)
        res.update(felder)
        if code:
            return raus(code, msg, "lesen")
        res.update(alter_s=0.0, gelesen_at=time.strftime("%Y-%m-%dT%H:%M:%S"),
                   sprache_fremd=False, userscript=None, summary_fehler=None)
        if order:
            if res.get("offen") or res.get("positionen"):
                # Prüfer 06.10.2026: seit die Augen Positionen lesen (tsx-0.6), endete K1 bei offener Position nicht mehr — die Probe
                # hätte Contract/Menge auf ein nicht flaches Konto getippt. Wie vor K4: ehrlich bei „lesen" enden, Ticket unberührt.
                return raus("tabelle_unklar", f"Konto {ext} hat eine offene Position — Ticket nicht angefasst, nichts gesendet.", "lesen")
            return _tsx_k3_probe(s, st, order, res, trail, raus, order_cmd)
        if (cmd or {}).get("ende"):
            res["exit_diag"] = {"fehler": "Exit-Fill über CDP kommt mit K5"}
        trail.append(f"gelesen (CDP): BAL {res.get('balance')} · RP&L {res.get('rpl')} · UP&L {res.get('upl')} · {len(res.get('positionen') or [])} Pos"
                     + ("" if frisch else " — NICHT frisch (alter_s leer, das Frontend zählt die Lesung nicht)"))
        if res.get("konto_gewechselt"):
            msg += f" — Konto gewechselt (von {str(res['konto_gewechselt'].get('von') or '-')[:40]})"
        if res.get("konto_hinweis"):
            msg += f" — Konto „{res['konto_hinweis']}“ (nur gelesen)"
        return raus("", msg + ("" if frisch else " — Seite nicht frisch bewiesen"), "fertig", ok=True)
    except Exception as e:
        return raus("cdp_fehler", f"TopstepX-Lesen abgebrochen: {type(e).__name__}: {str(e)[:160]}", "absturz")
    finally:
        wh.cancel()
        _handlauf_setzen(False)
        if sitz[0]:
            sitz[0].zu()


def modus_tsxinventar_cdp(cmd):
    """K0: TopstepX im Puls-Chrome erfassen (siehe Block-Kopf). Antwort wie modus_tsxinventar: {ok, code, msg, trail, schritt, weg,
    arts, offen}. Sperrt andere Puls-Chrome-Läufe (Handlauf-Sperre) für die Dauer."""
    res = {"ok": False, "code": "", "msg": "", "trail": "", "schritt": "start", "weg": "cdp", "etappe": "K0", "arts": []}
    trail = _StempelSpur()
    trail.append(puls_bot_stand())
    trail.append(maus_hand_text())                 # 06.10.2026: welche Hand lief
    trail.append("Weg: Puls-Chrome (CDP) — K0 Inventar TopstepX")
    pc = _augen_pc_id()
    sitz = [None]

    import threading
    antwort = _EineAntwort()

    def raus(code, msg, schritt, ok=False, zuerst=None):
        if not antwort.nehmen():
            return
        if zuerst:
            zuerst()                                          # Wachhund: erst die Sitzung schließen (Hauptpfad anhalten), dann antworten
        res.update(ok=ok, code=code, msg=msg, schritt=schritt)
        res["trail"] = " > ".join(trail)
        antwort.ausgeben(res)
        _puls_diagnose_senden(trail, "tsx_inventar_cdp")

    if _handlauf_aktiv():
        return raus("handlauf", "Im Puls-Chrome läuft gerade ein anderer Hand-Lauf — nichts gelesen, gleich erneut anstoßen.", "sperre")
    _handlauf_setzen(True)

    def _schliessen():
        try:
            if sitz[0]:
                sitz[0].zu()
        except Exception:
            pass

    def _wachhund():
        # Prüfer K0: ohne Wachhund beendete das Panel den Bot nach 150 s hart — die Sperre blieb 15 min und hielt Orbit fern.
        # Stapel-Prüfer 30.09.2026: erst die Sitzung schließen (der Hauptpfad klickt dann nicht mehr), dann antworten, die
        # Handlauf-Sperre erst direkt vor dem Beenden freigeben.
        trail.append(f"Wachhund: nach {int(TSX_K0_WACHHUND_S)} s abgebrochen (Schritt {res.get('schritt')})")
        try:
            raus("haenger", f"K0-Inventar hing nach {int(TSX_K0_WACHHUND_S)} s — abgebrochen (Puls-Chrome ansehen: Liste/Dialog offen?).",
                 "haenger", zuerst=_schliessen)
        finally:
            _schliessen()
            _handlauf_setzen(False)
            os._exit(0)
    wh = threading.Timer(TSX_K0_WACHHUND_S, _wachhund)
    wh.daemon = True
    wh.start()
    try:
        if not _puls_chrome_sicher(trail, url=TSX_URL):      # Kaltstart mit TopstepX, nie mit dem TradingView-Chart (Prüfer K0)
            return raus("chrome", "Puls-Chrome nicht erreichbar (Port 9333) — einmal `python order_bot.py augen start tsx` am PC.", "chrome")
        s, lg = _tsx_sitzung_waehlen(trail, sitz)
        if s is None:
            return raus("tab", lg, "tab")
        if lg is not True:
            return raus("login", lg, "login")
        res["schritt"] = "bereit"
        _, bereit = _tsx_bereit_warten(s, trail)            # Live 30.09.2026 20:48 UTC: Grund-Inventar 0,5 s nach dem Login = leere Seite
        g = _tsx_k0_lesen(s, trail, "grund", pc, blick=s.lese_js(TSX_K0_BLICK_JS))
        if not g:
            return raus("inventar", "Grund-Inventar nicht lesbar (augen_tsx.js) — nichts geklickt.", "grund")
        res["arts"] += g["arts"]
        if not bereit and not cmd.get("nur_grund"):
            trail.append("Seite nicht bereit (Konto-Auslöser/BAL fehlen) — Konto- und Bracket-Schritt ausgelassen, nichts geklickt")
            res.setdefault("offen", []).append("konto/bracket: Seite nach dem Login nicht bereit")
        elif not cmd.get("nur_grund"):
            _tsx_k0_zustand(s, trail, pc, "konto", res)
            if res.pop("_nicht_zu", False):
                trail.append("Konto-Liste nicht bewiesen zu — Bracket-Schritt ausgelassen (nichts rutscht unter die Maus)")
                res.setdefault("offen", []).append("bracket: ausgelassen (Konto-Liste nicht bewiesen zu)")
            else:
                _tsx_k0_zustand(s, trail, pc, "bracket", res)
        msg = f"Inventar TopstepX gelesen ({', '.join(res['arts']) or 'nur lokal'}) — keine Order."
        if res.get("offen"):
            msg += " Offen: " + "; ".join(res["offen"])
        return raus("", msg, "fertig", ok=True)
    except Exception as e:
        return raus("cdp_fehler", f"K0-Inventar abgebrochen: {type(e).__name__}: {str(e)[:160]}", "absturz")
    finally:
        wh.cancel()
        _handlauf_setzen(False)
        if sitz[0]:
            sitz[0].zu()


