def augen_regel_weiche(regel_datei, jetzt, pc_id):
    """REIN RECHNEND (testbar): 'cdp' nur, wenn die lokale Regel 'cdp' sagt, ≤ 12 h alt ist und zu DIESEM PC gehört; sonst 'uia'."""
    if not isinstance(regel_datei, dict) or regel_datei.get("augen") != "cdp" or not pc_id:
        return "uia"
    if regel_datei.get("pc") not in (None, pc_id):
        return "uia"
    try:
        alt = jetzt - float(regel_datei.get("at") or 0)
    except (TypeError, ValueError):
        return "uia"
    return "cdp" if 0 <= alt <= AUGEN_CDP_WEICHE_S else "uia"


def augen_modus_lauf():
    """'cdp' | 'uia' für DIESEN Lauf. Frische lokale Regel (≤ 12 h) → ohne Netz wie bisher. Fehlt sie oder ist sie alt, EINMAL Railway
    fragen (_augen_regel_holen, 2 s, schreibt die Datei; Netzfehler → letzte gemerkte Regel). Live-Befund Finn 01.10.2026 12:28 UTC
    (pc-…, auf der CDP-Liste): der PC war > 12 h ohne Puls-Lauf, die Merk-Datei veraltet → der ERSTE Lauf nahm den alten UIA-Weg im
    normalen Chrome; aufgefrischt wurde die Regel bisher erst NACH dem Lauf (augen_anstossen). Jeder Fehler = 'uia'."""
    try:
        pc = _augen_pc_id()
        rd = _augen_json_lesen("augen_regel.json")
        m = augen_regel_weiche(rd, time.time(), pc)
        if m != "cdp" and pc and augen_regel_entscheid(rd, time.time()):   # fehlt/alt (ein FRISCHES 'uia' fragt nicht)
            m = _augen_regel_holen(pc)
        return m if m in ("cdp", "uia") else "uia"
    except Exception:
        return "uia"


def cdp_klick_bahn(von, nach, schritte=8, streu=2.0, rnd=None):
    """REIN RECHNEND (testbar): Zwischenpunkte einer Mausbahn (leicht gekrümmt, gestreut, letzter Punkt exakt = Ziel)."""
    import random as _r
    rnd = rnd or _r
    (x0, y0), (x1, y1) = von, nach
    n = max(3, int(schritte))
    bogen = rnd.uniform(-0.12, 0.12)
    out = []
    for i in range(1, n + 1):
        t = i / n
        tt = t * t * (3 - 2 * t)
        x = x0 + (x1 - x0) * tt - (y1 - y0) * bogen * t * (1 - t)
        y = y0 + (y1 - y0) * tt + (x1 - x0) * bogen * t * (1 - t)
        if i < n:
            x += rnd.uniform(-streu, streu)
            y += rnd.uniform(-streu, streu)
        out.append((round(x, 1), round(y, 1)))
    out[-1] = (float(x1), float(y1))
    return out


def cdp_klickpunkt(rect, rnd=None, hand=None):
    """REIN RECHNEND (testbar): Klickpunkt in einem [x, y, w, h]-Rechteck (CSS-px) — seit 06.10.2026 über klick_punkt (Hand des Laufs,
    Zug, Streuung, Saum zum Rand), nie einfach die Mitte; vorher gleichverteilt im inneren Drittel. None bei Unsinn."""
    try:
        x, y, w, h = [float(v) for v in rect[:4]]
    except (TypeError, ValueError, IndexError):
        return None
    if w < 2 or h < 2:
        return None
    px, py = klick_punkt(x, y, x + w, y + h, zufall=rnd, hand=hand)
    return (float(px), float(py))


