# PULS-CHROME MIT ECHTER WINDOWS-MAUS (29.09.2026, Finn: „wirklich manuelle Klicks … eine Lösung für alles, die immer nur so
# funktioniert", kein Schalter). augen.js ist das AUGE (Rechtecke, Werte); geklickt und getippt wird auf den Windows-PCs IMMER mit
# der echten Maus/Tastatur (SendInput, sichtbarer Zeiger) — so war augen.js gedacht („geklickt wird weiter mit der ECHTEN Maus").
# Vor jedem Druck beweist die Seite per :hover, dass genau das Ziel unter dem Zeiger liegt (kein fremdes Fenster darüber,
# Umrechnung stimmt) — sonst KEIN Druck, der Lauf bricht ab. Kein stiller Rückfall auf CDP-Eingaben. Nur ohne Windows (Mac-Tests)
# bleibt der CDP-Weg. Das Puls-Chrome kommt dafür nach vorn (Wiederherstellen — nie Größe ändern, sonst verschieben sich alle
# Rechtecke) und wird am Ende des Laufs wieder minimiert (Reader-Chrome frei, sonst drosselt Chrome den Feed).
# ═══════════════════════════════════════════════════════════════════════════
_WIN_EINGABE = (os.name == "nt")
PULS_WIN_TASTEN = {"Tab": "{TAB}", "Enter": "{ENTER}", "Escape": "{ESC}", "Backspace": "{BACKSPACE}", "Delete": "{DELETE}",
                   "ArrowDown": "{DOWN}", "ArrowUp": "{UP}"}
WIN_GEO_JS = "({innerWidth: innerWidth, innerHeight: innerHeight, dpr: devicePixelRatio, titel: String(document.title || '')})"


def win_taste_text(key, modifiers=0):
    """REIN RECHNEND (testbar): CDP-Tastenname → pywinauto-send_keys-Text (Strg = ^). None = unbekannte Taste."""
    k = str(key or "")
    t = PULS_WIN_TASTEN.get(k) or (k if len(k) == 1 and k.isalnum() else None)
    if t is None:
        return None
    return ("^" if int(modifiers or 0) & 2 else "") + ("+" if int(modifiers or 0) & 8 else "") + t


def puls_fenster_waehlen(fenster, titel):
    """REIN RECHNEND (testbar): fenster = [{hwnd, text, klasse, sichtbar}] des Puls-Chrome-Browsers, titel = document.title des Tabs.
    GENAU EIN Browser-Fenster (Chrome_WidgetWin_1, mit Titel, kein DevTools); bei mehreren das, dessen Titel mit dem ersten Wort des
    Seitentitels beginnt (der Kurs im TradingView-Titel ändert sich laufend — nur das erste Wort ist stabil). -> hwnd | None"""
    kand = [f for f in fenster or [] if isinstance(f, dict) and f.get("sichtbar") and f.get("klasse") == "Chrome_WidgetWin_1"
            and str(f.get("text") or "").strip() and not str(f.get("text")).startswith("DevTools")]
    if len(kand) == 1:
        return kand[0].get("hwnd")
    wort = (str(titel or "").split() or [""])[0]
    if wort:
        k2 = [f for f in kand if str(f.get("text")).startswith(wort)]
        if len(k2) == 1:
            return k2[0].get("hwnd")
    return None


def win_hover_js(x, y):
    """Liegt das Element an diesem Viewport-Punkt unter dem Mauszeiger (:hover)? Liest nur."""
    return ("(function(){var e=document.elementFromPoint(" + f"{float(x):.1f},{float(y):.1f}" +
            ");return !!(e&&e.matches(':hover'));})()")


def win_ziel_js(x, y):
    """Am Viewport-Punkt: liegt das Element unter dem Mauszeiger (:hover) — und gehört es zu einer TradingView-Meldung (Toast)?
    Live 29.09.2026 16:13 UTC: der aufgeklappte Meldungsstapel lag über dem Konto-Umschalter, der Klick traf die Meldung. Liest nur."""
    return ("(function(){var e=document.elementFromPoint(" + f"{float(x):.1f},{float(y):.1f}" + ");if(!e)return {hover:false,toast:false};"
            "var t=e.closest('[data-name^=\"toast-group-\"],[class*=\"toastGroup-\"],[class*=\"toastListInner-\"],[class*=\"toastItem\"]');"
            "return {hover:e.matches(':hover'),toast:!!t};})()")


def win_ziel_pruef_js(x, y, pruef):
    """Ziel-Beweis beim Druck (K0-Prüfer 30.09.2026: der Hover-Beweis bestätigt JEDES oberste Element — bei ID A liegt „SELL -1 @
    MARKET" 31 px unter dem Bracket-Zahnrad). Am Punkt: :hover UND das klickbare Element dort ist der Kandidat — seine Mitte liegt darin,
    es ist höchstens ~4× so groß, Text bzw. Beschriftung passen — und trägt kein Order-/Close-Wort. Liest nur. pruef = {rect, text, aria, tabu}
    + optional wort (K3a 01.10.2026): der Text GENAU am Klickpunkt ist dieses Wort (Contract-Vorschlag: „nqz26" steckt als Teilstring
    auch in „mnqz26" — die Zeile allein beweist nichts)."""
    return ("(function(p){var e=document.elementFromPoint(" + f"{float(x):.1f},{float(y):.1f}" + ");if(!e)return {hover:false,passt:false,was:''};"
            "function T(n){return String((n&&n.textContent)||'').replace(/\\s+/g,' ').trim().toLowerCase();}"
            "function A(n){return String(n.getAttribute('aria-label')||n.getAttribute('title')||'').toLowerCase();}"
            "var k=e.closest('input,textarea,button,[role=\"button\"],[role=\"combobox\"],[aria-haspopup],a[href],[tabindex]')||e,r=k.getBoundingClientRect(),c=p.rect;"
            "var mx=c[0]+c[2]/2,my=c[1]+c[3]/2,drin=mx>=r.left-3&&mx<=r.right+3&&my>=r.top-3&&my<=r.bottom+3,klein=r.width*r.height<=Math.max(4*c[2]*c[3],2500);"
            "var t=(p.text||'').toLowerCase(),a=(p.aria||'').toLowerCase(),kt=T(k),ka=A(k);"
            "var text_ok=(!t&&!a)||(t&&(kt.indexOf(t)>=0||T(e).indexOf(t)>=0))||(a&&(ka.indexOf(a)>=0||A(e).indexOf(a)>=0));"
            "var tabu=p.tabu?new RegExp(p.tabu,'i').test(kt+' '+ka):false,w=String(p.wort||'').toLowerCase(),wort_ok=!w||T(e)===w;"
            "var hs=document.querySelectorAll(':hover'),d=hs.length?hs[hs.length-1]:null,dr=d?d.getBoundingClientRect():null;"
            "var unter=d?(d.tagName.toLowerCase()+' '+String(d.getAttribute('data-testid')||d.getAttribute('aria-label')||T(d)).slice(0,30)"
            "+' @'+Math.round(dr.left)+','+Math.round(dr.top)):'nichts';"
            "return {hover:e.matches(':hover'),passt:!!(drin&&klein&&text_ok&&!tabu&&wort_ok),was:(kt||ka||k.tagName.toLowerCase()).slice(0,40),tabu:tabu,wort:wort_ok,unter:unter};})("
            + json.dumps(pruef, ensure_ascii=False) + ")")


# Schließen-Knöpfe der Meldungen, die GANZ im Bild liegen: erst das X der Gruppe (toast-group-close-button-*), sonst das X einzelner
# Meldungen (aria-label/title „Close"/„Schließen", Text ×) innerhalb eines Toast-Containers. Nur lesen.
CDP_TOAST_ZU_JS = r"""(function () {
  function drin(r) { return r.width >= 3 && r.height >= 3 && r.left >= 0 && r.top >= 0 && r.right <= innerWidth && r.bottom <= innerHeight; }
  function sb(e) { try { var s = getComputedStyle(e); return s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0'; } catch (_) { return false; } }
  function R(e) { var r = e.getBoundingClientRect(); return [r.left, r.top, r.width, r.height]; }
  var gruppe = Array.prototype.slice.call(document.querySelectorAll('[data-name^="toast-group-close-button-"]')).filter(function (e) {
    return sb(e) && drin(e.getBoundingClientRect()); });
  if (gruppe.length) return gruppe.slice(0, 3).map(function (e) { return { art: 'gruppe', dn: e.getAttribute('data-name'), rect: R(e) }; });
  var box = '[class*="toastGroup-"],[class*="toastListInner-"],[class*="toastItem"]';
  var einzeln = Array.prototype.slice.call(document.querySelectorAll('button,[role="button"]')).filter(function (e) {
    if (!e.closest(box) || !sb(e) || !drin(e.getBoundingClientRect())) return false;
    var w = (e.getAttribute('aria-label') || '') + ' ' + (e.getAttribute('title') || '') + ' ' + (e.textContent || '').trim();
    return /\bclose\b|schlie(ß|ss)en|dismiss|^\s*[×✕✖]\s*$/i.test(w) && !/show (more|less)|mehr|weniger/i.test(w); });
  return einzeln.slice(0, 6).map(function (e) { return { art: 'einzeln', dn: e.getAttribute('data-name') || '', rect: R(e) }; });
})()"""


# KLEINE WERBE-KACHEL (05.10.2026, Finn: „jedes Mal, wenn unten eine Ad … kommt, die per X weggeklickt werden kann, soll er auch diese
# kleinen Ads unten links automatisch wegklicken"). Inventar eines Orbit-PCs vom selben Abend: TradingView hängt im Meldungsbereich unten
# links einen Kasten div#charting-ad (460×150) ein — darin eine Google-Anzeige im iframe fremder Herkunft (ihr Text ist für die Seite
# nicht lesbar, darum sieht CDP_WERBUNG_JS sie nicht: es verlangt zwei Werbe-Wörter) und EIN Knopf mit dem Text „Close ad" (10×10 px,
# oben rechts). Der Kasten liegt über den Reitern Positions/Orders/Account summary und dort, wo die Kontoliste aufklappt. Gesucht wird
# NUR dieser Kasten (id; sonst der Elternkasten einer div-gpt-ad-toast-ad-Anzeige) und darin NUR genau ein sichtbarer, unverdeckter
# Knopf ≤ 44 px mit der Beschriftung „Close ad" (bzw. „Anzeige/Werbung schließen"). Nie ein anderes X. Nur lesen.
CDP_KACHEL_JS = r"""(function () {
  var RX = /\bclose ad\b|(?:anzeige|werbung) schlie(?:ß|ss)en/i;
  function sb(e) { try { var s = getComputedStyle(e); if (s.visibility === 'hidden' || s.display === 'none' || s.opacity === '0') return false;
    var r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2 && r.bottom > 0 && r.right > 0 && r.left < innerWidth && r.top < innerHeight; } catch (_) { return false; } }
  function R(e) { var r = e.getBoundingClientRect(); return [r.left, r.top, r.width, r.height]; }
  function W(e) { return ((e.getAttribute('aria-label') || '') + ' ' + (e.getAttribute('title') || '') + ' ' + (e.textContent || '')).replace(/\s+/g, ' ').trim(); }
  var boxen = [], a = document.getElementById('charting-ad');
  if (a) boxen.push(a);
  Array.prototype.slice.call(document.querySelectorAll('[id^="div-gpt-ad-toast-ad"]')).forEach(function (g) {
    var p = g.parentElement;
    if (p && p !== document.body && p !== document.documentElement && !boxen.some(function (b) { return b === p || b.contains(p); })) boxen.push(p); });
  var out = [];
  boxen.forEach(function (b) {
    if (out.length >= 2 || !sb(b)) return;
    var r = b.getBoundingClientRect();
    if (r.width < 120 || r.height < 40 || r.width > 800 || r.height > 500) return;
    var xs = Array.prototype.slice.call(b.querySelectorAll('button,[role="button"]')).filter(function (e) {
      if (!sb(e) || !RX.test(W(e))) return false;
      var q = e.getBoundingClientRect();
      if (q.width < 6 || q.height < 6 || q.width > 44 || q.height > 44 || q.left < 0 || q.top < 0 || q.right > innerWidth || q.bottom > innerHeight) return false;
      var oben = document.elementFromPoint(q.left + q.width / 2, q.top + q.height / 2);
      return !!oben && (oben === e || e.contains(oben));
    });
    xs = xs.filter(function (e) { return !xs.some(function (f) { return f !== e && e.contains(f); }); });
    if (xs.length !== 1) return;
    out.push({ id: String(b.id || '').slice(0, 40), box: R(b), x: R(xs[0]), wort: RX.exec(W(xs[0]))[0].toLowerCase() });
  });
  return out;
})()"""
CDP_KACHEL_RX = re.compile(r"^(close ad|(anzeige|werbung) schlie(ß|ss)en)$", re.I)
CDP_KACHEL_TABU = r"\b(buy|sell|order|position|flatten|cancel|log ?out|connect|kauf|verkauf)\b"


def cdp_kachel_wahl(roh):
    """REIN RECHNEND (testbar): erste gültige Werbe-Kachel aus CDP_KACHEL_JS -> {x, box, wort, id} | None. Gültig nur mit Schließen-
    Wort, einem X von 6–44 px und dem X-Mittelpunkt IM Kasten — alles andere (auch eine Attrappen-Antwort) ist keine Kachel."""
    for k in (roh if isinstance(roh, list) else []):
        if not isinstance(k, dict):
            continue
        x, box, wort = k.get("x"), k.get("box"), str(k.get("wort") or "").strip().lower()
        if not (isinstance(x, (list, tuple)) and len(x) >= 4 and isinstance(box, (list, tuple)) and len(box) >= 4):
            continue
        try:
            x, box = [float(v) for v in x[:4]], [float(v) for v in box[:4]]
        except (TypeError, ValueError):
            continue
        if not CDP_KACHEL_RX.match(wort) or not (6 <= x[2] <= 44 and 6 <= x[3] <= 44):
            continue
        mx, my = x[0] + x[2] / 2.0, x[1] + x[3] / 2.0
        if not (box[0] <= mx <= box[0] + box[2] and box[1] <= my <= box[1] + box[3]):
            continue
        return {"x": x, "box": box, "wort": wort, "id": str(k.get("id") or "")[:40]}
    return None


def _cdp_kachel_weg(s, trail):
    """Kleine TradingView-Werbe-Kachel (CDP_KACHEL_JS) über genau IHR X schließen — echte Maus, Ziel-Beweis auf den Knopftext
    („Close ad", win_ziel_pruef_js), danach „Kachel weg" bewiesen. Aufgerufen VOR dem Konto-Schritt und VOR dem Login-Schritt, also
    bevor ein Rechteck gelesen wird, das der Klick auf das X verschieben oder schließen könnte (bewusst nicht in klick(): dort stünde
    womöglich schon die Kontoliste offen). Wirft nie; ohne Windows-Maus und im TopstepX-Tab nichts. -> Anzahl geschlossener Kacheln"""
    if not _WIN_EINGABE or not getattr(s, "tv_riegel", True):
        return 0
    weg = 0
    try:
        for _ in range(2):
            k = cdp_kachel_wahl(s.lese_js(CDP_KACHEL_JS))
            if not k:
                break
            pruef = {"rect": k["x"], "text": k["wort"], "aria": k["wort"], "tabu": CDP_KACHEL_TABU}
            if not s._win_klick(k["x"], "Werbe-Kachel schließen (X)", toast_ok=True, pruef=pruef):
                trail.append("Werbe-Kachel unten links: X nicht gedrückt (kein Beweis) — weiter, Kachel bleibt")
                break
            _warte(0.6, 0.3)
            if cdp_kachel_wahl(s.lese_js(CDP_KACHEL_JS)):
                trail.append("Werbe-Kachel steht nach dem Klick auf ihr X noch da — weiter ohne")
                break
            trail.append("Werbe-Kachel unten links geschlossen (ihr X, weg bewiesen)")
            weg += 1
    except Exception as e_:                            # darf keinen Lauf verhindern — schlimmstenfalls bleibt die Kachel stehen
        trail.append(f"Werbe-Kachel-Prüfung übersprungen ({type(e_).__name__})")
    return weg


# WERBUNG IM PULS-CHROME (30.09.2026, Finn an PC von ID C pc-iiiiii, Screenshot „Don't miss this Autumn sale · Up to 80% off · Explore
# offers"): TradingViews Sale-Modal legte sich über den Connect-Dialog und verschluckte den Klick; der neue Puls kannte — anders als der
# alte (_tv_popups_weg) — kein Wegklicken. Gesucht werden sichtbare Kästen (kleinster zuerst, höchstens 80 % des Bilds) mit
# MINDESTENS ZWEI verschiedenen Werbe-Merkmalen und ohne Handels-/Login-Wort; geklickt wird nur ihr EINES X oben rechts (≤ 60 px,
# nie ein Knopf mit Kauf-/Angebots-Wort). „You have a discount" in der Kopfleiste allein ist nur EIN Merkmal und zählt nicht. Nur lesen.
CDP_WERBUNG_JS = r"""(function () {
  var MERKMALE = [/\bsale\b/i, /\d+\s*%\s*off|up to \d+\s*%/i, /don.?t miss/i, /\bends in\b|offer ends/i, /explore offers?/i,
                  /special offer/i, /black friday|cyber monday/i, /\bdiscount\b/i, /\bupgrade\b/i, /\bsubscription\b/i];
  var HART = /take profit|stop loss|tradovate|\bconnect\b|\blog ?in\b|password|passwort|quantity|\bcontracts?\b|\b(buy|sell) \d/i;
  var NIE = /explore|offer|angebot|upgrade|\bbuy\b|kauf|trial|\bget\b|\bstart|subscri|abonn|premium|\bplan|claim/i;
  function sb(e) { try { var s = getComputedStyle(e); if (s.visibility === 'hidden' || s.display === 'none' || s.opacity === '0') return false;
    var r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2 && r.bottom > 0 && r.right > 0 && r.left < innerWidth && r.top < innerHeight; } catch (_) { return false; } }
  function drin(r) { return r.left >= 0 && r.top >= 0 && r.right <= innerWidth && r.bottom <= innerHeight; }
  function R(e) { var r = e.getBoundingClientRect(); return [r.left, r.top, r.width, r.height]; }
  var sel = '[role="dialog"],[role="alertdialog"],[aria-modal="true"],[data-dialog-name],body > div,body > section,body > aside,' +
            '[class*="toast"],[class*="popup"],[class*="dialog"],[class*="modal"]';
  var kand = Array.prototype.slice.call(document.querySelectorAll(sel)).filter(sb).map(function (b) {
    var r = b.getBoundingClientRect(); return { b: b, r: r, f: r.width * r.height }; })
    .filter(function (k) { return k.r.width >= 200 && k.r.height >= 80 && k.f <= 0.8 * innerWidth * innerHeight; })
    .sort(function (a, c) { return a.f - c.f; });
  var out = [], genommen = [];
  kand.forEach(function (k) {
    if (out.length >= 3 || genommen.some(function (g) { return k.b.contains(g) || g.contains(k.b); })) return;
    var t = (k.b.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 400);
    var n = MERKMALE.filter(function (rx) { return rx.test(t); }).length;
    if (n < 2 || HART.test(t)) return;
    var xs = Array.prototype.slice.call(k.b.querySelectorAll('button,[role="button"],[aria-label],[data-name*="close"],[class*="close"]')).filter(function (e) {
      if (!sb(e)) return false;
      var q = e.getBoundingClientRect();
      if (q.width > 60 || q.height > 60 || q.width < 6 || q.height < 6 || !drin(q)) return false;
      if (k.r.right - q.right > 70 || q.top - k.r.top > 70) return false;
      var oben = document.elementFromPoint(q.left + q.width / 2, q.top + q.height / 2);   // verdecktes X (Karte unter dem Modal) erst später
      if (!oben || !(oben === e || e.contains(oben))) return false;
      var w = (e.getAttribute('aria-label') || '') + ' ' + (e.getAttribute('title') || '') + ' ' + (e.getAttribute('data-name') || '') + ' ' + (e.textContent || '').trim();
      if (NIE.test(w)) return false;
      return /close|schlie|dismiss/i.test(w) || /^\s*[×✕✖xX]?\s*$/.test(e.textContent || '');
    });
    xs = xs.filter(function (e) { return !xs.some(function (f) { return f !== e && e.contains(f); }); });
    if (xs.length !== 1) return;
    genommen.push(k.b);
    out.push({ text: t.slice(0, 120), box: R(k.b), x: R(xs[0]) });
  });
  return out;
})()"""


def _puls_fenster_liste(pid):
    """Sichtbare Top-Level-Fenster des Puls-Chrome-Browserprozesses (Windows). -> [{hwnd, text, klasse, sichtbar, minimiert}]"""
    import ctypes
    import ctypes.wintypes as wt
    u32 = ctypes.windll.user32
    out = []

    @ctypes.WINFUNCTYPE(ctypes.c_bool, wt.HWND, wt.LPARAM)
    def cb(h, _l):
        try:
            p_ = ctypes.c_ulong()
            u32.GetWindowThreadProcessId(h, ctypes.byref(p_))
            if pid and p_.value == int(pid) and u32.IsWindowVisible(h):
                n = u32.GetWindowTextLengthW(h)
                b = ctypes.create_unicode_buffer(n + 1)
                u32.GetWindowTextW(h, b, n + 1)
                k = ctypes.create_unicode_buffer(128)
                u32.GetClassNameW(h, k, 128)
                out.append({"hwnd": int(h), "text": b.value or "", "klasse": k.value or "", "sichtbar": True,
                            "minimiert": bool(u32.IsIconic(h))})
        except Exception:
            pass
        return True
    u32.EnumWindows(cb, 0)
    return out


def _win_vordergrund():
    import ctypes
    return int(ctypes.windll.user32.GetForegroundWindow() or 0)


def _win_minimiert(hwnd):
    import ctypes
    return bool(ctypes.windll.user32.IsIconic(int(hwnd)))


def _win_zeigen(hwnd, befehl):
    import ctypes
    ctypes.windll.user32.ShowWindow(int(hwnd), int(befehl))


def _win_nach_vorn(hwnd):
    """Fenster in den Vordergrund (pywinautos set_focus wie beim UIA-Puls, sonst SetForegroundWindow)."""
    try:
        from pywinauto.controls.hwndwrapper import HwndWrapper
        HwndWrapper(int(hwnd)).set_focus()
        return
    except Exception:
        pass
    try:
        import ctypes
        ctypes.windll.user32.SetForegroundWindow(int(hwnd))
    except Exception:
        pass


def _win_root_am_punkt(x, y):
    """Top-Level-Fenster (GA_ROOT) unter diesem Bildschirmpunkt — dorthin geht ein Druck wirklich. -> (hwnd, titel)"""
    import ctypes
    import ctypes.wintypes as wt
    u32 = ctypes.windll.user32
    u32.WindowFromPoint.argtypes, u32.WindowFromPoint.restype = [wt.POINT], wt.HWND
    u32.GetAncestor.argtypes, u32.GetAncestor.restype = [wt.HWND, wt.UINT], wt.HWND
    h = u32.WindowFromPoint(wt.POINT(int(x), int(y)))
    r = u32.GetAncestor(h, 2) if h else None
    b = ctypes.create_unicode_buffer(256)
    if r:
        u32.GetWindowTextW(r, b, 256)
    return int(r or 0), b.value or ""


def win_fokus_js(rect):
    """Hat das Feld an diesem Rechteck (CSS-px) den Tastatur-Fokus UND die Seite selbst den Fokus? Liest nur."""
    x, y, w, h = [float(v) for v in rect[:4]]
    return ("(function(){var a=document.activeElement;if(!document.hasFocus()||!a||a===document.body||a===document.documentElement)"
            "return false;var r=a.getBoundingClientRect();return r.right>" + f"{x:.1f}" + "&&r.left<" + f"{x + w:.1f}" + "&&r.bottom>"
            + f"{y:.1f}" + "&&r.top<" + f"{y + h:.1f}" + ";})()")


def _win_tasten(text_sk):
    """Echte Tastatur (pywinauto send_keys → SendInput) an das Vordergrund-Fenster."""
    from pywinauto import keyboard
    keyboard.send_keys(text_sk, with_spaces=True, pause=0.04)



def cdp_fehlertext(r):
    """REIN RECHNEND (testbar): lesbarer Text einer CDP-Ausnahme — exception.description (z. B. „TypeError: Cannot read properties of
    undefined (reading 'stand')") statt nur „Uncaught"."""
    ed = (r or {}).get("exceptionDetails") if isinstance(r, dict) else None
    if not isinstance(ed, dict):
        return ""
    ex = ed.get("exception") if isinstance(ed.get("exception"), dict) else {}
    return " ".join(str(ex.get("description") or ex.get("value") or ed.get("text") or "unbekannt").split())[:200]


def augen_fehlt(text):
    """REIN RECHNEND (testbar): sagt die Ausnahme, dass globalThis.prophosAugen fehlt (Seite neu geladen)?"""
    return bool(re.search(r"prophosAugen|of undefined|of null|is not a function|is not defined", str(text or ""), re.I))

class _AugenSitzung:
    """Eine CDP-Verbindung zur TradingView-Seite im Puls-Chrome: augen.js einmal geladen, stand() lesen, klicken (Windows: echte Maus)."""

    def __init__(self, trail, ziel=None, js_datei="augen.js", tv_riegel=True):
        self.trail = trail
        # K0 (30.09.2026): js_datei 'augen_tsx.js' für den TopstepX-Tab; tv_riegel=False = ohne TradingView-Werbung/-Meldungen wegräumen
        self.tv_riegel = tv_riegel
        # 01.10.2026 (Kette in einem Lauf): stirbt das Puls-Chrome zwischen zwei Schritten, startet es für den TopstepX-Tab mit
        # TopstepX — nie mit dem TradingView-Chart (K0-Prüfer: Kaltstart mit TopstepX)
        if not _puls_chrome_sicher(trail, url=(TSX_URL if js_datei == "augen_tsx.js" else AUGEN_TV_URL)):
            raise RuntimeError("Puls-Chrome nicht erreichbar (Port 9333)")
        # ziel: ein bestimmter Tab (Auto-Login 29.09.2026: der neue Tab mit ?trade-now) — sonst wie bisher die Chart-Seite
        ziel = ziel or augen_target_waehlen(_cdp_http("/json/list"))
        if not ziel:
            raise RuntimeError("im Puls-Chrome ist keine TradingView-Seite offen")
        self.js = _augen_js_holen(trail, js_datei)
        if not self.js:
            raise RuntimeError(f"{js_datei} fehlt")
        self.ws = _CdpVerbindung(ziel.get("webSocketDebuggerUrl"), timeout=10.0)
        self.target_id = ziel.get("id")        # K3: Fenster des Tabs (Browser.getWindowForTarget) für den Login kurz nach vorn
        self.maus = (40.0, 40.0)
        # Menschliches Tempo (Finn 01.10.2026) nur im TopstepX-Tab: vor jedem Druck TSX_HOVER_PAUSE über dem Ziel stehen — Orbit unverändert
        self.hover_pause = TSX_HOVER_PAUSE if js_datei == "augen_tsx.js" else None
        try:
            self.ws.rufe("Emulation.setFocusEmulationEnabled", {"enabled": True}, timeout=3)   # minimiertes Fenster = „fokussiert"
        except Exception:
            pass
        self._seite_abwarten()
        self._augen_laden()

    def _seite_abwarten(self, sek=25.0):
        """Erst weiter, wenn die Seite fertig geladen ist (29.09.2026 14:45 UTC, frisch gestartetes Puls-Chrome: augen.js lag in der
        noch LADENDEN Seite, TradingView lud fertig, prophosAugen war weg → „stand() wirft: Uncaught"). Fertig = readyState
        'complete' und die Seite schon > 3 s alt oder dieselbe Adresse zwei Blicke lang. Seit 01.10.2026 (Jacob/Moritz: TradingView
        bleibt im Puls-Chrome bei 'interactive' hängen, Connect ist trotzdem klickbar) reicht auch 'interactive' auf derselben
        TradingView-Adresse CDP_INTERAKTIV_REICHT_S lang (cdp_seite_bereit) — sonst 25 s Leerlauf vor jedem Klick.
        -> True/False (False = trotzdem weiter)"""
        ende, vorher, interaktiv = time.time() + sek, None, None
        while time.time() < ende:
            try:
                r = self.ws.rufe("Runtime.evaluate", {"expression": "[document.readyState, String(location.href), performance.now()]",
                                                      "returnByValue": True}, timeout=4)
                v = (r.get("result") or {}).get("value")
            except Exception:
                v = None
            if isinstance(v, list) and len(v) == 3 and v[0] == "complete":
                if (isinstance(v[2], (int, float)) and v[2] > 3000) or v[1] == vorher:
                    return True
                vorher = v[1]
            else:
                vorher = None
            if isinstance(v, list) and len(v) == 3 and v[0] == "interactive":
                if not interaktiv or interaktiv[0] != v[1]:
                    interaktiv = (v[1], time.time())
                if cdp_seite_bereit("interactive", v[1], time.time() - interaktiv[1]):
                    self.trail.append("Seite 'interactive' (nicht 'complete') — reicht, weiter")
                    return True
            else:
                interaktiv = None
            _warte(0.4, 0.2)
        self.trail.append(f"Seite nach {sek:.0f} s nicht fertig geladen — weiter")
        return False

    def _augen_laden(self):
        r = self.ws.rufe("Runtime.evaluate", {"expression": self.js, "returnByValue": False}, timeout=8)
        if r.get("exceptionDetails"):
            raise RuntimeError("augen.js wirft beim Laden: " + cdp_fehlertext(r))

    def stand(self, opts=None):
        a = "globalThis.prophosAugen.stand(" + json.dumps(opts or {}) + ")"
        for versuch in (1, 2):
            r = self.ws.rufe("Runtime.evaluate", {"expression": a, "returnByValue": True, "awaitPromise": True}, timeout=10)
            if not r.get("exceptionDetails"):
                return ((r.get("result") or {}).get("value")) or {}
            text = cdp_fehlertext(r)
            if versuch == 1 and augen_fehlt(text):
                # Seite hat neu geladen (Navigation, Login-Rückkehr) — augen.js ist weg: einmal nachladen, dann erneut lesen
                self.trail.append(f"augen.js fehlte in der Seite ({text[:60]}) — neu geladen")
                self._seite_abwarten(15.0)
                self._augen_laden()
                continue
            raise RuntimeError("stand() wirft: " + text[:120])
        return {}

    def klick(self, rect, name, toast_ok=False, pruef=None, doppel=False):
        """pruef (K0, 30.09.2026): {rect, text, aria, tabu} — gedrückt wird nur, wenn am Zielpunkt genau dieser Kandidat liegt
        (win_ziel_pruef_js); ohne pruef wie bisher (nur :hover). doppel (K4, 05.10.2026): Doppelklick, nur zusammen mit pruef
        (Zellen Risk / To Make der TopstepX-Positions-Tabelle) — Standard False = unverändert ein Klick."""
        if _WIN_EINGABE:
            tv = getattr(self, "tv_riegel", True)          # TopstepX-Tab (K0): nichts TradingView-Eigenes wegklicken
            if tv:
                self.werbung_weg()                        # Werbe-Modal zuerst weg (30.09.2026, PC von ID C: Autumn-Sale über Connect)
            self._verdeckt = False
            self._druck_versucht = False                  # nur ein Druck auf DIESES Ziel zählt (ein Werbung-X davor nicht; K4)
            if pruef:
                return self._win_klick(rect, name, toast_ok=toast_ok, pruef=pruef, doppel=bool(doppel))
            ok = self._win_klick(rect, name, toast_ok=toast_ok)
            if tv and not ok and self._verdeckt and not toast_ok and self._toasts_weg():
                self._verdeckt = False
                ok = self._win_klick(rect, name)          # Meldungen weg — derselbe Klick genau einmal neu
            if tv and not ok and not toast_ok and self.werbung_weg(zwang=True):
                ok = self._win_klick(rect, name)          # Werbung kam gerade erst — derselbe Klick genau einmal neu
            return ok
        p = cdp_klickpunkt(rect)
        if not p:
            self.trail.append(f"{name}: kein klickbares Rechteck")
            return False
        for (x, y) in cdp_klick_bahn(self.maus, p):
            self.ws.rufe("Input.dispatchMouseEvent", {"type": "mouseMoved", "x": x, "y": y, "buttons": 0}, timeout=3)
            _warte(0.018, 0.02)
        _warte(0.08, 0.08)
        if getattr(self, "hover_pause", None):
            _warte(*tsx_hover_pause())                # wie im Windows-Weg (Finn 01.10.2026): erst stehen, dann drücken — je Klick anders
        if pruef:
            v = self.lese_js(win_ziel_pruef_js(p[0], p[1], pruef))
            if not (isinstance(v, dict) and v.get("passt")):
                self.trail.append(f"{name}: am Zielpunkt liegt nicht das Ziel ('{(v or {}).get('was') if isinstance(v, dict) else '-'}') — kein Druck")
                return False
        self._druck_versucht = True                   # ab hier KANN gedrückt sein (K4: Ausnahme davor = nichts gesendet)
        self.ws.rufe("Input.dispatchMouseEvent", {"type": "mousePressed", "x": p[0], "y": p[1], "button": "left",
                                                  "buttons": 1, "clickCount": 1, "force": 0.5}, timeout=3)
        _warte(0.07, 0.06)
        self.ws.rufe("Input.dispatchMouseEvent", {"type": "mouseReleased", "x": p[0], "y": p[1], "button": "left",
                                                  "buttons": 0, "clickCount": 1}, timeout=3)
        if doppel and pruef:                           # K4: zweiter Druck als Doppelklick (clickCount 2)
            _warte(0.06, 0.05)
            self.ws.rufe("Input.dispatchMouseEvent", {"type": "mousePressed", "x": p[0], "y": p[1], "button": "left",
                                                      "buttons": 1, "clickCount": 2, "force": 0.5}, timeout=3)
            _warte(0.07, 0.06)
            self.ws.rufe("Input.dispatchMouseEvent", {"type": "mouseReleased", "x": p[0], "y": p[1], "button": "left",
                                                      "buttons": 0, "clickCount": 2}, timeout=3)
        self.maus = p
        self.trail.append(f"{name} geklickt @{int(p[0])},{int(p[1])} (CDP)")
        return True

    # Tasten (Master-Klicktest 29.09.2026): keyDown(text)/keyUp je Zeichen — NIE Input.insertText (kein keydown/keypress);
    # Sondertasten mit windowsVirtualKeyCode, alle Abstände über _warte mit Streuung.
    _VK = {"Tab": 9, "Enter": 13, "Escape": 27, "Backspace": 8, "Delete": 46, "a": 65, "ArrowDown": 40, "ArrowUp": 38}

    def taste(self, key, modifiers=0):
        if _WIN_EINGABE:
            t = win_taste_text(key, modifiers)
            if t is None:
                raise RuntimeError(f"Taste '{key}' ohne Windows-Entsprechung")
            self._win_key(t)
            _warte(0.04, 0.14)                        # 06.10.2026: breiter gestreut (vorher 50–90 ms)
            return
        vk = self._VK.get(key, 0)
        code = {"a": "KeyA"}.get(key, key)
        self.ws.rufe("Input.dispatchKeyEvent", {"type": "rawKeyDown", "key": key, "code": code, "windowsVirtualKeyCode": vk,
                                                "nativeVirtualKeyCode": vk, "modifiers": modifiers}, timeout=3)
        _warte(0.05, 0.04)
        self.ws.rufe("Input.dispatchKeyEvent", {"type": "keyUp", "key": key, "code": code, "windowsVirtualKeyCode": vk,
                                                "nativeVirtualKeyCode": vk, "modifiers": modifiers}, timeout=3)
        _warte(0.05, 0.04)

    def tippen(self, text):
        if _WIN_EINGABE:
            for ch, dt in zip(str(text), tipp_takt(len(str(text)))):   # 06.10.2026: Tipp-Takt der Hand statt fix 60–120 ms
                self._win_key(tv_tasten_escape(ch))
                _warte(dt, 0.02)
            return
        for ch in str(text):
            vk = ord(ch.upper()) if ch.isalnum() else (190 if ch == "." else 188 if ch == "," else 0)
            self.ws.rufe("Input.dispatchKeyEvent", {"type": "keyDown", "key": ch, "text": ch, "unmodifiedText": ch,
                                                    "windowsVirtualKeyCode": vk, "nativeVirtualKeyCode": vk}, timeout=3)
            _warte(0.04, 0.04)
            self.ws.rufe("Input.dispatchKeyEvent", {"type": "keyUp", "key": ch, "windowsVirtualKeyCode": vk,
                                                    "nativeVirtualKeyCode": vk}, timeout=3)
            _warte(0.06, 0.06)

    def fokus_im(self, rect, name, versuche=3):
        """Beweis nach dem Klick: das Feld an diesem Rechteck hat den Tastatur-Fokus und die Seite selbst den Fokus. Ohne Beweis wird
        NICHTS getippt (Live 15:11 UTC: Klick gemeldet, Feld blieb leer — getippt wurde trotzdem). -> bool"""
        for i in range(versuche):
            try:
                if self.lese_js(win_fokus_js(rect), timeout=4) is True:
                    return True
            except Exception:
                pass
            _warte(0.25, 0.15)
        self.trail.append(f"{name}: Feld hat nach dem Klick keinen Fokus — nichts getippt")
        return False

    def feld_setzen(self, rect, wert, name):
        """Feld anklicken, Fokus beweisen, alles markieren (Strg+A), Wert Zeichen für Zeichen tippen, Tab. -> bool (getippt)"""
        if not self.klick(rect, f"Feld {name}"):
            return False
        _warte(0.15, 0.1)
        if not self.fokus_im(rect, f"Feld {name}"):
            return False
        self.taste("a", modifiers=2)          # Strg+A (Windows)
        _warte(0.1, 0.08)
        self.tippen(wert)
        _warte(0.12, 0.1)
        self.taste("Tab")
        self.trail.append(f"{name} getippt: {wert}")
        return True

    def hin(self, rect, name):
        """Maus nur HINFAHREN (Bahn mit Streuung, kein Druck) — z. B. damit TradingView die Knöpfe einer Tabellenzeile zeigt."""
        if _WIN_EINGABE:
            return self._win_klick(rect, name, druck=False, toast_ok=True)   # nur Hover, kein Druck — über einer Meldung harmlos
        p = cdp_klickpunkt(rect)
        if not p:
            return False
        for (x, y) in cdp_klick_bahn(self.maus, p):
            self.ws.rufe("Input.dispatchMouseEvent", {"type": "mouseMoved", "x": x, "y": y, "buttons": 0}, timeout=3)
            _warte(0.018, 0.02)
        self.maus = p
        self.trail.append(f"Maus über {name} @{int(p[0])},{int(p[1])}")
        return True

    def _win_vorn(self):
        """Windows-Fenster DIESES Tabs finden und in den Vordergrund holen — Wiederherstellen, nie Größe ändern. -> (hwnd | None, grund)"""
        _dpi_bewusst()
        try:
            self.ws.rufe("Page.bringToFront", {}, timeout=3)
        except Exception:
            pass
        g = self.lese_js(WIN_GEO_JS) or {}
        hwnd = puls_fenster_waehlen(_puls_fenster_liste(_puls_chrome_browser_pid()), g.get("titel"))
        if not hwnd:
            return None, "Puls-Chrome-Fenster nicht eindeutig gefunden"
        if getattr(self, "_win_hwnd", None) is None:
            self._win_hwnd = hwnd                       # am Ende wieder minimieren (zu)
        if getattr(self, "_win_gemeldet", None) != hwnd:
            self._win_gemeldet = hwnd                   # Live 15:11 UTC: welches Fenster Puls nahm, stand nirgends
            self.trail.append(f"Fenster {hwnd} '{str(g.get('titel') or '')[:40]}'")
        if _win_minimiert(hwnd):
            _win_zeigen(hwnd, 9)                        # SW_RESTORE: alte Größe bzw. Maximierung bleibt
            _warte(0.5, 0.2)
        ende = time.time() + 3.0
        while _win_vordergrund() != int(hwnd):
            if time.time() >= ende:
                return None, "Puls-Chrome kommt nicht in den Vordergrund"
            _win_nach_vorn(hwnd)
            _warte(0.25, 0.15)
        return hwnd, ""

    def werbung_weg(self, zwang=False):
        """Werbe-Modals (CDP_WERBUNG_JS) per X schließen, Verschwinden beweisen; X nicht klickbar → einmal Esc. Ohne zwang höchstens
        alle 3 s (ein Lese-Ausdruck, ~50 ms). -> Anzahl geschlossener Werbungen"""
        jetzt = time.time()
        if not zwang and jetzt - getattr(self, "_werbung_at", 0.0) < 3.0:
            return 0
        self._werbung_at = jetzt
        weg = 0
        try:
            return self._werbung_weg_kern()
        except Exception as e_:                        # darf keinen Klick verhindern — schlimmstenfalls bleibt die Werbung stehen
            self.trail.append(f"Werbung-Prüfung übersprungen ({type(e_).__name__})")
            return weg

    def _werbung_weg_kern(self):
        weg = 0
        for _ in range(3):
            kand = self.lese_js(CDP_WERBUNG_JS)
            kand = [x for x in kand if isinstance(x, dict)] if isinstance(kand, list) else []
            if not kand:
                break
            k = kand[0]
            text = str(k.get("text") or "")[:60]
            if self._win_klick(k.get("x"), f"Werbung schließen (X) '{text}'", toast_ok=True):
                _warte(0.6, 0.3)
            else:
                try:
                    self.taste("Escape")
                    self.trail.append(f"Werbung '{text}': X nicht klickbar — Esc gedrückt")
                except Exception:
                    pass
                _warte(0.5, 0.3)
            nach = self.lese_js(CDP_WERBUNG_JS)
            noch = [x for x in (nach if isinstance(nach, list) else []) if isinstance(x, dict) and str(x.get("text") or "")[:60] == text]
            if noch:
                self.trail.append(f"Werbung '{text}' bleibt — weiter ohne")
                break
            self.trail.append(f"Werbung weg (bewiesen): '{text}'")
            weg += 1
        return weg

    def _toasts_weg(self):
        """TradingView-Meldungen über dem Ziel schließen (X der Gruppe, sonst X einzelner Meldungen). -> True, wenn geklickt"""
        geklickt = False
        for _ in range(4):
            kand = self.lese_js(CDP_TOAST_ZU_JS) or []
            if not kand:
                break
            k = kand[0]
            if not self._win_klick(k.get("rect"), f"Meldungen schließen ({k.get('art')} X)", toast_ok=True):
                break
            geklickt = True
            _warte(0.5, 0.25)
            if k.get("art") == "gruppe":
                break                                        # das Gruppen-X räumt den ganzen Stapel
        if not geklickt:
            self.trail.append("Meldungen über dem Ziel, aber kein Schließen-Knopf im Bild")
        return geklickt

    def _win_klick(self, rect, name, druck=True, toast_ok=False, pruef=None, doppel=False):
        """Echte Windows-Maus: Punkt im inneren Drittel → Bildschirm-Pixel (Breiten-Abgleich), Zeiger sichtbar hinfahren, :hover des
        Ziels beweisen, dann EIN SendInput-Druck. Ohne Beweis kein Druck. druck=False = nur hinfahren (Hover)."""
        hwnd, grund = self._win_vorn()
        if not hwnd:
            self.trail.append(f"{name}: {grund} — nichts geklickt")
            return False
        p = cdp_klickpunkt(rect)
        if not p:
            self.trail.append(f"{name}: kein klickbares Rechteck")
            return False
        g = self.lese_js(WIN_GEO_JS) or {}
        punkt, grund = tv_bildschirm_punkt([p[0] - 0.5, p[1] - 0.5, 1.0, 1.0], g, _klient_rechteck(hwnd))
        if not punkt:
            self.trail.append(f"{name}: {grund} — nichts geklickt")
            return False
        _maus_fahren(*punkt)
        # Riegel (Live 29.09.2026 15:11 UTC, Tradeify-Login: „Benutzerfeld geklickt, Hover bewiesen", auf der Seite kam nichts an):
        # am Zielpunkt muss WIRKLICH dieses Puls-Chrome-Fenster liegen — :hover allein kann ein alter Stand der Seite sein
        try:
            wurzel, w_titel = _win_root_am_punkt(*punkt)
        except Exception as e_:
            self.trail.append(f"{name}: Fenster am Zielpunkt nicht prüfbar ({type(e_).__name__}) — kein Druck")
            return False
        if wurzel != int(hwnd):
            self.trail.append(f"{name}: am Zielpunkt @{punkt[0]},{punkt[1]} liegt ein anderes Fenster ({wurzel} '{w_titel[:40]}', "
                              f"erwartet {hwnd}) — kein Druck")
            return False
        hover, v = False, None
        ende = time.time() + 0.9
        gestupst = False
        while time.time() < ende:
            _warte(0.08, 0.05)
            if pruef:
                v = self.lese_js(win_ziel_pruef_js(p[0], p[1], pruef))
                if isinstance(v, dict) and v.get("hover") and not v.get("passt"):
                    self.trail.append(f"{name}: am Zielpunkt @{punkt[0]},{punkt[1]} liegt nicht das Ziel ('{v.get('was')}'"
                                      + (", Order-/Close-Wort" if v.get("tabu") else "") + ") — kein Druck")
                    return False
                if isinstance(v, dict) and v.get("hover"):
                    hover = True
                    break
                if not gestupst and time.time() >= ende - 0.15:
                    # Live 30.09.2026 11:18 UTC (erster Topstep-PC, Bracket-Zahnrad): Zeiger stand rechnerisch richtig, die Seite meldete
                    # 0,9 s lang kein :hover. EINMAL 2 px anstupsen (frische Mausbewegung, kein Druck) und noch 0,7 s schauen.
                    gestupst = True
                    try:
                        _cursor_set(int(punkt[0]) + 2, int(punkt[1]) + 1)
                        _warte(0.04, 0.03)
                        _cursor_set(int(punkt[0]), int(punkt[1]))
                    except Exception:
                        pass
                    ende = time.time() + 0.7
                continue
            v = self.lese_js(win_ziel_js(p[0], p[1]))
            if isinstance(v, dict) and v.get("toast") and not toast_ok:
                # das Ziel liegt unter einer TradingView-Meldung — ein Druck träfe die Meldung (Live 16:13 UTC, Konto-Umschalter)
                self._verdeckt = True
                self.trail.append(f"{name}: von einer TradingView-Meldung verdeckt @{punkt[0]},{punkt[1]} — kein Druck")
                return False
            if (v.get("hover") if isinstance(v, dict) else v):
                hover = True
                break
        if not hover:
            zus = (f" — am Punkt '{v.get('was')}', Zeiger laut Seite über '{v.get('unter')}'" if pruef and isinstance(v, dict) else "")
            self.trail.append(f"{name}: Maus steht @{punkt[0]},{punkt[1]}, Ziel NICHT unter dem Zeiger (Hover){zus} — kein Druck")
            return False
        self.maus = p
        if not druck:
            self.trail.append(f"Maus über {name} @{punkt[0]},{punkt[1]} (Windows-Maus)")
            return True
        hp = getattr(self, "hover_pause", None)
        if hp:
            # Menschliches Tempo (Finn 01.10.2026, TopstepX: das Dropdown ging „in einer Millisekunde" auf und zu): erst über dem Ziel
            # stehen bleiben, dann drücken — und das Ziel danach NEU beweisen, in der Pause kann sich die Seite bewegt haben.
            # Seit 06.10.2026 ist die Länge je Klick anders (tsx_hover_pause, Hand des Laufs).
            _warte(*tsx_hover_pause())
            if pruef:
                v2 = self.lese_js(win_ziel_pruef_js(p[0], p[1], pruef))
                if not (isinstance(v2, dict) and v2.get("hover") and v2.get("passt")):
                    self.trail.append(f"{name}: nach der Hover-Pause liegt am Zielpunkt nicht mehr das Ziel "
                                      f"('{v2.get('was') if isinstance(v2, dict) else '-'}') — kein Druck")
                    return False
        if _win_vordergrund() != int(hwnd):
            self.trail.append(f"{name}: Puls-Chrome nicht mehr vorn — kein Druck")
            return False
        self._druck_versucht = True                   # ab hier KANN gedrückt sein (K4: Ausnahme davor = nichts gesendet)
        if not _klick_absolut(punkt[0], punkt[1], doppel=bool(doppel and pruef)):   # doppel nur mit Ziel-Beweis (K4)
            self.trail.append(f"{name}: SendInput abgelehnt")
            return False
        self.trail.append(f"{name} geklickt @{punkt[0]},{punkt[1]} (Windows-Maus, Hover bewiesen)")
        return True

    def _win_key(self, text_sk):
        """Echte Tastatur — nur wenn das Puls-Chrome-Fenster dieses Tabs vorn ist, sonst Abbruch (Tasten gingen ins falsche Fenster)."""
        hwnd, grund = self._win_vorn()
        if not hwnd:
            raise RuntimeError("Tastatur: " + grund)
        _win_tasten(text_sk)

    def lese_js(self, ausdruck, timeout=8):
        """Eigener Lese-Ausdruck (returnByValue). -> Wert | None bei Ausnahme. NICHT „js" nennen: self.js ist der augen.js-Quelltext
        (Befund 29.09.2026 vor dem ersten K3-Lauf: eine Methode js() wurde vom Attribut überdeckt → TypeError NACH dem Kauf)."""
        r = self.ws.rufe("Runtime.evaluate", {"expression": ausdruck, "returnByValue": True, "awaitPromise": True}, timeout=timeout)
        return None if r.get("exceptionDetails") else ((r.get("result") or {}).get("value"))

    def rect_von(self, selektor):
        """[x, y, w, h] eines sichtbaren Elements (nur Lesen, kein Klick) — für Reiter, die augen.js nicht als Rechteck liefert."""
        a = ("(function(){var e=document.querySelector(" + json.dumps(selektor) + ");if(!e)return null;"
             "var r=e.getBoundingClientRect();return (r.width>0&&r.height>0)?[r.x,r.y,r.width,r.height]:null;})()")
        r = self.ws.rufe("Runtime.evaluate", {"expression": a, "returnByValue": True}, timeout=5)
        return ((r.get("result") or {}).get("value")) if not r.get("exceptionDetails") else None

    def zu(self):
        # 06.10.2026: nach einer gesendeten Order bleibt das Fenster stehen (_bleiben) — das Kind aus _tsx_bleiben_starten minimiert später
        if _WIN_EINGABE and getattr(self, "_win_hwnd", None) and not getattr(self, "_bleiben", False):
            try:
                _win_zeigen(self._win_hwnd, 7)          # SW_SHOWMINNOACTIVE: wieder minimiert, nichts aktiviert — Reader frei
            except Exception:
                pass
        try:
            self.ws.zu()
        except Exception:
            pass


def cdp_konto_passt(text, ext_id):
    """REIN RECHNEND (testbar): Trägt dieser Konto-Text (Umschalter/Listenzeile im Puls-Chrome) GENAU diese External ID?
    Ganzes Wort, nur ein Währungs-Anhang darf direkt folgen: augen.js liest den Umschalter als 'PAAPEX0000000000007USD' (zwei spans ohne
    Leerraum), tv_konto_wort_passt fände das nie. Kein Teilstring (Prüfer 30.09.2026 zur Regression .865, wie tv_konto_wort_passt am
    21.09.): 'APEX0000000000007' (Eval) steckt in 'PAAPEX0000000000007USD' (PA) — im Login APEX_000000 stehen 8 solche Paare.
    DB-Stand 30.09.: alle Tradovate-IDs (Apex/Tradeify/Lucid) sind volle Kontonamen. 3-Zeichen-Riegel wie tv_konto_passt."""
    e = _nur_alnum(ext_id)
    if len(e) < 3:
        return False
    for w in re.split(r"[\s·|,;:()\[\]/$]+", str(text or "")):
        n = _nur_alnum(w)
        if n == e or (n.startswith(e) and n[len(e):] in ("usd", "eur", "gbp", "chf", "aud", "cad", "jpy")):
            return True
    return False


def cdp_kontonr(text):
    """REIN RECHNEND (testbar): Kontonummer aus einem Umschalter-/Listen-Text ('PAAPEX0000000000008USD' → 'PAAPEX0000000000008') | ''
    Je Wort (Beiwerk davor wie 'Apex · PAAPEX…' klebt sonst an der Nummer, Prüfer Runde 2)."""
    for w in re.split(r"[^A-Za-z0-9_-]+", str(text or "")):
        m = k3_nr_treffer(w.upper(), am_anfang=True)
        if m:
            return m.group(0)
    return ""


def cdp_konto_familie(nr):
    """REIN RECHNEND (testbar): Zu welchem Tradovate-Login gehört eine Kontonummer? DB-Stand 30.09.2026: Apex immer (PA)APEX + 6-stellige
    User-ID + 7-stelliger Zähler (58/58, 7 User; Username APEX_<User-ID>), Tradeify immer (F)TDFY…, Lucid LFE…/TOF…, seit 02.10.2026
    FundedNext Futures FNFT… und MyFundedFutures MFFU…. -> 'apex:<id>' | 'tradeify' | 'lucid' | 'fundednext' | 'mff' | '' (unbekannt). Tradeify/Lucid tragen keine User-ID in der Nummer."""
    u = _nur_alnum(nr).upper()
    m = re.match(r"^(?:PA)?APEX(\d{6})\d{7}$", u)
    if m:
        return "apex:" + m.group(1)
    if re.match(r"^F?TDFY", u):
        return "tradeify"
    if re.match(r"^(LFE|TOF)", u):
        return "lucid"
    # 02.10.2026 (Finn + Pascal: Balance-Lesen FundedNext Futures scheiterte mit „kein Login-Beleg", weil die lange Tradeify-Liste
    # scrollbar war): FundedNext Futures (FNFT…) und MyFundedFutures (MFFU…) haben je einen eigenen Tradovate-Login
    if re.match(r"^FNFT", u):
        return "fundednext"
    if re.match(r"^MFFU", u):
        return "mff"
    return ""


def cdp_ein_konto_beleg(aktiv, ext):
    """REIN RECHNEND (testbar): Umschalter geklickt, keine Liste — belegt das einen anderen Tradovate-Login? Nur wenn das aktive Konto
    als Kontonummer lesbar ist und NICHT das Ziel (02.10.2026, Login mit nur einem Konto)."""
    nr = cdp_kontonr(aktiv)
    if not (nr and ext) or cdp_konto_passt(str(aktiv or ""), ext):
        return False
    fa, fz = cdp_konto_familie(nr), cdp_konto_familie(ext)
    if fa and fa == fz and fa.startswith("apex:"):
        return False   # derselbe Apex-User = derselbe Login (viele Konten) — die Liste wurde nur nicht erkannt
    return True


def cdp_konto_eintrag(eintraege, ext):
    """REIN RECHNEND (testbar): GENAU EIN Dropdown-Eintrag mit dieser External ID (cdp_konto_passt). -> (eintrag|None, anzahl)"""
    treffer = [e for e in (eintraege or []) if isinstance(e, dict) and cdp_konto_passt(str(e.get("text") or ""), ext)]
    return (treffer[0] if len(treffer) == 1 else None), len(treffer)


def cdp_liste_beleg(ko, aktiv, ext=""):
    """REIN RECHNEND (testbar): Belegt eine SELBST geöffnete Liste ohne Ziel einen fremden Tradovate-Login? -> (ja, grund)
    Prüfer 30.09.2026 (Regression .865): eine abgeschnittene Liste (maximiert ≈ 21 Zeilen, APEX_000000 hat 32 Konten) zeigte das Ziel
    0× — „Log out" einer richtigen Sitzung. Deshalb zuerst die Nummern selbst (cdp_konto_familie): andere Firma bzw. anderer Apex-User
    = sicher ein anderer Login (so bleibt der live grüne Wechsel Apex↔Tradeify auch bei 94 Konten möglich); derselbe Apex-User = nie
    (das Ziel steht nur außer Sicht). Sonst (Tradeify↔Tradeify, unbekannt) nur mit vollständiger Liste (augen.js liste_voll ≥ 0.7.4
    oder, seit 05.10.2026, liste_kurz ≥ 0.7.6 — auch FundedNext↔FundedNext: die Nummer verrät dort den Login nicht)
    UND dem aktiven Konto selbst als Zeile darin."""
    nr = cdp_kontonr(aktiv)
    if not nr:
        return False, f"aktives Konto nicht lesbar ('{str(aktiv or '')[:40] or '-'}')"
    fa, fz = cdp_konto_familie(nr), cdp_konto_familie(ext)
    if fa and fz and fa != fz:
        return True, ""
    if fa and fa == fz and fa.startswith("apex:"):
        return False, f"Ziel und aktives Konto gehören zum selben Apex-Login (User {fa[5:]}) — das Ziel steht nur nicht sichtbar in der Liste"
    # 05.10.2026 (Finn + Pascal, Endlesung zweier FundedNext-Futures-Konten bei verbundenem anderem FundedNext-Login): die Liste hatte
    # drei Zeilen und war ganz zu sehen, liste_voll sagte trotzdem nein → kein Beleg → Abbruch statt Login-Wechsel. Seit augen.js 0.7.6
    # zählt auch liste_kurz (≤ 8 Zeilen, Platz darüber und darunter, keine weitere Konto-Zeile im Dokument); liste_voll_grund nennt,
    # woran liste_voll scheiterte.
    if (ko or {}).get("liste_voll") is not True and (ko or {}).get("liste_kurz") is not True:
        g = str((ko or {}).get("liste_voll_grund") or "")[:80]
        return False, ("Liste nicht vollständig im Bild (abgeschnitten/scrollbar oder augen.js < 0.7.6"
                       + (f"; augen.js: {g}" if g else "") + ")")
    if not any(isinstance(x, dict) and cdp_konto_passt(str(x.get("text") or ""), nr) for x in (ko or {}).get("eintraege") or []):
        return False, f"aktives Konto {nr} steht nicht in der Liste"
    return True, ""


def cdp_rect(x):
    """rect aus einem augen.js-Element ({rect: [...]}) oder direkt einer Liste."""
    if isinstance(x, dict):
        return x.get("rect")
    return x if isinstance(x, (list, tuple)) else None


def cdp_summary(ks):
    """REIN RECHNEND (testbar): augen.js konto_summary → tvlesen-'summary' {Label: Text}. texte gewinnt; fehlt es, aus den
    geparsten Einträgen (label/text) — 'Account Balance'/'Equity' als Rückfall-Label, damit Prophos (tvBalanceAus) sie findet."""
    if not isinstance(ks, dict):
        return None
    out = {}
    t = ks.get("texte")
    if isinstance(t, dict):
        out.update({str(k): str(v) for k, v in t.items() if v is not None})
    for key, rueck in (("balance", "Account Balance"), ("equity", "Equity"), ("today_pnl", "Today's P&L"),
                       ("realisiert", "Realized P&L"), ("unrealisiert", "Unrealized P&L")):
        e = ks.get(key)
        if isinstance(e, dict) and e.get("text") not in (None, ""):
            lab = str(e.get("label") or rueck)
            if lab not in out:
                out[lab] = str(e.get("text"))
    return out or None


def cdp_positionen_vertrag(pos):
    """REIN RECHNEND (testbar): augen.js positionen → tvlesen-Vertragsform (Texte + *_zahl)."""
    out = []
    for p in (pos or []):
        if not isinstance(p, dict):
            continue
        menge, avg, pl = p.get("menge"), p.get("avg"), p.get("pl_text")
        out.append({"symbol": p.get("symbol"), "seite": p.get("seite"),
                    "menge": None if menge is None else str(menge), "einstieg": None if avg is None else str(avg),
                    "pnl": pl, "sl": None, "tp": None,
                    "menge_zahl": menge if isinstance(menge, (int, float)) else tv_geld_lesen(menge),
                    "einstieg_zahl": avg if isinstance(avg, (int, float)) else tv_geld_lesen(avg),
                    "pnl_zahl": tv_geld_lesen(pl)})
    return out


# ORDER-PANEL EINGEKLAPPT (Finn 30.09.2026, pc-cccccc, Schließen 150k Apex PAAPEX0000000000008 NQZ6: „Konto-Umschalter geklickt,
# Dropdown nicht erkannt (aktiv '…0007USD')"). Belegt im Stand 00:52 UTC: innerHeight 773, Broker-Leiste #footer-chart-panel bei
# y 686–724, Umschalter bei y 745–773 — unter der Leiste blieben 49 px, die Tradovate-Kontoliste (32-px-Zeilen) hatte keinen Platz.
# „Collapse panel" meldete dabei „offen", deshalb griff der alte Weg (Open panel) nicht. Bei pc-jjjjjj (Liste ging auf) waren es 320 px.
# Rechts im Panel-Kopf stehen „—" = [data-name=toggle-visibility-button] (Collapse/Open panel) und „⌐" =
# [data-name=toggle-maximize-button] (aria „Maximize panel"), beide im Inventar pc-cccccc/pc-jjjjjj belegt. Finns Regel: Panel nicht
# zu sehen → rechts aufklappen und nochmal; ist auch das Symbol nicht da, ist kein Konto verbunden → Login-Weg.
CDP_NIE_MAXIMIEREN = True   # Finn 01.10.2026: „nie wieder Maximize panel, immer nur Open panel" — alter Maximize-Weg bleibt nur als Code
CDP_PANEL_MIN_H = 150       # px unter der Broker-Leiste: Platz für Reiter + Kontoliste (gut: 320, Vorfall: 49)
CDP_PANEL_LAGE_JS = r"""(function () {
  function r(e) { if (!e) return null; var b = e.getBoundingClientRect(); return (b.width > 0 && b.height > 0) ? [b.x, b.y, b.width, b.height] : null; }
  function knopf(sel) { var e = document.querySelector(sel), rr = r(e);
    return rr ? { rect: rr, aria: String(e.getAttribute('aria-label') || e.getAttribute('title') || '').slice(0, 40) } : null; }
  var lr = r(document.getElementById('footer-chart-panel')), tr = r(document.getElementById('id_account-manager-tabs'));
  return { innen: innerHeight, leiste: lr, unter_leiste: lr ? Math.round(innerHeight - (lr[1] + lr[3])) : null, reiter: tr,
           max_knopf: knopf('#footer-chart-panel [data-name="toggle-maximize-button"], [data-name="toggle-maximize-button"]'),
           vis_knopf: knopf('#footer-chart-panel [data-name="toggle-visibility-button"], [data-name="toggle-visibility-button"]') };
})()"""


def cdp_panel_lage(d, min_h=CDP_PANEL_MIN_H):
    """REIN RECHNEND (testbar): Lage des Order-Panels aus CDP_PANEL_LAGE_JS. -> 'ok' | 'eingeklappt' | 'unklar'
    unklar = keine Broker-Leiste bzw. keine Höhe (dann entscheidet der alte Weg: kein Umschalter = kein Broker)."""
    if not isinstance(d, dict) or not cdp_rect(d.get("leiste")):
        return "unklar"
    h = d.get("unter_leiste")
    if not isinstance(h, (int, float)) or isinstance(h, bool):
        return "unklar"
    return "ok" if h >= min_h else "eingeklappt"


def _cdp_panel_aufklappen(s, trail, ohne_max=False):
    """Order-Panel eingeklappt? Dann „Maximize panel" EINMAL je Sitzung (Windows-Maus über s.klick: Werbung weg, Hover-/Fenster-/
    Overlay-Riegel), Wirkung beweisen (≤ 5 Blicke). Liest sonst nur. -> (lage, daten)
    lage: 'ok' | 'unklar' | 'aufgeklappt' | 'ohne_knopf' (Symbol fehlt) | 'bleibt_eingeklappt' (verdeckt, ohne Wirkung, schon versucht)"""
    if not hasattr(s, "lese_js"):
        return "unklar", None
    d = s.lese_js(CDP_PANEL_LAGE_JS)
    lage = cdp_panel_lage(d)
    if lage != "eingeklappt":
        return lage, d
    h = d.get("unter_leiste")
    # NIE MAXIMIEREN (Finn 01.10.2026 11:29 UTC, Orbit V3 bei Moritz: „nie wieder Maximize, immer nur Open panel" — Puls maximierte, weil
    # das OFFENE Panel dort nur 113 px hoch ist (< CDP_PANEL_MIN_H), und scheiterte dann am Kontextmenü „Tradovate ▾" oben in der
    # maximierten Ansicht → Login-Wechsel nicht geschafft). Offenes Panel (Kopf-Knopf „Collapse panel") zählt jetzt als ok, egal wie hoch.
    va0 = str(((d.get("vis_knopf") if isinstance(d.get("vis_knopf"), dict) else {}) or {}).get("aria") or "")
    if CDP_NIE_MAXIMIEREN and re.search(r"collapse|close|schlie|hide|ausblenden|einklappen|zuklappen", va0, re.I):
        return "ok", d
    # ERST „Open panel" (Finn 01.10.2026, Live-Befund Moritz 23:08 UTC, Orbit V3: nach „Maximize panel" war der Chart weg, das Symbol
    # ließ sich nicht einstellen — „nur auf Open Panel, das Dropdown sieht man da perfekt"). Normale Höhe, Chart bleibt sichtbar;
    # „Maximize panel" nur noch als Rückfall, wenn das offene Panel zu niedrig bleibt (Vorfall pc-cccccc 30.09.: 49 px trotz „offen").
    vk = d.get("vis_knopf") if isinstance(d.get("vis_knopf"), dict) else None
    va = str((vk or {}).get("aria") or "")
    if (not getattr(s, "_panel_open_versucht", False) and vk and cdp_rect(vk)
            and re.search(r"open|öffnen|oeffnen|show|expand|einblenden", va, re.I) and not re.search(r"collapse|close|schlie|hide", va, re.I)):
        s._panel_open_versucht = True
        if hasattr(s, "werbung_weg"):
            s.werbung_weg()
        frei_o = s.lese_js(cdp_panel_frei_js(cdp_rect(vk)))
        if isinstance(frei_o, dict) and not frei_o.get("frei"):
            trail.append(f"„Open panel“ verdeckt ('{frei_o.get('was')}' liegt darüber) — kein Klick")
        else:
            trail.append(f"Order-Panel eingeklappt ({h} px unter der Broker-Leiste) → „Open panel“")
            if s.klick(cdp_rect(vk), "Order-Panel öffnen (Open panel)"):
                for _ in range(5):                        # Treffer ≠ Wirkung (Regel .835)
                    _warte(0.6, 0.3)
                    d2 = s.lese_js(CDP_PANEL_LAGE_JS)
                    va2 = str(((d2.get("vis_knopf") if isinstance(d2, dict) and isinstance(d2.get("vis_knopf"), dict) else {}) or {}).get("aria") or "")
                    if cdp_panel_lage(d2) == "ok" or (CDP_NIE_MAXIMIEREN and re.search(r"collapse|close|schlie|hide|ausblenden|einklappen", va2, re.I)):
                        s._panel_aufgeklappt = True
                        trail.append(f"Order-Panel offen ({(d2 or {}).get('unter_leiste')} px, Chart bleibt sichtbar)")
                        return "aufgeklappt", d2
                    if isinstance(d2, dict):
                        d = d2
                trail.append(f"Order-Panel nach „Open panel“ zu niedrig ({(d or {}).get('unter_leiste')} px) → Rückfall „Maximize panel“")
                h = (d or {}).get("unter_leiste")
    if ohne_max or CDP_NIE_MAXIMIEREN:   # 01.10.2026 (Finn): nie maximieren, der Chart bleibt sichtbar
        return "bleibt_eingeklappt", d
    if getattr(s, "_panel_max_versucht", False):
        return "bleibt_eingeklappt", d
    s._panel_max_versucht = True
    kn = d.get("max_knopf") if isinstance(d.get("max_knopf"), dict) else None
    if not kn or not cdp_rect(kn) or not re.search(r"maxim", str(kn.get("aria") or ""), re.I):
        trail.append(f"Order-Panel eingeklappt ({h} px unter der Broker-Leiste), Aufklapp-Symbol „Maximize panel“ fehlt"
                     + (f" (Knopf heißt '{kn.get('aria')}')" if kn else ""))
        return "ohne_knopf", d
    if hasattr(s, "werbung_weg"):
        s.werbung_weg()
    frei = s.lese_js(cdp_panel_frei_js(cdp_rect(kn)))
    if isinstance(frei, dict) and not frei.get("frei"):
        trail.append(f"„Maximize panel“ verdeckt ('{frei.get('was')}' liegt darüber) — kein Klick")
        return "bleibt_eingeklappt", d
    trail.append(f"Order-Panel eingeklappt ({h} px unter der Broker-Leiste — kein Platz für die Kontoliste) → „Maximize panel“")
    if not s.klick(cdp_rect(kn), "Order-Panel aufklappen (Maximize panel)"):
        return "bleibt_eingeklappt", d
    d2 = d
    for _ in range(5):                                    # Treffer ≠ Wirkung (Regel .835): Panel wirklich groß?
        _warte(0.6, 0.3)
        d2 = s.lese_js(CDP_PANEL_LAGE_JS)
        if cdp_panel_lage(d2) == "ok":
            s._panel_aufgeklappt = True
            trail.append(f"Order-Panel aufgeklappt ({d2.get('unter_leiste')} px)")
            return "aufgeklappt", d2
    trail.append(f"Order-Panel nach „Maximize panel“ weiter eingeklappt ({(d2 or {}).get('unter_leiste')} px)")
    return "bleibt_eingeklappt", d2


def _cdp_panel_zurueck(s, trail):
    """Am Ende eines Orbit-Laufs (Lesen/Order/Schließen): ist das Broker-Panel maximiert („Restore panel" im Panel-Kopf), EINMAL
    zurückstellen — Finn 01.10.2026 (erster Orbit-V3-Trade bei Moritz): „am Ende einfach noch mal auf Restore drücken, dann geht es
    zurück, wo ich es haben will" — Chart wieder sichtbar, Positions-Tabelle in normaler Höhe (das Userscript liest sie per
    textContent auch dort). Nur der Layout-Knopf, nie etwas an Order/Konto; Frei-Probe wie beim Aufklappen; jeder Fehler nur Spur."""
    try:
        if not hasattr(s, "lese_js"):
            return False
        d = s.lese_js(CDP_PANEL_LAGE_JS)
        kn = d.get("max_knopf") if isinstance(d, dict) and isinstance(d.get("max_knopf"), dict) else None
        if not kn or not cdp_rect(kn) or not re.search(r"restore|wiederherst", str(kn.get("aria") or ""), re.I):
            return False                                   # nicht maximiert (oder Knopf unbekannt) → nichts tun
        frei = s.lese_js(cdp_panel_frei_js(cdp_rect(kn)))
        if isinstance(frei, dict) and not frei.get("frei"):
            trail.append(f"„Restore panel“ am Ende verdeckt ('{frei.get('was')}') — Panel bleibt maximiert")
            return False
        if not s.klick(cdp_rect(kn), "Broker-Panel am Ende wiederherstellen (Restore panel)"):
            return False
        for _ in range(4):                                 # Treffer ≠ Wirkung
            _warte(0.5, 0.2)
            d2 = s.lese_js(CDP_PANEL_LAGE_JS)
            k2 = d2.get("max_knopf") if isinstance(d2, dict) and isinstance(d2.get("max_knopf"), dict) else {}
            if re.search(r"maxim", str(k2.get("aria") or ""), re.I):
                trail.append("Panel zurück in normaler Größe (Chart sichtbar)")
                return True
        trail.append("„Restore panel“ geklickt, Panel wirkt weiter maximiert")
    except Exception as e_:
        trail.append(f"Panel zurückstellen: {type(e_).__name__}")
    return False


def _cdp_esc(s, st, trail, grund):
    """Esc im Konto-Schritt — nur ohne offenen Dialog (Prüfer Runde 2, 30.09.2026: ein „Session disconnected"-Modal würde sonst
    geschlossen, bevor _cdp_sitzung_zurueck es sieht) und ohne Ausnahme (Windows: Puls-Chrome nicht vorn → RuntimeError aus _win_key,
    die ehrliche Rückgabe käme nie an). -> True, wenn gedrückt"""
    if isinstance(st, dict) and st.get("popups"):
        trail.append(f"{grund}: Dialog offen — kein Esc")
        return False
    try:
        s.taste("Escape")
    except Exception as e_:
        trail.append(f"{grund}: Esc nicht möglich ({type(e_).__name__})")
        return False
    trail.append(f"{grund} → Esc")
    return True


def _cdp_konto_sichern(s, ext, opts, trail):
    """Konto im Puls-Chrome sicherstellen (Panel auf → Umschalter höchstens EINMAL → genau ein Eintrag), je Schritt neu gelesen.
    -> (ok, code, msg, stand, extra). Steht das Konto nicht im Dropdown (anderer Tradovate-Login), Esc — die Liste bleibt nie offen
    (K1-Test 2, 00:59 UTC: Liste blieb offen, der nächste Lauf klickte direkt einen Eintrag).
    Seit 30.09.2026: eingeklapptes Order-Panel (s. CDP_PANEL_MIN_H) wird vor dem Umschalter bzw. nach „Dropdown nicht erkannt" EINMAL
    aufgeklappt und der Konto-Schritt EINMAL wiederholt; ohne Aufklapp-Symbol bzw. ohne Wirkung → 'kein_broker' (Login-Weg im
    Aufrufer _cdp_konto_mit_login). Gilt für jeden CDP-Lauf mit Konto-Schritt (Lesen, Order, Schließen).
    Seit der Regression .865 (30.09.2026): eine Liste zählt nur, wenn DIESER Lauf den Umschalter geklickt hat; 0 Treffer sind nur mit
    cdp_liste_beleg ein Login-Beleg (extra liste_aktiv, sonst konto_treffer None); Konto-Abgleich streng (cdp_konto_passt)."""
    _cdp_kachel_weg(s, trail)                             # kleine Werbe-Kachel unten links zuerst weg (05.10.2026) — dann erst lesen
    st = s.stand(opts)
    geklickt_umschalter = False
    wiederholt = False
    fremd_esc = False

    def _eintr(ko_):
        return [str(x.get("text"))[:40] for x in (ko_.get("eintraege") or []) if isinstance(x, dict)][:20]
    for _runde in range(6):
        ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
        aktiv = str(ko.get("aktiv") or "")
        if aktiv and cdp_konto_passt(aktiv, ext):
            trail.append(f"Konto steht: '{aktiv[:40]}'")
            # Prüfer 30.09.2026: eine offene Liste (z. B. aus einem früheren Lauf) liegt maximiert direkt über den Reitern Positions/
            # Account summary — der Reiter-Klick drückte sonst eine Kontozeile. Erst zu, dann weiter.
            if ko.get("liste_offen"):
                _cdp_esc(s, st, trail, "Konto-Liste stand offen")
                _warte(0.6, 0.3)
                st = s.stand(opts)
                if (st.get("konto") or {}).get("liste_offen"):
                    return False, "konto_nicht_erreicht", (f"Konto {ext} steht, aber die Konto-Liste geht mit Esc nicht zu — nichts "
                                                           "gelesen/geklickt (die Reiter lägen darunter)."), st, {"konto_eintraege": _eintr(ko)}
            # Konto passt, Panel aber eingeklappt: höchstens „Open panel“, NIE maximieren (Finn 01.10.2026, Orbit V3 bei Moritz: „ich will
            # den Chart sehen, wenn die Order platziert wird — alles in der normalen Ansicht, Maximize nur ganz kurz, wenn nötig").
            if _cdp_panel_aufklappen(s, trail, ohne_max=True)[0] == "aufgeklappt":
                st = s.stand(opts)
            # War für den Kontowechsel kurz maximiert → sofort zurück, BEVOR Ticket/Order drankommen
            if _cdp_panel_zurueck(s, trail):
                st = s.stand(opts)
            if getattr(s, "_panel_aufgeklappt", False) and geklickt_umschalter:
                trail.append("Order-Panel war eingeklappt → aufgeklappt → Konto gewechselt")
            return True, "", "", st, {"konto_aktiv": aktiv[:80]}
        if ko.get("panel") == "zu" and cdp_rect(ko.get("panel_knopf")):
            s.klick(cdp_rect(ko.get("panel_knopf")), "Handelspanel auf")
            _warte(1.0, 0.5)
            st = s.stand(opts)
            continue
        if ko.get("liste_offen") and not geklickt_umschalter:
            # REGRESSION .865 (30.09.2026, pc-cccccc, Orbit-Endlesung Plan …): nach „Maximize panel" stand der Umschalter oben,
            # augen.js ≤ 0.7.3 fand ihn nicht (aktiv '') und hielt ihn selbst für eine offene Liste mit 1 Zeile ('…0008'); das Ziel
            # '…0007' stand darin 0× → Login-Weg → „Log out" einer richtigen Sitzung. Eine Liste, die dieser Lauf NICHT selbst geöffnet
            # hat, ist deshalb nie ein Beleg: nichts daraus wählen, keinen Login daraus ableiten — EINMAL Esc und neu lesen.
            eintr = _eintr(ko)
            if fremd_esc:
                return False, "konto_nicht_erreicht", (f"Konto-Liste steht ohne eigenen Klick offen und bleibt es nach Esc "
                                                       f"(aktiv '{aktiv[:40] or '-'}', Zeilen {eintr[:4]}) — nichts gewählt, kein Login."), st, \
                    {"konto_eintraege": eintr, "konto_stand": ko}
            fremd_esc = True
            _cdp_esc(s, st, trail, f"Konto-Liste stand schon offen, nicht von diesem Lauf ({len(eintr)} Zeilen, aktiv '{aktiv[:40] or '-'}'), neu lesen")
            _warte(0.6, 0.3)
            st = s.stand(opts)
            continue
        if ko.get("liste_offen"):
            e, n = cdp_konto_eintrag(ko.get("eintraege"), ext)
            if not e:
                im_text = _cdp_ziel_im_text(s, ext) if n == 0 else None   # VOR dem Esc, solange die Liste offen ist (cdp_konto_weg)
                _cdp_esc(s, st, trail, "Konto-Liste schließen")
                ex = {"konto_eintraege": _eintr(ko), "konto_treffer": n}
                grund = ""
                if n == 0:
                    # Beleg für „anderer Tradovate-Login" nur mit lesbarem aktivem Konto, vollständiger Liste und dem aktiven Konto
                    # darin — der Login-Weg vergleicht liste_aktiv vor dem Abmelden noch einmal (cdp_abmelden_erlaubt)
                    ja, grund = cdp_liste_beleg(ko, aktiv, ext)
                    if ja:
                        ex["liste_aktiv"] = aktiv[:80]
                        ex["ziel_im_text"] = im_text
                    else:
                        ex["konto_treffer"] = None
                return False, "konto_nicht_erreicht", (f"Konto {ext} steht im Dropdown {n}x (nicht genau einmal) — nichts geklickt"
                                                        + ((" (anderer Tradovate-Login?)" if ex.get("liste_aktiv") else
                                                            f" — kein Login-Beleg: {grund}") if n == 0 else "") + "."), st, ex
            if not s.klick(cdp_rect(e), f"Konto {ext}"):
                # Prüfer 30.09.2026: ein nicht gedrückter Eintrag verbrauchte alle Runden und ließ die Liste offen
                _cdp_esc(s, st, trail, "Konto-Eintrag nicht gedrückt")
                return False, "konto_nicht_erreicht", f"Konto-Eintrag {ext} nicht gedrückt (Klick ohne Beweis) — Liste mit Esc zu, nichts gewechselt.", \
                    st, {"konto_eintraege": _eintr(ko)}
            _warte(1.2, 0.6)
            st = s.stand(opts)
            continue
        # Order-Panel (30.09.2026): vor dem Umschalter-Klick bzw. nach „Dropdown nicht erkannt" prüfen — eingeklappt → EINMAL
        # aufklappen und den Konto-Schritt EINMAL wiederholen; Symbol fehlt / ohne Wirkung → wie kein Broker (Login-Weg).
        # VOR der Umschalter-Abfrage: ist das Panel ganz unten, kann auch der Umschalter selbst aus dem Bild sein.
        lage, pd = _cdp_panel_aufklappen(s, trail) if (not geklickt_umschalter or not wiederholt) else ("", None)
        if lage == "aufgeklappt":
            if geklickt_umschalter:
                wiederholt, geklickt_umschalter = True, False
                _cdp_esc(s, st, trail, "Liste vom ersten Umschalter-Klick")   # evtl. halb offen — zu, bevor neu geklickt wird
                trail.append("Konto-Schritt nach dem Aufklappen einmal wiederholt")
            st = s.stand(opts)
            continue
        if lage in ("ohne_knopf", "bleibt_eingeklappt"):
            if geklickt_umschalter:
                _cdp_esc(s, st, trail, "Umschalter geklickt, Panel bleibt eingeklappt")
            return False, "kein_broker", (f"Order-Panel eingeklappt ({(pd or {}).get('unter_leiste')} px) und "
                                          + ("kein Aufklapp-Symbol „Maximize panel“" if lage == "ohne_knopf" else "nicht aufklappbar")
                                          + f" (aktiv '{aktiv[:40] or '-'}') → wie kein Broker: Login-Weg"), st, {"panel_lage": pd}
        if not cdp_rect(ko.get("schalter")):
            return False, "kein_broker", (f"Kein Konto-Umschalter zu sehen (aktiv '{aktiv[:40] or '-'}', "
                                          f"{str(ko.get('hinweis') or '')[:80]}) — Tradovate im Puls-Chrome verbunden?"), st, {}
        # Umschalter höchstens EINMAL (erster Live-Lauf 00:44 UTC: 4 Klicks hintereinander — ein zweiter Klick schließt ein
        # offenes Dropdown wieder). Danach zweimal lesen; bleibt es zu, ehrlich raus MIT dem Stand für T1.
        if geklickt_umschalter:
            _cdp_esc(s, st, trail, "Dropdown nicht erkannt")   # was auch immer aufging: nicht offen stehen lassen (Prüfer 30.09.2026)
            # LOGIN MIT NUR EINEM KONTO (02.10.2026, Moritz, Balance-Lesen: aktiv TDFYSL…, Umschalter-Klick öffnet keine Liste): ist das
            # aktive Konto als Kontonummer lesbar und ein ANDERES als das Ziel, gilt das als Beleg „anderer Tradovate-Login" — wie beim
            # Order-Weg. Lesbarkeit ist der Schutz aus .865 (dort war aktiv '-'); cdp_abmelden_erlaubt prüft vor dem Abmelden noch einmal.
            if cdp_ein_konto_beleg(aktiv, ext):
                trail.append(f"Umschalter öffnet keine Liste, aktiv {cdp_kontonr(aktiv)} ≠ Ziel {ext} → anderer Tradovate-Login (Login mit einem Konto)")
                return False, "konto_nicht_erreicht", (f"Konto {ext} nicht im aktiven Tradovate-Login (der hat nur {cdp_kontonr(aktiv)}) — Login-Wechsel."), st, \
                    {"konto_treffer": 0, "liste_aktiv": aktiv[:80], "ein_konto": True, "ziel_im_text": _cdp_ziel_im_text(s, ext)}
            return False, "konto_nicht_erreicht", (f"Konto-Umschalter geklickt, Dropdown nicht erkannt (aktiv '{aktiv[:40] or '-'}') — "
                                                   "augen.js sieht die Liste nicht (Selektoren?), der Klick trifft nicht, oder der Login hat "
                                                   "nur dieses eine Konto" + (f"; Order-Panel {lage} ({(pd or {}).get('unter_leiste')} px)" if lage else "")
                                                   + " — Esc, nichts gewählt."), st, \
                {"konto_stand": ko, "popups": st.get("popups"), "panel_lage": pd}
        geklickt_umschalter = True
        s.klick(cdp_rect(ko.get("schalter")), "Konto-Umschalter")
        _warte(0.9, 0.4)
        st = s.stand(opts)
        if not (st.get("konto") or {}).get("liste_offen"):
            _warte(1.0, 0.4)
            st = s.stand(opts)
    ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
    if ko.get("liste_offen"):
        _cdp_esc(s, st, trail, "Konto-Liste nach der letzten Runde")
    return False, "konto_nicht_erreicht", f"Konto {ext} nicht aktiv (steht: '{str(ko.get('aktiv') or '-')[:40]}')", st, {}


def _cdp_today_aus_reiter(s, opts, trail):
    """Tagesergebnis steht bei Tradovate NUR im Reiter „Account summary" („Total P/L", T1/Finn 29.09.2026) — kurz hin, lesen,
    zurück auf „Positions". Nur Reiter-Klicks, nie etwas im Ticket. -> (summary|None, today, label, text)"""
    r_sum = s.rect_von("#id_account-manager-tabs #summary")
    if not r_sum:
        return None, None, None, None
    s.klick(r_sum, "Reiter Account summary")
    _warte(0.7, 0.3)
    st = s.stand(opts)
    summary = cdp_summary(st.get("konto_summary"))
    today, lab, txt = tv_today_pnl(summary)
    if today is None and isinstance(summary, dict):
        for k_, v_ in summary.items():
            if re.match(r"^\s*total\s*p\s*/\s*l\s*$", str(k_), re.I):
                w_ = tv_geld_lesen(v_)
                if w_ is not None:
                    today, lab, txt = w_, str(k_), str(v_)
                    break
    r_pos = s.rect_von("#id_account-manager-tabs #positions")
    if r_pos:
        s.klick(r_pos, "Reiter Positions")
        _warte(0.5, 0.2)
    trail.append(f"Today aus „Account summary\": {today} ('{lab}')")
    return summary, today, lab, txt


def tvlesen_cdp_mit_wiederholung(cmd, lauf=None):
    """Lesen mit EINEM zweiten Versuch bei Zeitüberschreitung (02.10.2026, Mike: „Puls-Chrome/CDP: TimeoutError: timed out" beim
    Balance-Lesen — die TradingView-Seite antwortete 10 s nicht). Nur Lesen, nie Order: ein zweiter Lauf klickt nichts, was handelt.
    Das Ergebnis des ersten Laufs wird nur gedruckt, wenn kein zweiter folgt."""
    import io
    lauf = lauf or modus_tvlesen_cdp

    def einmal():
        puffer, echt = io.StringIO(), sys.stdout
        sys.stdout = puffer
        try:
            lauf(cmd)
        finally:
            sys.stdout = echt
        roh = puffer.getvalue().strip()
        try:
            return roh, (json.loads(roh.splitlines()[-1]) if roh else {})
        except (ValueError, IndexError):
            return roh, {}

    roh1, r1 = einmal()
    if r1.get("code") == "cdp_fehler" and "Timeout" in str(r1.get("msg") or ""):
        _warte(3.0, 1.0)
        roh2, r2 = einmal()
        if r2:
            r2["trail"] = "1. Versuch: " + str(r1.get("msg") or "")[:120] + " → neu verbunden > " + str(r2.get("trail") or "")
            try:
                print(json.dumps(r2, ensure_ascii=False))
            except UnicodeEncodeError:
                print(json.dumps(r2, ensure_ascii=True))
            return
        roh1 = roh2 or roh1
    print(roh1)


def modus_tvlesen_cdp(cmd):
    """tvlesen über das Puls-Chrome (CDP). Konto sicherstellen, dann EIN Stand: Positionen + Zusammenfassung (Today aus dem
    Reiter „Account summary"). Nichts im Order-Ticket."""
    res = {"ok": False, "code": "", "msg": "", "trail": "", "schritt": "start", "konto_aktiv": "",
           "konto_quelle": "cdp", "quelle": "cdp"}
    trail = _StempelSpur()
    ende = bool(cmd.get("ende")) if isinstance(cmd, dict) else False
    sitz = [None]

    def raus(code, msg, schritt, **extra):
        res["code"], res["msg"], res["schritt"] = code, msg, schritt
        res.update(extra)
        if sitz[0]:
            _cdp_panel_zurueck(sitz[0], trail)   # 01.10.2026: maximiertes Panel am Ende zurück („Restore panel“)
        res["trail"] = " > ".join(trail)
        if sitz[0]:
            sitz[0].zu()
        try:
            print(json.dumps(res, ensure_ascii=False))
        except UnicodeEncodeError:
            print(json.dumps(res, ensure_ascii=True))

    fehler = pruefe_tv_lesen_befehl(cmd)
    if fehler:
        return raus("befehl", "Befehl unvollstaendig: " + " / ".join(fehler), "befehl")
    ext = str(cmd.get("konto") or cmd.get("ext_id") or "").strip()
    geschwister = [str(x).strip() for x in (cmd.get("geschwister") or []) if len(_nur_alnum(x)) >= 3][:60]
    opts = {"kontoTexte": [ext] + geschwister}
    trail.append("Weg: Puls-Chrome (CDP)")
    if _handlauf_aktiv():                    # K3-Handlauf (29.09.2026): im Puls-Chrome klickt gerade ein Hand-Befehl — nicht dazwischen
        return raus("handlauf", "K3-Handlauf läuft im Puls-Chrome — nichts gelesen, bitte gleich erneut anstoßen.", "sperre")
    try:
        s = sitz[0] = _cdp_sitzung_holen(cmd, trail)          # kein TradingView-Tab offen → einer wird geöffnet (Auto-Login)
        ok, code, msg, st, extra = _cdp_konto_mit_login(sitz, ext, opts, cmd, trail, res)
        s = sitz[0]                                          # der Auto-Login tauscht den Tab → neue Sitzung
        res.update({k: v for k, v in extra.items() if k == "konto_aktiv"})
        if not ok:
            return raus(code, msg, "konto", **{k: v for k, v in extra.items() if k != "konto_aktiv"})
        _warte(0.6, 0.3)
        st = s.stand(opts)
        summary = cdp_summary(st.get("konto_summary"))
        today, today_label, today_text = tv_today_pnl(summary)
        ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
        if ko.get("positionen_sichtbar") is False:
            return raus("tabelle_unklar", "Positions-Tabelle im Puls-Chrome nicht sichtbar — kein Stand ohne Tabelle.", "lesen",
                        summary=summary, today_pnl=today, today_label=today_label, today_pnl_text=today_text)
        positionen = cdp_positionen_vertrag(st.get("positionen"))
        if today is None:
            try:
                sum2, t2, l2, x2 = _cdp_today_aus_reiter(s, opts, trail)
                if t2 is not None:
                    today, today_label, today_text = t2, l2, x2
                    summary = dict(summary or {}, **(sum2 or {}))
            except Exception as e_:
                trail.append(f"Today-Reiter nicht lesbar ({type(e_).__name__})")
        trail.append(f"gelesen (CDP): {len(positionen)} Pos, {len(summary or {})} Summary-Paare, Today {today} ('{today_label}')")
        res.update({"ok": True, "positionen": positionen, "offen": bool(positionen),
                    "avg_fill_je_wurzel": tv_avg_fill_je_wurzel(positionen), "summary": summary,
                    "today_pnl": today, "today_label": today_label, "today_pnl_text": today_text,
                    "alter_s": 0.0, "gelesen_at": time.strftime("%Y-%m-%dT%H:%M:%S"), "userscript": None,
                    "sprache_fremd": False, "summary_fehler": None if summary else "keine Zusammenfassung (augen.js)"})
        if ende:
            res["exit_diag"] = {"fehler": "Exit-Fill über CDP kommt mit K4"}
        return raus("", f"Konto {res['konto_aktiv'][:40]}: {len(positionen)} Position(en) (CDP)"
                    + (f", Today's P&L {today:g} ({today_label})" if today is not None else ", Tages-G&V nicht gefunden"),
                    "fertig")
    except Exception as e:
        return raus("cdp_fehler", f"Puls-Chrome/CDP: {type(e).__name__}: {str(e)[:160]}", "cdp")


# ═══════════════════════════════════════════════════════════════════════════
# PULS ÜBER CDP — K2 ORDER-PROBELAUF (29.09.2026 nachts, Finn: „let's go mit K2"). tvkonto verzweigt NUR bei lokaler Regel
# 'cdp' hierher. Konto → Symbol (Watchlist) → Seite → Market → Units → TP/SL (Schalter + Wert, Einheit $) → Units nochmal
# (TV dreht Units nach TP/SL gern zurück, 24.09.2026) → Knopf-Beweis (tv_senden_text_passt + Symbol + nicht disabled).
# Nach JEDEM Schritt neu gelesen (stand()). Bis K4 gab es hier KEINEN Senden-Klick (scharfer Start = Probelauf, gesendet:false).
# K4 (29.09.2026 abends, Finn: „einfach den letzten Button unten noch drücken, Buy oder Sell, je nachdem was eingestellt ist"):
# mit Marke 'scharf' (tv_ist_scharf) nach vollständiger Rücklesung EIN Klick auf den Knopf „Buy/Sell N SYMBOL MARKET" (Text
# exakt, nicht gesperrt, Konto stimmt, kein Popup), Beweis über TradingViews Meldungen bzw. die Positions-Tabelle, Rückgabe wie
# der alte Puls (gesendet/bestaetigt/einstieg/tp_limit/order_klick_ms/meldung_roh). Ohne 'scharf' bleibt es der Probelauf.
# ═══════════════════════════════════════════════════════════════════════════

def cdp_zahl(x):
    """REIN RECHNEND (testbar): Zahl aus augen.js-Wert (Zahl oder Text wie '1,050.00'/'4')."""
    if isinstance(x, bool):
        return None
    if isinstance(x, (int, float)):
        return float(x)
    return tv_zahl_lesen(x)


def cdp_watchlist_ziel(watchlist, symbol):
    """REIN RECHNEND (testbar): Watchlist-Zeile mit derselben Wurzel wie das Plan-Symbol (MNQZ6 → MNQZ2026, nie NQ für MNQ). -> dict|None"""
    ziel = tv_symbol_root(symbol)
    kand = [w for w in (watchlist or []) if isinstance(w, dict) and cdp_rect(w) and tv_symbol_root(str(w.get("symbol") or "")) == ziel]
    return kand[0] if len(kand) == 1 else None


def cdp_ticket_typ_market(typen):
    """REIN RECHNEND (testbar): (market_eintrag|None, ist_aktiv)."""
    for t in typen or []:
        if isinstance(t, dict) and str(t.get("id") or "").lower() == "market":
            return t, str(t.get("aria-selected")).lower() == "true"
    return None, False


def _cdp_ticket_fuellen(s, st, plan, symbol, opts, trail):
    """Ticket im Puls-Chrome füllen und jeden Wert zurücklesen — K2 und K3 gemeinsam (29.09.2026 unverändert aus
    modus_tvkette_cdp herausgezogen). KEIN Klick auf den Senden-Knopf. -> (ok, code, msg, schritt, st, knopf)"""
    ziel = tv_symbol_root(symbol)

    def ticket():
        return st.get("ticket") if isinstance(st.get("ticket"), dict) else {}

    def knopf():
        return st.get("kauf_knopf") if isinstance(st.get("kauf_knopf"), dict) else {}

    # --- Order-Ticket zu? (Live 30.09.2026 04:12–04:14 Dubai, ID B pc-cccccc, Apex …0008, NQZ6: dreimal „Symbol NQ nicht
    # einstellbar (Ticket zeigt '-')" — Chart + Watchlist standen richtig auf NQZ2026, aber puls_augen zeigte ticket.da=false:
    # das Order-Panel rechts war schlicht zu, und der neue Puls öffnete es nie.) Wie der alte Puls: Shift+T ist ein UMSCHALTER
    # (22.09.2026: ein im Aufbau „leer" gesehenes Panel wurde damit zugemacht) — also erst nach 4 leeren Blicken über ≥ 3 s,
    # Werbung vorher weg, Fokus per Klick in den Chart, danach Beweis. Geht es nicht auf: klare Meldung statt „Symbol".
    if not ticket().get("da") and not knopf():
        t0, leer = time.time(), 0
        while leer < 4 or time.time() - t0 < 3.0:
            _warte(0.6, 0.25)
            st = s.stand(opts)
            if ticket().get("da") or knopf():
                break
            leer += 1
            if time.time() - t0 > 8.0:
                break
        if not ticket().get("da") and not knopf():
            if hasattr(s, "werbung_weg"):
                s.werbung_weg()
            g = s.lese_js(WIN_GEO_JS) or {}
            bw, bh = float(g.get("innerWidth") or 0), float(g.get("innerHeight") or 0)
            # Prüfer 30.09.2026: seit .865 kann das Broker-Panel maximiert stehen (Konto-Schritt) — dann läge bei 35 %/35 % die
            # Positions-Tabelle statt des Charts. Erst „Restore panel" (TradingView-Layout, kein Broker-Knopf), dann der Chart-Klick.
            # Runde 2: ohne gedrücktes Restore KEIN Chart-Klick (sonst Tabelle); danach wieder maximieren (unten), sonst fehlt der
            # Positions-Beweis für den Rest des Laufs (K3/tvkette)
            pl = s.lese_js(CDP_PANEL_LAGE_JS) if hasattr(s, "lese_js") else None
            mk = (pl or {}).get("max_knopf") if isinstance(pl, dict) and isinstance(pl.get("max_knopf"), dict) else None
            chart_frei, restored = True, False
            if mk and cdp_rect(mk) and re.search(r"restore|wiederherst", str(mk.get("aria") or ""), re.I):
                gedrueckt = bool(s.klick(cdp_rect(mk), "Broker-Panel wiederherstellen (Restore panel) — Chart für Shift+T frei"))
                restored = False
                for _ in range(5 if gedrueckt else 0):     # Treffer ≠ Wirkung (Regel .835, Prüfer Runde 3): Knopf heißt wieder „Maximize"?
                    _warte(0.6, 0.3)
                    pl2 = s.lese_js(CDP_PANEL_LAGE_JS) or {}
                    mk2 = pl2.get("max_knopf") if isinstance(pl2, dict) and isinstance(pl2.get("max_knopf"), dict) else {}
                    if re.search(r"maxim", str(mk2.get("aria") or ""), re.I) and not re.search(r"restore|wiederherst", str(mk2.get("aria") or ""), re.I):
                        restored = True
                        break
                chart_frei = restored
                if restored:
                    g = s.lese_js(WIN_GEO_JS) or {}
                    bw, bh = float(g.get("innerWidth") or 0), float(g.get("innerHeight") or 0)
                else:
                    trail.append("„Restore panel“ " + ("ohne Wirkung" if gedrueckt else "nicht gedrückt") + " — kein Chart-Klick, nur Shift+T")
            if chart_frei and bw > 200 and bh > 200:
                # mittig-links im oberen Chart-Drittel: weit weg von BUY/SELL oben links und vom Broker-Panel unten
                s.klick([bw * 0.35 - 10, bh * 0.35 - 10, 20.0, 20.0], "Chart (Fokus für Shift+T)")
                _warte(0.25, 0.15)
            s.taste("t", 8)
            trail.append("Order-Ticket war zu — per Shift+T geöffnet")
            for _ in range(8):
                _warte(0.6, 0.3)
                st = s.stand(opts)
                if ticket().get("da") or knopf():
                    break
            if restored:
                # NICHT wieder maximieren (Live-Befund Moritz 01.10.2026 23:08 UTC: danach war der Chart weg, MNQ ließ sich nicht
                # einstellen). Höchstens „Open panel" in normaler Höhe; Maximize bleibt für diesen Lauf gesperrt.
                s._panel_max_versucht, s._panel_open_versucht = True, False
                if _cdp_panel_aufklappen(s, trail)[0] == "aufgeklappt":
                    st = s.stand(opts)
            if not ticket().get("da") and not knopf():
                return (False, "asset", "Order-Ticket rechts ist zu und ging auch mit Shift+T nicht auf — in TradingView oben "
                        "rechts auf „Trade“ klicken, sodass Market/Limit/Stop und Units zu sehen sind.", "asset", st, None)
            trail.append("Order-Ticket offen (bewiesen)")

    # --- Seite VOR dem Symbol, wenn das Ticket noch „Start creating order" zeigt (Live-Befund Moritz 01.10.2026 00:51 UTC, zweimal:
    # Chart MNQZ2026, Ticket-Kopf MNQZ6 — alles richtig, aber ohne gewählte Seite steht das Symbol nicht im Senden-Knopf, augen.js las
    # '-' → „Symbol MNQ nicht einstellbar — nichts gesendet"). Erst die Kachel BUY/SELL, dann zeigt der Knopf „Buy 1 MNQZ6 MARKET" und
    # das Symbol ist lesbar. Die exakte Knopf-Prüfung vor dem Senden bleibt der Beweis.
    if ticket().get("da") and not tv_symbol_root(str(knopf().get("symbol") or ticket().get("symbol") or "")):
        kachel0 = ticket().get("kaufen" if plan["richtung"] == "buy" else "verkaufen")
        if cdp_rect(kachel0):
            trail.append("Symbol im Ticket nicht lesbar (keine Seite gewählt) → erst Seite " + plan["richtung"].upper())
            s.klick(cdp_rect(kachel0), f"Seite {plan['richtung'].upper()} (vor dem Symbol)")
            _warte(0.6, 0.3)
            st = s.stand(opts)

    # --- Symbol
    for _v in range(2):
        ist = tv_symbol_root(str(knopf().get("symbol") or ticket().get("symbol") or ""))
        if ist == ziel:
            trail.append(f"Symbol steht: {knopf().get('symbol') or ticket().get('symbol')}")
            break
        wl = cdp_watchlist_ziel(((ticket().get("symbolsuche") or {}).get("watchlist")), symbol)
        if not wl or _v:
            return (False, "asset", f"Symbol {ziel} nicht einstellbar (Ticket zeigt '{ist or '-'}', Watchlist-Treffer "
                    f"{'1' if wl else '0'}).", "asset", st, None)
        s.klick(cdp_rect(wl), f"Watchlist {wl.get('symbol')}")
        # Bis ~6 s auf das neue Symbol warten (Live-Befund Moritz 01.10.2026: EIN Blick nach 1,2 s sah '-', kurz danach stand MNQZ6 im Ticket)
        _seite_nach = False
        for _b in range(6):
            _warte(1.0, 0.4)
            st = s.stand(opts)
            sym_jetzt = tv_symbol_root(str(knopf().get("symbol") or ticket().get("symbol") or ""))
            if sym_jetzt == ziel:
                break
            # Symbolwechsel setzt das Ticket auf „Start creating order" zurück (Live-Befund 01.10.2026 13:42 + 13:50 UTC, Moritz und Jakob,
            # Plan NQ, Chart MNQ: Watchlist-Klick wirkte, Ticket-Kopf „NQZ6", aber ohne Seite steht das Symbol nicht im Knopf → '-' →
            # „Symbol NQ nicht einstellbar"). Dann EINMAL die Seite des Plans wählen — danach zeigt der Knopf „Buy 3 NQZ6 MARKET".
            if not sym_jetzt and not _seite_nach and ticket().get("da"):
                kachel_n = ticket().get("kaufen" if plan["richtung"] == "buy" else "verkaufen")
                if cdp_rect(kachel_n):
                    _seite_nach = True
                    trail.append("Symbol nach dem Wechsel nicht lesbar (Ticket ohne Seite) → Seite " + plan["richtung"].upper())
                    s.klick(cdp_rect(kachel_n), f"Seite {plan['richtung'].upper()} (nach dem Symbol)")
    if not ticket().get("da"):
        return False, "ticket", "Order-Ticket im Puls-Chrome nicht offen — nichts getippt.", "ticket", st, None
    # --- Seite
    # Bis zu 3 Versuche, jedes Mal mit frisch gelesenem Rechteck (Live-Befund Moritz 01.10.2026 12:50 UTC, Orbit V3, Plan SELL, Ticket stand
    # vom vorigen Trade auf Buy: direkt nach dem Login-Wechsel meldete TradingView an der SELL-Kachel 1,6 s lang kein :hover → kein Druck,
    # EIN Versuch, Abbruch „Seite steht nicht auf SELL"). Der Hover-Riegel bleibt: ohne Beweis nie ein Druck.
    for _sv in range(3):
        if str(knopf().get("seite") or ticket().get("seite") or "") == plan["richtung"]:
            break
        kachel = ticket().get("kaufen" if plan["richtung"] == "buy" else "verkaufen")
        if not cdp_rect(kachel):
            return False, "ticket", f"Seiten-Kachel {plan['richtung'].upper()} nicht gefunden.", "ticket", st, None
        s.klick(cdp_rect(kachel), f"Seite {plan['richtung'].upper()}" + (f" (Versuch {_sv + 1})" if _sv else ""))
        _warte(0.6, 0.3)
        st = s.stand(opts)
    if str(knopf().get("seite") or ticket().get("seite") or "") != plan["richtung"]:
        return False, "ticket", f"Seite steht nicht auf {plan['richtung'].upper()} ('{knopf().get('text') or '-'}', 3 Versuche).", "ticket", st, None
    trail.append(f"Seite = {plan['richtung'].upper()}")
    # --- Order-Typ Market
    m_, aktiv_ = cdp_ticket_typ_market(ticket().get("typen"))
    if not aktiv_:
        if not cdp_rect(m_):
            return False, "ticket", "Reiter Market nicht gefunden.", "ticket", st, None
        s.klick(cdp_rect(m_), "Reiter Market")
        _warte(0.6, 0.3)
        st = s.stand(opts)
        if not cdp_ticket_typ_market(ticket().get("typen"))[1]:
            return False, "ticket", "Reiter Market ist nach dem Klick nicht aktiv.", "ticket", st, None
    trail.append("Typ = Market")

    def units_setzen():
        nonlocal st
        mg = ticket().get("menge") if isinstance(ticket().get("menge"), dict) else {}
        if cdp_zahl(mg.get("wert")) == float(plan["menge"]):
            return True
        if not cdp_rect(mg):
            return False
        for _v in range(2):
            s.feld_setzen(cdp_rect(mg), str(plan["menge"]), "Units")
            _warte(0.4, 0.2)
            st = s.stand(opts)
            mg = ticket().get("menge") if isinstance(ticket().get("menge"), dict) else {}
            if cdp_zahl(mg.get("wert")) == float(plan["menge"]):
                return True
            trail.append(f"Units: '{mg.get('wert')}' statt {plan['menge']} — tippe einmal neu")
        return False

    if not units_setzen():
        return False, "ticket", f"Units stehen nicht auf {plan['menge']} (Feld: '{(ticket().get('menge') or {}).get('wert')}').", "ticket", st, None
    trail.append(f"Units = {plan['menge']}")
    # --- TP / SL: Schalter + Wert (Einheit $)
    for schl, name, soll in (("tp", "Take profit", plan["tp"]), ("sl", "Stop loss", plan["sl"])):
        f_ = ticket().get(schl) if isinstance(ticket().get(schl), dict) else {}
        if not f_.get("da", True) and soll is not None:
            return False, "ticket", f"'{name}' im Ticket nicht gefunden.", "ticket", st, None
        an = f_.get("an")
        if soll is None:
            if an:
                if not cdp_rect(f_.get("schalter")):
                    return False, "ticket", f"'{name}' ist AN, Schalter nicht greifbar.", "ticket", st, None
                s.klick(cdp_rect(f_.get("schalter")), f"Schalter {name} AUS")
                _warte(0.5, 0.2)
                st = s.stand(opts)
                if (ticket().get(schl) or {}).get("an"):
                    return False, "ticket", f"Schalter '{name}' ließ sich nicht AUS stellen.", "ticket", st, None
            trail.append(f"{name} AUS")
            continue
        if "$" not in str(f_.get("einheit") or ""):
            return False, "ticket", f"'{name}' steht nicht auf $ (Einheit '{f_.get('einheit') or '?'}') — der Wert {soll:g} wäre etwas anderes.", "ticket", st, None
        if an is False:
            if not cdp_rect(f_.get("schalter")):
                return False, "ticket", f"'{name}' ist AUS, Schalter nicht greifbar.", "ticket", st, None
            s.klick(cdp_rect(f_.get("schalter")), f"Schalter {name} AN")
            _warte(0.5, 0.2)
            st = s.stand(opts)
            f_ = ticket().get(schl) if isinstance(ticket().get(schl), dict) else {}
        if cdp_zahl(f_.get("wert")) != float(soll):
            ok_w = False
            for _v in range(2):
                if not cdp_rect(f_.get("feld")):
                    break
                s.feld_setzen(cdp_rect(f_.get("feld")), f"{soll:g}", name)
                _warte(0.4, 0.2)
                st = s.stand(opts)
                f_ = ticket().get(schl) if isinstance(ticket().get(schl), dict) else {}
                if cdp_zahl(f_.get("wert")) == float(soll):
                    ok_w = True
                    break
            if not ok_w:
                return False, "ticket", f"{name}: im Feld steht '{f_.get('wert')}' statt {soll:g}.", "ticket", st, None
        if f_.get("an") is False:
            return False, "ticket", f"'{name}' steht auf {soll:g} $, aber der Schalter ist AUS — die Order ginge ohne {name} raus.", "ticket", st, None
        trail.append(f"{name} = {soll:g} $ (Schalter {'AN' if f_.get('an') else 'unlesbar'})")
    # --- Units nach TP/SL nochmal (TradingView dreht sie gern auf den alten Ticket-Wert zurück)
    st = s.stand(opts)
    if not units_setzen():
        return False, "ticket", "Units nach TP/SL nicht mehr korrekt.", "ticket", st, None
    # --- Knopf-Beweis
    kk = knopf()
    ok_k, f_k = tv_senden_text_passt(str(kk.get("text") or ""), plan["richtung"], plan["menge"])
    if not ok_k:
        return False, "knopf", f_k, "knopf", st, None
    if not any(tv_symbol_root(w) == ziel for w in str(kk.get("text") or "").split()):
        return False, "knopf", f"Auf dem Knopf steht nicht {ziel} ('{str(kk.get('text'))[:40]}').", "knopf", st, None
    if kk.get("disabled"):
        return False, "knopf", f"Senden-Knopf ist gesperrt ('{str(kk.get('text'))[:40]}').", "knopf", st, None
    return True, "", "", "knopf", st, kk



def cdp_ticket_ruecklesung(st, plan):
    """REIN RECHNEND (testbar): das ganze Ticket direkt vor dem Senden noch einmal gelesen — wie k3_ruecklesung, aber TP/SL dürfen
    AUS sein (Plan ohne TP bzw. SL, z. B. Winning Days ohne Stop Loss): dann darf der Schalter nicht AN stehen. -> (ok, zeile, fehler[])"""
    tk = st.get("ticket") if isinstance(st, dict) and isinstance(st.get("ticket"), dict) else {}
    kk = st.get("kauf_knopf") if isinstance(st, dict) and isinstance(st.get("kauf_knopf"), dict) else {}
    fehler = []
    market = cdp_ticket_typ_market(tk.get("typen"))[1]
    if not market:
        fehler.append("Typ nicht Market")
    seite = str(kk.get("seite") or tk.get("seite") or "")
    if seite != plan["richtung"]:
        fehler.append(f"Seite '{seite or '-'}' statt {plan['richtung']}")
    mg = cdp_zahl((tk.get("menge") or {}).get("wert")) if isinstance(tk.get("menge"), dict) else None
    if mg != float(plan["menge"]):
        fehler.append(f"Units '{mg}' statt {plan['menge']}")
    teile = [f"Typ {'Market' if market else '?'}", f"Seite {seite or '-'}", f"Units {k3_fmt(mg, 0) if mg is not None else '-'}"]
    for schl, name, soll in (("tp", "TP", plan["tp"]), ("sl", "SL", plan["sl"])):
        f_ = tk.get(schl) if isinstance(tk.get(schl), dict) else {}
        w, an, einh = cdp_zahl(f_.get("wert")), f_.get("an"), str(f_.get("einheit") or "")
        if soll is None:
            if an is True:
                fehler.append(f"{name}-Schalter AN, der Plan hat kein {name}")
            teile.append(f"{name} aus")
            continue
        if an is not True:
            fehler.append(f"{name}-Schalter nicht AN")
        if "$" not in einh:
            fehler.append(f"{name}-Einheit '{einh or '?'}' statt $")
        if w != float(soll):
            fehler.append(f"{name} '{w}' statt {soll}")
        teile.append(f"{name} {k3_fmt(w, 0) if w is not None else '-'} {einh or '?'} {'AN' if an is True else 'AUS/unlesbar'}")
    return not fehler, " · ".join(teile), fehler


def cdp_zeilen_menge(zeilen, richtung):
    """REIN RECHNEND (testbar): Summe der (vorzeichenlosen) Menge sichtbarer Positionszeilen dieser Seite."""
    summe = 0.0
    for z in zeilen or []:
        if isinstance(z, dict) and z.get("seite") == richtung:
            m = cdp_zahl(z.get("menge"))
            if m:
                summe += abs(m)
    return summe



def cdp_im_bild(rect, geo):
    """REIN RECHNEND (testbar): Rechteck [x, y, w, h] ganz im Viewport (innerWidth/innerHeight aus geo)? Ohne geo: nur plausibel."""
    try:
        x, y, w, h = [float(v) for v in rect[:4]]
    except (TypeError, ValueError, IndexError):
        return False
    if w < 3 or h < 3 or x < 0 or y < 0:
        return False
    iw, ih = (geo or {}).get("innerWidth"), (geo or {}).get("innerHeight")
    return not (iw and ih) or (x + w <= float(iw) and y + h <= float(ih))


def cdp_meldungen_zu(toasts):
    """REIN RECHNEND (testbar): der EINGEKLAPPTE Meldungsstapel (augen.js toasts.gruppen: offen = aria-expanded) — bevorzugt die
    Gruppe „orders", sonst genau eine Gruppe mit Texten. -> Gruppe (mit 'mehr' = Show-more-Knopf, falls sichtbar) | None"""
    gruppen = [g for g in ((toasts or {}).get("gruppen") or []) if isinstance(g, dict) and g.get("offen") is False
               and (g.get("texte") or cdp_rect(g.get("mehr")))]
    orders = [g for g in gruppen if str(g.get("gruppe") or "").lower() == "orders"]
    if len(orders) == 1:
        return orders[0]
    return gruppen[0] if len(gruppen) == 1 else None



# Knöpfe „Show more" am Meldungsstapel, die GANZ im Bild liegen (Rand eingeschlossen) — Text („Show more", „Show more 3", „Mehr
# anzeigen") oder data-name toast-group-expand-button-*; der klickbare Vorfahr (button/[role=button]) liefert das Rechteck.
CDP_SHOW_MORE_JS = r"""(function () {
  function drin(r) { return r.width >= 3 && r.height >= 3 && r.left >= 0 && r.top >= 0 && r.right <= innerWidth && r.bottom <= innerHeight; }
  function T(e) { return String((e && e.textContent) || '').replace(/\s+/g, ' ').trim(); }
  function sb(e) { try { var s = getComputedStyle(e); return s.visibility !== 'hidden' && s.display !== 'none' && s.opacity !== '0'; } catch (_) { return false; } }
  var c = [];
  document.querySelectorAll('[data-name^="toast-group-expand-button-"],button,[role="button"],span,div').forEach(function (e) {
    var t = T(e), dn = e.getAttribute('data-name') || '';
    if (!/^toast-group-expand-button-/.test(dn) && (t.length > 30 || !/^(show more|mehr anzeigen)/i.test(t) || /show less|weniger/i.test(t))) return;
    if (!sb(e) || !drin(e.getBoundingClientRect())) return;
    c.push(e);
  });
  c = c.filter(function (e) { return !c.some(function (f) { return f !== e && e.contains(f); }); });
  var out = [];
  c.forEach(function (e) {
    var k = e.closest('button,[role="button"]') || e, r = k.getBoundingClientRect();
    if (!drin(r) || out.some(function (o) { return o._k === k; })) return;
    out.push({ _k: k, text: T(k).slice(0, 30), dn: (k.getAttribute('data-name') || e.getAttribute('data-name') || ''),
               expanded: k.getAttribute('aria-expanded'), rect: [r.left, r.top, r.width, r.height] });
  });
  return out.slice(0, 8).map(function (o) { delete o._k; return o; });
})()"""


def cdp_show_more_wahl(kandidaten, stapel_rect=None):
    """REIN RECHNEND (testbar): GENAU EIN „Show more" am Meldungsstapel. Schon offene (aria-expanded true) und „Show less" zählen nie.
    Mehrere: der toast-group-expand-Knopf vor Text-Treffern, dann der nächste zum Stapel (höchstens 400 px). -> Kandidat | None"""
    kand = [k for k in kandidaten or [] if isinstance(k, dict) and cdp_klickpunkt(k.get("rect")) is not None
            and str(k.get("expanded")).lower() != "true" and not re.search(r"show less|weniger", str(k.get("text") or ""), re.I)]
    if len(kand) <= 1:
        return kand[0] if kand else None
    dn = [k for k in kand if str(k.get("dn") or "").startswith("toast-group-expand-button-")]
    if len(dn) == 1:
        return dn[0]
    kand = dn or kand
    if not stapel_rect:
        return None
    try:
        sx, sy, sw, sh = [float(v) for v in stapel_rect[:4]]
    except (TypeError, ValueError, IndexError):
        return None

    def abstand(k):
        x, y, w, h = [float(v) for v in k["rect"][:4]]
        dx = max(0.0, sx - (x + w), x - (sx + sw))
        dy = max(0.0, sy - (y + h), y - (sy + sh))
        return dx + dy
    nah = sorted((abstand(k), i) for i, k in enumerate(kand))
    if nah[0][0] > 400 or (len(nah) > 1 and nah[1][0] - nah[0][0] < 10):
        return None                                   # zu weit weg oder zwei gleich nah = mehrdeutig
    return kand[nah[0][1]]


def cdp_summary_start(summary):
    """REIN RECHNEND (testbar): Start-Werte aus „Account summary" für die Order-Antwort — Schlüssel wie tsx-konto
    (balance_start), dazu equity_start und today_pnl_start (Total P/L = heute, Finn). Nicht lesbar = None, nie 0."""
    bal, tpl = k3_summary_werte(summary)
    eq = None
    for k, v in (summary or {}).items():
        if re.match(r"^\s*(equity|net\s*liq)", str(k), re.I):
            eq = tv_geld_lesen(v)
            if eq is not None:
                break
    return {"balance_start": bal, "equity_start": eq, "today_pnl_start": tpl}


def cdp_brackets_aus_orders(orders, root, richtung, menge):
    """REIN RECHNEND (testbar): TP = offene Limit-Order der Gegenseite, SL = offene Stop-Order der Gegenseite (sichtbare Zeilen der
    Wurzel, Menge passt), je GENAU eine. Preis aus augen.js 'preis', bei Stop-Orders notfalls aus der Spalte „Stop Price".
    -> (tp|None, sl|None)"""
    gegen = "sell" if richtung == "buy" else "buy"
    offen = [o for o in k3_offene_orders(orders, root) if o.get("seite") == gegen
             and (o.get("menge") is None or cdp_zahl(o.get("menge")) == float(menge))]

    def preis(o):
        sp_ = o.get("spalten") if isinstance(o.get("spalten"), dict) else {}
        for w in (o.get("preis"), sp_.get("Stop Price"), sp_.get("Stopp-Preis"), sp_.get("Limit Price"), sp_.get("Limitpreis")):
            z = cdp_zahl(w)
            if z:
                return z
        return None
    typ = lambda o: str(o.get("typ") or "")
    lim = [o for o in offen if re.search(r"limit", typ(o), re.I) and not re.search(r"stop", typ(o), re.I)]
    stp = [o for o in offen if re.search(r"stop", typ(o), re.I)]
    return (preis(lim[0]) if len(lim) == 1 else None), (preis(stp[0]) if len(stp) == 1 else None)


def cdp_pruefung(b, fill_tabelle, tp_orders, sl_orders, plan, toleranz=0.01):
    """REIN RECHNEND (testbar): Endprüfung — Meldungswerte (b: einstieg/tp/sl) gegen Tabelle (Avg Fill) und Reiter Orders (TP/SL).
    ok = jeder gebrauchte Wert ist da (Fill; TP/SL nur, wenn der Plan sie hat) und kein Paar weicht mehr als die Toleranz ab.
    -> {ok, fill_tabelle, tp_orders, sl_orders, abweichung: {fill, tp, sl}, text}"""
    b = b or {}
    fill_m = b.get("einstieg") if b.get("einstieg_quelle") == "fill_toast" else None
    paare = {"fill": (fill_m, fill_tabelle), "tp": (b.get("tp"), tp_orders), "sl": (b.get("sl"), sl_orders)}
    ab, teile, ok = {}, [], True
    for name, (m, t) in paare.items():
        brauch = name == "fill" or bool(plan.get(name))
        if m is not None and t is not None:
            ab[name] = round(abs(float(m) - float(t)), 4)
            if ab[name] > toleranz:
                ok = False
            teile.append(f"{name.upper()} Meldung {k3_fmt(m)} / {'Tabelle' if name == 'fill' else 'Orders'} {k3_fmt(t)}"
                         + (" ✓" if ab[name] <= toleranz else f" ABWEICHUNG {ab[name]:g}"))
        else:
            ab[name] = None
            if brauch and m is None and t is None:
                ok = False
                teile.append(f"{name.upper()} nirgends gelesen")
            elif brauch or m is not None or t is not None:
                teile.append(f"{name.upper()} {k3_fmt(m if m is not None else t)} (nur {'Meldung' if m is not None else ('Tabelle' if name == 'fill' else 'Orders')})")
    return {"ok": ok, "fill_tabelle": fill_tabelle, "tp_orders": tp_orders, "sl_orders": sl_orders, "abweichung": ab,
            "text": ("passt: " if ok else "NICHT sicher: ") + " · ".join(teile)}


def _cdp_endpruefung(s, opts, plan, root, trail):
    """Avg Fill der Positions-Zeile (Reiter Positions) + TP/SL-Limit aus dem Reiter „Orders", danach zurück auf Positions.
    Nur Reiter-Klicks. Live 29.09.2026 14:58 UTC (.807): Reiter Orders geklickt, aber augen.js lieferte keine Order-Zeile
    (liest nur td[data-label]) — dann liest Puls die sichtbaren Tabellen selbst (CDP_TABELLEN_JS: data-label, sonst Spaltenkopf)
    und schreibt kompakt in die Spur, was dort steht. -> (avg|None, tp|None, sl|None, diag|None)"""
    st = s.stand(opts)
    zeile = next((z for z in k3_zeilen(st.get("positionen"), root) if z.get("seite") == plan["richtung"]), None)
    avg = cdp_zahl((zeile or {}).get("avg"))
    tp_o = sl_o = diag = None
    brauch = lambda: (tp_o is None and plan["tp"]) or (sl_o is None and plan["sl"])
    # Live 15:29 UTC (.814): „Reiter Orders geklickt @211,554", aber aktiv blieb „positions" und sichtbar die Positions-Tabelle —
    # der Wechsel wird jetzt bewiesen (aria-selected), sonst ein zweiter Klick, sonst steht die Reiterleiste in der Spur
    if _cdp_reiter(s, "orders", trail):
        roh = None
        for _ in range(3):
            _warte(0.6, 0.3)
            st2 = s.stand(opts)
            tp_o, sl_o = cdp_brackets_aus_orders(st2.get("orders"), root, plan["richtung"], plan["menge"])
            if not brauch():
                break
            roh = s.lese_js(CDP_TABELLEN_JS) or {}
            tp2, sl2 = cdp_brackets_aus_orders(cdp_orders_aus_roh(roh), root, plan["richtung"], plan["menge"])
            tp_o = tp_o if tp_o is not None else tp2
            sl_o = sl_o if sl_o is not None else sl2
            if not brauch():
                trail.append("TP/SL aus dem eigenen Tabellen-Blick (augen.js sah keine Order-Zeile)")
                break
        if brauch():
            diag = cdp_tabellen_kurz(roh)
            trail.append(f"Reiter Orders: TP/SL nicht gefunden — sichtbar: {diag[:700]}")
        _cdp_reiter(s, "positions", trail)
    else:
        trail.append("Reiter Orders nicht aktiv zu bekommen — TP/SL nur aus den Meldungen")
        _cdp_reiter(s, "positions", trail)
    return avg, tp_o, sl_o, diag


# Reiterleiste des Account-Managers (Positions / Orders / Account summary …): id, Text, aria-selected, Rechteck. Nur lesen.
CDP_REITER_JS = r"""(function () {
  function T(e) { return String((e && e.textContent) || '').replace(/\s+/g, ' ').trim(); }
  var box = document.getElementById('id_account-manager-tabs');
  if (!box) return null;
  return Array.prototype.slice.call(box.querySelectorAll('[role="tab"],[id],button')).filter(function (e) {
    var r = e.getBoundingClientRect(); return r.width > 3 && r.height > 3 && r.top < innerHeight && r.bottom > 0; }).slice(0, 16).map(function (e) {
    var r = e.getBoundingClientRect();
    return { id: e.id || '', text: T(e).slice(0, 30), role: e.getAttribute('role') || '', sel: e.getAttribute('aria-selected'),
             rect: [r.left, r.top, r.width, r.height] }; });
})()"""


def cdp_reiter_passt(e, name):
    """REIN RECHNEND (testbar): ist dieser Eintrag der Reiter 'name' (id gleich oder Text beginnt damit, z. B. „Orders 2")?"""
    if not isinstance(e, dict):
        return False
    n = str(name or "").lower()
    return str(e.get("id") or "").lower() == n or bool(re.match(re.escape(n) + r"\b", str(e.get("text") or "").lower()))


def cdp_reiter_aktiv(reiter, name):
    """REIN RECHNEND (testbar): steht der Reiter 'name' auf aria-selected=true?"""
    return any(cdp_reiter_passt(e, name) and str(e.get("sel")).lower() == "true" for e in reiter or [])


def cdp_reiter_wahl(reiter, name):
    """REIN RECHNEND (testbar): GENAU EIN klickbarer Eintrag für den Reiter (role=tab bevorzugt, innerster bei gleichem Ort). -> Eintrag|None"""
    kand = [e for e in reiter or [] if cdp_reiter_passt(e, name) and cdp_klickpunkt(e.get("rect")) is not None]
    tabs = [e for e in kand if e.get("role") == "tab"]
    kand = tabs or kand
    kand = [k for k in kand if not any(j is not k and _k3_rect_in(j["rect"], k["rect"]) and list(j["rect"]) != list(k["rect"]) for j in kand)]
    return kand[0] if len(kand) == 1 else None


def cdp_reiter_kurz(reiter):
    """REIN RECHNEND (testbar): Reiterleiste für die Spur."""
    return " | ".join(f"{e.get('id') or '-'}:{e.get('text') or ''}{'*' if str(e.get('sel')).lower() == 'true' else ''}@{[int(v) for v in (e.get('rect') or [])[:2]]}"
                      for e in (reiter or [])[:10] if isinstance(e, dict))[:500] or "keine Reiterleiste"


def _cdp_reiter(s, name, trail):
    """Reiter des Account-Managers aktiv machen und den Wechsel beweisen (aria-selected). Höchstens 2 Klicks. -> bool"""
    reiter = []
    for versuch in (1, 2):
        reiter = s.lese_js(CDP_REITER_JS) or []
        if cdp_reiter_aktiv(reiter, name):
            return True
        z = cdp_reiter_wahl(reiter, name)
        if not z:
            break
        if s.klick(z["rect"], f"Reiter {name} ({z.get('id') or z.get('text')})"):
            for _ in range(5):
                _warte(0.3, 0.15)
                reiter = s.lese_js(CDP_REITER_JS) or []
                if cdp_reiter_aktiv(reiter, name):
                    return True
    trail.append(f"Reiter {name} nicht aktiv — Leiste: {cdp_reiter_kurz(reiter)}")
    return False


# Sichtbare Tabellen roh (Endprüfung, Reiter Orders): je Tabelle Spaltenköpfe + bis 8 sichtbare Zeilen [data-label, Text] — auch
# Zellen ohne data-label (dann zählt die Spalte des Kopfs). Nur lesen.
CDP_TABELLEN_JS = r"""(function () {
  function sb(e) { try { var r = e.getBoundingClientRect(); if (r.width < 3 || r.height < 3 || r.bottom < 0 || r.top > innerHeight) return false;
    var s = getComputedStyle(e); return s.visibility !== 'hidden' && s.display !== 'none'; } catch (_) { return false; } }
  function T(e) { return String((e && e.textContent) || '').replace(/\s+/g, ' ').trim(); }
  var aktiv = document.querySelector('#id_account-manager-tabs [aria-selected="true"]');
  var out = { reiter: aktiv ? String(aktiv.id || T(aktiv)).slice(0, 20) : null, tabellen: [] };
  document.querySelectorAll('table').forEach(function (t) {
    if (out.tabellen.length >= 3 || !sb(t)) return;
    var koepfe = Array.prototype.slice.call(t.querySelectorAll('th,[role="columnheader"]')).map(function (h) { return T(h).slice(0, 24); });
    var zeilen = [];
    t.querySelectorAll('tr').forEach(function (tr) {
      if (zeilen.length >= 8 || !sb(tr)) return;
      var tds = tr.querySelectorAll('td'); if (!tds.length) return;
      zeilen.push(Array.prototype.slice.call(tds).map(function (td) { return [td.getAttribute('data-label') || '', T(td).slice(0, 24)]; }));
    });
    out.tabellen.push({ koepfe: koepfe.slice(0, 20), zeilen: zeilen });
  });
  return out;
})()"""


def cdp_orders_aus_roh(roh):
    """REIN RECHNEND (testbar): Order-Zeilen aus dem eigenen Tabellen-Blick — Spaltenname = data-label, sonst der Kopf an derselben
    Stelle. Form wie augen.js orders (symbol, seite, menge, typ, preis, status, sichtbar, spalten)."""
    out = []
    for t in (roh or {}).get("tabellen") or [] if isinstance(roh, dict) else []:
        koepfe = t.get("koepfe") or [] if isinstance(t, dict) else []
        for z in (t.get("zeilen") or []) if isinstance(t, dict) else []:
            d = {}
            for i, zelle in enumerate(z if isinstance(z, list) else []):
                lab, txt = (list(zelle) + ["", ""])[:2] if isinstance(zelle, (list, tuple)) else ("", "")
                name = str(lab or (koepfe[i] if i < len(koepfe) else "")).strip()
                if name and name not in d:
                    d[name] = str(txt or "").strip()

            def feld(rx):
                for k, v in d.items():
                    if re.fullmatch(rx, k, re.I) and v and v not in ("—", "-"):
                        return v
                return None
            sym = feld(r"symbol")
            if not sym:
                continue
            sd = feld(r"side|seite") or ""
            out.append({"symbol": sym, "seite": "buy" if re.match(r"(buy|kauf|long)", sd, re.I) else "sell" if re.match(r"(sell|verkauf|short)", sd, re.I) else None,
                        "menge": cdp_zahl(feld(r"qty|quantity|menge|anz(ahl|\.)?")), "typ": feld(r"type|typ|order type|auftragsart"),
                        "status": feld(r"status"),
                        "preis": cdp_zahl(feld(r"limit\s*price|limitpreis|limit-preis")) or cdp_zahl(feld(r"stop\s*price|stopp-preis|stop-preis"))
                        or cdp_zahl(feld(r"price|preis")), "sichtbar": True, "spalten": d})
    return out


def cdp_tabellen_kurz(roh, max_zeichen=700):
    """REIN RECHNEND (testbar): der Tabellen-Blick kompakt für die Spur — Reiter, Köpfe, erste Zeilen als Name=Wert."""
    if not isinstance(roh, dict):
        return "kein Tabellen-Blick"
    teile = [f"Reiter {roh.get('reiter') or '?'}"]
    for t in roh.get("tabellen") or []:
        teile.append("Köpfe " + "/".join(str(k) for k in (t.get("koepfe") or [])[:12]))
        for z in (t.get("zeilen") or [])[:3]:
            teile.append(" ".join(f"{(c[0] or '·')}={c[1]}" for c in z if isinstance(c, (list, tuple)) and len(c) >= 2 and c[1])[:220])
    return " | ".join(teile)[:max_zeichen]

def cdp_meldung_text(m):
    """REIN RECHNEND (testbar): eine gelesene Meldung als Rohtext für order_signale/Diagnose — Art, Status, Seite, Menge, Preis."""
    if not isinstance(m, dict):
        return ""
    teile = [str(m.get("art") or "?"), str(m.get("status") or "-"), str(m.get("seite") or "?"),
             k3_fmt(m.get("menge"), 0) if m.get("menge") is not None else "?", "@", k3_fmt(m.get("preis"))]
    return (" ".join(teile) + f" ({str(m.get('text') or '')[:60]})")[:160]

def cdp_order_beweis(neu, zeilen, plan, menge_vorher):
    """REIN RECHNEND (testbar): Liegt die Order nach dem EINEN Klick? Beweis = neue Fill-Meldung dieser Seite und Menge („Market
    order executed") ODER die sichtbare Positionsmenge dieser Seite ist um die Plan-Menge gewachsen. Einstieg: Fill aus der
    Meldung, sonst Avg der Zeile — aber nur, wenn vorher nichts offen war (sonst wäre es der Schnitt mit der alten Position).
    -> {bestaetigt, einstieg, einstieg_quelle, tp, sl, symbol, beweis}"""
    om = k3_order_meldungen(neu, plan["richtung"], plan["menge"])
    vorher = float(menge_vorher or 0.0)
    gewachsen = cdp_zeilen_menge(zeilen, plan["richtung"]) >= vorher + float(plan["menge"]) - 1e-9
    zeile = next((z for z in zeilen or [] if isinstance(z, dict) and z.get("seite") == plan["richtung"]), None)
    out = {"bestaetigt": bool(om.get("fill") is not None or gewachsen), "tp": om.get("tp"), "sl": om.get("sl"),
           "symbol": (zeile or {}).get("symbol"), "einstieg": None, "einstieg_quelle": None, "beweis": ""}
    if om.get("fill") is not None:
        out.update(einstieg=om["fill"], einstieg_quelle="fill_toast", beweis="TradingView-Meldung (Fill)")
    elif gewachsen:
        avg = cdp_zahl((zeile or {}).get("avg")) if vorher == 0 else None
        out.update(einstieg=avg, einstieg_quelle="tabelle_avg_fill" if avg is not None else None, beweis="Positions-Tabelle")
    return out

