def _k3_eingabe(ws, trail):
    """Klick/Tasten-Werkzeug für ein ANDERES Target (Tradovate-Fenster) — dieselben Regeln wie _AugenSitzung, ohne augen.js."""
    e = _AugenSitzung.__new__(_AugenSitzung)
    e.trail, e.ws, e.maus, e.target_id = trail, ws, (40.0, 40.0), None
    return e


class _K3Ort:
    """Wo das Login-Formular sitzt: die TradingView-Seite selbst oder ein eigenes Tradovate-Fenster (neues Target)."""

    def __init__(self, name, ws, eingabe, anfang, eigen=False):
        self.name, self.ws, self.eingabe, self.anfang, self.eigen = name, ws, eingabe, anfang, eigen

    def blick(self):
        try:
            r = self.ws.rufe("Runtime.evaluate", {"expression": K3_LOGIN_BLICK_JS + "(" + json.dumps(self.anfang) + ")",
                                                  "returnByValue": True}, timeout=6)
            return {} if r.get("exceptionDetails") else (((r.get("result") or {}).get("value")) or {})
        except Exception:
            return {}

    def zu(self):
        if self.eigen:
            try:
                self.ws.zu()
            except Exception:
                pass


def _k3_fenster(s, zustand, trail):
    """Puls-Chrome-Fenster 'normal' (nach vorn — Finn: für den Login ok) bzw. zurück 'minimized'. -> vorheriger Zustand | None
    Auf Windows nichts: dort holt jeder Klick das Fenster per Wiederherstellen nach vorn, zu() minimiert es wieder."""
    if _WIN_EINGABE:
        return None
    try:
        v = _cdp_http("/json/version") or {}
        b = _CdpVerbindung(v.get("webSocketDebuggerUrl"), timeout=5.0)
        try:
            w = b.rufe("Browser.getWindowForTarget", {"targetId": s.target_id}, timeout=3)
            vorher = (w.get("bounds") or {}).get("windowState")
            b.rufe("Browser.setWindowBounds", {"windowId": w.get("windowId"), "bounds": {"windowState": zustand}}, timeout=3)
        finally:
            b.zu()
        if zustand == "normal":
            s.ws.rufe("Page.bringToFront", {}, timeout=3)
        trail.append(f"Puls-Chrome-Fenster: {vorher} -> {zustand}")
        return vorher
    except Exception as e:
        trail.append(f"Fenster '{zustand}' nicht gesetzt ({type(e).__name__}: {str(e)[:60]})")
        return None


def _k3_summary(s, opts, trail, schritt):
    summary, _t, _l, _x = _cdp_today_aus_reiter(s, opts, trail)
    bal, tpl = k3_summary_werte(summary)
    return bal, tpl, summary


def _k3_flach_konto(s, opts, trail):
    """Aktives Konto flach? Nur mit sichtbarer Tabelle, zwei Lesungen. -> (ja, text)"""
    n = 0
    for _ in range(4):
        st = s.stand(opts)
        ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
        z = [p for p in st.get("positionen") or [] if isinstance(p, dict) and p.get("sichtbar")]
        if ko.get("positionen_sichtbar") is True and not z:
            n += 1
            if n >= 2:
                return True, f"flach ({str(ko.get('aktiv') or '-')[:30]}, Tabelle sichtbar, 2 Lesungen)"
        else:
            if z:
                return False, f"{len(z)} Position(en) offen: " + ", ".join(f"{p.get('symbol')} {p.get('seite')} {p.get('menge')}" for p in z[:3])
            n = 0
        _warte(1.0, 0.4)
    return False, "Positions-Tabelle nicht sichtbar — flach nicht bewiesen"


def _k3_demo(eingabe, bl, trail, box=None):
    """Umgebung melden und „Demo" wählen, falls angeboten und nicht aktiv (puls-chrome-starten.bat: „Tradovate (Demo)").
    Nur Einträge im Login-Kasten bzw. Dialog (box), nie irgendein „Live" der Chartseite."""
    umg = [x for x in (bl or {}).get("umgebung") or [] if isinstance(x, dict) and (not box or _k3_rect_in(x.get("rect") or [], box))]
    if not umg:
        return
    trail.append("[8] Umgebung: " + ", ".join(f"{k3_label(x)}{' (aktiv)' if x.get('an') else ''}" for x in umg))
    demo = [x for x in umg if re.fullmatch(r"\s*demo\s*", str(x.get("text") or ""), re.I)]
    if len(demo) == 1 and not demo[0].get("an") and cdp_rect(demo[0]):
        eingabe.klick(cdp_rect(demo[0]), "Umgebung Demo")
        _warte(0.6, 0.3)


def _k3_login_wechsel(s, anfang, opts, trail, res):
    """K3 Schritte 8+9: Tradovate im Puls-Chrome ab-/neu anmelden (Chrome-Autofill), Tradeify beweisen. -> (code, msg, schritt)"""
    res["fenster_vorher"] = vorher = _k3_fenster(s, "normal", trail)
    ort_tv = _K3Ort("TradingView-Seite", s.ws, s, anfang)
    b = ort_tv.blick()
    # --- 8a Abmelden über das Kontextmenü neben „Tradovate" (Inventar 01:30 UTC: button title „Open context menu" in #footer-chart-panel)
    if not cdp_rect(b.get("ctx")):
        return "abmelden", f"Kontextmenü-Knopf neben 'Tradovate' nicht eindeutig ({b.get('ctx')}) — nichts geklickt, Tradovate bleibt verbunden.", "8-abmelden"
    s.klick(cdp_rect(b.get("ctx")), "Kontextmenü neben Tradovate")
    _warte(0.8, 0.3)
    b = ort_tv.blick()
    texte = [k3_label(m) for m in b.get("menue") or []]
    trail.append(f"[8] Kontextmenü: {texte}")
    e, n = k3_eindeutig(b.get("menue"), K3_RX_ABMELDEN)
    if not e:
        s.taste("Escape")
        return "abmelden", f"Im Kontextmenü kein eindeutiger Eintrag 'Log out/Disconnect' ({n} Treffer) — Menü mit Esc zu, Tradovate bleibt verbunden.", "8-abmelden"
    s.klick(cdp_rect(e), f"Menü '{k3_label(e)}'")
    ja_geklickt = False
    getrennt = False
    ende = time.time() + 14
    while time.time() < ende:
        _warte(0.9, 0.3)
        st = s.stand(opts)
        ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
        if not ko.get("schalter") and not k3_nr_treffer(str(ko.get("aktiv") or "")):
            getrennt = True
            break
        b = ort_tv.blick()
        if not ja_geklickt:
            for d in b.get("dialoge") or []:
                j, nj = k3_eindeutig(d.get("knoepfe"), K3_RX_JA)
                if j:
                    trail.append(f"[8] Rückfrage '{str(d.get('titel') or d.get('text') or '')[:60]}'")
                    s.klick(cdp_rect(j), f"Rückfrage '{k3_label(j)}'")
                    ja_geklickt = True
                    break
    if not getrennt:
        return "abmelden", "Nach 'Log out' ist das Konto weiter sichtbar (14 s) — Stand bitte im Puls-Chrome ansehen.", "8-abmelden"
    b = ort_tv.blick()
    trail.append(f"[8] OK Tradovate abgemeldet (Konto-Umschalter weg, Leiste '{str(b.get('leiste') or '')[:40]}')")
    # --- 8b Tradovate neu verbinden: Kachel (ggf. erst „Trading Panel" auf)
    vorher_ids = {str(t.get("id")) for t in (_cdp_http("/json/list") or []) if isinstance(t, dict)}
    b = ort_tv.blick()
    if not b.get("kacheln") and not b.get("login") and cdp_rect(b.get("panel_knopf")):
        s.klick(cdp_rect(b.get("panel_knopf")), "Trading Panel")
        _warte(1.2, 0.5)
        b = ort_tv.blick()
    if not b.get("login"):
        kach = b.get("kacheln") or []
        if len(kach) != 1 or not cdp_rect(kach[0]):
            return "verbinden", (f"Tradovate-Kachel nicht eindeutig ({len(kach)}) — Tradovate ist ABGEMELDET, Puls-Chrome steht vorn: "
                                 "bitte von Hand verbinden."), "8-verbinden"
        s.klick(cdp_rect(kach[0]), "Kachel Tradovate")
    ort, zwischen = None, 0
    ende = time.time() + 20
    while time.time() < ende and not ort:
        _warte(0.9, 0.3)
        b = ort_tv.blick()
        if b.get("login"):
            ort = ort_tv
            break
        for t in _cdp_http("/json/list") or []:
            if not isinstance(t, dict) or str(t.get("id")) in vorher_ids or t.get("type") != "page":
                continue
            if not re.match(r"https://([a-z0-9-]+\.)*tradovate\.com/", str(t.get("url") or "")):
                continue
            try:
                ws2 = _CdpVerbindung(t.get("webSocketDebuggerUrl"), timeout=8.0)
            except Exception as e_:
                trail.append(f"Tradovate-Fenster nicht erreichbar ({type(e_).__name__})")
                continue
            o2 = _K3Ort("Tradovate-Fenster", ws2, _k3_eingabe(ws2, trail), anfang, eigen=True)
            if o2.blick().get("login"):
                try:
                    ws2.rufe("Page.bringToFront", {}, timeout=3)
                except Exception:
                    pass
                ort = o2
                break
            o2.zu()
        if ort:
            break
        if zwischen == 0:
            # TradingView-Zwischendialog (z. B. Umgebung + „Connect", noch ohne Passwortfeld) — genau einmal, Umgebung nur melden
            for d in b.get("dialoge") or []:
                c, nc = k3_eindeutig(d.get("knoepfe"), K3_RX_CONNECT)
                if c:
                    trail.append(f"[8] Zwischendialog '{str(d.get('titel') or '')[:40]}'")
                    _k3_demo(s, b, trail, d.get("rect"))
                    s.klick(cdp_rect(c), f"'{k3_label(c)}' im Zwischendialog")
                    zwischen = 1
                    break
    if not ort:
        res["login_diag"] = {"dialoge": b.get("dialoge"), "iframes": b.get("iframes"), "kacheln": b.get("kacheln")}
        return "login_formular", ("Kein Login-Formular gefunden (20 s) — Tradovate ist ABGEMELDET, Puls-Chrome steht vorn: bitte von Hand "
                                  "verbinden. Dialoge/iframes stehen in login_diag."), "8-formular"
    try:
        lb = (ort.blick().get("login") or {})
        u = lb.get("user") or {}
        trail.append(f"[8] Login-Formular ({ort.name}): Benutzerfeld {'gefüllt' if u.get('gefuellt') else 'leer'}, "
                     f"Passwortfeld {'gefüllt' if (lb.get('pw') or {}).get('gefuellt') else 'leer'}, Remember me "
                     f"{'-' if lb.get('merken') is None else ('AN' if lb['merken'].get('an') else 'AUS')} (Werte nie gelesen)")
        if not cdp_rect(u):
            return "login_feld", "Benutzerfeld vor dem Passwortfeld nicht gefunden — nichts getippt.", "8-autofill"
        bl0 = ort.blick()
        _k3_demo(ort.eingabe, bl0, trail, (bl0.get("login") or {}).get("box"))
        lb = (ort.blick().get("login") or {})
        u = lb.get("user") or u
        # --- 8c Chrome-Autofill per Tastatur (Finn): Feld anklicken, alten Inhalt weg, Anfang tippen, Pfeil runter, Enter
        ort.eingabe.klick(cdp_rect(u), "Login-Feld")
        _warte(0.5, 0.3)
        if u.get("gefuellt"):
            ort.eingabe.taste("a", modifiers=2)
            ort.eingabe.taste("Backspace")
            _warte(0.3, 0.2)
        ort.eingabe.tippen(anfang)
        trail.append(f"Anfang '{anfang}' getippt")
        _warte(0.9, 0.4)
        ort.eingabe.taste("ArrowDown")
        _warte(0.6, 0.3)
        lb = (ort.blick().get("login") or {})
        if not ((lb.get("user") or {}).get("autofill") or (lb.get("pw") or {}).get("autofill")):
            return "autofill", ("Kein Chrome-Vorschlag markiert (keine Autofill-Vorschau nach Pfeil runter) — KEIN Enter, kein Connect. "
                                "Tradovate ist ABGEMELDET, Puls-Chrome steht vorn: bitte von Hand einloggen."), "8-autofill"
        ort.eingabe.taste("Enter")
        _warte(0.9, 0.4)
        lb = (ort.blick().get("login") or {})
        u, pw = lb.get("user") or {}, lb.get("pw") or {}
        user_ok, pw_ok = bool(u.get("gefuellt") and u.get("passt")), bool(pw.get("gefuellt") or pw.get("autofill"))
        trail.append(f"[8] Autofill übernommen: Benutzer {'gefüllt' if u.get('gefuellt') else 'LEER'}, beginnt mit '{anfang}': "
                     f"{'ja' if u.get('passt') else 'NEIN'}; Passwort {'nicht leer' if pw_ok else 'LEER'} (Wert nie gelesen)")
        if not user_ok or not pw_ok:
            return "autofill", "Autofill nicht vollständig (siehe Zeile davor) — kein Connect. Puls-Chrome steht vorn: bitte von Hand.", "8-autofill"
        c, nc = k3_eindeutig(lb.get("knoepfe"), K3_RX_CONNECT)
        if not c:
            return "connect", f"Kein eindeutiger Connect-Knopf ({nc}; Knöpfe: {[k3_label(k) for k in lb.get('knoepfe') or []][:8]}) — nicht verbunden.", "8-connect"
        ort.eingabe.klick(cdp_rect(c), f"'{k3_label(c)}' (Connect)")
        verbunden, ko = False, {}
        ende = time.time() + 30
        while time.time() < ende:
            _warte(1.0, 0.4)
            st = s.stand(opts)
            ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
            if ko.get("schalter") and k3_nr_treffer(str(ko.get("aktiv") or "")):
                verbunden = True
                break
            bo = ort.blick()
            if bo.get("freigabe"):
                return "freigabe", "Tradovate fragt nach einer Freigabe ('Allow') — NICHT automatisch bestätigt; bitte im Puls-Chrome von Hand.", "8-connect"
            if bo.get("login") and bo.get("fehler_text"):
                return "login_fehler", f"Login-Meldung: '{bo.get('fehler_text')}' — nicht verbunden.", "8-connect"
        if not verbunden:
            return "verbunden", "Nach Connect kein Konto sichtbar (30 s) — Puls-Chrome ansehen.", "8-connect"
        trail.append(f"[8] OK verbunden, aktiv '{str(ko.get('aktiv'))[:40]}'")
    finally:
        if ort is not ort_tv and ort is not None:
            ort.zu()
    # --- 9 Beweis: Dropdown zeigt Tradeify (und kein Apex), ein Tradeify-Konto wählen, Summary lesen — KEINE Order
    st = s.stand(opts)
    ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
    if not ko.get("liste_offen") and cdp_rect(ko.get("schalter")):
        s.klick(cdp_rect(ko.get("schalter")), "Konto-Umschalter")
        _warte(0.9, 0.4)
        st = s.stand(opts)
        ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
        if not ko.get("liste_offen"):
            _warte(1.0, 0.4)
            st = s.stand(opts)
            ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
    nrs = [k3_kontonr(e) for e in ko.get("eintraege") or []]
    tdf = [x for x in nrs if K3_RX_TRADEIFY.match(x)]
    apx = [x for x in nrs if K3_RX_APEX.match(x)]
    res["dropdown"] = nrs[:40]
    trail.append(f"[9] Dropdown: {len(nrs)} Konten — Tradeify {len(tdf)}, Apex {len(apx)}: {', '.join(nrs[:6])}{' …' if len(nrs) > 6 else ''}")
    if not tdf or apx:
        if ko.get("liste_offen"):
            s.taste("Escape")
        return "dropdown", f"Dropdown zeigt nicht nur Tradeify (Tradeify {len(tdf)}, Apex {len(apx)}) — kein Konto gewählt.", "9-dropdown"
    # schon aktives Tradeify-Konto bevorzugen (dann kein Klick in die Liste, nur Esc — sonst schlösse der Reiter-Klick nur die Liste)
    aktiv_nr = k3_kontonr({"text": ko.get("aktiv")})
    wahl = aktiv_nr if aktiv_nr in tdf else tdf[0]
    if wahl == aktiv_nr and ko.get("liste_offen"):
        s.taste("Escape")
        _warte(0.4, 0.2)
    ok, code, msg, st, extra = _cdp_konto_sichern(s, wahl, {"kontoTexte": [wahl]}, trail)
    if not ok:
        return code, msg, "9-konto"
    bal, tpl, _sm = _k3_summary(s, {"kontoTexte": [wahl]}, trail, "9")
    res["tradeify"] = {"konto": wahl, "balance": bal, "total_pl": tpl}
    trail.append(f"[9] OK Tradeify-Konto {wahl}: Balance {k3_fmt(bal)} · Total P/L {k3_fmt(tpl)} (keine Order)")
    if vorher == "minimized":
        _k3_fenster(s, "minimized", trail)
    return "", f"Login gewechselt: Tradeify {wahl} aktiv, Balance {k3_fmt(bal)}, Total P/L {k3_fmt(tpl)}.", "9-fertig"


def _k3_hochladen(res, pc):
    """Ergebnis + Spur nach puls_augen (art 'inventar', unter daten.inventar.k3 — die Route bleibt unverändert) und lokal."""
    try:
        with open(os.path.join(_AUGEN_HIER, "k3_" + time.strftime("%Y%m%d_%H%M%S") + ".json"), "w", encoding="utf-8") as f:
            json.dump(res, f, ensure_ascii=False, default=str)
    except Exception:
        pass
    if not pc:
        return
    import urllib.request
    spur = list(res.get("trail") or [])
    for n in (160, 80, 30):
        daten = {"inventar": {"art": "k3", "k3": {k: v for k, v in res.items() if k not in ("trail", "login_diag")},
                              "login_diag": res.get("login_diag"), "trail": spur[-n:]}, "ts": int(time.time() * 1000)}
        body = json.dumps({"art": "inventar", "daten": daten}, ensure_ascii=False, default=str).encode("utf-8")
        if len(body) < 55_000:
            break
    try:
        req = urllib.request.Request(f"{PULS_BACKEND}/puls-augen/{pc}", data=body, headers={"Content-Type": "application/json"})
        urllib.request.urlopen(req, timeout=8.0).read()
    except Exception:
        pass


def modus_k3(cmd):
    """K3 scharfer Handlauf (siehe Block-Kopf). Druckt die Spur live, am Ende das Ergebnis als JSON."""
    nur_login = bool(cmd.get("nur_login"))
    res = {"ok": False, "code": "", "msg": "", "schritt": "start", "gesendet": False, "flach": None, "quelle": "cdp",
           "modus": "k3login" if nur_login else "k3", "at": time.strftime("%Y-%m-%dT%H:%M:%S")}
    trail = _LiveSpur()
    pc = _augen_pc_id()
    sitz, gesperrt = [None], [False]

    def raus(code, msg, schritt, **extra):
        res["code"], res["msg"], res["schritt"] = code, msg, schritt
        res.update(extra)
        res["ok"] = not code
        trail.append(("FERTIG: " if not code else "ABBRUCH: ") + msg)
        res["trail"] = list(trail)
        if sitz[0]:
            sitz[0].zu()
        if gesperrt[0]:
            _handlauf_setzen(False)
        _k3_hochladen(res, pc)
        try:
            print(json.dumps({k: v for k, v in res.items() if k != "trail"}, ensure_ascii=False, default=str))
        except UnicodeEncodeError:
            print(json.dumps({k: v for k, v in res.items() if k != "trail"}, ensure_ascii=True, default=str))
        return res

    anfang = str(cmd.get("login_anfang") or "").strip()
    anfang = "" if anfang == "-" else anfang
    ext = str(cmd.get("ext_id") or "").strip()
    symbol = str(cmd.get("symbol") or "").strip().upper()
    print(f"K3-Handlauf ({res['modus']}) auf {pc or '?'} — Spur live:", flush=True)
    if pc not in K3_PCS:
        return raus("pc", f"K3 läuft nur auf {', '.join(K3_PCS)} (dieser PC: {pc or 'ohne pc_id'}) — nichts getan.", "befehl")
    if nur_login and not anfang:
        return raus("befehl", "k3login braucht den Anfang des Tradeify-Logins — nichts getan.", "befehl")
    plan, root = None, ""
    if not nur_login:
        plan, fehler = tv_order_plan(cmd)
        root = tv_symbol_root(symbol)
        if not plan:
            return raus("befehl", f"Befehl: {fehler} — nichts getan.", "befehl")
        if plan["menge"] != 1 or root not in K3_PUNKTWERT:
            return raus("befehl", f"K3 nur mit 1 MNQ (Befehl: {plan['menge']} {symbol}) — nichts getan.", "befehl")
        if not plan["tp"] or not plan["sl"]:
            return raus("befehl", "K3 verlangt TP und SL in $ — nichts getan.", "befehl")
        if not K3_RX_APEX.match(re.sub(r"[^A-Z0-9]", "", ext.upper())):
            return raus("befehl", f"K3 nur auf einem Apex-Konto ('{ext}') — nichts getan.", "befehl")
    if _augen_regel_holen(pc) != "cdp":
        return raus("regel", "Schalter puls_augen_cdp steht für diesen PC nicht auf 'cdp' — nichts getan.", "befehl")
    if _handlauf_aktiv():
        return raus("sperre", "Ein K3-Handlauf läuft schon (puls_handlauf.lock jünger als 15 min) — nichts getan.", "befehl")
    _handlauf_setzen(True)
    gesperrt[0] = True
    trail.append("Sperre gesetzt: tvlesen/tvkette (CDP) und Augen-Prozess halten still")
    try:
        s = sitz[0] = _AugenSitzung(trail)
        if nur_login:
            opts = {"kontoTexte": []}
            ja, text = _k3_flach_konto(s, opts, trail)
            trail.append(f"[8] Vorprüfung aktives Konto: {text}")
            if not ja:
                return raus("nicht_flach", f"Aktives Konto nicht nachweislich flach ({text}) — kein Login-Wechsel.", "8-vorpruefung")
            res["flach"] = True
            code, msg, schritt = _k3_login_wechsel(s, anfang, opts, trail, res)
            return raus(code, msg, schritt)
        opts = {"kontoTexte": [ext]}
        # [1] Panel + Konto
        trail.append(f"[1] Konto {ext}: Panel öffnen, im Dropdown wählen")
        ok, code, msg, st, extra = _cdp_konto_sichern(s, ext, opts, trail)
        if not ok:
            return raus(code, msg + " — nichts gesendet.", "1-konto")
        ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
        if not cdp_konto_passt(str(ko.get("aktiv") or ""), ext):
            return raus("konto", f"Aktiv ist '{ko.get('aktiv')}', nicht {ext} — nichts gesendet.", "1-konto")
        res["konto"] = str(ko.get("aktiv"))[:40]
        trail.append(f"[1] OK Konto aktiv: '{res['konto']}' (Broker {ko.get('broker') or '?'}, Panel {ko.get('panel') or '?'})")
        # [2] Account Summary vorher
        bal0, tpl0, _sm = _k3_summary(s, opts, trail, "2")
        if bal0 is None or tpl0 is None:
            return raus("summary", f"Account Summary unvollständig (Balance {bal0}, Total P/L {tpl0}) — nichts gesendet.", "2-summary")
        res["vorher"] = {"balance": bal0, "total_pl": tpl0}
        trail.append(f"[2] OK Summary vorher: Balance {k3_fmt(bal0)} · Total P/L {k3_fmt(tpl0)}")
        _warte(0.5, 0.3)
        st = s.stand(opts)
        ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
        if ko.get("positionen_sichtbar") is not True:
            return raus("tabelle", "Positions-Tabelle nicht sichtbar — ohne Tabelle kein Beweis, nichts gesendet.", "2-flach")
        schon = [p for p in st.get("positionen") or [] if isinstance(p, dict) and p.get("sichtbar")]
        if schon:
            return raus("nicht_flach", f"Konto hat schon {len(schon)} Position(en) ({schon[0].get('symbol')} {schon[0].get('menge')}) — nichts gesendet.", "2-flach")
        trail.append("[2] OK Konto flach vor der Order (Tabelle sichtbar, keine Zeile)")
        # [3] Ticket füllen + alles zurücklesen
        trail.append(f"[3] Ticket: {symbol}, {plan['richtung'].upper()}, Market, Units 1, TP {plan['tp']:g} $, SL {plan['sl']:g} $")
        ok, code, msg, schritt, st, kk = _cdp_ticket_fuellen(s, st, plan, symbol, opts, trail)
        if not ok:
            return raus(code, msg + " — nichts gesendet.", "3-" + schritt)
        _warte(0.4, 0.2)
        st = s.stand(opts)
        rl_ok, rl_text, rl_fehler = k3_ruecklesung(st, plan)
        trail.append(f"[3] Rücklesung: {rl_text}")
        if not rl_ok:
            return raus("ruecklesung", "Rücklesung passt nicht: " + "; ".join(rl_fehler) + " — nichts gesendet.", "3-ruecklesung")
        # [4] Knopf-Text EXAKT, dann EIN Klick
        kk = st.get("kauf_knopf") if isinstance(st.get("kauf_knopf"), dict) else {}
        soll = k3_knopf_soll(plan["richtung"], 1, symbol)
        ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
        if not k3_knopf_exakt(kk.get("text"), plan["richtung"], 1, symbol):
            return raus("knopf", f"Knopf zeigt '{kk.get('text')}', verlangt '{soll}' — nichts gesendet.", "4-knopf")
        if kk.get("disabled") or cdp_klickpunkt(cdp_rect(kk)) is None:
            return raus("knopf", f"Senden-Knopf gesperrt oder ohne Rechteck ('{kk.get('text')}') — nichts gesendet.", "4-knopf")
        if st.get("popups"):
            return raus("popup", f"Dialog/Popup offen ({[p.get('titel') or p.get('text') for p in st['popups']][:2]}) — nichts gesendet.", "4-knopf")
        if not cdp_konto_passt(str(ko.get("aktiv") or ""), ext):
            return raus("konto", f"Konto vor dem Klick nicht mehr {ext} ('{ko.get('aktiv')}') — nichts gesendet.", "4-knopf")
        vorher_m = [k3_meldung_schluessel(m) for m in ((st.get("toasts") or {}).get("meldungen") or []) if isinstance(m, dict)]
        trail.append(f"[4] Knopf-Text EXAKT '{soll}', nicht gesperrt, Konto {ext}, kein Popup — EIN Klick")
        res["gesendet"] = True                 # ab hier: nie wiederholen, jeder Abbruch = „Stand ansehen"
        s.klick(cdp_rect(kk), "SENDEN-Knopf")
        # [5] Beweis: sichtbare Zeile + Meldungen
        zl, om, neu = [], {}, []
        ende = time.time() + 15
        while time.time() < ende:
            _warte(0.8, 0.3)
            st = s.stand(opts)
            neu = k3_neue_meldungen(vorher_m, (st.get("toasts") or {}).get("meldungen"))
            om = k3_order_meldungen(neu, plan["richtung"], 1)
            zl = k3_zeilen(st.get("positionen"), root)
            if st.get("popups") and not zl and not om.get("fill"):
                return raus("dialog_nach_senden", (f"Nach dem Klick erschien ein Dialog ({[p.get('titel') or p.get('text') for p in st['popups']][:2]}) "
                                                   "— NICHTS weiter geklickt. Stand bitte in TradingView ansehen."), "5-beweis")
            if len(zl) == 1 and om.get("fill") and om.get("tp") and om.get("sl"):
                break
        res["meldungen_order"] = [m.get("text") for m in neu][:8]
        if not zl:
            return raus("kein_beweis", "Nach dem Klick keine sichtbare MNQ-Zeile (15 s) — Stand UNKLAR, nichts weiter geklickt. "
                                       "Bitte in TradingView nachsehen.", "5-beweis")
        z0 = zl[0]
        if len(zl) != 1 or cdp_zahl(z0.get("menge")) != 1.0 or z0.get("seite") != plan["richtung"]:
            return raus("position_unerwartet", f"Unerwartete Position(en): {[(p.get('symbol'), p.get('seite'), p.get('menge')) for p in zl]} "
                                               "— NICHT geschlossen, bitte von Hand prüfen.", "5-beweis")
        pw = K3_PUNKTWERT[root]
        fill = om.get("fill") or z0.get("avg")
        d_tp = plan["tp"] / pw
        d_sl = plan["sl"] / pw
        vz = 1 if plan["richtung"] == "buy" else -1
        pr = []
        for name, preis, soll_p in (("TP", om.get("tp"), (fill + vz * d_tp) if fill else None), ("SL", om.get("sl"), (fill - vz * d_sl) if fill else None)):
            if preis is None:
                pr.append(f"{name}-Limit nicht in den Meldungen")
            else:
                pr.append(f"{name} {k3_fmt(preis)}" + (f" ({'passt' if soll_p is not None and abs(preis - soll_p) <= 1.0 else 'ABWEICHUNG'}, "
                                                       f"Soll {k3_fmt(soll_p)})" if soll_p is not None else ""))
        res["order"] = {"symbol": z0.get("symbol"), "seite": z0.get("seite"), "menge": z0.get("menge"), "avg": z0.get("avg"),
                        "fill_meldung": om.get("fill"), "tp_limit": om.get("tp"), "sl_limit": om.get("sl")}
        trail.append(f"[5] OK Position {z0.get('symbol')} {str(z0.get('seite')).upper()} {k3_fmt(z0.get('menge'), 0)} @ Avg {k3_fmt(z0.get('avg'))} · "
                     f"Fill (Meldung) {k3_fmt(om.get('fill')) if om.get('fill') else 'nicht gesehen'} · " + " · ".join(pr))
        # [6] Schließen: Close-Knopf der EINEN Zeile beweisen, klicken, Dialog [data-name=submit-button]
        _warte(1.5, 0.8)
        st = s.stand(opts)
        vorher_c = [k3_meldung_schluessel(m) for m in ((st.get("toasts") or {}).get("meldungen") or []) if isinstance(m, dict)]
        zl = k3_zeilen(st.get("positionen"), root)
        if not zl:
            trail.append("[6] MNQ-Zeile schon weg (TP/SL ausgelöst?) — kein Close-Klick")
        else:
            knopf_c, zeile_c = None, None
            for runde in range(2):
                roh = s.lese_js(K3_ZEILEN_JS) or []
                kz = [z for z in roh if isinstance(z, dict) and z.get("sichtbar") and tv_symbol_root(str(z.get("symbol") or "")) == root
                      and not any(k in (z.get("spalten") or {}) for k in ("Status", "Order ID", "Order-ID"))]
                if len(kz) != 1:
                    return raus("close_zeile", f"{len(kz)} sichtbare MNQ-Zeilen in der Tabelle — POSITION OFFEN, bitte von Hand schließen.", "6-close")
                zeile_c = kz[0]
                knopf_c, n_k = k3_close_knopf(zeile_c)
                if knopf_c:
                    break
                if runde == 0 and cdp_rect(zeile_c.get("zeile")):
                    s.hin(zeile_c.get("zeile"), "MNQ-Zeile (Knöpfe einblenden)")
                    _warte(0.6, 0.3)
            if not knopf_c:
                res["zeile_knoepfe"] = (zeile_c or {}).get("knoepfe")
                return raus("close_knopf", f"Kein eindeutiger Schließen-Knopf in der MNQ-Zeile ({[k3_label(k) or k.get('dn') for k in (zeile_c or {}).get('knoepfe') or []][:8]}) "
                                           "— POSITION OFFEN, bitte von Hand schließen.", "6-close")
            st = s.stand(opts)
            zl = k3_zeilen(st.get("positionen"), root)
            if len(zl) != 1 or cdp_zahl(zl[0].get("menge")) != 1.0 or zl[0].get("seite") != plan["richtung"]:
                return raus("close_beweis", f"Zeile vor dem Close-Klick nicht mehr eindeutig ({[(p.get('symbol'), p.get('menge')) for p in zl]}) "
                                            "— nichts geklickt, bitte von Hand prüfen.", "6-close")
            sp_ = zeile_c.get("spalten") or {}
            trail.append(f"[6] Close-Knopf bewiesen: Zeile {sp_.get('Symbol')} {sp_.get('Side') or sp_.get('Seite') or ''} "
                         f"{sp_.get('Qty') or sp_.get('Quantity') or sp_.get('Menge') or ''}, Knopf '{k3_label(knopf_c) or knopf_c.get('dn')}' @{knopf_c.get('rect')}")
            s.klick(cdp_rect(knopf_c), "Close-Knopf der MNQ-Zeile")
            bestaetigt = False
            ende = time.time() + 6
            while time.time() < ende:
                _warte(0.5, 0.2)
                st = s.stand(opts)
                dl = [p for p in st.get("popups") or [] if isinstance(p, dict) and cdp_rect(p.get("submit"))]
                if len(dl) > 1:
                    return raus("close_dialog", f"{len(dl)} Dialoge mit Bestätigen-Knopf — nichts bestätigt, POSITION OFFEN, bitte von Hand.", "6-close")
                if dl:
                    p = dl[0]
                    sub = p.get("submit") or {}
                    wort = f"{p.get('titel') or ''} {p.get('text') or ''} {sub.get('text') or ''}"
                    if sub.get("dn") != "submit-button" or not re.search(r"close|schlie", wort, re.I):
                        return raus("close_dialog", f"Dialog passt nicht zum Schließen ('{wort.strip()[:80]}', Knopf {sub.get('dn')}) — nichts bestätigt, POSITION OFFEN.", "6-close")
                    trail.append(f"[6] Dialog '{str(p.get('titel') or p.get('text') or '')[:50]}': Knopf '{str(sub.get('text') or '')[:30]}' [data-name=submit-button]")
                    s.klick(cdp_rect(sub), "Bestätigen (submit-button)")
                    bestaetigt = True
                    break
                ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
                if ko.get("positionen_sichtbar") is True and not k3_zeilen(st.get("positionen"), root):
                    trail.append("[6] Position ohne Rückfrage-Dialog geschlossen")
                    bestaetigt = True
                    break
            if not bestaetigt:
                return raus("close_dialog", "Nach dem Close-Klick kein Bestätigungs-Dialog (6 s) und die Position steht noch — POSITION OFFEN, bitte von Hand.", "6-close")
        # Flach-Beweis: zwei Lesungen mit sichtbarer Tabelle ohne MNQ-Zeile
        n_flach, neu_c = 0, []
        ende = time.time() + 15
        while time.time() < ende:
            _warte(1.2, 0.4)
            st = s.stand(opts)
            ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
            neu_c = k3_neue_meldungen(vorher_c, (st.get("toasts") or {}).get("meldungen"))
            if ko.get("positionen_sichtbar") is True and not k3_zeilen(st.get("positionen"), root):
                n_flach += 1
                if n_flach >= 2:
                    break
            else:
                n_flach = 0
        if n_flach < 2:
            return raus("nicht_flach", "Flach NICHT bewiesen (MNQ-Zeile noch da oder Tabelle unsichtbar) — bitte in TradingView nachsehen.", "6-flach")
        res["flach"] = True
        c_fill, storno = k3_close_meldungen(neu_c, plan["richtung"], 1)
        res["close"] = {"fill_meldung": c_fill, "storniert": sorted(storno)}
        trail.append(f"[6] OK FLACH: 2 Lesungen ohne MNQ-Zeile (Tabelle sichtbar) · Close-Fill {k3_fmt(c_fill) if c_fill else 'nicht in den Meldungen'} · "
                     f"storniert: {', '.join(sorted(storno)).upper() or 'nicht gemeldet'}")
        # Offene Orders (Brackets) im Reiter „Orders" gegenlesen, dann zurück auf „Positions"
        orders_ok = None
        r_ord = s.rect_von("#id_account-manager-tabs #orders")
        if r_ord:
            s.klick(r_ord, "Reiter Orders")
            _warte(0.9, 0.3)
            st = s.stand(opts)
            ko = st.get("konto") if isinstance(st.get("konto"), dict) else {}
            offen = k3_offene_orders(st.get("orders"), root)
            sichtbar_n = len([o for o in st.get("orders") or [] if isinstance(o, dict) and o.get("sichtbar")])
            orders_ok = bool(ko.get("orders_sichtbar")) and not offen
            trail.append(f"[6] Reiter Orders: {sichtbar_n} sichtbare Zeilen, davon offen (Working) MNQ: {len(offen)}"
                         + ("" if ko.get("orders_sichtbar") else " — Tabelle nicht lesbar"))
            r_pos = s.rect_von("#id_account-manager-tabs #positions")
            if r_pos:
                s.klick(r_pos, "Reiter Positions")
                _warte(0.5, 0.2)
            if offen:
                return raus("order_offen", f"OFFENE ORDER nach dem Schließen ({[(o.get('typ'), o.get('preis'), o.get('status')) for o in offen][:3]}) "
                                           "— bitte von Hand stornieren, kein Login-Wechsel.", "6-orders")
        brackets_zu = ("tp" in storno and "sl" in storno) or orders_ok is True
        # [7] Account Summary nachher
        bal1, tpl1, _sm = _k3_summary(s, opts, trail, "7")
        res["nachher"] = {"balance": bal1, "total_pl": tpl1}
        d_bal = (bal1 - bal0) if bal1 is not None else None
        trail.append(f"[7] OK Summary nachher: Balance {k3_fmt(bal1)} (Δ {k3_fmt(d_bal)}) · Total P/L {k3_fmt(tpl1)}")
        if not anfang:
            return raus("", f"K3 fertig (ohne Login-Wechsel): Order + Close bewiesen, flach. Balance {k3_fmt(bal0)} → {k3_fmt(bal1)}.", "7-fertig")
        if not brackets_zu:
            return raus("brackets_unklar", "TP/SL-Storno weder gemeldet noch im Orders-Reiter bewiesen — kein Login-Wechsel. Orders-Reiter bitte ansehen.", "7-brackets")
        # [8]+[9] Login-Wechsel auf Tradeify (nur flach)
        trail.append("[8] Konto flach bewiesen, Brackets storniert — Login-Wechsel auf Tradeify")
        code, msg, schritt = _k3_login_wechsel(s, anfang, {"kontoTexte": []}, trail, res)
        if code:
            return raus(code, "Order + Close fertig und flach; Login-Wechsel: " + msg, schritt)
        return raus("", f"K3 komplett: Order + Close bewiesen, flach (Balance {k3_fmt(bal0)} → {k3_fmt(bal1)}); {msg}", schritt)
    except Exception as e:
        wo = ("NACH dem Senden-Klick — Stand UNKLAR, erst in TradingView nachsehen" if res.get("gesendet") and not res.get("flach")
              else "vor dem Senden — nichts gesendet" if not res.get("gesendet") else "nach dem Flach-Beweis")
        return raus("cdp_fehler", f"Puls-Chrome/CDP: {type(e).__name__}: {str(e)[:140]} ({wo})", res.get("schritt") or "cdp")


# ═══════════════════════════════════════════════════════════════════════════
# PULS ÜBER CDP — TRADOVATE SELBST VERBINDEN (29.09.2026, Finn: „wenn das neue Chrome-Tab geöffnet wird und man in keinem
# Tradovate-Konto drin ist bzw. im falschen, muss er das eigenständig erkennen" — dann wie beim alten Puls über TradingViews
# Connect-to-Tradovate-Seite, „Don't remember me", mit dem Tradovate-Login der Firma anmelden, zurück zu TradingView).
# Bis hierhin endete der CDP-Weg (tvlesen/tvkette) mit „kein_broker" bzw. „Konto 0x im Dropdown (anderer Tradovate-Login?)";
# der Hand-Befehl k3login fand nach dem Log out keine Tradovate-Kachel (29.09.2026 12:27 UTC) und ließ Tradovate abgemeldet stehen.
# Ablauf wie der alte UIA-Puls (modus_tvkonto, live 22.09.2026) — Auge = augen.js/Login-Blick, Hand = echte Windows-Maus:
#   [1] Konto lesen — steht es oder liegt es im Dropdown: fertig, kein Login (_cdp_konto_sichern, unverändert).
#   [2] kein Broker bzw. Konto 0× im Dropdown + tv_username der Firma → ist Tradovate verbunden, erst Log out (Kontextmenü neben
#       „Tradovate", K3-Weg, live 12:27 UTC).
#   [3] NEUER Tab mit ?trade-now=TRADOVATE, danach der alte TradingView-Tab zu (Finns Weg 22.09.2026: „Tab zu, neuer Tab mit dem
#       Link — dann kommt man JEDES MAL zu dem Connect"). Verbindet sich eine gemerkte Sitzung von selbst: zweiter Durchgang.
#   [4] Connect-Dialog: Demo (Pflicht — Prop-Konten leben auf Demo) → „Don't remember me" (Standard setzen; cmd.sitzung_merken =
#       Haken AUS, wie beim alten Puls) → Connect; „Network error occurred" → bis 3× erneut.
#   [5] Tradovate-Anmeldeseite (eigener Tab): ins Benutzerfeld klicken, in Chromes Vorschlagsliste (Windows-UIA) den Eintrag mit
#       genau diesem Username anklicken, Username EXAKT und Passwort gefüllt beweisen (Werte nie gelesen), dann Anmelden. Nie Enter
#       vor diesem Beweis (erster Live-Lauf .799: Enter schickte einen falschen Username ab).
#   [6] TradingView zeigt ein Konto → [1] wählt das Zielkonto im Dropdown.
# Nie: ein Passwort tippen, eine Freigabe („Allow") bestätigen, bei Mehrdeutigkeit raten. Das Puls-Chrome hat ein EIGENES Profil —
# jeder Tradovate-Login muss dort einmal von Hand gespeichert sein, sonst endet der Lauf mit genau diesem Hinweis.
# Diagnose: Spur in puls_diagnose (vor dem Connect-Klick und am Ende), volle Kopie lokal login_<zeit>.json.
# ═══════════════════════════════════════════════════════════════════════════
CDP_RX_DEMO = re.compile(r"^\s*demo\s*$", re.I)
CDP_RX_TV_SEITE = re.compile(r"https://([a-z]+\.)?tradingview\.com/")
CDP_RX_TRADOVATE_SEITE = re.compile(r"https://([a-z0-9-]+\.)*tradovate\.com/")
CDP_LOGIN_ZWEITER_BIS_S = 120.0       # zweiter Durchgang nur, wenn der erste früh genug fertig war (Panel-Deckel 260 s)


def cdp_login_noetig(code, extra):
    """REIN RECHNEND (testbar): Braucht es einen Tradovate-Login? Nur bei „kein Broker" oder wenn das Dropdown offen war und das
    Konto darin 0× stand (anderer Login). Mehrdeutig (≥ 2) oder Dropdown nicht erkannt = nein (ein Abmelden wäre geraten)."""
    if code == "kein_broker":
        return True
    return code == "konto_nicht_erreicht" and isinstance(extra, dict) and extra.get("konto_treffer") == 0


# KONTO WEG (05.10.2026, Finn: zwei Endlesungen geblowter FundedNext-Futures-Konten endeten als Login-Fehler „… auch nach dem
# Tradovate-Login. Gehört der Username wirklich zu dieser Firma?" — der Login stimmte, die Konten gab es bei Tradovate nicht mehr).
# Der Bot sieht nirgends, mit welchem Benutzer Tradovate verbunden ist. Sicher weiß er es nur, wenn er sich in DIESEM Lauf selbst über
# das Tradovate-Formular angemeldet hat (Username dort exakt bewiesen, _cdp_anmelden ohne Fehler — nicht bei „ohne Anmeldeseite
# verbunden" und nicht bei einer gemerkten Sitzung). Steht das Ziel danach zweimal hintereinander nicht im Login, endet der Lauf mit
# dem eigenen Code 'konto_weg' statt 'konto_nicht_erreicht'. Am selben Abend stand ein Konto sichtbar in der Liste und galt wegen
# einer Erkennungslücke (vier Endziffern) als „0×" — deshalb zählt zusätzlich nur, wenn das Ziel nirgends im sichtbaren Text der Seite
# stand (cdp_ziel_im_text_js, gelesen bei offener Liste).
def cdp_ziel_schluessel(ext):
    """REIN RECHNEND (testbar): die letzten 8 Zeichen der External ID (nur Buchstaben/Ziffern, groß) — damit wird das Ziel im
    sichtbaren Text gesucht. Unter 6 Zeichen '' (zu kurz für einen Beweis)."""
    u = _nur_alnum(str(ext or "")).upper()
    return u[-8:] if len(u) >= 6 else ""


def cdp_ziel_im_text_js(ext):
    """Steht das Ziel irgendwo im sichtbaren Text der Seite (ohne Trennzeichen verglichen)? Liest nur. -> JS-Ausdruck | ''"""
    k = cdp_ziel_schluessel(ext)
    if not k:
        return ""
    return ("(function(){var t=((document.body&&document.body.innerText)||'').replace(/[^A-Za-z0-9]/g,'').toUpperCase();"
            "return t.indexOf(" + json.dumps(k) + ")>=0;})()")


def _cdp_ziel_im_text(s, ext):
    """-> True (steht da) | False (steht nirgends) | None (nicht prüfbar — zählt nie als Beweis). Wirft nie."""
    js = cdp_ziel_im_text_js(ext)
    if not js:
        return None
    try:
        v = s.lese_js(js)
    except Exception:
        return None
    return v if isinstance(v, bool) else None


def cdp_konto_weg(extra, formular, ext):
    """REIN RECHNEND (testbar): Belegt der Konto-Schritt NACH dem eigenen Formular-Login, dass es das Ziel bei Tradovate nicht mehr
    gibt? -> (ja, konten_im_login, einzelkonto). Nur wenn alles gilt: formular (s. Block-Kopf) · Ziel 0× mit Beleg (konto_treffer 0 +
    liste_aktiv: selbst geöffnete Liste bzw. Login mit genau einem lesbaren anderen Konto) · das aktive Konto gehört zur selben Firma
    wie das Ziel (sonst stimmt der hinterlegte Username nicht — alte Meldung; damit zählt in der Listen-Variante auch nur die
    vollständige Liste, cdp_liste_beleg) · Ziel stand nirgends im sichtbaren Text (ziel_im_text genau False)."""
    nein = (False, None, False)
    if formular is not True or not isinstance(extra, dict) or extra.get("konto_treffer") != 0 or not extra.get("liste_aktiv"):
        return nein
    if extra.get("ziel_im_text") is not False:
        return nein
    fa, fz = cdp_konto_familie(cdp_kontonr(extra.get("liste_aktiv"))), cdp_konto_familie(ext)
    if not fa or fa != fz:
        return nein
    if extra.get("ein_konto") is True:
        return True, 1, True
    n = len([x for x in (extra.get("konto_eintraege") or []) if x])
    return (True, n, False) if n >= 1 else nein


def cdp_abmelden_erlaubt(aktiv, beleg):
    """REIN RECHNEND (testbar): Darf der Login-Weg die laufende Tradovate-Sitzung abmelden? -> (ja, grund)
    Regression .865 (30.09.2026, pc-cccccc, Plan …): der Login-Weg las den aktuellen Login als '-' und klickte „Log out" —
    eine richtige Sitzung war weg. Seitdem NUR mit Beleg: der Konto-Schritt hat die Liste selbst geöffnet, das Ziel stand darin 0×
    (beleg konto_treffer 0 + liste_aktiv), und das aktive Konto ist jetzt lesbar und dasselbe wie beim Beleg.
    grund: 'unlesbar' (nie abmelden, ehrlich abbrechen) | 'ohne_beleg' / 'anders' (nicht abmelden, Konto-Schritt neu) | ''"""
    a = _nur_alnum(aktiv).upper()
    if not a or not k3_nr_treffer(a):
        return False, "unlesbar"
    b = beleg if isinstance(beleg, dict) else {}
    if b.get("konto_treffer") != 0 or not b.get("liste_aktiv"):
        return False, "ohne_beleg"
    if _nur_alnum(b.get("liste_aktiv")).upper() != a:
        return False, "anders"
    return True, ""


def cdp_konto_verbunden(stand):
    """REIN RECHNEND (testbar): Zeigt TradingView ein Tradovate-Konto (Umschalter + Kontonummer)? -> Kontotext | ''"""
    ko = (stand or {}).get("konto") if isinstance(stand, dict) and isinstance(stand.get("konto"), dict) else {}
    aktiv = str(ko.get("aktiv") or "")
    return aktiv if cdp_rect(ko.get("schalter")) and k3_nr_treffer(re.sub(r"\s", "", aktiv).upper()) else ""


def cdp_panel_zu(stand):
    """REIN RECHNEND (testbar): Broker-Panel zugeklappt und der „Open panel"-Knopf greifbar? -> Knopf | None"""
    ko = (stand or {}).get("konto") if isinstance(stand, dict) and isinstance(stand.get("konto"), dict) else {}
    return ko.get("panel_knopf") if ko.get("panel") == "zu" and cdp_rect(ko.get("panel_knopf")) else None


def cdp_panel_frei_js(rect):
    """Liegt über der Mitte des „Open panel"-Knopfs wirklich der Knopf? Live 29.09.2026 23:04 UTC (pc-jjjjjj, erster Login im
    Puls-Chrome): dreimal „geklickt, Hover bewiesen", das Panel blieb zu — TradingViews Connect-Dialog stand während des Logins noch
    und seine Fläche lag über der Seite; :hover bewies nur die Fläche. Verdeckt heißt NUR: Dialog/Overlay (#overlap-manager-root,
    role=dialog, aria-modal) oder ein Element über ≥ 40 % des Bilds; Meldungen und alles Unklare gelten als frei (wie bisher). Liest nur.
    -> {frei, was}"""
    x, y = rect[0] + rect[2] / 2.0, rect[1] + rect[3] / 2.0
    return ("(function(){var e=document.elementFromPoint(" + f"{float(x):.1f},{float(y):.1f}" + ");if(!e)return {frei:true,was:''};"
            "if(e.closest('[data-name=\"toggle-visibility-button\"]'))return {frei:true,was:''};"
            "if(e.closest('[data-name^=\"toast-group-\"],[class*=\"toastGroup-\"],[class*=\"toastListInner-\"],[class*=\"toastItem\"]'))"
            "return {frei:true,was:'Meldung'};"
            "var r=e.getBoundingClientRect(),gross=r.width*r.height>=0.4*innerWidth*innerHeight;"
            "var d=e.closest('#overlap-manager-root,[role=\"dialog\"],[role=\"alertdialog\"],[aria-modal=\"true\"]');"
            "var c=(typeof e.className==='string'?e.className:'').split(' ')[0]||'';"
            "return {frei:!(d||gross),was:((e.getAttribute('data-name')||e.tagName.toLowerCase())+(c?'.'+c:'')).slice(0,50)};})()")


def _cdp_verbunden_lesen(s, opts, trail):
    """cdp_konto_verbunden — ist das Broker-Panel zugeklappt (Live 29.09.2026 16:25 UTC nach dem Login: nur „Tradovate ▾" +
    „Open panel", Umschalter unsichtbar → 40 s „kein Konto"), wird es aufgeklappt (höchstens 3× je Sitzung) und neu gelesen.
    Live 29.09.2026 23:04 UTC (pc-jjjjjj): alle 3 Klicks fielen in den Login (1,2 s nach Connect, 1–4 s nach „Anmelden") und trafen
    den noch offenen Connect-Dialog — als Tradovate verbunden war, war das Kontingent leer und der Lauf wartete 40 s auf „kein Konto".
    Seitdem: liegt ein Dialog über dem Knopf, wird NICHT geklickt (zählt nicht, der Aufrufer fragt ohnehin wieder), und nach dem Klick
    wird bewiesen, dass das Panel aufging. -> Kontotext | ''"""
    st = s.stand(opts)
    aktiv = cdp_konto_verbunden(st)
    if aktiv:
        return aktiv
    knopf = cdp_panel_zu(st)
    if not knopf or getattr(s, "_panel_klicks", 0) >= 3:
        return ""
    if hasattr(s, "werbung_weg"):
        s.werbung_weg()                                   # eine Werbung über dem Knopf zählt nicht als Dialog-Warten
    frei = s.lese_js(cdp_panel_frei_js(cdp_rect(knopf))) if hasattr(s, "lese_js") else None
    if isinstance(frei, dict) and not frei.get("frei"):
        if not getattr(s, "_panel_verdeckt_gemeldet", False):
            s._panel_verdeckt_gemeldet = True
            trail.append(f"„Open panel“ verdeckt ('{frei.get('was')}' liegt darüber, z. B. der Connect-Dialog im Login) — kein Klick, warte")
        return ""
    s._panel_klicks = getattr(s, "_panel_klicks", 0) + 1
    if not s.klick(cdp_rect(knopf), "Handelspanel auf (Open panel)"):
        return ""
    st2 = st
    for _ in range(5):                                    # ~3 s: Panel auf + Konto geladen?
        _warte(0.6, 0.3)
        st2 = s.stand(opts)
        aktiv = cdp_konto_verbunden(st2)
        if aktiv or not cdp_panel_zu(st2):
            break
    if not aktiv:
        trail.append("Handelspanel " + ("offen (bewiesen), Konto lädt noch" if not cdp_panel_zu(st2) else "bleibt nach dem Klick zu"))
    return aktiv


def cdp_abgemeldet(stand):
    """REIN RECHNEND (testbar): nach „Log out" — weder Umschalter noch Kontonummer zu sehen (Bedingung des K3-Laufs 12:27 UTC)."""
    ko = (stand or {}).get("konto") if isinstance(stand, dict) and isinstance(stand.get("konto"), dict) else {}
    return not ko.get("schalter") and not k3_nr_treffer(re.sub(r"\s", "", str(ko.get("aktiv") or "")).upper())


def cdp_innerste(items):
    """REIN RECHNEND (testbar): klickbare Elemente; Hülle + inneres zählen einmal (das innere gewinnt), gleiche Rechtecke einmal."""
    kand = [k for k in items or [] if isinstance(k, dict) and cdp_klickpunkt(k.get("rect")) is not None]
    kand = [k for k in kand if not any(j is not k and list(j["rect"]) != list(k["rect"]) and _k3_rect_in(j["rect"], k["rect"]) for j in kand)]
    einzeln = {}
    for k in kand:
        einzeln.setdefault(tuple(k["rect"]), k)
    return list(einzeln.values())


def cdp_connect_dialog(bl):
    """REIN RECHNEND (testbar): TradingViews Tradovate-Dialog (nach ?trade-now) im Login-Blick — GENAU EIN Dialog mit GENAU EINEM
    Knopf „Connect" (TV_RX_CONNECT, nie „Sign in" — das wäre TradingViews eigene Anmeldung), kein Login-Formular darin.
    -> {dialog, connect, demo: [...], nicht_merken, netzfehler} | None"""
    if not isinstance(bl, dict):
        return None
    lg = bl.get("login") if isinstance(bl.get("login"), dict) else {}
    kand = []
    for d in bl.get("dialoge") or []:
        if not isinstance(d, dict) or (lg.get("box") and d.get("rect") and _k3_rect_in(lg["box"], d["rect"])):
            continue
        if CDP_RX_SITZUNG_WEG.search(str(d.get("titel") or "") + " " + str(d.get("text") or "")):
            continue                                  # TradingViews „Session disconnected" hat auch „Connect" — kein Broker-Dialog
        c, _n = k3_eindeutig(d.get("knoepfe"), TV_RX_CONNECT)
        if c:
            kand.append((d, c))
    if len(kand) != 1:
        return None
    d, c = kand[0]
    box = d.get("rect")
    demo = cdp_innerste([x for x in list(d.get("knoepfe") or []) + list(bl.get("umgebung") or [])
                         if isinstance(x, dict) and CDP_RX_DEMO.match(str(x.get("text") or ""))
                         and (not box or _k3_rect_in(x.get("rect") or [], box))])
    nm = d.get("nicht_merken") if isinstance(d.get("nicht_merken"), dict) else None
    return {"dialog": d, "connect": c, "demo": demo, "nicht_merken": nm, "netzfehler": bool(d.get("netzfehler"))}


# TradingViews Modal (Finn-Screenshot 29.09.2026 15:48 UTC): „Session disconnected — Your session ended because your account was
# accessed from another browser or device … only one active session per user … simply click "Connect" to continue"
CDP_RX_SITZUNG_WEG = re.compile(r"session disconnected|only one active session|accessed from another (browser|device)|"
                                r"sitzung (wurde )?getrennt|nur eine aktive sitzung", re.I)


def cdp_sitzung_getrennt(bl):
    """REIN RECHNEND (testbar): steht TradingViews „Session disconnected"-Dialog mit GENAU EINEM „Connect"-Knopf da? -> Knopf | None"""
    kand = []
    for d in (bl or {}).get("dialoge") or [] if isinstance(bl, dict) else []:
        if isinstance(d, dict) and CDP_RX_SITZUNG_WEG.search(str(d.get("titel") or "") + " " + str(d.get("text") or "")):
            c, _n = k3_eindeutig(d.get("knoepfe"), TV_RX_CONNECT)
            if c:
                kand.append(c)
    return kand[0] if len(kand) == 1 else None


CDP_RX_CONNECT_FEHLER = re.compile(r"error!|cancel+ed\b|\bfailed\b|abgebrochen|fehlgeschlagen", re.I)


def cdp_connect_fehler(bl):
    """REIN RECHNEND (testbar): Fehlermeldung im Tradovate-Connect-Dialog (z. B. „Error! The login operation has been canceled",
    „Error! Network error occurred …") als kurzer Text, sonst ''."""
    d = cdp_connect_dialog(bl)
    t = " ".join(str(((d or {}).get("dialog") or {}).get("text") or "").split())
    m = CDP_RX_CONNECT_FEHLER.search(t)
    return t[max(0, m.start() - 20): m.start() + 100].strip() if m else ""


def cdp_nicht_merken_plan(nm, merken):
    """REIN RECHNEND (testbar): Was tun mit „Don't remember me"? merken = Sitzung soll gemerkt werden (cmd.sitzung_merken, wie beim
    alten Puls). -> ('klick'|'lassen'|'fehlt', text). Zustand unlesbar (nur Beschriftung): im frisch geöffneten Dialog ist der Haken
    AUS (alter Puls, 22.09.2026) — geklickt wird dann nur, wenn er gesetzt werden soll. Nie ein Abbruchgrund."""
    soll = not merken
    if not isinstance(nm, dict) or nm.get("mehrdeutig") or not cdp_rect(nm):
        return "fehlt", "'Don't remember me' nicht eindeutig gefunden — TradingView merkt sich diese Sitzung"
    an = nm.get("an")
    if an is None:
        return (("klick", "'Don't remember me' setzen (Zustand unlesbar, Standard AUS)") if soll
                else ("lassen", "Sitzung wird gemerkt (Haken bleibt AUS)"))
    if bool(an) == soll:
        return "lassen", f"'Don't remember me' steht schon {'AN' if an else 'AUS'}"
    return "klick", "'Don't remember me' " + ("setzen" if soll else "entfernen (Sitzung merken)")


def cdp_login_bereit(lb):
    """REIN RECHNEND (testbar): Steht im Tradovate-Formular EXAKT der Username (Anfang + gleiche Länge) und ist das Passwort gefüllt
    bzw. als Autofill markiert? Werte werden nie gelesen, nur diese Ja/Nein. -> (ok, text)"""
    lb = lb if isinstance(lb, dict) else {}
    u = lb.get("user") if isinstance(lb.get("user"), dict) else {}
    pw = lb.get("pw") if isinstance(lb.get("pw"), dict) else {}
    user_ok = bool(u.get("gefuellt") and u.get("passt") and u.get("laenge_gleich"))
    pw_ok = bool(pw.get("gefuellt") or pw.get("autofill"))
    return user_ok and pw_ok, (f"Benutzer {'= Username' if user_ok else ('gefüllt, aber NICHT der Username' if u.get('gefuellt') else 'LEER')}, "
                               f"Passwort {'gefüllt' if pw_ok else 'LEER'} (Werte nie gelesen)")


def cdp_tab_frisch(neu, time_origin_ms, klick_ms, spiel_ms=1500.0):
    """REIN RECHNEND (testbar): Gehört dieser Tradovate-Tab zu DIESEM Connect-Klick? Neu seit dem Klick, oder die Seite hat nach dem
    Klick geladen (performance.timeOrigin in ms seit 1970, etwas Spiel für die Uhr). Unlesbar = nur, wenn neu."""
    if neu:
        return True
    try:
        return float(time_origin_ms) >= float(klick_ms) - spiel_ms > 0
    except (TypeError, ValueError):
        return False


def cdp_tradovate_tabs(liste, ohne=()):
    """REIN RECHNEND (testbar): Seiten-Tabs auf tradovate.com, die nicht in 'ohne' stehen (IDs vor dem Connect-Klick)."""
    return [t for t in liste or [] if isinstance(t, dict) and t.get("type") == "page" and str(t.get("id")) not in ohne
            and CDP_RX_TRADOVATE_SEITE.match(str(t.get("url") or ""))]


def _cdp_tab_neu(url, trail):
    """Neuer Tab im Puls-Chrome (DevTools /json/new: ein Tab im bestehenden Fenster, nie ein neues Fenster). -> Target | None"""
    import urllib.parse
    t = _cdp_http("/json/new?" + urllib.parse.quote(url, safe=":/"), methode="PUT", timeout=5.0)
    if isinstance(t, dict) and t.get("webSocketDebuggerUrl"):
        trail.append(f"[Login] neuer Tab: {url[:90]}")
        return t
    trail.append(f"[Login] neuer Tab ließ sich nicht öffnen ({url[:60]})")
    return None


# Live-Befund Jacob 01.10.2026 12:38 UTC: nach dem Abmelden stand im neuen ?trade-now-Tab der Tradovate-Connect-Dialog längst
# da, der Bot wartete aber 30 s auf readyState „complete" und brach ab („neuer TradingView-Tab lädt nicht fertig"). TradingView
# kommt im Puls-Chrome oft nie über „interactive" hinaus (Moritz 01.10. 11:49–12:10 dasselbe auf dem Order-Weg). „interactive"
# heißt: Dokument geparst, wird nicht mehr ersetzt — steht es kurz stabil auf tradingview.com, reicht das (Finn: „Connect kann
# man da schon drücken, nicht insta, 1–2 s warten"). Bleibt der Tab ganz hängen, geht es nach CDP_TAB_WARTEN_S trotzdem weiter:
# _cdp_nach_link sucht den Dialog noch bis zu 40 s und klickt nur bei genau einem Dialog.
CDP_INTERAKTIV_REICHT_S = 1.5
CDP_TAB_WARTEN_S = 15.0


def cdp_seite_bereit(zustand, url, interaktiv_seit_s):
    """REIN RECHNEND (testbar): Ist der Tab bereit für augen.js? „complete" sofort, „interactive" erst nach
    CDP_INTERAKTIV_REICHT_S Sekunden auf derselben TradingView-Adresse, alles andere (loading, fremde Seite) nie."""
    if not CDP_RX_TV_SEITE.match(str(url or "")):
        return False
    if zustand == "complete":
        return True
    return zustand == "interactive" and interaktiv_seit_s is not None and interaktiv_seit_s >= CDP_INTERAKTIV_REICHT_S


def _cdp_seite_geladen(ziel, trail, warten_s=CDP_TAB_WARTEN_S):
    """Wartet, bis der Tab auf tradingview.com bereit steht (cdp_seite_bereit) — augen.js vorher zu laden hieße, es in eine Seite
    zu legen, die gleich ersetzt wird. -> True/False"""
    try:
        ws = _CdpVerbindung(ziel.get("webSocketDebuggerUrl"), timeout=8.0)
    except Exception as e:
        trail.append(f"[Login] Tab nicht erreichbar ({type(e).__name__})")
        return False
    try:
        start = time.time()
        ende = start + warten_s
        interaktiv = None                     # (url, seit) — „interactive" auf derselben Adresse
        zuletzt = ""
        while time.time() < ende:
            _warte(0.6, 0.3)
            try:
                r = ws.rufe("Runtime.evaluate", {"expression": "[document.readyState, String(location.href)]",
                                                 "returnByValue": True}, timeout=4)
            except Exception:
                continue
            v = (r.get("result") or {}).get("value")
            if not (isinstance(v, list) and len(v) == 2):
                continue
            zustand, url = str(v[0]), str(v[1])
            zuletzt = url
            if zustand == "interactive":
                if not interaktiv or interaktiv[0] != url:
                    interaktiv = (url, time.time())
            else:
                interaktiv = None
            seit = time.time() - interaktiv[1] if interaktiv else None
            if cdp_seite_bereit(zustand, url, seit):
                if zustand != "complete":
                    trail.append(f"[Login] Tab nach {time.time() - start:.0f} s 'interactive' (nicht 'complete') — reicht, weiter")
                return True
        if CDP_RX_TV_SEITE.match(zuletzt):
            trail.append(f"[Login] Tab nach {warten_s:.0f} s nicht fertig geladen — steht auf TradingView, weiter (Dialog-Suche entscheidet)")
            return True
        trail.append(f"[Login] Tab nach {warten_s:.0f} s nicht fertig geladen")
        return False
    finally:
        ws.zu()


def _cdp_sitzung_auf(ziel, trail, alt=None):
    """Augen-Sitzung auf genau diesem Tab, sobald er geladen ist; übernimmt das gemerkte Windows-Fenster der alten Sitzung (zu()
    minimiert es am Ende des Laufs wieder — Reader-Chrome frei)."""
    if not _cdp_seite_geladen(ziel, trail):
        raise RuntimeError("neuer TradingView-Tab lädt nicht fertig")
    _warte(1.5, 1.0)                          # TradingView baut Leiste, Panel und Dialog erst nach dem Laden
    s = _AugenSitzung(trail, ziel=ziel)
    if alt is not None and getattr(alt, "_win_hwnd", None):
        s._win_hwnd = alt._win_hwnd
    return s


def _cdp_tab_zu(s, trail):
    """Tab der Sitzung s schließen. Fragt die Seite „Seite verlassen?", wird das bestätigt (Browser-Dialog, kein Seiten-Klick).
    -> True, wenn weg"""
    tid, weg = s.target_id, False
    if tid:
        try:
            s.ws.rufe("Page.enable", {}, timeout=3)
        except Exception:
            pass
        _cdp_http(f"/json/close/{tid}")
        ende = time.time() + 6.0
        while time.time() < ende:
            _warte(0.5, 0.2)
            liste = _cdp_http("/json/list")
            if isinstance(liste, list) and not any(isinstance(t, dict) and t.get("id") == tid for t in liste):
                weg = True
                break
            try:
                s.ws.rufe("Page.handleJavaScriptDialog", {"accept": True}, timeout=2)
                trail.append("[Login] 'Seite verlassen?' bestätigt")
            except Exception:
                pass
    try:
        s.ws.zu()
    except Exception:
        pass
    trail.append("[Login] alter TradingView-Tab " + ("geschlossen" if weg else "ging nicht zu — bleibt offen"))
    return weg


def _cdp_tab_mit_link(sitz, url, trail):
    """[3] Finns Weg (22.09.2026): neuer Tab mit ?trade-now=TRADOVATE, dann der alte TradingView-Tab zu. sitz[0] = neue Sitzung.
    Erst der neue, dann der alte — das Fenster geht so nie zu."""
    alt = sitz[0]
    neu = _cdp_tab_neu(url, trail)
    if not neu:
        raise RuntimeError("neuer TradingView-Tab ließ sich nicht öffnen")
    sitz[0] = _cdp_sitzung_auf(neu, trail, alt=alt)
    if alt is not None and alt.target_id and alt.target_id != neu.get("id"):
        _cdp_tab_zu(alt, trail)


def _cdp_sitzung_holen(cmd, trail):
    """Augen-Sitzung für tvlesen/tvkette. Ist im Puls-Chrome gar keine TradingView-Seite offen (Tab zu, frischer Start), wird eine
    geöffnet — mit tv_username gleich mit ?trade-now, dann steht der Connect-Dialog sofort da."""
    if not _puls_chrome_sicher(trail):
        raise RuntimeError("Puls-Chrome nicht erreichbar (Port 9333)")
    ende = time.time() + 5.0
    while not augen_target_waehlen(_cdp_http("/json/list")):
        if time.time() >= ende:
            benutzer = str((cmd or {}).get("tv_username") or "").strip()
            url = tv_trade_now_url((cmd or {}).get("tv_url")) if benutzer else tv_start_url((cmd or {}).get("tv_url"))
            trail.append("[Login] keine TradingView-Seite im Puls-Chrome — neuer Tab")
            neu = _cdp_tab_neu(url, trail)
            if not neu:
                raise RuntimeError("im Puls-Chrome ist keine TradingView-Seite offen, ein neuer Tab ließ sich nicht öffnen")
            return _cdp_sitzung_auf(neu, trail)
        _warte(0.8, 0.4)                      # gerade gestartetes Puls-Chrome: die Chart-Seite taucht erst nach dem Laden auf
    return _AugenSitzung(trail)


def _cdp_abmelden(s, opts, trail):
    """[2] Log out über das Kontextmenü neben „Tradovate" (K3-Weg, live 29.09.2026 12:27 UTC: „Log out ok"). -> (ok, text)"""
    ort = _K3Ort("TradingView-Seite", s.ws, s, "")
    b = ort.blick()
    if not cdp_rect(b.get("ctx")):
        return False, f"Kontextmenü-Knopf neben 'Tradovate' nicht eindeutig ({b.get('ctx')}) — nicht abgemeldet."
    if not s.klick(cdp_rect(b.get("ctx")), "Kontextmenü neben Tradovate"):
        return False, "Kontextmenü neben 'Tradovate' ließ sich nicht klicken — nicht abgemeldet."
    _warte(0.8, 0.3)
    b = ort.blick()
    trail.append(f"[Login] Kontextmenü: {[k3_label(m) for m in b.get('menue') or []][:8]}")
    e, n = k3_eindeutig(b.get("menue"), K3_RX_ABMELDEN)
    if not e:
        s.taste("Escape")
        return False, f"Im Kontextmenü kein eindeutiges 'Log out' ({n} Treffer) — Menü mit Esc zu, nicht abgemeldet."
    s.klick(cdp_rect(e), f"Menü '{k3_label(e)}'")
    ja, ende = False, time.time() + 14
    while time.time() < ende:
        _warte(0.9, 0.3)
        if cdp_abgemeldet(s.stand(opts)):
            trail.append("[Login] Tradovate abgemeldet")
            return True, ""
        if not ja:
            for d in ort.blick().get("dialoge") or []:
                j, _nj = k3_eindeutig(d.get("knoepfe"), K3_RX_JA)
                if j:
                    trail.append(f"[Login] Rückfrage '{str(d.get('titel') or d.get('text') or '')[:60]}'")
                    s.klick(cdp_rect(j), f"Rückfrage '{k3_label(j)}'")
                    ja = True
                    break
    return False, "Nach 'Log out' zeigt TradingView weiter ein Konto (14 s) — nicht abgemeldet."


def _cdp_nach_link(s, opts, trail, warten_s=40.0):
    """Nach dem Öffnen mit ?trade-now: Was zeigt TradingView? -> ('dialog', blick) | ('verbunden', kontotext) | ('nichts', blick)"""
    ort = _K3Ort("TradingView-Seite", s.ws, s, "")
    ende = time.time() + warten_s
    while True:
        bl = ort.blick()
        if cdp_connect_dialog(bl):
            return "dialog", bl
        aktiv = _cdp_verbunden_lesen(s, opts, trail)
        if aktiv:
            return "verbunden", aktiv
        if time.time() >= ende:
            return "nichts", bl
        _warte(0.7, 0.4)


def _cdp_dialog_verbinden(s, merken, trail):
    """[4] Connect-Dialog: Demo (Pflicht) → „Don't remember me" → Connect. -> (code, text, Tab-IDs vor dem Connect-Klick)"""
    ort = _K3Ort("TradingView-Seite", s.ws, s, "")
    # 06.10.2026 (Endlesung 23:16 Dubai: „Connect: Maus steht @…, Ziel NICHT unter dem Zeiger — kein Druck"): der Dialog steht in einem
    # FRISCH geladenen Tab (?trade-now) — die Werbe-Kachel unten links wurde bis hier nur im alten Tab vor dem Abmelden geschlossen
    _cdp_kachel_weg(s, trail)
    d = cdp_connect_dialog(ort.blick())
    if not d:
        return "dialog", "Connect-Dialog nicht (mehr) eindeutig zu sehen.", None
    dl = d["dialog"]
    trail.append(f"[Login] Connect-Dialog '{str(dl.get('titel') or '')[:40]}': {[k3_label(k) for k in dl.get('knoepfe') or []][:10]}")
    if len(d["demo"]) != 1:
        return "demo", (f"Demo-Schalter im Tradovate-Dialog nicht eindeutig ({len(d['demo'])}) — Prop-Konten leben auf Demo, ohne ihn "
                        "wird nicht verbunden."), None
    if d["demo"][0].get("an"):
        trail.append("[Login] Demo ist schon gewählt")
    else:
        if not s.klick(cdp_rect(d["demo"][0]), "Demo"):
            return "demo", "Demo ließ sich nicht klicken (Maus nicht bewiesen über dem Schalter) — nicht verbunden.", None
        _warte(0.5, 0.3)
        d = cdp_connect_dialog(ort.blick()) or d
    plan, txt = cdp_nicht_merken_plan(d.get("nicht_merken"), merken)
    if plan == "klick":
        vorher_an = d["nicht_merken"].get("an")
        s.klick(cdp_rect(d["nicht_merken"]), "Don't remember me")
        _warte(0.4, 0.3)
        d = cdp_connect_dialog(ort.blick()) or d
        an2 = (d.get("nicht_merken") or {}).get("an")
        if vorher_an is None and an2 is False and not merken:
            # vorher unlesbar, jetzt lesbar AUS: der Klick hat einen gesetzten Haken entfernt → einmal zurück (alter Puls, 22.09.2026)
            s.klick(cdp_rect(d.get("nicht_merken")), "Don't remember me (zurück)")
            _warte(0.4, 0.3)
            d = cdp_connect_dialog(ort.blick()) or d
            an2 = (d.get("nicht_merken") or {}).get("an")
        trail.append(f"[Login] {txt} → jetzt {'AN' if an2 else ('AUS' if an2 is False else 'unlesbar')}")
    else:
        trail.append(f"[Login] {txt}")
    ids = {str(t.get("id")) for t in _cdp_http("/json/list") or [] if isinstance(t, dict)}
    _puls_diagnose_senden(spur=trail, schritt="cdp-connect")     # Spur liegt im Backend, bevor sich die Anmeldeseite öffnet
    vorher = {"ids": ids, "ms": time.time() * 1000.0,           # Klick-Zeit: auch ein wiederverwendeter Tab lädt danach neu
              "fehler": cdp_connect_fehler(ort.blick())}        # Fehlermeldung, die schon VOR dem Klick dastand, zählt nicht als neu
    if not s.klick(cdp_rect(d["connect"]), "Connect"):
        # 06.10.2026: ein gescheiterter klick() hat nie gedrückt (kein Hover-Beweis = kein Druck). EINMAL neu: Werbe-Kachel weg, Dialog
        # neu lesen (die Seite kann sich nach dem Laden noch verschoben haben), Demo muss weiter AN sein, derselbe Klick mit frischem
        # Rechteck. Scheitert auch der, steht in der Spur, was am Punkt liegt (Befund für den nächsten Fall — bisher nur „NICHT unter dem Zeiger").
        _cdp_kachel_weg(s, trail)
        _warte(0.8, 0.5)
        d2 = cdp_connect_dialog(ort.blick())
        r2 = cdp_rect((d2 or {}).get("connect"))
        demo_an = bool(d2 and len(d2["demo"]) == 1 and d2["demo"][0].get("an") is True)
        if not (r2 and demo_an):
            return "connect", ("Connect ließ sich nicht klicken (Maus nicht bewiesen über dem Knopf) — nicht verbunden"
                               + ("; danach Connect-Dialog oder Demo nicht mehr eindeutig, kein zweiter Versuch" if not (r2 and demo_an) else "") + "."), None
        trail.append("[Login] Connect nicht gedrückt — Dialog neu gelesen, Demo an: ein zweiter Versuch")
        vorher["ms"] = time.time() * 1000.0
        if not s.klick(r2, "Connect (2. Versuch)"):
            was = ""
            try:
                v = s.lese_js(cdp_panel_frei_js(r2))
                was = str(v.get("was") or "")[:50] if isinstance(v, dict) else ""
            except Exception:
                was = ""
            if was:
                trail.append(f"[Login] am Connect-Punkt liegt: '{was}'")
            return "connect", ("Connect ließ sich zweimal nicht klicken (Maus nicht bewiesen über dem Knopf"
                               + (f"; am Punkt liegt '{was}'" if was else "") + ") — nicht verbunden."), None
    return "", "", vorher


def _cdp_login_ort(s, vorher, benutzer, opts, trail, warten_s=25.0):
    """[5] Wo steht das Tradovate-Formular — eigener Tab (neu seit dem Connect-Klick) oder in der TradingView-Seite? Verbindet sich
    TradingView ohne Formular (Tradovate noch angemeldet), ist der Schritt erledigt. „Network error occurred" → Connect erneut
    (höchstens TV_CONNECT_NETZ_MAX×, wie beim alten Puls). -> (ort | 'verbunden' | None, text)
    vorher = {ids, ms}: ein Tradovate-Tab zählt, wenn er NEU ist oder seit dem Connect-Klick neu geladen hat (performance.timeOrigin) —
    der Tab eines gescheiterten Laufs bleibt offen (erster Live-Lauf .799), und TradingView öffnet die Anmeldung womöglich darin neu."""
    vorher = vorher if isinstance(vorher, dict) else {}
    ids, klick_ms, fehler_alt = vorher.get("ids") or set(), float(vorher.get("ms") or 0.0), vorher.get("fehler") or ""
    ort_tv = _K3Ort("TradingView-Seite", s.ws, s, benutzer)
    ende, netz_n, nochmal_n, werbung_seit = time.time() + warten_s, 0, 0, False
    while time.time() < ende:
        _warte(0.8, 0.3)
        if s.werbung_weg():                               # Autumn-Sale über dem Dialog (30.09.2026, PC von ID C)
            werbung_seit = True
        b = ort_tv.blick()
        if b.get("login"):
            return ort_tv, ""
        for t in cdp_tradovate_tabs(_cdp_http("/json/list")):
            try:
                ws2 = _CdpVerbindung(t.get("webSocketDebuggerUrl"), timeout=8.0)
            except Exception as e_:
                trail.append(f"[Login] Tradovate-Tab nicht erreichbar ({type(e_).__name__})")
                continue
            o2 = _K3Ort("Tradovate-Tab", ws2, _k3_eingabe(ws2, trail), benutzer, eigen=True)
            if not cdp_tab_frisch(str(t.get("id")) not in ids, o2.eingabe.lese_js("performance.timeOrigin", timeout=4), klick_ms):
                o2.zu()                               # alter Tab (z. B. vom gescheiterten Lauf), seit dem Klick nicht neu geladen
                continue
            if o2.blick().get("login"):
                o2.target_id = t.get("id")
                trail.append(f"[Login] Tradovate-Anmeldeseite offen ({str(t.get('url') or '')[:60]})")
                return o2, ""
            o2.zu()
        aktiv = _cdp_verbunden_lesen(s, opts, trail)
        if aktiv:
            trail.append(f"[Login] ohne Anmeldeseite verbunden ('{aktiv[:40]}') — Tradovate war noch angemeldet")
            return "verbunden", ""
        d = cdp_connect_dialog(b)
        f_neu = cdp_connect_fehler(b)
        if f_neu and f_neu != fehler_alt and not (d and d["netzfehler"]):
            return "abgebrochen", f_neu
        if d and d["netzfehler"]:
            netz_n += 1
            trail.append(f"[Login] 'Network error occurred' im Connect-Dialog ({netz_n}. Mal)")
            if netz_n > TV_CONNECT_NETZ_MAX:
                return None, f"Tradovate meldet nach {TV_CONNECT_NETZ_MAX}× Connect weiter 'Network error occurred' — Internet/Tradovate am PC prüfen."
            _warte(1.0, 1.0)
            klick_ms = time.time() * 1000.0
            s.klick(cdp_rect(d["connect"]), f"Connect (erneut {netz_n}/{TV_CONNECT_NETZ_MAX})")
            _warte(2.0, 0.8)                  # der alte Fehlertext steht nach dem Klick noch kurz da
            ende = time.time() + warten_s
            continue
        # Connect-Dialog steht noch, ohne Fehler und ohne Anmeldeseite (30.09.2026, PC von ID C: die Werbung verschluckte den Klick) —
        # nach geschlossener Werbung sofort, sonst nach 8 s ohne Wirkung: Connect genau noch einmal (höchstens 2×)
        seit_s = time.time() - (klick_ms / 1000.0 if klick_ms else 0.0)
        if d and cdp_rect(d.get("connect")) and nochmal_n < 2 and (werbung_seit or seit_s > 8.0):
            nochmal_n += 1
            trail.append(f"[Login] Connect-Dialog steht noch ({'Werbung lag darüber' if werbung_seit else f'{seit_s:.0f} s ohne Wirkung'}) — Connect erneut ({nochmal_n}/2)")
            werbung_seit = False
            klick_ms = time.time() * 1000.0
            s.klick(cdp_rect(d["connect"]), f"Connect (nochmal {nochmal_n}/2)")
            _warte(1.5, 0.6)
            ende = max(ende, time.time() + warten_s / 2)
    return None, f"Nach 'Connect' keine Tradovate-Anmeldeseite ({warten_s:.0f} s)."


CDP_AUTOFILL_TYPEN = ("ListItem", "MenuItem", "Button", "DataItem", "Text", "Group", "Custom", "Hyperlink")


def cdp_liste_kurz(roh, max_n=30, max_zeichen=700):
    """REIN RECHNEND (testbar): Inhalt der Vorschlagsliste für die Spur — Typ:Name, ohne reine Punkt-/Sternzeilen (maskierte
    Passwörter), doppelte einmal."""
    out, gesehen = [], set()
    for e in roh or []:
        try:
            n, typ = " ".join(str(e[0]).split()), str(e[2] if len(e) > 2 else "")
        except (TypeError, IndexError):
            continue
        if not n or re.fullmatch(r"[•●*·\s]+", n) or (typ, n) in gesehen:
            continue
        gesehen.add((typ, n))
        out.append(f"{typ}:{n[:40]}")
        if len(out) >= max_n:
            break
    return (" | ".join(out) or "leer")[:max_zeichen]


def _cdp_autofill_klick(eingabe, benutzer, feld_rect, trail, diag=False):
    """Chromes Vorschlagsliste (eigenes kleines Fenster des Puls-Chrome-Prozesses, für CDP unsichtbar) per Windows-UIA lesen und den
    Eintrag mit GENAU diesem Username als ganzem Wort (tv_konto_wort_passt, wie der alte Puls — „APEX_000000TDFYU000000000" zählt
    nicht) mit der echten Maus anklicken. Das Benutzerfeld selbst ist ausgenommen. -> True/False"""
    if not _WIN_EINGABE:
        trail.append("[Login] Vorschlagsliste nur unter Windows lesbar")
        return False
    from pywinauto import Desktop
    ohne = None
    try:
        g, kl = eingabe.lese_js(WIN_GEO_JS) or {}, _klient_rechteck(getattr(eingabe, "_win_hwnd", None))
        x, y, w, h = [float(v) for v in feld_rect[:4]]
        a, _g1 = tv_bildschirm_punkt([x, y, 1.0, 1.0], g, kl)
        b, _g2 = tv_bildschirm_punkt([x + w - 1.0, y + h - 1.0, 1.0, 1.0], g, kl)
        if a and b:
            ohne = (int(a[0]), int(a[1]), int(b[0]), int(b[1]))
    except Exception:
        ohne = None

    class _Nadel:                       # Vorfilter mit derselben Schnittstelle wie ein Regex
        @staticmethod
        def search(name):
            return tv_konto_wort_passt(name, benutzer)
    # Live 29.09.2026 15:11 UTC (Tradeify-Wechsel): „TDFYU000000000 · tradovate.com" (für die Domain gespeichert, nicht für
    # trader.tradovate.com) wurde mit den fünf alten Typen 3× nicht gefunden, „Passwort für APEX_000000" schon — deshalb mehr Typen,
    # und beim ersten Fehlversuch steht der Inhalt der Liste (Typ:Name, ohne maskierte Passwörter) in der Spur.
    roh, popup_roh = [], []
    for f in _puls_fenster_liste(_puls_chrome_browser_pid()):
        try:
            w_ = Desktop(backend="uia").window(handle=int(f["hwnd"])).wrapper_object()
            alle_ = _tv_uia_roh(w_, CDP_AUTOFILL_TYPEN, 600, muster=(_Nadel,))
            roh += [x_ for x_ in alle_ if x_[1]]
            if diag and not str(f.get("text") or "").strip():      # kleines Popup-Fenster ohne Titel = Chromes Vorschlagsliste
                popup_roh += alle_
        except Exception:
            continue
    kand = tv_uia_namen_filtern(roh, _Nadel, typ_vorrang=None, ohne=ohne)
    if len(kand) != 1:
        trail.append(f"[Login] Vorschlag '{benutzer}' in Chromes Liste {len(kand)}× gesehen"
                     + (f": {[k['text'][:30] for k in kand][:4]}" if kand else ""))
        if diag:
            trail.append(f"[Login] Vorschlagsliste enthält: {cdp_liste_kurz(popup_roh)}")
        return False
    x_, y_ = kand[0]["punkt"]
    _maus_fahren(x_, y_)
    _warte(0.12, 0.1)
    if not _klick_absolut(x_, y_):
        trail.append("[Login] Klick auf den Vorschlag von Windows abgelehnt")
        return False
    trail.append(f"[Login] Vorschlag '{kand[0]['text'][:40]}' geklickt @{x_},{y_} (Windows-Maus)")
    return True


def cdp_rect_gleich(a, b, tol=1.0):
    """REIN RECHNEND (testbar): zwei Rechtecke [x, y, w, h] am selben Ort (±tol px)?"""
    try:
        return all(abs(float(x) - float(y)) <= tol for x, y in zip(list(a)[:4], list(b)[:4])) and len(a) >= 4 and len(b) >= 4
    except (TypeError, ValueError):
        return False


def _cdp_formular_ruhig(ort, trail, max_s=3.0, grundruhe=True):
    """Tradovate schiebt das Anmeldeformular beim Laden von links herein (Live 29.09.2026 16:33 UTC: „Benutzerfeld geklickt, Hover
    bewiesen", der Druck traf daneben, das Formular flog noch). Erst ~1 s Grundruhe, dann warten, bis das Benutzerfeld zwei Blicke
    (~0,3 s) lang am selben Ort steht, höchstens max_s. -> True = ruhig"""
    if grundruhe:
        _warte(1.0, 0.4)
    t0, vorher = time.time(), None
    while time.time() - t0 < max_s:
        r = cdp_rect((ort.blick().get("login") or {}).get("user"))
        if r and vorher and cdp_rect_gleich(r, vorher):
            return True
        vorher = r
        _warte(0.3, 0.1)
    trail.append(f"[Login] Formular nach {max_s:.0f} s noch in Bewegung — weiter")
    return False


def cdp_verbindung_weg_urteil(chrome_lebt, tv_tabs, target_id=None):
    """REIN RECHNEND (testbar): Nach „Anmelden" ist die Verbindung zum TradingView-Tab abgerissen — was nun? -> ('neu_anhaengen', tab) |
    ('chrome_weg', None) (Port 9333 antwortet nicht) | ('tab_weg', None). Neu angehängt wird NUR an DENSELBEN Tab (target_id der
    Sitzung) — nie an einen anderen TradingView-Tab (Prüfer 30.09.2026: alter ?trade-now-Tab, zweiter TV-Tab; alle Folgeschritte liefen
    sonst im falschen Tab). Ohne bekannte target_id gilt genau EIN TradingView-Tab als derselbe."""
    if not chrome_lebt:
        return "chrome_weg", None
    tabs = [t for t in (tv_tabs or []) if isinstance(t, dict) and t.get("webSocketDebuggerUrl")]
    if target_id:
        tabs = [t for t in tabs if t.get("id") == target_id]
    elif len(tabs) != 1:
        tabs = []
    return ("neu_anhaengen", tabs[0]) if tabs else ("tab_weg", None)


def _cdp_anmelden(s, ort, benutzer, opts, trail, vorher=None, sitz=None):
    """[5] Username + gespeichertes Passwort (Chrome) beweisen, Login, warten bis TradingView ein Konto zeigt. -> (code, text)
    sitz = [Sitzung] des Aufrufers: reißt die Verbindung zum TradingView-Tab nach „Anmelden" ab, hängt sich der Lauf EINMAL neu an
    (sitz[0] wird ersetzt) bzw. meldet ehrlich, ob das Puls-Chrome noch lebt."""
    _cdp_formular_ruhig(ort, trail)
    lb = ort.blick().get("login") or {}
    u = lb.get("user") or {}
    trail.append(f"[Login] Formular ({ort.name}): Benutzerfeld {'gefüllt' if u.get('gefuellt') else 'leer'}, Passwort "
                 f"{'gefüllt' if (lb.get('pw') or {}).get('gefuellt') else 'leer'}, Remember me "
                 f"{'-' if lb.get('merken') is None else ('AN' if lb['merken'].get('an') else 'AUS')} (Werte nie gelesen)")
    ok_b, txt_b = cdp_login_bereit(lb)
    if ok_b:
        trail.append(f"[Login] schon ausgefüllt: {txt_b}")
    else:
        # FINNS HANDWEG (29.09.2026, Screenshot nach dem ersten Live-Lauf .799): ins Benutzerfeld klicken → Chrome zeigt die
        # gespeicherten Logins → den passenden anklicken → Passwort kommt mit → Anmelden. NIE Enter im Formular: im ersten Lauf
        # hatte Chrome „APEX_000000" vorbelegt (für die Seite vor dem ersten Klick unsichtbar), der Username wurde angehängt, die
        # Autofill-Markierung des Passworts galt als Vorschau, und Enter schickte „APEX_000000TDFYU000000000" ab → „Incorrect
        # username or password" (ein Fehlversuch bei Tradovate). Die Liste ist ein eigenes Browser-Fenster → Windows-UIA wie beim
        # alten Puls; geklickt wird nur ein Eintrag mit genau diesem Username als ganzem Wort.
        if not cdp_rect(u):
            return "login_feld", "Benutzerfeld vor dem Passwortfeld nicht gefunden — nichts eingegeben."
        # Klick ins Benutzerfeld mit Fokus-Beweis; kam er nicht an (Formular bewegte sich noch), Rechteck neu lesen und bis zu 2× neu
        feld_ok = False
        for k_versuch in range(3):
            if ort.eingabe.klick(cdp_rect(u), "Benutzerfeld") and ort.eingabe.fokus_im(cdp_rect(u), "Benutzerfeld"):
                feld_ok = True
                break
            if k_versuch < 2:
                _warte(0.4, 0.2)
                _cdp_formular_ruhig(ort, trail, max_s=2.0, grundruhe=False)
                u = (ort.blick().get("login") or {}).get("user") or u
                trail.append(f"[Login] Benutzerfeld: Klick kam nicht an — Rechteck neu gelesen {cdp_rect(u)}, {k_versuch + 2}. Versuch")
        if not feld_ok:
            return "login_feld", "Klick ins Benutzerfeld kam dreimal nicht an (kein Fokus) — nichts eingegeben."
        gewaehlt = False
        for versuch in (1, 2, 3):
            if versuch == 1:
                pass                                   # Feld hat den Fokus — Chrome zeigt die Liste jetzt
            elif not ort.eingabe.fokus_im(cdp_rect(u), "Benutzerfeld"):
                # vor Strg+A/Backspace/Tippen: ohne bewiesenen Fokus gingen die Tasten womöglich woanders hin
                return "login_feld", "Benutzerfeld hat keinen Fokus (Klick nicht angekommen?) — nichts eingegeben."
            elif versuch == 2:
                # Vorschlag nicht in der Liste (vorbelegtes Feld filtert sie): Feld leeren — leer zeigt Chrome alle Logins;
                # Pfeil runter öffnet die Liste nur (markiert, schickt nie ab)
                ort.eingabe.taste("a", modifiers=2)
                ort.eingabe.taste("Backspace")
                _warte(0.4, 0.2)
                ort.eingabe.taste("ArrowDown")
                trail.append("[Login] Benutzerfeld geleert, Liste neu geöffnet")
            else:
                ort.eingabe.tippen(benutzer)       # letzter Versuch: die Liste auf genau diesen Login filtern (kein Enter)
                trail.append(f"[Login] '{benutzer}' getippt, um die Liste zu filtern")
            _warte(0.8, 0.4)
            if _cdp_autofill_klick(ort.eingabe, benutzer, cdp_rect(u), trail, diag=(versuch == 1)):
                gewaehlt = True
                break
        if not gewaehlt:
            if ort.eigen:
                ort.eingabe.taste("Escape")          # nur im eigenen Tradovate-Tab — in TradingView schlösse Esc den Dialog
            return "autofill", (f"Chrome zeigt keinen gespeicherten Login '{benutzer}' in der Vorschlagsliste — ist er im Puls-Chrome "
                                "(eigenes Profil) gespeichert? Nichts abgeschickt.")
        _warte(0.8, 0.4)
        lb = ort.blick().get("login") or {}
        ok_b, txt_b = cdp_login_bereit(lb)
        trail.append(f"[Login] nach dem Vorschlag: {txt_b}")
        if not ok_b:
            return "autofill", f"Nach dem Klick auf den Vorschlag nicht bewiesen ({txt_b}) — Anmelden NICHT geklickt."
    k, nk = k3_eindeutig(lb.get("knoepfe"), K3_RX_CONNECT)
    if not k:
        return "login_knopf", f"Kein eindeutiger Login-Knopf ({nk}; Knöpfe {[k3_label(x) for x in lb.get('knoepfe') or []][:8]}) — nicht angemeldet."
    geklickt_login = False
    for k_versuch in range(3):
        if ort.eingabe.klick(cdp_rect(k), f"'{k3_label(k)}' (Login)"):
            geklickt_login = True
            break
        if k_versuch < 2:                              # nicht gedrückt (Hover/Fenster) → Formular ruhig, Knopf neu lesen, erneut
            _cdp_formular_ruhig(ort, trail, max_s=2.0, grundruhe=False)
            k2, _n2 = k3_eindeutig((ort.blick().get("login") or {}).get("knoepfe"), K3_RX_CONNECT)
            k = k2 or k
    if not geklickt_login:
        return "login_knopf", "Login-Knopf ließ sich dreimal nicht klicken (Maus nicht bewiesen über dem Knopf) — nicht angemeldet."
    t0, enter, neu_dran, zeit_gemeldet = time.time(), False, False, False
    while time.time() - t0 < 40.0:
        _warte(1.0, 0.4)
        try:
            aktiv = _cdp_verbunden_lesen(s, opts, trail)
        except (OSError, RuntimeError) as e_:
            # Live 30.09.2026 03:23 UTC (ein Orbit-PC, 6 Versuche in Folge): ~1 s nach „Anmelden" ConnectionAbortedError (WinError
            # 10053) → roher 'cdp_fehler', 9 s später startete der Augen-Prozess ein FRISCHES Puls-Chrome (Start-Adresse, about:blank) —
            # das Puls-Chrome hatte sich beim Login beendet. Ursache offen; seitdem steht in der Spur, ob Chrome noch lebt und welche
            # Tabs da sind, und der Lauf hängt sich EINMAL neu an DENSELBEN TradingView-Tab (der Login kann trotzdem gelungen sein).
            import socket as _so
            if isinstance(e_, (TimeoutError, _so.timeout)):
                # langsamer Tab ≠ Verbindung weg (Prüfer): nur vermerken und weiter warten — die 40-s-Grenze bleibt
                if not zeit_gemeldet:
                    zeit_gemeldet = True
                    trail.append("[Login] TradingView-Tab antwortet gerade nicht (Zeitüberschreitung) — warte weiter")
                continue
            lebt = bool(_cdp_http("/json/version", timeout=1.5))
            liste = _cdp_http("/json/list", timeout=1.5) or []
            tabs = [str(t.get("url"))[:50] for t in liste if isinstance(t, dict) and t.get("type") == "page"][:6]
            urteil, tab = cdp_verbindung_weg_urteil(lebt, augen_tv_targets(liste), getattr(s, "target_id", None))
            trail.append(f"[Login] Verbindung zum TradingView-Tab weg ({type(e_).__name__}: {str(e_)[:60]}) — Puls-Chrome "
                         f"{'läuft' if lebt else 'ANTWORTET NICHT (beendet)'}, Tabs {tabs} → {urteil}")
            if urteil == "neu_anhaengen" and sitz is not None and not neu_dran:
                neu_dran = True
                try:
                    alt_s = s
                    s = sitz[0] = _AugenSitzung(trail, ziel=tab)
                    if getattr(alt_s, "_win_hwnd", None):
                        s._win_hwnd = alt_s._win_hwnd      # zu() minimiert das Fenster am Ende wieder (wie beim Tab-Tausch)
                    if not ort.eigen:                      # Formular in der TradingView-Seite: auch der Login-Blick braucht die neue Verbindung
                        ort.ws, ort.eingabe = s.ws, s
                    trail.append("[Login] neu an denselben TradingView-Tab angehängt — warte weiter auf das Konto")
                    continue
                except Exception as e2:
                    lebt = bool(_cdp_http("/json/version", timeout=1.5))     # Chrome kann genau jetzt geendet sein
                    trail.append(f"[Login] Neu-Anhängen gescheitert ({type(e2).__name__}) — Puls-Chrome {'läuft' if lebt else 'antwortet nicht'}")
            return ("chrome_weg" if not lebt else "verbindung"), (
                "Beim Tradovate-Login " + ("hat sich das Puls-Chrome beendet" if not lebt else
                                           ("ist der TradingView-Tab weg" if urteil == "tab_weg" else "ist die Verbindung zum TradingView-Tab abgerissen"))
                + " — ob der Login durchging, ist offen. Puls-Chrome ansehen, NICHT mehrfach hintereinander neu anstoßen.")
        if aktiv:
            trail.append(f"[Login] OK verbunden, aktiv '{aktiv[:40]}'")
            return "", ""
        # Live 29.09.2026 14:56 UTC: nach „Anmelden" verschwand das Formular, TradingView zeigte im Connect-Dialog „Error! The login
        # operation has been canceled" — Puls wartete 40 s auf ein Konto. Eine NEUE Fehlermeldung dort beendet das Warten sofort.
        f_tv = cdp_connect_fehler(_K3Ort("TradingView-Seite", s.ws, s, "").blick()) if ort.eigen else ""
        if f_tv and f_tv != ((vorher or {}).get("fehler") or ""):
            return "abgebrochen", f_tv
        bo = ort.blick()
        if bo.get("freigabe"):
            return "freigabe", "Tradovate fragt nach einer Freigabe ('Allow') — NICHT automatisch bestätigt; bitte im Puls-Chrome einmal von Hand."
        lb2 = bo.get("login") or {}
        if lb2 and bo.get("fehler_text"):
            return "login_fehler", f"Tradovate meldet '{bo.get('fehler_text')}' — nicht angemeldet."
        if lb2 and ort.eigen and not enter and time.time() - t0 >= 3.0:
            # Login-Klick ohne Wirkung (alter Puls 23.09.2026: Hover ja, Klick nicht — die offene Autofill-Liste schluckte ihn) →
            # Esc, ins Passwortfeld, Esc, und NUR mit bewiesenem Username/Passwort Enter (schickt das Formular ab)
            enter = True
            try:
                ort.eingabe.taste("Escape")
                _warte(0.2, 0.15)
                pw = lb2.get("pw") or {}
                if cdp_rect(pw) and ort.eingabe.klick(cdp_rect(pw), "Passwortfeld"):
                    _warte(0.3, 0.2)
                    ort.eingabe.taste("Escape")
                    ok3, txt3 = cdp_login_bereit(ort.blick().get("login"))
                    if ok3:
                        ort.eingabe.taste("Enter")
                        trail.append("[Login] Login-Klick ohne Wirkung → Enter im Passwortfeld")
                    else:
                        trail.append(f"[Login] Rückfall Enter abgesagt: {txt3}")
            except Exception as e_:
                trail.append(f"[Login] Rückfall Enter nicht möglich ({type(e_).__name__})")
    return "verbunden", "Nach dem Login zeigt TradingView kein Konto (40 s) — Puls-Chrome ansehen."


def _cdp_tradovate_verbinden(sitz, cmd, opts, trail, beleg=None, merk=None):
    """Schritte [2]–[5]: einmal Tradovate mit dem Login der Firma verbinden. sitz = [Sitzung], wird beim Tab-Tausch ersetzt.
    -> (code, text, wie) — code '' = TradingView zeigt danach ein Tradovate-Konto (welches, klärt der Aufrufer über das Dropdown);
    wie 'login' = selbst angemeldet, 'selbst' = eine gemerkte Sitzung hat sich von allein verbunden, 'steht' = ein Konto ist zu
    sehen, aber ohne Beleg für einen fremden Login (nichts abgemeldet, der Aufrufer macht den Konto-Schritt neu).
    beleg = extra des letzten Konto-Schritts (cdp_abmelden_erlaubt). code 'login_unlesbar' = verbunden, Konto nicht lesbar.
    merk (05.10.2026, cdp_konto_weg): bekommt formular=True NUR, wenn die Anmeldung über das Tradovate-Formular mit genau diesem
    Username durchlief — der einzige Beweis, mit welchem Benutzer Tradovate jetzt verbunden ist."""
    benutzer = str(cmd.get("tv_username") or "").strip()
    s = sitz[0]
    _cdp_kachel_weg(s, trail)                             # Werbe-Kachel vor dem Login-Schritt weg (05.10.2026)
    bl = _K3Ort("TradingView-Seite", s.ws, s, benutzer).blick()
    if cdp_connect_dialog(bl):
        trail.append("[Login] Connect-Dialog steht schon da — direkt verbinden")
    else:
        aktiv = _cdp_verbunden_lesen(s, opts, trail)
        if aktiv or cdp_rect(bl.get("ctx")):
            ja, grund = cdp_abmelden_erlaubt(aktiv, beleg)
            if grund == "unlesbar":
                trail.append(f"[Login] Tradovate ist verbunden, das aktive Konto aber nicht lesbar ('{aktiv[:40] or '-'}') — NICHT abgemeldet")
                return "login_unlesbar", ("Tradovate ist im Puls-Chrome verbunden, aber welches Konto aktiv ist, war nicht lesbar "
                                          "(kein Konto-Umschalter im Broker-Panel erkannt) — nichts abgemeldet, kein Login. "
                                          "Puls-Chrome ansehen (Broker-Panel)."), ""
            if not ja:
                trail.append(f"[Login] Tradovate zeigt '{aktiv[:40]}' — kein Beleg für einen fremden Login ({grund}) → nicht "
                             "abmelden, Konto-Schritt neu")
                return "", "", "steht"
            trail.append(f"[Login] Tradovate verbunden mit anderem Login ('{aktiv[:40]}', Ziel 0× in der selbst geöffneten Liste) → abmelden")
            ok, f = _cdp_abmelden(s, opts, trail)
            if not ok:
                return "abmelden", f, ""
        _cdp_tab_mit_link(sitz, tv_trade_now_url(bl.get("url") or cmd.get("tv_url")), trail)
        s = sitz[0]
        art, x = _cdp_nach_link(s, opts, trail)       # trail fehlte seit .828 (NameError → nach Log-out abgebrochen, Prüfer 30.09.2026)
        if art == "verbunden":
            trail.append(f"[Login] TradingView hat sich von selbst verbunden ('{str(x)[:40]}') — gemerkte Sitzung")
            return "", "", "selbst"
        if art != "dialog":
            bl2 = x if isinstance(x, dict) else {}
            trail.append("[Login] gesehen: " + json.dumps({"dialoge": [{"titel": d_.get("titel"), "knoepfe": [k3_label(k) for k in d_.get("knoepfe") or []][:8]}
                                                                        for d_ in bl2.get("dialoge") or [] if isinstance(d_, dict)][:3],
                                                           "leiste": bl2.get("leiste"), "url": bl2.get("url")}, ensure_ascii=False)[:500])
            return "dialog", "TradingView ist mit ?trade-now=TRADOVATE neu offen, aber der Tradovate-Dialog erscheint nicht (40 s).", ""
    for versuch in (1, 2):
        code, text, vorher = _cdp_dialog_verbinden(s, bool(cmd.get("sitzung_merken")), trail)
        if code:
            return code, text, ""
        ort, text = _cdp_login_ort(s, vorher, benutzer, opts, trail)
        if ort == "verbunden":
            return "", "", "login"
        if ort is None:
            return "login_formular", text + " Tradovate ist NICHT verbunden.", ""
        if ort == "abgebrochen":
            code = "abgebrochen"
        else:
            code = "?"
            try:
                code, text = _cdp_anmelden(s, ort, benutzer, opts, trail, vorher, sitz=sitz)
                s = sitz[0]                              # beim Neu-Anhängen ersetzt
            finally:
                if ort.eigen:
                    tid = getattr(ort, "target_id", None)
                    if not code and tid and any(isinstance(t, dict) and t.get("id") == tid for t in _cdp_http("/json/list") or []):
                        _cdp_http(f"/json/close/{tid}")      # Tradovate-Tab blieb nach dem Login offen → zu (bei Fehlern bleibt er für die Hand)
                        trail.append("[Login] Tradovate-Tab geschlossen")
                    ort.zu()
            if code != "abgebrochen":
                if not code and isinstance(merk, dict):
                    merk["formular"] = True
                return code, text, "login"
        if versuch == 1:
            # TradingView hat den Login abgebrochen („Error! The login operation has been canceled") — Dialog steht mit Connect
            # wieder da: EINMAL neu verbinden; Tradovate ist dann meist schon angemeldet (Connect ohne Anmeldeseite)
            trail.append(f"[Login] TradingView meldet '{text[:90]}' — Connect noch einmal")
            _warte(1.0, 0.8)
            continue
        return "abgebrochen", f"TradingView bricht den Login zweimal ab ('{text[:90]}') — Tradovate ist NICHT verbunden.", ""
    return "abgebrochen", "Login nicht abgeschlossen.", ""


def _cdp_login_sichern(res, trail):
    """Spur des Auto-Logins ins Backend (puls_diagnose, letzte 1800 Zeichen) und voll lokal (login_<zeit>.json). Nie ein Passwort —
    der Login-Blick liefert keins."""
    _puls_diagnose_senden(spur=trail, schritt="cdp-login")
    try:
        with open(os.path.join(_AUGEN_HIER, "login_" + time.strftime("%Y%m%d_%H%M%S") + ".json"), "w", encoding="utf-8") as f:
            json.dump({"login": res.get("login"), "trail": list(trail)}, f, ensure_ascii=False, default=str)
    except Exception:
        pass


def _cdp_sitzung_zurueck(s, opts, trail):
    """Finn 29.09.2026 („offensichtliche Fehlerdialoge selbst lösen"), Live 15:48 UTC: TradingViews „Session disconnected"-Modal lag
    im Puls-Chrome, der Konto-Schritt scheiterte am Umschalter darunter. Steht der Dialog mit genau einem „Connect" da: klicken
    (echte Maus), warten, bis er weg ist. „Connect" holt die TradingView-Sitzung in DIESES Chrome — die andere (z. B. Reader-Chrome
    mit demselben Konto) wird getrennt. -> True, wenn geklickt und weg"""
    try:
        bl = _K3Ort("TradingView-Seite", s.ws, s, "").blick()
    except Exception:
        return False
    k = cdp_sitzung_getrennt(bl)
    if not k:
        return False
    trail.append("TradingView: „Session disconnected“ (Konto in anderem Browser/Gerät aktiv) — „Connect“ im Puls-Chrome")
    if not s.klick(cdp_rect(k), "Connect (Sitzung zurückholen)"):
        trail.append("„Connect“ im Sitzungs-Dialog NICHT gedrückt — Dialog bleibt")
        return False
    ende = time.time() + 12.0
    while time.time() < ende:
        _warte(0.8, 0.3)
        try:
            if not cdp_sitzung_getrennt(_K3Ort("TradingView-Seite", s.ws, s, "").blick()):
                _warte(1.5, 0.8)                     # TradingView baut Panel/Konto nach dem Wiederverbinden neu auf
                trail.append("Sitzung wieder verbunden — weiter")
                return True
        except Exception:
            continue
    trail.append("Sitzungs-Dialog nach „Connect“ noch da (12 s)")
    return False


def _cdp_konto_mit_login(sitz, ext, opts, cmd, trail, res):
    """Konto sicherstellen wie _cdp_konto_sichern — steht es nicht im Puls-Chrome (kein Broker / anderer Tradovate-Login), verbindet
    Puls selbst (Block-Kopf). sitz = [Sitzung] (der Login tauscht den Tab). -> (ok, code, msg, stand, extra) wie _cdp_konto_sichern.
    Scheitert der Login, bleibt der Code 'konto_nicht_erreicht' (Frontend „Konto ?", Panel 409) — der Grund steht in msg."""
    _cdp_sitzung_zurueck(sitz[0], opts, trail)
    ok, code, msg, st, extra = _cdp_konto_sichern(sitz[0], ext, opts, trail)
    if not ok and _cdp_sitzung_zurueck(sitz[0], opts, trail):
        ok, code, msg, st, extra = _cdp_konto_sichern(sitz[0], ext, opts, trail)   # der Dialog lag über dem Umschalter
    if not ok and code == "kein_broker":
        # ein Blick kann in die Ladephase fallen (Regel seit .327: nie aus EINEM Blick urteilen) — zweiter Blick mit Streuung
        _warte(1.5, 1.0)
        ok, code, msg, st, extra = _cdp_konto_sichern(sitz[0], ext, opts, trail)
    if ok or not cdp_login_noetig(code, extra):
        return ok, code, msg, st, extra
    benutzer = str(cmd.get("tv_username") or "").strip()
    if not benutzer:
        return False, "konto_nicht_erreicht", (msg + " Puls kann nicht selbst verbinden: für die Firma ist kein Tradovate-Username hinterlegt "
                             "(Einstellungen > Prop Firms > Firma bearbeiten > 'Tradovate-Username für TradingView')."), st, extra
    t0 = time.time()
    res["login"] = {"username": benutzer, "anlass": code, "durchgaenge": 0}
    wege, merk = [], {}
    for durchgang in (1, 2, 3):
        res["login"]["durchgaenge"] = durchgang
        trail.append(f"[Login] {durchgang}. Durchgang: Konto {ext} im Puls-Chrome nicht erreichbar ({code}) → Tradovate mit '{benutzer}' verbinden")
        c2, m2, wie = _cdp_tradovate_verbinden(sitz, cmd, opts, trail, beleg=extra, merk=merk)
        if c2 == "login_unlesbar":
            # Regression .865 (30.09.2026): nichts abgemeldet — ehrlich raus mit dem Befund, kein „Login nicht geschafft"
            res["login"].update(ok=False, code=c2)
            _cdp_login_sichern(res, trail)
            return False, "konto_nicht_erreicht", f"Konto {ext}: {m2}", st, {"login_code": c2}
        if c2:
            res["login"].update(ok=False, code=c2)
            _cdp_login_sichern(res, trail)
            return False, "konto_nicht_erreicht", f"Tradovate-Login '{benutzer}' nicht geschafft ({c2}): {m2}", {}, {"login_code": c2}
        wege.append(wie)
        res["login"]["wie"] = wie
        ok, code, msg, st, extra = _cdp_konto_sichern(sitz[0], ext, opts, trail)
        # weiter nur, wenn sich eine GEMERKTE Sitzung von selbst verbunden hat (ggf. fremder Login) oder ein Konto ohne Beleg stand
        # ('steht': erst jetzt kann die selbst geöffnete Liste den fremden Login belegen). 'steht' zählt nicht als Login-Durchgang
        # (Prüfer 30.09.2026: sonst fiel die Rettung über die gemerkte Sitzung weg): höchstens 2 echte Durchgänge, 'steht' höchstens
        # einmal; nach einem eigenen Login mit dem Username der Firma brächte ein weiterer nichts
        echte = sum(1 for w in wege if w != "steht")
        if (ok or not cdp_login_noetig(code, extra) or wie not in ("selbst", "steht") or time.time() - t0 > CDP_LOGIN_ZWEITER_BIS_S
                or wege.count("steht") > 1 or echte >= 2):
            break
    # KONTO WEG (Block-Kopf bei cdp_konto_weg): eigener Formular-Login war der letzte Schritt, das Ziel steht danach nicht im Login →
    # nach einer Pause EIN zweiter Konto-Schritt (die Kontoliste kann nach dem Login noch nachladen). Kommt das Konto dabei doch,
    # läuft der Lauf normal weiter; nur zwei gleiche Befunde ergeben 'konto_weg'. Danach kein weiterer Abmelde-/Login-Versuch.
    weg = (False, None, False)
    if not ok and merk.get("formular") is True and wege and wege[-1] == "login":
        erst = cdp_konto_weg(extra, True, ext)
        if erst[0]:
            trail.append(f"[Login] Ziel {ext} steht nach dem eigenen Login nicht im Login ({erst[1]} Konto/Konten) — zweiter Blick")
            _warte(2.5, 1.0)
            ok, code, msg, st, extra = _cdp_konto_sichern(sitz[0], ext, opts, trail)
            zweit = (False, None, False) if ok else cdp_konto_weg(extra, True, ext)
            if zweit[0] and zweit[1:] == erst[1:]:
                weg = zweit
    res["login"].update(ok=bool(ok), code="" if ok else code)
    noetig = not ok and cdp_login_noetig(code, extra)
    if not ok and code == "kein_broker":
        code = "konto_nicht_erreicht"          # nach dem Login-Weg gilt der Vertrag des Docstrings (Panel 409 „Konto ?")
    if weg[0]:
        code = "konto_weg"
        # Kontonummer hier nur mit den letzten vier Stellen: msg landet in puls_fehler und im Radar-Tooltip (Master 06.10.2026)
        msg = (f"Konto …{str(ext)[-4:]} bei Tradovate nicht mehr vorhanden (im Login des Kontos "
               + ("steht 1 Konto" if weg[1] == 1 else f"stehen {weg[1]} Konten") + ", dieses nicht) — vermutlich geblowt.")
        extra = dict(extra, retry_ok=False, konten_im_login=weg[1], einzelkonto=bool(weg[2]))
        res["login"]["code"] = code
        trail.append(f"[Login] Konto weg: nach dem eigenen Login mit '{benutzer}' zweimal gelesen — {weg[1]} Konto/Konten im Login, "
                     "Ziel nicht dabei, kein weiterer Login-Versuch")
    elif noetig:
        if "login" in wege:
            msg += f" — auch nach dem Tradovate-Login '{benutzer}'. Gehört der Username wirklich zu dieser Firma?"
        elif "selbst" in wege:
            msg += " — die gemerkte Tradovate-Sitzung verbindet immer wieder denselben Login; bitte im Puls-Chrome von Hand abmelden."
        else:
            msg += " — nichts abgemeldet (kein weiterer Durchgang)."
    elif not ok and wege and all(w == "steht" for w in wege):
        msg += " — Tradovate zeigt ein Konto, aber ohne Beleg für einen fremden Login: nichts abgemeldet."
    _cdp_login_sichern(res, trail)
    return ok, code, msg, st, extra


def main():
    # Konsole robust (24.09.2026 abends, Finns PC: tvlesen 'absturz @ raus' = UnicodeEncodeError, cp1252 kann
    # '\u25bc' aus dem TradingView-Tab-Titel nicht kodieren — die Spur traegt den Titel, die JSON-Antwort
    # scheiterte beim print). Unkodierbares wird ersetzt statt zu werfen; das Panel liest mit errors=replace.
    for _s in (sys.stdout, sys.stderr):
        try:
            _s.reconfigure(errors="replace")
        except Exception:
            pass
    if len(sys.argv) >= 2 and sys.argv[1] == "mousetest":
        modus_mousetest()
        return 0
    if len(sys.argv) >= 2 and sys.argv[1] == "tvfokus":
        # Orbit Schritt 1 (28.08.2026): nur den TradingView-Tab nach vorn —
        # wie mousetest ohne Config, und ohne den Prophos-Heimweg unten.
        modus_tvfokus()
        return 0
    if len(sys.argv) >= 2 and sys.argv[1] == "tvstart":
        # Futures-Puls Neuaufbau Schritt 1 (21.09.2026): pruefen, ob
        # TradingView offen ist — wenn nicht, starten. Optionales JSON mit
        # tv_url / tv_browser_path / tv_chrome_profil (kommt vom Panel aus der
        # Config). Wie tvfokus ohne Prophos-Heimweg: der PC soll danach auf
        # TradingView stehen.
        try:
            cfg = json.loads(sys.argv[2]) if len(sys.argv) >= 3 else {}
        except ValueError:
            cfg = {}
        modus_tvstart(cfg if isinstance(cfg, dict) else {})
        return 0
    if len(sys.argv) >= 3 and sys.argv[1] == "tvkonto":
        # Futures-Puls Neuaufbau Schritt 2a (21.09.2026): TradingView
        # sicherstellen, dann pruefen, ob das richtige Tradovate-Konto aktiv
        # ist. Liest nur — kein Klick in die Seite, keine Order.
        try:
            cmd = json.loads(sys.argv[2])
        except ValueError as e:
            print(json.dumps({"ok": False, "msg": f"Befehl kein gueltiges JSON: {e}"}))
            return 2
        try:
            modus_tvkette(cmd)      # Schritt 1+2, mit 'symbol' im Befehl auch Schritt 3
        except Exception as e:
            print(json.dumps({"ok": False, "schritt": "absturz",
                              "msg": f"TV-Kette abgebrochen: {type(e).__name__}: {e}"}))
        augen_anstossen()      # Augen E0 (29.09.2026): entkoppelt, nur mit Schalter 'cdp'
        return 0
    if len(sys.argv) >= 2 and sys.argv[1] in ("k3", "k3login"):
        # K3 scharfer Handlauf (29.09.2026, Finns direkte Anweisung an T3) — NUR von Hand am CDP-Test-PC, kein Weg aus Prophos/Panel:
        # 'order_bot.py k3 <ApexExtID> <Symbol> <buy|sell> 1 <TP$> <SL$> [<Login-Anfang>]' bzw. 'order_bot.py k3login <Login-Anfang>'
        a = sys.argv[2:]
        if sys.argv[1] == "k3" and len(a) >= 6:
            cmd = {"ext_id": a[0], "symbol": a[1], "richtung": a[2].lower(), "volumen": a[3], "tp_usd": a[4], "sl_usd": a[5],
                   "login_anfang": a[6] if len(a) > 6 else ""}
        elif sys.argv[1] == "k3login" and len(a) >= 1:
            cmd = {"nur_login": True, "login_anfang": a[0]}
        else:
            print("Aufruf: order_bot.py k3 <ApexExtID> <Symbol> <buy|sell> 1 <TP$> <SL$> [<Login-Anfang>]  |  order_bot.py k3login <Login-Anfang>")
            return 2
        try:
            modus_k3(cmd)
        except Exception as e:
            _handlauf_setzen(False)
            print(json.dumps({"ok": False, "code": "absturz", "msg": f"K3 abgebrochen: {type(e).__name__}: {e} @ {_absturz_ort(e)} — "
                              "erst in TradingView nachsehen, ob eine Position/Order offen ist."}, ensure_ascii=False))
        return 0
    if len(sys.argv) >= 6 and sys.argv[1] == "probe":
        # K2-Probelauf am PC (29.09.2026): 'order_bot.py probe <ExternalID> <Symbol> <buy|sell> <Menge> [TP$] [SL$]' —
        # füllt das Ticket im Puls-Chrome und beweist jeden Wert, sendet NIE (modus_tvkette_cdp kennt keinen Senden-Klick)
        a = sys.argv[2:]
        modus_tvkette_cdp({"ext_id": a[0], "symbol": a[1], "richtung": a[2].lower(), "volumen": a[3],
                           "tp_usd": a[4] if len(a) > 4 else None, "sl_usd": a[5] if len(a) > 5 else None, "scharf": False})
        return 0
    if len(sys.argv) >= 3 and sys.argv[1] == "tsxbleiben":
        # Kind nach gesendeter TopstepX-Order (06.10.2026): Puls-Chrome stehen lassen, später minimieren — keine Ausgabe
        try:
            cmd = json.loads(sys.argv[2])
        except ValueError:
            cmd = {}
        try:
            modus_tsxbleiben(cmd if isinstance(cmd, dict) else {})
        except Exception:
            pass
        return 0
    if len(sys.argv) >= 2 and sys.argv[1] == "augen":
        # Puls-Augen über CDP (29.09.2026, E0): nur lesen, entkoppelt angestoßen; 'augen {"start": true}' = Puls-Chrome
        # für den einmaligen Menschen-Login öffnen
        if len(sys.argv) >= 3 and sys.argv[2].strip().lower() == "start":
            cmd = {"start": True}          # 'order_bot.py augen start' / puls-chrome-starten.bat — ohne JSON-Quoting in cmd
            if len(sys.argv) >= 4 and sys.argv[3].strip().lower() == "tsx":
                cmd["tsx"] = True          # 'order_bot.py augen start tsx' (K0): TopstepX-Tab im Puls-Chrome öffnen
        elif len(sys.argv) >= 3 and sys.argv[2].strip().lower() == "jetzt":
            cmd = {"jetzt": True}          # 'order_bot.py augen jetzt': sofort einmal lesen (Test am PC, 29.09.2026)
        elif len(sys.argv) >= 4 and sys.argv[2].strip().lower() == "aufnahme" and sys.argv[3].strip().lower() in ("start", "stopp", "senden"):
            cmd = {"aufnahme": sys.argv[3].strip().lower()}   # 'augen aufnahme start|stopp' (Finns Idee 29.09.2026)
        else:
            try:
                cmd = json.loads(sys.argv[2]) if len(sys.argv) >= 3 else {}
            except ValueError:
                cmd = {}
        modus_augen(cmd if isinstance(cmd, dict) else {})
        return 0
    if len(sys.argv) >= 3 and sys.argv[1] == "tsxorder":
        # Puls für Topstep, Etappe 2 (27.09.2026): Order bzw. Probe (scharf:false) — retry_ok bei Absturz immer False
        try:
            cmd = json.loads(sys.argv[2])
        except ValueError as e:
            print(json.dumps({"ok": False, "code": "befehl", "retry_ok": True, "gesendet": False, "msg": f"Befehl kein gueltiges JSON: {e}"}))
            return 2
        try:
            modus_tsxorder(cmd if isinstance(cmd, dict) else {})
        except Exception as e:
            print(json.dumps({"ok": False, "code": "absturz", "schritt": "absturz", "retry_ok": False,
                              "msg": f"TopstepX-Order abgebrochen: {type(e).__name__}: {e} @ {_absturz_ort(e)} — erst in TopstepX nachsehen."}))
        return 0
    if len(sys.argv) >= 2 and sys.argv[1] in ("tsxinventar", "tsxlesen"):
        # Puls für Topstep, Etappe 1 (27.09.2026, B16): nur lesen, keine Order
        try:
            cmd = json.loads(sys.argv[2]) if len(sys.argv) >= 3 else {}
        except ValueError:
            cmd = {}
        try:
            (modus_tsxinventar if sys.argv[1] == "tsxinventar" else modus_tsxlesen)(cmd if isinstance(cmd, dict) else {})
        except Exception as e:
            print(json.dumps({"ok": False, "code": "absturz", "schritt": "absturz",
                              "msg": f"TopstepX-Lauf abgebrochen: {type(e).__name__}: {e} @ {_absturz_ort(e)}"}))
        augen_anstossen()
        return 0
    if len(sys.argv) >= 3 and sys.argv[1] == "tvlesen":
        # Orbit-V2-Rundgang (24.09.2026): Konto anfahren, dann NUR lesen —
        # Position offen? Today's P&L? Klickt hoechstens den Konto-Umschalter
        # (ueber modus_tvkonto), nie ins Order-Panel. Kein Prophos-Heimweg:
        # der PC bleibt auf TradingView, sonst drosselt Chrome den Reader.
        try:
            cmd = json.loads(sys.argv[2])
        except ValueError as e:
            print(json.dumps({"ok": False, "code": "befehl", "msg": f"Befehl kein gueltiges JSON: {e}"}))
            return 2
        try:
            modus_tvlesen(cmd)
        except Exception as e:
            # Ort dazu (24.09.2026 abends, Finn: 'der Reader ist aktiv, liest die Position trotzdem
            # nicht' — in der DB stand nur 'absturz'): letzte eigene Stelle aus dem Traceback.
            print(json.dumps({"ok": False, "code": "absturz", "schritt": "absturz",
                              "msg": f"TV-Lesen abgebrochen: {type(e).__name__}: {e} @ {_absturz_ort(e)}"}))
        augen_anstossen()
        return 0
    if len(sys.argv) >= 3 and sys.argv[1] == "tvclose":
        # Orbit V2 schliessen (24.09.2026, Auto-Close 23:45–00:00 Dubai): Konto
        # anfahren wie tvlesen, dann in der Positions-Tabelle GENAU EINE Zeile
        # der Wurzel ueber TradingViews eigenen Schliessen-Knopf flatten und den
        # Beweis (Reader ohne die Position, Streak 2) + Today's P&L liefern.
        # Kein Prophos-Heimweg, derselbe Grund wie bei tvlesen.
        try:
            cmd = json.loads(sys.argv[2])
        except ValueError as e:
            print(json.dumps({"ok": False, "code": "befehl", "retry_ok": True,
                              "msg": f"Befehl kein gueltiges JSON: {e}"}))
            return 2
        try:
            modus_tvclose(cmd)
        except Exception as e:
            # retry_ok=False: der Bot weiss nach einem Absturz nicht, ob der
            # Schliessen-Klick schon raus war (Doktrin wie tvorder).
            print(json.dumps({"ok": False, "code": "absturz", "schritt": "absturz", "retry_ok": False,
                              "msg": f"TV-Schliessen abgebrochen: {type(e).__name__}: {e} — erst in "
                                     "TradingView nachsehen, ob die Position noch offen ist."}))
        return 0
    if len(sys.argv) >= 3 and sys.argv[1] == "tvorder":
        # Orbit-Puls Schritt 2 (30.08.2026): die Order auf TradingView
        # platzieren. Wie tvfokus OHNE Config-Datei — der Weg fuehrt durch den
        # Browser, nicht durch ein MT5-Terminal; das Zielkonto steht als
        # ext_id IM BEFEHL. Und wie tvfokus ohne den Prophos-Heimweg unten:
        # der PC muss auf TradingView stehen bleiben, sonst drosselt Chrome
        # den Reader im Hintergrund-Tab und der Hedge wird blind.
        try:
            cmd = json.loads(sys.argv[2])
        except ValueError as e:
            print(json.dumps({"ok": False, "retry_ok": True,
                              "msg": f"Befehl kein gueltiges JSON: {e}"}))
            return 2
        try:
            modus_tvorder(cmd)
        except Exception as e:
            # Ein stummer Bot ist der Diagnose-Killer (Lehre 15.08.2026) — und
            # hier ist er zusaetzlich gefaehrlich: das Panel wuesste nicht, ob
            # vor oder nach dem Senden-Klick abgebrochen wurde. Deshalb ist
            # retry_ok bei einem UNERWARTETEN Fehler immer False.
            print(json.dumps({"ok": False, "retry_ok": False, "schritt": "absturz",
                              "msg": f"TV-Order abgebrochen: {type(e).__name__}: {e} — "
                                     "erst in TradingView nachsehen, ob eine Order "
                                     "liegt, bevor irgendetwas wiederholt wird."}))
        return 0
    if len(sys.argv) >= 3 and sys.argv[1] == "inspect":
        modus_inspect(sys.argv[2])
        return 0
    if len(sys.argv) < 3:
        print(json.dumps({"ok": False, "retry_ok": True,
                          "msg": "Aufruf: order_bot.py <config.json> '<befehl-json>'"}))
        return 2
    try:
        cmd = json.loads(sys.argv[2])
    except ValueError as e:
        print(json.dumps({"ok": False, "retry_ok": True, "msg": f"Befehl kein gueltiges JSON: {e}"}))
        return 2
    fehler = pruefe_befehl(cmd)
    if fehler:
        print(json.dumps({"ok": False, "retry_ok": True,
                          "msg": "Befehl unvollstaendig: " + " · ".join(fehler)}))
        return 2
    # Close-Befehle (28.08.2026, Remote-Close) laufen ueber denselben Aufruf —
    # 'aktion' entscheidet den Weg, pruefe_befehl hat den Zweig schon validiert.
    _api_stat_reset()
    try:
        if str(cmd.get("aktion") or "").lower() == "close":
            res = run_close(sys.argv[1], cmd)
        else:
            res = run(sys.argv[1], cmd)
    finally:
        # Die offen gehaltene Terminal-Verbindung sauber loesen (31.08.2026) —
        # hier statt in run(), damit JEDER Ausgang sie loest, auch der Absturz.
        # Ohne das haenge der Prozess bis zu seinem Ende am Terminal.
        _api_trennen()
    # Ausgangssituation (28.08.2026): nach jedem Lauf zurueck in den Prophos-
    # Tab — hier statt in run(), damit ausnahmslos JEDER Ausgang (Erfolg,
    # Abbruch, SL/TP-Warnung) denselben Heimweg nimmt. mousetest/inspect
    # bleiben bewusst aussen vor: wer diagnostiziert, will am Terminal bleiben.
    heim = _zurueck_zu_prophos()
    res["trail"] = (res["trail"] + " → " + heim) if res.get("trail") else heim
    print(json.dumps(res))
    return 0 if res.get("ok") else 1


if __name__ == "__main__":
    sys.exit(main())
